update public.learning_topics set short_description='Treat a specific enrollment association as a participant in monitoring, preserve its independent identity, and map references without inventing student-course combinations.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Treat a specific enrollment association as a participant in monitoring, preserve its independent identity, and map references without inventing student-course combinations.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Aggregation.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-aggregation' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-aggregation-application','MCQ Test 2',category,10,10,'Application and scenarios for Aggregation.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-aggregation' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-1','pt-dbms-sql-6-aggregation','What problem does aggregation solve in EER modeling?','["It merges two similar entity sets that share attributes into one", "It lets an entire relationship (with its connected entities) be treated as a higher-level entity so a third entity set can relate to it", "It restricts the values an attribute can take", "It converts a weak entity into a strong entity"]'::jsonb,1,'Aggregation elevates a relationship into an entity-like construct so it can itself participate in further relationships.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-2','pt-dbms-sql-6-aggregation','In the example of Faculty needing to be linked to a specific (Student, Course) enrollment pairing, why is aggregation used instead of connecting Faculty directly to Student and Course separately?','["Because Faculty cannot have relationships to Student or Course at all", "Because Faculty needs to relate specifically to the enrollment combination as a whole, not independently to any Student or any Course", "Because aggregation is required whenever three entity sets exist in a schema", "Because Student and Course are weak entities"]'::jsonb,1,'The intended meaning is tied to the specific enrollment instance, which aggregation captures by treating Enrolls_In as a unit.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-3','pt-dbms-sql-6-aggregation','In the EER aggregation convention used here, what does a boundary around Student, EnrollsIn and Course communicate?','["As a double-line diamond", "The enrollment association is treated as a unit for a further relationship; boundary styling depends on the notation", "As an ISA triangle", "As a double-line rectangle"]'::jsonb,1,'The semantic grouping matters; a dashed boundary is one drawing convention, not a universal database implementation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-4','pt-dbms-sql-6-aggregation','Which statement correctly distinguishes aggregation from generalization/specialization?','["They are the same EER concept under different names", "Aggregation abstracts an association occurrence; generalization and specialization express an is-a hierarchy", "Generalization is only used with weak entities; aggregation is only used with strong entities", "Aggregation always requires a recursive relationship"]'::jsonb,1,'The abstractions have different purposes and must preserve their respective identity meanings.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-5','pt-dbms-sql-6-aggregation','Why can''t the basic ER model directly connect a relationship diamond to another relationship diamond?','["Because relationships can only connect to entity sets, not to other relationships, in the basic ER model — aggregation is specifically introduced to work around this limitation", "Because diamonds can only have one line coming out of them", "Because relationships never have cardinality", "Because this is actually allowed without needing aggregation"]'::jsonb,0,'The basic ER model restricts relationships to connecting entity sets; aggregation is the EER extension that allows a relationship to be treated like an entity so it can connect further.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-6','pt-dbms-sql-6-aggregation','In relational mapping, how is an aggregation-derived relationship (like Monitored_By) typically implemented?','["It is discarded entirely since aggregation cannot be mapped to tables", "By referencing the key of the junction table that already represents the aggregated relationship (e.g., the Enrollment table''s key), treating its rows as referenceable entities", "By duplicating all attributes of Student and Course into a new table", "By making Faculty a weak entity"]'::jsonb,1,'The aggregated relationship''s table (e.g., Enrollment) becomes referenceable, letting the new relationship point to specific enrollment rows.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-7','pt-dbms-sql-6-aggregation','Would a plain ternary relationship (Faculty, Student, Course) capture exactly the same meaning as the aggregation example?','["Yes, they are always semantically identical", "Not automatically; the mapping must preserve that monitoring refers to an existing enrollment association, not merely arbitrary participant triples", "No, because ternary relationships cannot involve Faculty", "No, because ternary relationships require weak entities"]'::jsonb,1,'A ternary encoding can carry additional constraints, but its column list alone does not preserve the original association dependency.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-aggregation-8','pt-dbms-sql-6-aggregation','Which everyday phrase best captures the core idea of aggregation?','["''Is-a'' relationship between similar entity sets", "''Has-a'' composition of sub-attributes", "''Treating a relationship as a thing'' so it can have its own further relationships", "''One entity depends on another for identity''"]'::jsonb,2,'Aggregation is memorably summarized as relationship-as-entity, distinct from is-a (generalization) or dependency (weak entity/identifying relationship).',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-aggregation-new-9','pt-dbms-sql-6-aggregation','Does Faculty 7 monitoring Student 17 in Course 10 imply monitoring that student in Course 20?','["Yes; every monitor is global to the student", "No; the particular enrollment matters", "Only if titles match", "Only if the query is sorted"]'::jsonb,1,'Independent participant links do not establish every combination.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-aggregation-new-10','pt-dbms-sql-6-aggregation','Is EER aggregation the same operation as SQL SUM?','["Yes; every aggregation totals numbers", "Only if no faculty exists", "No; association abstraction and numeric calculation are different concepts", "Only if rows are grouped"]'::jsonb,2,'The term has distinct modeling and query uses.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
