insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-alter-table-1','pt-dbms-sql-9-alter-table','What does ALTER TABLE allow you to do?','["Only rename a table", "Modify an existing table''s structure — add/drop columns, change types, add/drop constraints", "Only delete rows from a table", "Create a brand new table"]'::jsonb,1,'ALTER TABLE modifies an existing table''s structure without recreating it.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-alter-table-2','pt-dbms-sql-9-alter-table','Why can a type-changing ALTER be expensive?','["It always requires dropping the whole database", "The exact engine and change can require rewriting data or indexes and restrictive locking", "It only works on empty tables", "It automatically creates a backup first"]'::jsonb,1,'Not every change rewrites the table or uses an identical lock.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-alter-table-3','pt-dbms-sql-9-alter-table','Which is a possible staged strategy for a new required property on populated live data?','["Add the column as NOT NULL directly in one statement", "Add a nullable field, coordinate writers and backfill, verify completeness, then enforce the requirement", "Drop and recreate the table", "Only possible during scheduled downtime"]'::jsonb,1,'This strategy still requires concurrency, compatibility and locking analysis.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-alter-table-4','pt-dbms-sql-9-alter-table','Why must adding a required column to populated data be evaluated against engine rules and existing values?','["It succeeds silently, leaving nulls in old rows", "Existing rows need a valid defined value; outcomes depend on defaults, engine behaviour and modes", "It automatically deletes all existing rows", "It converts the column to nullable automatically"]'::jsonb,1,'It is inaccurate to promise the same unconditional failure behaviour on every engine.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
