insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-alter-table-application-new-8','pt-dbms-sql-9-alter-table-application','What must a MySQL MODIFY COLUMN definition preserve deliberately?','["Every old query alias", "Relevant attributes such as intended type and nullability", "Only the spelling of SELECT", "An arbitrary default address"]'::jsonb,1,'Restating an incomplete definition can change properties.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-alter-table-application-new-9','pt-dbms-sql-9-alter-table-application','Does successful DDL guarantee every existing caller remains compatible?','["Yes", "Only when no default is given", "No", "Only for small tables"]'::jsonb,2,'Application contracts need their own review.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-alter-table-application-new-10','pt-dbms-sql-9-alter-table-application','Why preserve the original checker and setup?','["To force a production deployment", "To skip testing the new column", "To change saved identities", "To retain the assessment’s observable structural contract"]'::jsonb,3,'Existing assessment semantics must not be silently weakened.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
if exists(select 1 from public.dsa_problems where learning_topic_id=topic_uuid and id not in ('cx-alter-inspection-date','cp-dbms-sql-add-an-email-column')) then raise exception 'Existing coding problems require explicit integration: %', 'alter-table'; end if;
if exists(select 1 from public.dsa_problems where (id='cx-alter-inspection-date' or slug='alter-inspection-date') and (id<>'cx-alter-inspection-date' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-alter-inspection-date'; end if;
if exists(select 1 from public.dsa_problems where id='cx-alter-inspection-date' and description is distinct from 'Add inspected_on DATE NULL to stock. Set it to 2026-09-01 only for rows with quantity > 0. Return item_id, quantity, inspected_on without replacing stock or changing existing identifiers.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL);
INSERT INTO stock VALUES (2,0),(1,3);
```

**Required ordering:** Ascending item_id.

**Edge cases:**
- Zero stock keeps NULL.
- Empty stock still requires the definition change.') then raise exception 'New coding ID already has other content: %', 'cx-alter-inspection-date'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-alter-inspection-date',null::text,'Add an optional inspection date without replacing stock rows','Easy','alter-inspection-date','Add inspected_on DATE NULL to stock. Set it to 2026-09-01 only for rows with quantity > 0. Return item_id, quantity, inspected_on without replacing stock or changing existing identifiers.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL);
INSERT INTO stock VALUES (2,0),(1,3);
```

**Required ordering:** Ascending item_id.

**Edge cases:**
- Zero stock keeps NULL.
- Empty stock still requires the definition change.','[{"input": "INSERT INTO stock VALUES (2,0),(1,3);", "output": "item_id\tquantity\tinspected_on\n1\t3\t2026-09-01\n2\t0\tNULL", "explanation": "The optional addition preserves rows while the subsequent write records only the stated inspection cases."}]'::jsonb,'[{"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO stock VALUES (7,0),(8,1);", "expected": "item_id\tquantity\tinspected_on\n7\t0\tNULL\n8\t1\t2026-09-01", "hidden": true}]'::jsonb,'["Preserve existing table and quantities.", "Missing inspection is represented as NULL."]'::jsonb,'["Add the column before using it in UPDATE.", "Use the stated positive-quantity predicate only."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The optional addition preserves rows while the subsequent write records only the stated inspection cases.','{"sql": "ALTER TABLE stock ADD COLUMN inspected_on DATE NULL; UPDATE stock SET inspected_on=''2026-09-01'' WHERE quantity>0; SELECT item_id,quantity,inspected_on FROM stock ORDER BY item_id;"}'::jsonb,'The optional addition preserves rows while the subsequent write records only the stated inspection cases.',array['sql'],'CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL);','INSERT INTO stock VALUES (2,0),(1,3);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-9-alter-table' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cp-dbms-sql-add-an-email-column' or slug='add-an-email-column') and (id<>'cp-dbms-sql-add-an-email-column' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cp-dbms-sql-add-an-email-column'; end if;
if not exists(select 1 from public.dsa_problems where id='cp-dbms-sql-add-an-email-column' and learning_topic_id=topic_uuid) then raise exception 'Original coding problem was removed; review required: %', 'cp-dbms-sql-add-an-email-column'; end if;
if exists(select 1 from public.dsa_problems where id='cp-dbms-sql-add-an-email-column' and (md5(description) not in ('6d010b75107cc7c2280ceb52bf3db071','2564e89c67b02e33098477c89dfb93a2') or sql_schema_sql is distinct from 'CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);' or sql_seed_sql is distinct from 'INSERT INTO customers (id, name) VALUES (1, ''Asha''), (2, ''Rohan'');' or sql_check_sql is distinct from 'INSERT INTO customers (id, name, email) VALUES (99, ''Placeholder'', ''test@x.com''); SELECT id, name, email FROM customers ORDER BY id;')) then raise exception 'Edited coding problem requires review: %', 'cp-dbms-sql-add-an-email-column'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbms-sql-add-an-email-column',null::text,'Add an Email Column','Medium','add-an-email-column','Add a nullable email TEXT column to the existing customers table using ALTER TABLE. Preserve all existing ids and names. The original trailing checker inserts customer 99 with a supplied email and reads the table in id order. Do not add a fake address to existing rows or recreate customers.

**MySQL dialect.**

```sql
CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);
INSERT INTO customers (id, name) VALUES (1, ''Asha''), (2, ''Rohan'');
```

**Required ordering:** The retained checker orders all rows by id.

**Edge cases:**
- Existing customers have NULL email.
- A new checker row can supply email.
- No original customers still permits the checker insert.','[{"input": "INSERT INTO customers (id, name) VALUES (1, ''Asha''), (2, ''Rohan'');", "output": "id\tname\temail\n1\tAsha\tNULL\n2\tRohan\tNULL\n99\tPlaceholder\ttest@x.com", "explanation": "The additive definition leaves old identities and names intact and permits the original checker\u2019s new property.", "check_sql": "INSERT INTO customers (id, name, email) VALUES (99, ''Placeholder'', ''test@x.com''); SELECT id, name, email FROM customers ORDER BY id;"}]'::jsonb,'[{"seed_sql": "INSERT INTO customers (id, name) VALUES (5, ''Zara''), (6, ''Omar'');", "expected": "id\tname\temail\n5\tZara\tNULL\n6\tOmar\tNULL\n99\tPlaceholder\ttest@x.com", "hidden": true}, {"seed_sql": "", "expected": "id\tname\temail\n99\tPlaceholder\ttest@x.com", "hidden": true}, {"seed_sql": "INSERT INTO customers VALUES (7,''Mira'');", "expected": "id\tname\temail\n7\tMira\tNULL\n99\tPlaceholder\ttest@x.com", "hidden": true}]'::jsonb,'["Original identity, schema, sample rows and checker retained.", "The new email property permits NULL."]'::jsonb,'["Add the optional column before the trailing checker executes.", "No UPDATE is needed for existing unknown email values."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The additive definition leaves old identities and names intact and permits the original checker’s new property.','{"sql": "ALTER TABLE customers ADD COLUMN email TEXT NULL;"}'::jsonb,'The additive definition leaves old identities and names intact and permits the original checker’s new property.',array['sql'],'CREATE TABLE customers (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL
);','INSERT INTO customers (id, name) VALUES (1, ''Asha''), (2, ''Rohan'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-9-alter-table' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
