if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-alternate-key-1' and (question_text,options,correct_index,explanation) is distinct from ('What is an alternate key?','["A foreign key that references a different table", "A candidate key that was not chosen as the primary key", "A key made of alternating data types", "A key that changes value periodically"]'::jsonb,1,'Alternate key = candidate key minus whichever one became the primary key.') and (question_text,options,correct_index,explanation) is distinct from ('What is an alternate key?','["A foreign key that references a different table", "A candidate key that was not chosen as the primary key", "A key made of alternating data types", "A key that changes value periodically"]'::jsonb,1,'Alternate key = candidate key minus whichever one became the primary key.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-alternate-key-1'; end if;
