if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-alternate-key-2' and (question_text,options,correct_index,explanation) is distinct from ('How is an alternate key typically implemented in SQL?','["With the PRIMARY KEY keyword", "With a UNIQUE constraint", "With a FOREIGN KEY constraint", "It cannot be enforced in SQL at all"]'::jsonb,1,'SQL reserves PRIMARY KEY for the chosen key; alternate keys are enforced with UNIQUE.') and (question_text,options,correct_index,explanation) is distinct from ('How is an alternate key typically implemented in SQL?','["With the PRIMARY KEY keyword", "With UNIQUE and an appropriate NOT NULL policy for a required candidate identity", "With a FOREIGN KEY constraint", "It cannot be enforced in SQL at all"]'::jsonb,1,'A required alternate candidate identity needs both uniqueness and nonmissing values; optional uniqueness is a different contract.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-alternate-key-2'; end if;
