if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-alternate-key-3' and (question_text,options,correct_index,explanation) is distinct from ('Does a UNIQUE constraint by itself forbid NULL values the same way PRIMARY KEY does?','["Yes, identically", "No \u2014 most engines allow multiple NULLs in a UNIQUE column, since NULL is not considered equal to another NULL", "UNIQUE forbids exactly one NULL value", "UNIQUE converts NULLs to zero automatically"]'::jsonb,1,'This is the key SQL-level difference: UNIQUE alone doesn''t imply NOT NULL, and NULLs aren''t compared as duplicates of each other.') and (question_text,options,correct_index,explanation) is distinct from ('In MySQL, does a plain nullable UNIQUE column forbid NULL like a primary key?','["Yes, identically", "No; nullable UNIQUE permits NULL, including multiple absent values under MySQL rules", "UNIQUE forbids exactly one NULL value", "UNIQUE converts NULLs to zero automatically"]'::jsonb,1,'The absence policy must be specified separately. Ordinary NULL inequality is not the explanation for a TRUE comparison.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-alternate-key-3'; end if;
