if exists(select 1 from public.test_questions where id='tq-dbx2-application-developer-2-7' and (question_text,options,correct_index,explanation) is distinct from ('A database driver returns a detailed internal error. What is appropriate handling?','["Display all private credentials in the interface", "Provide a suitable user response and bounded authorized diagnostics without secrets", "Report success regardless of the result", "Copy every private row into a public log"]'::jsonb,1,'User-facing messages and diagnostic evidence have different audiences and privacy requirements.') and (question_text,options,correct_index,explanation) is distinct from ('A database driver returns a detailed internal error. What is appropriate handling?','["Display all private credentials in the interface", "Provide a suitable user response and bounded authorized diagnostics without secrets", "Report success regardless of the result", "Copy every private row into a public log"]'::jsonb,1,'User-facing messages and diagnostic evidence have different audiences and privacy requirements.')) then raise exception 'Edited question requires review: %', 'tq-dbx2-application-developer-2-7'; end if;
