if exists(select 1 from public.test_questions where id='tq-dbx2-application-developer-2-9' and (question_text,options,correct_index,explanation) is distinct from ('An application function calls a method named transaction. What further evidence is needed?','["That allowed, failed, and concurrent behavior preserves the intended invariant", "Nothing; the method name proves every guarantee", "Only a screenshot of the database product logo", "Proof that every query uses SELECT *"]'::jsonb,0,'The behavior of the actual boundary matters more than the name of an abstraction.') and (question_text,options,correct_index,explanation) is distinct from ('An application function calls a method named transaction. What further evidence is needed?','["That allowed, failed, and concurrent behavior preserves the intended invariant", "Nothing; the method name proves every guarantee", "Only a screenshot of the database product logo", "Proof that every query uses SELECT *"]'::jsonb,0,'The behavior of the actual boundary matters more than the name of an abstraction.')) then raise exception 'Edited question requires review: %', 'tq-dbx2-application-developer-2-9'; end if;
