update public.learning_topics set short_description='Understand application developers'' responsibilities for database contracts, parameter binding, trusted authorization, transaction boundaries, useful errors, and failure-focused tests.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand application developers'' responsibilities for database contracts, parameter binding, trusted authorization, transaction boundaries, useful errors, and failure-focused tests.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Application Developer.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-application-developer' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-application-developer-application','MCQ Test 2',category,10,10,'Application and scenarios for Application Developer.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-application-developer' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-1','pt-dbms-sql-1-application-developer','What is the primary responsibility of the Application Developer, according to the notes?','["Writing the application code that implements business logic and lets end users interact with the database", "Designing the ER diagram and choosing primary/foreign keys", "Managing server backups and security patches", "Consuming the finished application without writing any code"]'::jsonb,0,'The notes define the Developer''s role as writing the software that interacts with the database on behalf of end users, implementing business logic.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-2','pt-dbms-sql-1-application-developer','In a student-name lookup, which technique safely supplies a user-controlled value to a database query?','["A parameterized query with placeholders instead of directly concatenating user input", "Directly concatenating the raw username and password into the SQL string", "Bypassing SQL entirely and reading a flat file", "Asking the DBA to run the query manually for every login"]'::jsonb,0,'The notes describe the Developer using a parameterized query with placeholders (?) rather than string concatenation, to query student credentials safely.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-3','pt-dbms-sql-1-application-developer','Which of the following is listed as a typical Application Developer responsibility?','["Mapping application objects to and from database rows, often via an ORM", "Granting and revoking database user privileges", "Deciding whether a relationship is one-to-many or many-to-many during schema design", "Physically allocating disk space for database files"]'::jsonb,0,'The notes list ORM-based object-to-row mapping as one of the Developer''s core responsibilities.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-4','pt-dbms-sql-1-application-developer','How does the Developer''s relationship to the schema typically differ from the Designer''s, per the notes?','["The Developer generally works within the schema the Designer created, though may propose changes back to the Designer", "The Developer always creates the schema from scratch with no Designer involvement", "The Designer writes all of the application''s business logic instead of the Developer", "There is no difference; they are the same role"]'::jsonb,0,'The notes state the Developer works within the existing schema and may propose, but does not usually decide, its structure.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-5','pt-dbms-sql-1-application-developer','Why does the notes recommend that a Developer''s application should connect to the database using a limited-privilege account rather than a DBA-level account?','["So that a bug or breach in the application is contained to only what the app legitimately needs, rather than exposing the whole database", "Because limited-privilege accounts always run faster than DBA accounts", "Because DBA-level accounts cannot be used by application code under any circumstances", "Because this is required only for NoSQL databases"]'::jsonb,0,'The notes explain this exact reasoning: limiting the blast radius of a compromised or buggy application account.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-6','pt-dbms-sql-1-application-developer','What happens if a multi-table operation, like inserting a grade and updating a GPA, is not wrapped in a single transaction, according to the notes?','["An application crash between the two steps can leave the database in an inconsistent state, with only part of the update applied", "Nothing; the DBMS automatically wraps every statement pair in a transaction regardless of the application code", "The operation becomes faster because there is less overhead", "The Designer''s schema becomes invalid"]'::jsonb,0,'The notes explicitly describe this exact risk under ''ignoring transaction boundaries'' — a crash mid-operation leaves inconsistent data.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-7','pt-dbms-sql-1-application-developer','A Developer writes: `"SELECT * FROM students WHERE name = ''" + userInput + "''"` directly in application code. What specific vulnerability does this create, per the notes?','["SQL injection, because raw user input is concatenated directly into the query string", "A crash-recovery failure, because the transaction manager cannot parse string concatenation", "A metadata drift issue, because the schema''s catalog becomes outdated", "A buffer pool eviction problem, because the query is too long"]'::jsonb,0,'The notes name this exact code pattern as the classic SQL injection mistake specific to the Application Developer role.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-application-developer-8','pt-dbms-sql-1-application-developer','How does the Application Developer role differ from ordinary use of the interface?','["The developer implements the interface and trusted operations; ordinary users perform tasks through the provided facilities", "Every ordinary user must own all database tables", "Developers and users always have identical technical privileges", "An interface automatically makes every database action authorized"]'::jsonb,0,'The responsibilities differ. Interfaces may hide SQL or deliberately expose approved reporting; neither arrangement removes the need for appropriate authorization.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-1-9','pt-dbms-sql-1-application-developer','Does using an ORM prove that every database operation is authorized?','["Yes; every generated query is automatically permitted", "No; authorization and transaction behavior still require explicit design and verification", "Yes; object mapping replaces record ownership checks", "No; ORMs can never query relational databases"]'::jsonb,1,'An ORM maps application work to database operations. It does not independently establish the caller''s authority.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-1-10','pt-dbms-sql-1-application-developer','Does parameter binding make unrestricted input safe as an SQL column name?','["Yes; every bound string becomes an approved field", "Yes; it grants permission to alter the schema", "No; value binding and selecting approved identifiers are different responsibilities", "No; a parameterized value must always be an integer"]'::jsonb,2,'Dynamic identifiers require a verified mapping or allowlist. Binding data values is a separate mechanism.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-1','pt-dbx2-application-developer-application','A student changes a URL identifier to request another student''s restricted grades. What must enforce the boundary?','["The trusted server or database authorization mechanism", "Only the absence of an edit button", "Only the spelling of the URL", "A promise that users will not edit requests"]'::jsonb,0,'The caller can bypass the interface. The trusted operation must check the actual actor and records.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-2','pt-dbx2-application-developer-application','A student name contains an apostrophe. Which query-construction approach handles it as a value?','["The supported driver''s parameter-binding facility", "Raw concatenation into quoted SQL", "Removing every punctuation character and assuming safety", "Giving the application administrative privileges"]'::jsonb,0,'Binding values separates data from statement syntax and avoids ordinary quoting mistakes as well as injection paths.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-3','pt-dbx2-application-developer-application','A programmer binds a student identifier correctly but forgets to check ownership. What remains at risk?','["Only whether SQL keywords are uppercase", "Unauthorized access to a correctly parameterized record lookup", "No security property, because binding grants authority", "Whether the parameter must become a table name"]'::jsonb,1,'Injection prevention does not decide which records an authenticated user may access.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-4','pt-dbx2-application-developer-application','A stored grade commits but its maintained summary does not update after a crash. What should be reviewed?','["Only the label on the submit button", "Whether all records should be copied into another uncoordinated file", "A claim that every separate statement is automatically one transaction", "The invariant and transaction boundary covering the related changes"]'::jsonb,3,'If the two representations must change together, the actual grouping and failure behavior need appropriate guarantees.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-5','pt-dbx2-application-developer-application','A workflow includes a local database write and an external service call. What does a local transaction alone not prove?','["That local statements can be grouped", "That uncommitted local changes can be handled by the database", "That the application needs to inspect failures", "Atomic completion across both independent systems"]'::jsonb,3,'A local transaction does not automatically coordinate an external system''s commit or rollback.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-6','pt-dbx2-application-developer-application','A query finds no matching student record. What should the application avoid assuming?','["That the result shape matters", "That every empty result is necessarily a network failure", "That missing data can be represented explicitly", "That a successful query may return no rows"]'::jsonb,1,'An empty result is a semantic outcome distinct from connection or query failure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-7','pt-dbx2-application-developer-application','A database driver returns a detailed internal error. What is appropriate handling?','["Display all private credentials in the interface", "Provide a suitable user response and bounded authorized diagnostics without secrets", "Report success regardless of the result", "Copy every private row into a public log"]'::jsonb,1,'User-facing messages and diagnostic evidence have different audiences and privacy requirements.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-8','pt-dbx2-application-developer-application','A schema change affects a website table also read by a mobile client. What should the developer inspect?','["Only the current browser tab", "Only whether one new query compiles", "The shared contract and all relevant callers before changing it", "An assumption that mobile cannot use the same database"]'::jsonb,2,'A schema is a shared interface. Compatibility requires checking actual consumers.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-9','pt-dbx2-application-developer-application','An application function calls a method named transaction. What further evidence is needed?','["That allowed, failed, and concurrent behavior preserves the intended invariant", "Nothing; the method name proves every guarantee", "Only a screenshot of the database product logo", "Proof that every query uses SELECT *"]'::jsonb,0,'The behavior of the actual boundary matters more than the name of an abstraction.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-application-developer-2-10','pt-dbx2-application-developer-application','An interface deliberately supports approved analyst queries. Does that contradict the developer''s role?','["Yes; every user interface must permanently hide every SQL capability", "Yes; analysts must become administrators", "No; the interface should fit the authorized task and its access rules", "No; approved reporting removes the need for authorization"]'::jsonb,2,'Some interfaces hide SQL, while others expose controlled reporting. The developer implements the appropriate task and trusted boundaries.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
