select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-4-relational-model/attribute' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'attribute'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'attribute'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('ccf57552c1988cf38c79ba3e927fdfad','1cac66425f0e9e78d57cc7be63606439')) then raise exception 'Notes changed since seed; review before applying: %', 'attribute'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-attribute' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'attribute'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-attribute' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'attribute'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-4-attribute','pt-dbms-sql-4-attribute-application')) then raise exception 'Extra topic tests require manual integration: %', 'attribute'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-attribute-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'attribute'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "An attribute role is different from its value and implementation type", "description": "Each row connects a schema role to an example value and a validity rule; shared integer storage does not make the roles equivalent.", "columns": ["Attribute", "Example value", "Representation", "Meaning or restriction"], "rows": [["student_id", "17", "INT", "Student identity; enforce uniqueness"], ["advisor_id", "42", "INT", "Advisor reference; needs its own relationship rule"], ["credits", "4", "INT", "Course workload; enforce the permitted range"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'attribute'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "An attribute role is different from its value and implementation type", "description": "Each row connects a schema role to an example value and a validity rule; shared integer storage does not make the roles equivalent.", "columns": ["Attribute", "Example value", "Representation", "Meaning or restriction"], "rows": [["student_id", "17", "INT", "Student identity; enforce uniqueness"], ["advisor_id", "42", "INT", "Advisor reference; needs its own relationship rule"], ["credits", "4", "INT", "Course workload; enforce the permitted range"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "An attribute role is different from its value and implementation type", "description": "Each row connects a schema role to an example value and a validity rule; shared integer storage does not make the roles equivalent.", "columns": ["Attribute", "Example value", "Representation", "Meaning or restriction"], "rows": [["student_id", "17", "INT", "Student identity; enforce uniqueness"], ["advisor_id", "42", "INT", "Advisor reference; needs its own relationship rule"], ["credits", "4", "INT", "Course workload; enforce the permitted range"]]}]'::jsonb;
