if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-attribute-1' and (question_text,options,correct_index,explanation) is distinct from ('What is an attribute in the relational model?','["A single row of data", "A named column of a relation schema, bound to a domain of legal values", "The total number of rows in a relation", "A synonym for ''relation''"]'::jsonb,1,'An attribute is a named property/column of the schema, not a data value or a row.') and (question_text,options,correct_index,explanation) is distinct from ('What is an attribute in the relational model?','["A single row of data", "A named column of a relation schema, bound to a domain of legal values", "The total number of rows in a relation", "A synonym for ''relation''"]'::jsonb,1,'An attribute is a named property/column of the schema, not a data value or a row.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-attribute-1'; end if;
