if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-attribute-3' and (question_text,options,correct_index,explanation) is distinct from ('In the tuple (3, Meera, CS, 9.1), what role does ''gpa'' play with respect to the value 9.1?','["''gpa'' is the tuple and 9.1 is the attribute", "''gpa'' is the attribute name that holds the value 9.1 in this tuple", "''gpa'' and 9.1 are both attributes", "''gpa'' is a domain and 9.1 is a relation"]'::jsonb,1,'The attribute ''gpa'' is the label; 9.1 is the actual value that attribute takes in this particular tuple.') and (question_text,options,correct_index,explanation) is distinct from ('In the tuple (3, Meera, CS, 9.1), what role does ''gpa'' play with respect to the value 9.1?','["''gpa'' is the tuple and 9.1 is the attribute", "''gpa'' is the attribute name that holds the value 9.1 in this tuple", "''gpa'' and 9.1 are both attributes", "''gpa'' is a domain and 9.1 is a relation"]'::jsonb,1,'The attribute ''gpa'' is the label; 9.1 is the actual value that attribute takes in this particular tuple.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-attribute-3'; end if;
