if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-attribute-4' and (question_text,options,correct_index,explanation) is distinct from ('Which best distinguishes an Attribute from a Domain?','["An attribute is the named role/column; a domain is the pool of legal values it may take", "A domain is the row; an attribute is the table", "They are identical concepts with different names", "An attribute always has a larger set of values than its domain"]'::jsonb,0,'The attribute names a column; the domain defines what values are legally allowed for that column.') and (question_text,options,correct_index,explanation) is distinct from ('Which best distinguishes an Attribute from a Domain?','["An attribute is the named role/column; a domain is the pool of legal values it may take", "A domain is the row; an attribute is the table", "They are identical concepts with different names", "An attribute always has a larger set of values than its domain"]'::jsonb,0,'The attribute names a column; the domain defines what values are legally allowed for that column.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-attribute-4'; end if;
