if exists(select 1 from public.test_questions where id='pt-dbms-sql-6-attributes-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('Why might Programme be an entity rather than copied text?','["Every short string must be an entity", "All descriptive attributes require new tables", "It can have an independent catalogue identity, properties and relationships", "Text cannot be stored in a relation"]'::jsonb,2,'The lifecycle and relationships can justify a separate entity.') and (question_text,options,correct_index,explanation) is distinct from ('Why might Programme be an entity rather than copied text?','["Every short string must be an entity", "All descriptive attributes require new tables", "It can have an independent catalogue identity, properties and relationships", "Text cannot be stored in a relation"]'::jsonb,2,'The lifecycle and relationships can justify a separate entity.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-6-attributes-application-new-9'; end if;
