update public.learning_topics set short_description='Classify ER attributes by meaning, structure, multiplicity and derivation, then map descriptive roles to consistent SQL projections and relationship facts.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Classify ER attributes by meaning, structure, multiplicity and derivation, then map descriptive roles to consistent SQL projections and relationship facts.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Attributes.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-attributes' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-attributes-application','MCQ Test 2',category,10,10,'Application and scenarios for Attributes.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-attributes' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-1','pt-dbms-sql-6-attributes','What is an attribute in the ER model?','["A relationship between two entity sets", "A property or characteristic that describes an entity (or relationship)", "A rectangle in an ER diagram", "A synonym for entity set"]'::jsonb,1,'Attributes are the descriptive details attached to entities (and relationships), such as Name or CGPA for a Student.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-2','pt-dbms-sql-6-attributes','In the stated model where Course and Department are entity types and Enrollment is a relationship, which choice is a descriptive Student attribute?','["Enrollment", "Course", "Date_of_Birth", "Department"]'::jsonb,2,'Date_of_Birth is a descriptive property of a Student entity, unlike Course/Department/Enrollment which are separate entities/relationships.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-3','pt-dbms-sql-6-attributes','What is the ''domain'' of an attribute?','["The physical table it is stored in", "The set of legal/permitted values the attribute may take", "Another name for the primary key", "The entity set it belongs to"]'::jsonb,1,'The domain defines the valid range or set of values, e.g., CGPA between 0.0 and 10.0.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-4','pt-dbms-sql-6-attributes','Can attributes be attached to a relationship, not just to an entity?','["No, only entities can have attributes", "Yes — e.g., Grade and Enrollment_Date logically describe the Enrollment relationship between Student and Course", "Only weak entities'' relationships can have attributes", "Only recursive relationships can have attributes"]'::jsonb,1,'Relationships can carry their own descriptive attributes, distinct from the attributes of the entities they connect.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-5','pt-dbms-sql-6-attributes','When the model permits an absent optional phone and maps it to a nullable SQL column, how can unknown phone information be represented?','["The attribute is deleted from the entity set", "As NULL for that entity''s value of that attribute", "As the value zero", "The entity is deleted"]'::jsonb,1,'A permitted NULL represents the defined absence; it does not erase the attribute role. Required inputs have a separate policy.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-6','pt-dbms-sql-6-attributes','Which of these is the correct general relationship between ''Attributes'' and its subtypes (simple, composite, derived, etc.)?','["They are unrelated concepts", "''Attributes'' is the umbrella category; simple/composite, single/multi-valued, and stored/derived are classification dimensions within it", "Only composite attributes are real attributes; the rest are a misnomer", "Derived attributes are not attributes at all"]'::jsonb,1,'All these subtypes classify different characteristics of the general concept ''attribute''.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-7','pt-dbms-sql-6-attributes','Why can two entities of the same entity set have different attribute values?','["Because each entity is a distinct occurrence, and attributes hold instance-specific values drawn from the same defined set of attributes", "Because entity sets allow different attribute names per entity", "Because attributes are randomly regenerated", "This is not possible; all entities of a set must share identical values"]'::jsonb,0,'The entity set defines which attributes exist; each entity instance supplies its own value for each.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-attributes-8','pt-dbms-sql-6-attributes','Which statement is FALSE about attributes?','["Every attribute value must fall within the attribute''s defined domain", "Attributes can only exist on strong entities, never on weak entities or relationships", "An attribute may be NULL if the value is unknown", "Attributes describe properties of entities or relationships"]'::jsonb,1,'Weak entities and relationships can also have attributes — this restriction is false.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-attributes-new-9','pt-dbms-sql-6-attributes','Where does the grade for one student-course attempt belong?','["As one universal student grade for every course", "With that assessment or enrollment occurrence", "As the course title", "As the programme identifier"]'::jsonb,1,'Property ownership follows the fact grain.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
