if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-buffer-manager-2' and (question_text,options,correct_index,explanation) is distinct from ('What happens on a ''cache hit'' in the Buffer Manager?','["The requested page is already in the buffer pool and is returned immediately with no disk access", "The Storage Manager must always be contacted regardless", "The page is permanently deleted from memory", "The Transaction Manager rolls back the current query"]'::jsonb,0,'The notes describe a cache hit as returning an already-cached page immediately, with no disk access needed.') and (question_text,options,correct_index,explanation) is distinct from ('What happens on a ''cache hit'' in the Buffer Manager?','["The valid requested page can be served without that new persistent fetch, while other work or waits may remain", "The whole request is guaranteed to finish with zero latency", "Every page in the database becomes cached automatically", "All permission checks are eliminated"]'::jsonb,0,'A hit concerns one relevant page access, not a guarantee about all work in the complete query.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-buffer-manager-2'; end if;
