insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-1','pt-dbms-sql-1-buffer-manager','What is the core purpose of the Buffer Manager?','["To cache disk pages in memory (the buffer pool) so frequently accessed data can be served from RAM instead of slow disk I/O", "To parse and optimize SQL statements", "To enforce foreign-key constraints between tables", "To authenticate database user accounts"]'::jsonb,0,'The notes define the Buffer Manager''s purpose as caching disk pages in memory to avoid slow disk I/O.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-2','pt-dbms-sql-1-buffer-manager','What happens on a ''cache hit'' in the Buffer Manager?','["The valid requested page can be served without that new persistent fetch, while other work or waits may remain", "The whole request is guaranteed to finish with zero latency", "Every page in the database becomes cached automatically", "All permission checks are eliminated"]'::jsonb,0,'A hit concerns one relevant page access, not a guarantee about all work in the complete query.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-3','pt-dbms-sql-1-buffer-manager','Which replacement policy is given as an example of how the Buffer Manager decides which cached page to evict when the pool is full?','["LRU (Least Recently Used)", "FIFO ordering of user logins", "Alphabetical order of table names", "Random selection of the DBA''s choice each morning"]'::jsonb,0,'The notes name LRU (or a clock algorithm) as an example replacement policy for evicting pages from a full buffer pool.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-4','pt-dbms-sql-1-buffer-manager','Why can a small, repeatedly accessed departments table be a useful buffer-reuse candidate without guaranteeing permanent residency?','["Its working set can be small and frequently revisited, but policy and competing pressure still matter", "Every small table is pinned forever by definition", "Table names determine permanent cache residency", "All queries stop reading storage once the table is cached"]'::jsonb,0,'Repeated access and fit can favor reuse. Actual residency depends on the workload and implementation.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-5','pt-dbms-sql-1-buffer-manager','What is ''thrashing'' as described in the notes?','["Pages being repeatedly evicted from an undersized buffer pool and then immediately re-read from disk", "A type of SQL injection attack", "A method for compressing dirty pages before writing them to disk", "The process of renaming a table while it is being queried"]'::jsonb,0,'The notes define thrashing exactly this way: repeated eviction and re-reading of pages because the pool is too small for the working set.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-6','pt-dbms-sql-1-buffer-manager','How can a single large, unindexed report query over a huge table affect other users'' queries running at the same time, per the notes?','["It can create cache pressure and displace useful pages, depending on workload and replacement protections", "It always evicts every useful page in every engine", "It has no possible interaction with any other work", "It automatically proves every query is unauthorized"]'::jsonb,0,'Large accesses can affect shared memory behavior, but products can use scan-resistant policies and the actual effect needs evidence.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-7','pt-dbms-sql-1-buffer-manager','Why does dirty-page handling need coordination with transaction, storage, and recovery facilities?','["Buffered modifications are not necessarily persisted yet; log ordering and the other durability conditions must be coordinated", "A dirty page is always already durable", "Logging alone proves survival of every possible failure", "Every cache page is a complete independent backup"]'::jsonb,0,'Write-ahead logging can support recovery, but acknowledgement settings, storage behavior and the failure assumptions also matter.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-buffer-manager-8','pt-dbms-sql-1-buffer-manager','A DBA notices that increasing buffer pool memory by a modest amount dramatically improves performance on a workload that was previously very slow. What does the notes suggest was likely happening before the change?','["Previous cache pressure or thrashing is a plausible cause to test against workload, cache and I/O observations", "A faster request alone proves every aspect of thrashing", "Every larger buffer setting is correct for every host", "No measurements are needed after any memory change"]'::jsonb,0,'A performance change can suggest a hypothesis without proving it. Compare the relevant conditions and measurements.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-1-9','pt-dbms-sql-1-buffer-manager','Is a database page buffer the same thing as a cached formatted API response?','["Yes; every page is already a complete web response", "Yes; page residency proves every response is current and authorized", "No; they cache different representations and have different correctness responsibilities", "No; applications can never use caches"]'::jsonb,2,'A page pool manages physical database content. An application cache can hold a higher-level computed result.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-1-10','pt-dbms-sql-1-buffer-manager','Does a database buffer miss by itself specify the final storage-device latency?','["Yes; every miss has identical latency", "Yes; all hosts have the same storage device", "No; misses can never involve I/O", "No; the observation concerns that buffer layer and other layers or work may matter"]'::jsonb,3,'Define the cache layer and workload before making a performance claim.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-1','pt-dbx2-buffer-manager-application','The required valid page is in the buffer pool. What does that hit establish?','["That every query finishes instantly", "That every user is authorized for the page", "That all other required pages are present", "That this access can avoid fetching that page again from persistent storage"]'::jsonb,3,'A hit is about a particular access; the complete request can still have other work or waits.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-2','pt-dbx2-buffer-manager-application','A frequently read small departments table fits in the working memory. What is a reasonable explanation?','["Its pages are guaranteed never to be replaced", "Its pages can be useful reuse candidates, subject to policy and pressure", "It proves the whole database fits in RAM", "It needs no visibility or access rules"]'::jsonb,1,'Repeated use and a small working set can favor reuse without guaranteeing permanent residency.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-3','pt-dbx2-buffer-manager-application','A page has unpersisted modifications relative to its stored representation. What must replacement respect?','["A rule that the page is necessarily corrupt", "The required persistence and recovery handling for those changes", "A rule that all dirty pages can be discarded immediately", "The assumption that every modification already has durable commit status"]'::jsonb,1,'Dirty state adds correctness constraints to memory replacement.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-4','pt-dbx2-buffer-manager-application','Which pattern is consistent with thrashing?','["Useful pages are repeatedly evicted and reloaded soon afterward", "The whole workload stays in memory with no relevant replacement", "An index is named differently", "Every client has the same account title"]'::jsonb,0,'Thrashing concerns ineffective retention of the working set and repeated fetch work.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-5','pt-dbx2-buffer-manager-application','The database is larger than RAM. Does that fact alone prove thrashing?','["Yes; total size alone diagnoses every query", "Yes; every page must be read for every request", "No; buffer pools never have finite capacity", "No; the workload may repeatedly use only a small part of the data"]'::jsonb,3,'The relevant working set and access pattern determine whether replacement is harming useful reuse.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-6','pt-dbx2-buffer-manager-application','A large scan runs alongside common short lookups. What should be investigated?','["A guarantee that every hot page must be evicted", "A guarantee that no shared workload can ever be affected", "Whether it creates cache pressure or displaces useful pages under the actual policy", "Only the report''s title length"]'::jsonb,2,'Competing access patterns can matter, but scan-resistance and other product behavior affect the outcome.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-7','pt-dbx2-buffer-manager-application','Increasing the pool coincides with better performance. What is justified?','["Investigate whether previous cache pressure explains the measured change", "Declare thrashing proven without any other evidence", "Assume every unrelated bottleneck disappeared", "Use the same setting for every deployment"]'::jsonb,0,'A plausible cause still needs evidence about comparable workload conditions, cache behavior and I/O.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-8','pt-dbx2-buffer-manager-application','Required recovery logging has not reached its necessary durable state. What must not be inferred from a dirty page in RAM?','["That an in-memory representation can exist", "That memory and persistent storage are different", "That the intended durable commit guarantee is already established", "That coordinated recovery protocols can matter"]'::jsonb,2,'Buffer presence is not durable persistence. Logging, acknowledgement, storage and failure assumptions need to align.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-9','pt-dbx2-buffer-manager-application','A process restart loses its page memory. What does recovery rely on?','["The vanished RAM pages acting as a permanent backup", "Persistent state and recovery information under the actual configured guarantees", "A claim that caches are equivalent to backups", "Automatically invented copies of every missing value"]'::jsonb,1,'Caching improves access behavior; recoverability requires appropriate persistent information and procedures.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-buffer-manager-2-10','pt-dbx2-buffer-manager-application','Which buffer-pool explanation is strongest?','["State the observed layer and workload, identify replacement/page state, and consider other required work", "Promise zero query latency whenever one page hits", "Infer universal settings from one faster request", "Treat every dirty page as corruption"]'::jsonb,0,'A useful explanation connects memory reuse, correctness constraints, and measured context without unsupported guarantees.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
