if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-business-constraints-1' and (question_text,options,correct_index,explanation) is distinct from ('What are business constraints?','["Rules automatically generated by the SQL standard", "Integrity rules coming from the real-world domain/business rather than the structural relational model", "A synonym for foreign key constraints", "Constraints that only apply to financial data"]'::jsonb,1,'Business constraints encode domain-specific rules like ''salary must be positive,'' not structural rules like uniqueness.') and (question_text,options,correct_index,explanation) is distinct from ('What are business constraints?','["Rules automatically generated by the SQL standard", "Integrity rules coming from the real-world domain/business rather than the structural relational model", "A synonym for foreign key constraints", "Constraints that only apply to financial data"]'::jsonb,1,'Business policies can require ranges, relationships, uniqueness or other invariants; the domain supplies the particular requirement.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-business-constraints-1'; end if;
