if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-business-constraints-2' and (question_text,options,correct_index,explanation) is distinct from ('Which SQL mechanism is primarily used to enforce single-row business constraints?','["FOREIGN KEY", "CHECK", "UNIQUE", "PRIMARY KEY"]'::jsonb,1,'CHECK constraints directly express arbitrary boolean conditions a row''s data must satisfy.') and (question_text,options,correct_index,explanation) is distinct from ('Which SQL mechanism is primarily used to enforce single-row business constraints?','["FOREIGN KEY", "An enforced CHECK for supported row-local predicates, with separate required-value declarations where needed", "UNIQUE", "PRIMARY KEY"]'::jsonb,1,'CHECK has supported-expression limits and an absence policy; it is not an unrestricted arbitrary-code facility.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-business-constraints-2'; end if;
