if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-business-constraints-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is `CHECK (salary > 0)` considered a business constraint rather than a structural one?','["Because CHECK constraints are always structural", "Because nothing about the relational model itself requires salary to be positive \u2014 this rule comes from real-world business logic", "Because it references another table", "Because it involves a NULL comparison"]'::jsonb,1,'The rule reflects a domain fact (salaries can''t be negative), not a requirement of relational theory.') and (question_text,options,correct_index,explanation) is distinct from ('Why is `CHECK (salary > 0)` considered a business constraint rather than a structural one?','["Because CHECK constraints are always structural", "Because nothing about the relational model itself requires salary to be positive \u2014 this rule comes from real-world business logic", "Because it references another table", "Because it involves a NULL comparison"]'::jsonb,1,'Positivity is an explicit policy in this example, not an inherent rule of relational theory or every possible compensation model.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-business-constraints-3'; end if;
