if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-business-constraints-4' and (question_text,options,correct_index,explanation) is distinct from ('Why might a CHECK constraint need to be revisited over time more often than a PRIMARY KEY constraint?','["CHECK constraints expire automatically after a year", "Business rules change as the actual business changes, while structural integrity rules like entity integrity are stable and timeless", "PRIMARY KEY constraints are also frequently revised for the same reasons", "CHECK constraints are deprecated and always being phased out"]'::jsonb,1,'Business logic evolves with real-world policy/regulation changes, unlike the timeless structural rules of the relational model.') and (question_text,options,correct_index,explanation) is distinct from ('Why might a CHECK constraint need to be revisited over time more often than a PRIMARY KEY constraint?','["CHECK constraints expire automatically after a year", "Policy can evolve, so existing facts, exceptions and callers must be reviewed before changing the enforced contract", "PRIMARY KEY constraints are also frequently revised for the same reasons", "CHECK constraints are deprecated and always being phased out"]'::jsonb,1,'Business rules can change, and particular schema identities can also evolve; neither should be revised without dependency review.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-business-constraints-4'; end if;
