if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-business-constraints-5' and (question_text,options,correct_index,explanation) is distinct from ('Can a simple single-table CHECK constraint enforce a rule like ''the sum of an order''s line items must equal the order''s total''?','["Yes, easily, with a single CHECK clause", "Generally no \u2014 multi-row/multi-table rules like this typically require triggers or application-level enforcement instead", "Only if the order has exactly one line item", "CHECK constraints can only be used on numeric columns"]'::jsonb,1,'CHECK constraints evaluate a single row''s own columns; enforcing a rule that spans multiple rows needs a trigger or equivalent mechanism.') and (question_text,options,correct_index,explanation) is distinct from ('Can a simple single-table CHECK constraint enforce a rule like ''the sum of an order''s line items must equal the order''s total''?','["Yes, easily, with a single CHECK clause", "No in the stated MySQL row-CHECK model; the wider invariant needs a supported trusted mechanism and transaction/concurrency design", "Only if the order has exactly one line item", "CHECK constraints can only be used on numeric columns"]'::jsonb,1,'A multi-row total is not enforced by a simple row predicate or a client-side preliminary query.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-business-constraints-5'; end if;
