update public.learning_topics set short_description='Translate explicit campus policies into scoped validity rules, distinguish row checks from aggregate invariants, and test both allowed boundaries and rejected writes.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Translate explicit campus policies into scoped validity rules, distinguish row checks from aggregate invariants, and test both allowed boundaries and rejected writes.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Business Constraints.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-5-business-constraints' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-5-business-constraints-application','MCQ Test 2',category,10,10,'Application and scenarios for Business Constraints.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-5-business-constraints' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-1','pt-dbms-sql-5-business-constraints','What are business constraints?','["Rules automatically generated by the SQL standard", "Integrity rules coming from the real-world domain/business rather than the structural relational model", "A synonym for foreign key constraints", "Constraints that only apply to financial data"]'::jsonb,1,'Business policies can require ranges, relationships, uniqueness or other invariants; the domain supplies the particular requirement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-2','pt-dbms-sql-5-business-constraints','Which SQL mechanism is primarily used to enforce single-row business constraints?','["FOREIGN KEY", "An enforced CHECK for supported row-local predicates, with separate required-value declarations where needed", "UNIQUE", "PRIMARY KEY"]'::jsonb,1,'CHECK has supported-expression limits and an absence policy; it is not an unrestricted arbitrary-code facility.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-3','pt-dbms-sql-5-business-constraints','Why is `CHECK (salary > 0)` considered a business constraint rather than a structural one?','["Because CHECK constraints are always structural", "Because nothing about the relational model itself requires salary to be positive — this rule comes from real-world business logic", "Because it references another table", "Because it involves a NULL comparison"]'::jsonb,1,'Positivity is an explicit policy in this example, not an inherent rule of relational theory or every possible compensation model.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-4','pt-dbms-sql-5-business-constraints','Why might a CHECK constraint need to be revisited over time more often than a PRIMARY KEY constraint?','["CHECK constraints expire automatically after a year", "Policy can evolve, so existing facts, exceptions and callers must be reviewed before changing the enforced contract", "PRIMARY KEY constraints are also frequently revised for the same reasons", "CHECK constraints are deprecated and always being phased out"]'::jsonb,1,'Business rules can change, and particular schema identities can also evolve; neither should be revised without dependency review.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-5','pt-dbms-sql-5-business-constraints','Can a simple single-table CHECK constraint enforce a rule like ''the sum of an order''s line items must equal the order''s total''?','["Yes, easily, with a single CHECK clause", "No in the stated MySQL row-CHECK model; the wider invariant needs a supported trusted mechanism and transaction/concurrency design", "Only if the order has exactly one line item", "CHECK constraints can only be used on numeric columns"]'::jsonb,1,'A multi-row total is not enforced by a simple row predicate or a client-side preliminary query.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-6','pt-dbms-sql-5-business-constraints','What is a real risk of an overly strict CHECK constraint?','["It has no risk if written correctly", "It can block legitimate real-world edge cases the designer didn''t originally anticipate", "CHECK constraints can never be too strict", "It will automatically loosen itself over time"]'::jsonb,1,'A rule that seemed universally true at design time can turn out to have legitimate exceptions later, requiring the constraint to be revisited.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-7','pt-dbms-sql-5-business-constraints','Why is relying only on application code (and not a database CHECK constraint) to enforce a business rule considered risky?','["Application code is always slower than CHECK constraints", "Every application/service that writes to the table would need to correctly duplicate and maintain the same validation logic, and any one that misses it can insert bad data", "Application code cannot access business rules at all", "This is not actually risky in any way"]'::jsonb,1,'A database-level constraint is enforced centrally for every writer, whereas application-only validation must be correctly replicated everywhere data is written.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-business-constraints-8','pt-dbms-sql-5-business-constraints','Which of these is a structural (relational-model) rule rather than a business constraint?','["Salary must be positive", "Entity integrity (primary key uniqueness and non-nullability)", "Termination date must be after hire date", "A discount code must not exceed 50%"]'::jsonb,1,'Entity integrity is a foundational relational-model rule, independent of any specific business domain — unlike the other, domain-specific examples.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-new-9','pt-dbms-sql-5-business-constraints','What is missing from the requirement bookings must be valid?','["Only a shorter table name", "Concrete allowed states, boundaries and scope", "Only a display colour", "Only a font choice"]'::jsonb,1,'The policy must be precise before implementation.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-new-10','pt-dbms-sql-5-business-constraints','Can end > start alone enforce an interval entirely inside the stated day?','["Yes; order implies every bound", "Only if sorted", "No; range boundaries are also needed", "Only if identifiers are unique"]'::jsonb,2,'Ordering and allowed range are distinct ingredients.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-application-new-1','pt-dbms-sql-5-business-constraints-application','For the stated positive single-day interval policy, is start=end allowed?','["Yes; every endpoint equality is valid", "Only if id is odd", "No; the duration is zero", "Only if no other bookings exist"]'::jsonb,2,'The contract requires a strict positive duration.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-application-new-2','pt-dbms-sql-5-business-constraints-application','Why does a required booking need NOT NULL as well as its MySQL CHECK?','["CHECK always treats NULL as zero", "NOT NULL generates the end value", "Every missing value is a separate row", "UNKNOWN CHECK results can be accepted"]'::jsonb,3,'Required inputs need an explicit absence policy.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-application-new-3','pt-dbms-sql-5-business-constraints-application','Does a row quantity range ensure summed reservations fit course capacity?','["No; aggregate capacity spans multiple facts", "Yes; every row validates the total", "Only if each row is indexed", "Only if a label says capacity"]'::jsonb,0,'The global invariant needs a mechanism appropriate to its scope.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-application-new-4','pt-dbms-sql-5-business-constraints-application','Why can two preliminary availability checks both pass yet lead to overbooking?','["SELECT always adds seats", "Concurrent writes can change the combined state before acceptance", "Only empty courses have concurrency", "The screen order changes capacity"]'::jsonb,1,'The trusted accepted operation must protect the invariant under concurrency.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-business-constraints-application-new-5','pt-dbms-sql-5-business-constraints-application','What should happen when overnight bookings become legitimate?','["Remove every check without replacement", "Claim all reversed intervals are valid", "Review the representation and policy before an authorized change", "Ignore existing callers"]'::jsonb,2,'A new legitimate case may require a different interval model.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
