if exists(select 1 from public.dsa_problems where learning_topic_id=topic_uuid and id not in ('cx-business-constraints-audit','cx-business-constraints-enforce')) then raise exception 'Existing coding problems require explicit integration: %', 'business-constraints'; end if;
if exists(select 1 from public.dsa_problems where (id='cx-business-constraints-audit' or slug='business-constraints-audit') and (id<>'cx-business-constraints-audit' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-business-constraints-audit'; end if;
if exists(select 1 from public.dsa_problems where id='cx-business-constraints-audit' and description is distinct from 'Return proposal_id for invalid single-day intervals: either endpoint missing, start_minute < 0, end_minute > 1440, or end_minute <= start_minute. Positive intervals within the day are valid.

**MySQL dialect.**

```sql
CREATE TABLE proposals (proposal_id INT PRIMARY KEY, start_minute INT NULL, end_minute INT NULL);
INSERT INTO proposals VALUES (1,0,1),(2,1439,1440),(3,10,10),(4,20,10),(5,-1,10),(6,10,1441),(7,NULL,10),(8,10,NULL);
```

**Required ordering:** Ascending proposal_id.

**Edge cases:**
- Equal endpoints are invalid.
- Both ends of the documented day support valid positive intervals.') then raise exception 'New coding ID already has other content: %', 'cx-business-constraints-audit'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-business-constraints-audit',null::text,'Audit single-day booking interval proposals','Easy','business-constraints-audit','Return proposal_id for invalid single-day intervals: either endpoint missing, start_minute < 0, end_minute > 1440, or end_minute <= start_minute. Positive intervals within the day are valid.

**MySQL dialect.**

```sql
CREATE TABLE proposals (proposal_id INT PRIMARY KEY, start_minute INT NULL, end_minute INT NULL);
INSERT INTO proposals VALUES (1,0,1),(2,1439,1440),(3,10,10),(4,20,10),(5,-1,10),(6,10,1441),(7,NULL,10),(8,10,NULL);
```

**Required ordering:** Ascending proposal_id.

**Edge cases:**
- Equal endpoints are invalid.
- Both ends of the documented day support valid positive intervals.','[{"input": "INSERT INTO proposals VALUES (1,0,1),(2,1439,1440),(3,10,10),(4,20,10),(5,-1,10),(6,10,1441),(7,NULL,10),(8,10,NULL);", "output": "proposal_id\n3\n4\n5\n6\n7\n8", "explanation": "The audit diagnoses the specified row-local rule only. It does not check overlap, room existence or caller authority."}]'::jsonb,'[{"seed_sql": "INSERT INTO proposals VALUES (1,0,1440),(2,100,101);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO proposals VALUES (2,1440,1440),(1,NULL,NULL);", "expected": "proposal_id\n1\n2", "hidden": true}]'::jsonb,'["Minute offsets describe one abstract day; overnight bookings are outside this exercise."]'::jsonb,'["Test missing endpoints explicitly.", "Combine the invalid conditions with OR."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The audit diagnoses the specified row-local rule only. It does not check overlap, room existence or caller authority.','{"sql": "SELECT proposal_id FROM proposals WHERE start_minute IS NULL OR end_minute IS NULL OR start_minute < 0 OR end_minute > 1440 OR end_minute <= start_minute ORDER BY proposal_id;"}'::jsonb,'The audit diagnoses the specified row-local rule only. It does not check overlap, room existence or caller authority.',array['sql'],'CREATE TABLE proposals (proposal_id INT PRIMARY KEY, start_minute INT NULL, end_minute INT NULL);','INSERT INTO proposals VALUES (1,0,1),(2,1439,1440),(3,10,10),(4,20,10),(5,-1,10),(6,10,1441),(7,NULL,10),(8,10,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-5-business-constraints' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-business-constraints-enforce' or slug='business-constraints-enforce') and (id<>'cx-business-constraints-enforce' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-business-constraints-enforce'; end if;
if exists(select 1 from public.dsa_problems where id='cx-business-constraints-enforce' and description is distinct from 'Add an enforced CHECK named valid_interval to bookings requiring start_minute >= 0, end_minute <= 1440 and end_minute > start_minute. Both endpoints are already NOT NULL. Return booking_id, start_minute and end_minute.

**MySQL dialect.**

```sql
CREATE TABLE bookings (booking_id INT PRIMARY KEY, start_minute INT NOT NULL, end_minute INT NOT NULL);
INSERT INTO bookings VALUES (1,0,1),(2,1439,1440),(3,100,200);
```

**Required ordering:** Ascending booking_id.

**Edge cases:**
- Negative starts, excessive ends and equal or reversed intervals must fail.
- A valid row updated to a zero-length interval must also fail.') then raise exception 'New coding ID already has other content: %', 'cx-business-constraints-enforce'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-business-constraints-enforce',null::text,'Enforce a positive bounded booking interval','Medium','business-constraints-enforce','Add an enforced CHECK named valid_interval to bookings requiring start_minute >= 0, end_minute <= 1440 and end_minute > start_minute. Both endpoints are already NOT NULL. Return booking_id, start_minute and end_minute.

**MySQL dialect.**

```sql
CREATE TABLE bookings (booking_id INT PRIMARY KEY, start_minute INT NOT NULL, end_minute INT NOT NULL);
INSERT INTO bookings VALUES (1,0,1),(2,1439,1440),(3,100,200);
```

**Required ordering:** Ascending booking_id.

**Edge cases:**
- Negative starts, excessive ends and equal or reversed intervals must fail.
- A valid row updated to a zero-length interval must also fail.','[{"input": "INSERT INTO bookings VALUES (1,0,1),(2,1439,1440),(3,100,200);", "output": "booking_id\tstart_minute\tend_minute\n1\t0\t1\n2\t1439\t1440\n3\t100\t200", "explanation": "The constraint enforces the deliberately defined single-row interval policy. Wider booking-system invariants need their own trusted design."}]'::jsonb,'[{"seed_sql": "INSERT INTO bookings VALUES (7,0,1440);", "expected": "booking_id\tstart_minute\tend_minute\n7\t0\t1440", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["Initial fixture intervals satisfy the proposed rule.", "No overlap, parent-reference or authorization guarantee is claimed."]'::jsonb,'["Use one supported CHECK combining all three requirements.", "Retain the separate required-value column declarations."]'::jsonb,'{"sql": "-- Add valid_interval and return the booking facts."}'::jsonb,'The constraint enforces the deliberately defined single-row interval policy. Wider booking-system invariants need their own trusted design.','{"sql": "ALTER TABLE bookings ADD CONSTRAINT valid_interval CHECK (start_minute >= 0 AND end_minute <= 1440 AND end_minute > start_minute);\nSELECT booking_id, start_minute, end_minute FROM bookings ORDER BY booking_id;"}'::jsonb,'The constraint enforces the deliberately defined single-row interval policy. Wider booking-system invariants need their own trusted design.',array['sql'],'CREATE TABLE bookings (booking_id INT PRIMARY KEY, start_minute INT NOT NULL, end_minute INT NOT NULL);','INSERT INTO bookings VALUES (1,0,1),(2,1439,1440),(3,100,200);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-5-business-constraints' on conflict(id) do nothing;
