update public.learning_topics set short_description='Find minimal identifying sets from explicit guarantees, distinguish minimal from minimum, and implement a composite student identity without rejecting valid reuse.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Find minimal identifying sets from explicit guarantees, distinguish minimal from minimum, and implement a composite student identity without rejecting valid reuse.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Candidate Key.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-5-candidate-key' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-5-candidate-key-application','MCQ Test 2',category,10,10,'Application and scenarios for Candidate Key.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-5-candidate-key' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-1','pt-dbms-sql-5-candidate-key','What distinguishes a candidate key from a general super key?','["A candidate key must be exactly one column", "A candidate key is a MINIMAL super key — no attribute can be removed without losing uniqueness", "A candidate key can never be chosen as the primary key", "There is no difference"]'::jsonb,1,'Candidate key adds the minimality requirement on top of the super key''s basic uniqueness requirement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-2','pt-dbms-sql-5-candidate-key','If {id} and {email} are the only guaranteed nonmissing minimal identifying sets, how many candidate keys are established?','["Zero", "Exactly one — you must pick just one", "Two — {id} and {email} are both separate candidate keys", "It depends on which one is declared PRIMARY KEY"]'::jsonb,2,'Both {id} and {email} are independently minimal and unique, so both qualify as candidate keys, regardless of which is later chosen as primary.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-3','pt-dbms-sql-5-candidate-key','What happens to candidate keys that are NOT chosen as the primary key?','["They cease to exist", "They remain valid candidate keys, often called alternate keys", "They automatically become foreign keys", "The database deletes those columns"]'::jsonb,1,'An unchosen candidate key doesn''t disappear — it''s simply referred to as an alternate key (topic 5.4).',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-4','pt-dbms-sql-5-candidate-key','Assuming {student_id, course_id} is guaranteed unique, what additional condition makes it a minimal candidate key?','["Both student_id and course_id must be unique on their own", "Neither student_id alone nor course_id alone can already be unique by itself", "The table must have no other columns", "Enrollments must have exactly two rows"]'::jsonb,1,'Minimality requires that no proper subset of the key (here, neither single column) is already sufficient for uniqueness.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-5','pt-dbms-sql-5-candidate-key','Which situation can motivate introducing a surrogate identifier for distinct records?','["A legal requirement", "The natural descriptive attributes do not reliably identify separate occurrences under the intended model", "A performance optimization with no relation to uniqueness", "A requirement that every table have exactly two candidate keys"]'::jsonb,1,'Surrogates can supply occurrence identity; stability and reference convenience can also motivate them.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-6','pt-dbms-sql-5-candidate-key','Is having multiple candidate keys in one table considered a design flaw?','["Yes, always", "No — it''s common and often desirable, e.g. an internal id plus a natural identifier like email or ISBN", "Only if there are more than 3", "Only for tables representing people"]'::jsonb,1,'Multiple legitimate ways to uniquely identify a row is normal and frequently useful, not a design problem.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-7','pt-dbms-sql-5-candidate-key','Which statement correctly relates candidate keys and super keys?','["All super keys are candidate keys", "All candidate keys are super keys, but only the minimal ones qualify as candidate keys", "Candidate keys and super keys are unrelated categories", "A table can have super keys but never candidate keys"]'::jsonb,1,'A candidate key is a minimal superkey: uniqueness alone does not establish minimality.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-candidate-key-8','pt-dbms-sql-5-candidate-key','Why might distinct event occurrences need an explicit identifier beyond their natural descriptive fields?','["This is mathematically impossible for any table", "Different occurrences can share all recorded descriptive values, so those values do not reliably identify an occurrence", "Because SQL forbids more than one candidate key", "Because the table has too few rows"]'::jsonb,1,'This is an occurrence-modeling issue. A strict duplicate-free relation still has its full heading as a superkey.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-new-9','pt-dbms-sql-5-candidate-key','Can a one-attribute candidate key coexist with a two-attribute candidate key?','["No; all candidate keys have equal size", "Yes; minimality is relative to subsets of each set", "Only if both contain the same identifier", "Only if the table has two rows"]'::jsonb,1,'Minimal does not mean globally minimum cardinality.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-new-10','pt-dbms-sql-5-candidate-key','Why is proving neither component is a key insufficient to prove the pair is a candidate key?','["Every pair is unique automatically", "Minimality replaces identification", "The pair must also be guaranteed to identify tuples", "Only SQL aliases can identify pairs"]'::jsonb,2,'Identification and minimality are separate requirements.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-1','pt-dbms-sql-5-candidate-key-application','Under A determines B, B determines A and C determines D in R(A,B,C,D), which pair has full closure?','["{A, B}", "{C, D}", "{A, C}", "{A, D}"]'::jsonb,2,'A reaches B and C reaches D, giving the full heading.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-2','pt-dbms-sql-5-candidate-key-application','Why is {A, B, C} nonminimal under those dependencies?','["C can always be removed", "It cannot determine D", "Three attributes can never identify", "Either A or B can be removed while retaining full closure"]'::jsonb,3,'A and B determine each other, making one redundant.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-3','pt-dbms-sql-5-candidate-key-application','Does finding candidate {A,C} justify skipping {B,C}?','["No; unrelated minimal identifying alternatives may exist", "Yes; only one candidate is allowed", "Only if names are short", "Yes; every key contains A"]'::jsonb,0,'One found candidate only prunes its own supersets.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-4','pt-dbms-sql-5-candidate-key-application','What does selecting a primary key do to other candidate keys?','["It deletes their attributes", "They remain alternate candidate keys", "It makes them nonunique", "It automatically makes them references"]'::jsonb,1,'Primary choice does not erase other guarantees.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-5','pt-dbms-sql-5-candidate-key-application','Which accepted fixture tests local-number reuse across campuses?','["NORTH,17 twice", "One row alone", "NORTH,17 and SOUTH,17", "Two identical full tuples"]'::jsonb,2,'The composite identity permits reuse of one component.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
