insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-7','pt-dbms-sql-5-candidate-key-application','Does a surrogate primary key remove a required institutional uniqueness rule?','["No; that rule needs its own enforcement", "Yes; every generated id verifies all business labels", "Only if SQL is declarative", "Only if the table is empty"]'::jsonb,0,'Internal identity and alternate business identity differ.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
