insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-candidate-key-application-new-9','pt-dbms-sql-5-candidate-key-application','What does a nullable UNIQUE declaration need before claiming a required classical identifier?','["Only a shorter column name", "Only ORDER BY", "A compatible nonmissing policy as well as uniqueness", "Only a generated display row number"]'::jsonb,2,'SQL optionality must match the identity contract.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
