if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-cardinality-ratio-4' and (question_text,options,correct_index,explanation) is distinct from ('Which correctly distinguishes cardinality from participation?','["They are the same concept described differently", "Cardinality is a maximum/structural limit on how many instances can be linked; participation is about whether linking is mandatory for every instance", "Participation only applies to M:N relationships", "Cardinality only applies to weak entities"]'::jsonb,1,'Cardinality answers ''how many can relate'', participation answers ''must every instance relate'' — independent, combinable properties.') and (question_text,options,correct_index,explanation) is distinct from ('Which correctly distinguishes cardinality from participation?','["They are the same concept described differently", "Cardinality is a maximum/structural limit on how many instances can be linked; participation is about whether linking is mandatory for every instance", "Participation only applies to M:N relationships", "Cardinality only applies to weak entities"]'::jsonb,1,'Cardinality answers ''how many can relate'', participation answers ''must every instance relate'' — independent, combinable properties.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-cardinality-ratio-4'; end if;
