if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-cardinality-ratio-5' and (question_text,options,correct_index,explanation) is distinct from ('Which correctly distinguishes cardinality from relationship degree?','["Degree counts entity instances; cardinality counts entity sets", "Cardinality counts how many entity instances can be linked (1, N, M); degree counts how many entity SETS participate in the relationship", "They are identical", "Degree only matters for 1:1 relationships"]'::jsonb,1,'Degree = structural count of entity sets (e.g., 2 for binary); cardinality = numeric limit on instances within that relationship.') and (question_text,options,correct_index,explanation) is distinct from ('Which correctly distinguishes cardinality from relationship degree?','["Degree counts entity instances; cardinality counts entity sets", "Cardinality ratio concerns permitted occurrence multiplicities; degree classifies the relationship\u2019s participating categories under the stated convention", "They are identical", "Degree only matters for 1:1 relationships"]'::jsonb,1,'Distinguish both from the current cardinality and degree of a mapped SQL relation.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-cardinality-ratio-5'; end if;
