insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-1','pt-dbms-sql-4-cardinality','What does the cardinality of a relation measure?','["The number of attributes in the schema", "The number of tuples (rows) currently in the relation", "The number of distinct relations in the database", "The number of foreign keys pointing to it"]'::jsonb,1,'Cardinality is the count of tuples (rows) currently present in the relation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-2','pt-dbms-sql-4-cardinality','If Students holds tuples for Asha, Ravi, Meera, and Karan, what is its current cardinality?','["1", "4", "It equals the degree", "It cannot be determined"]'::jsonb,1,'There are 4 tuples currently in the relation, so cardinality is 4.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-3','pt-dbms-sql-4-cardinality','After a 5th student, Priya, is admitted and inserted into Students, what happens to the relation''s degree?','["It increases by 1, to 5", "It stays exactly the same, since inserting a row never changes degree", "It becomes undefined", "It doubles"]'::jsonb,1,'Degree depends only on the number of attributes, which is unaffected by inserting a new row (which changes cardinality instead).',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-4','pt-dbms-sql-4-cardinality','If exactly one new tuple is successfully added, or exactly one existing tuple removed, which measurement changes while the schema stays fixed?','["Degree", "Cardinality", "Both change equally", "Neither changes"]'::jsonb,1,'The successful addition or removal changes tuple cardinality by one. Rejected inserts, duplicate set additions and no-match deletes need not change it.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-5','pt-dbms-sql-4-cardinality','Can a relation have cardinality 0 while still having a well-defined, non-zero degree?','["No, cardinality and degree must always be equal", "Yes — an empty table (e.g., right after CREATE TABLE) has cardinality 0 but a fixed, non-zero degree", "No, a relation with cardinality 0 has no schema", "Yes, but only if the primary key is NULL"]'::jsonb,1,'Degree and cardinality are independent measures; a freshly created empty table has 0 cardinality but its full degree from the schema.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-6','pt-dbms-sql-4-cardinality','For a strict relation over finite attribute domains, which expression bounds its cardinality before other constraints are considered?','["There is no upper bound at all", "It is bounded by the size of the Cartesian product of the attribute domains, |D1| x |D2| x ... x |Dn|", "It equals the degree", "It is always exactly 2^degree"]'::jsonb,1,'The finite Cartesian product contains all domain-compatible tuples. Keys and other constraints can reduce the maximum further.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-7','pt-dbms-sql-4-cardinality','In the pure mathematical relational model, does inserting an exact duplicate of an existing tuple increase cardinality?','["Yes, cardinality always increases by 1 on every insert attempt", "No — since a relation is a set, an exact duplicate tuple does not add a new element, so cardinality is unchanged", "Only if the primary key allows duplicates", "Cardinality decreases instead"]'::jsonb,1,'Because relations are sets, adding an already-present element does not change the set (though SQL without a uniqueness constraint would physically add a duplicate row).',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-cardinality-8','pt-dbms-sql-4-cardinality','The term ''cardinality'' used in ER-diagram relationship notation (e.g., one-to-many) refers to:','["The exact same concept as relation cardinality (row count)", "A related but distinct concept describing relationship multiplicity between entity sets, not a row count", "The degree of the relation", "A synonym for the primary key"]'::jsonb,1,'ER-diagram cardinality describes multiplicity of relationships (1:1, 1:N, M:N), which is a different, though related, use of the term from a relation''s row count.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
