update public.learning_topics set short_description='Understand all-pairs tuple combinations, distinguish intentional grids from missing join predicates, and reason about product size without inventing physical execution guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand all-pairs tuple combinations, distinguish intentional grids from missing join predicates, and reason about product size without inventing physical execution guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Cartesian Product.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-7-cartesian-product' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-7-cartesian-product-application','MCQ Test 2',category,10,10,'Application and scenarios for Cartesian Product.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-7-cartesian-product' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-1','pt-dbms-sql-7-cartesian-product','What does the Cartesian Product (×) of two relations produce?','["Only rows where a shared column matches", "Every possible combination of rows from both relations", "The rows common to both relations", "A single row combining aggregated data"]'::jsonb,1,'Cartesian Product pairs every row of one relation with every row of the other, with no filtering.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-2','pt-dbms-sql-7-cartesian-product','If relation A has 5 rows and relation B has 8 rows, how many rows does A × B have?','["13", "40", "5", "8"]'::jsonb,1,'Cartesian Product''s row count is the product of the two operand row counts: 5 x 8 = 40.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-3','pt-dbms-sql-7-cartesian-product','Must the two relations combined by Cartesian Product be union-compatible (same columns)?','["Yes, exactly like Union and Intersection", "No — they can have entirely different columns; the result simply includes all columns from both", "Only if they share a primary key", "Cartesian Product requires exactly one shared column"]'::jsonb,1,'Unlike the set operations, Cartesian Product has no compatibility requirement between the two relations'' schemas.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-4','pt-dbms-sql-7-cartesian-product','Which defect can produce an unintended all-pairs population in SQL forms that allow unconditioned source combinations?','["Using SELECT * instead of naming columns", "Forgetting the JOIN ... ON condition (or WHERE filter in comma-join syntax), which silently returns all combinations instead of an error", "Using ORDER BY without LIMIT", "Using DISTINCT unnecessarily"]'::jsonb,1,'The query lacks its intended relationship predicate. Exact syntax acceptance depends on the dialect and join form.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-5','pt-dbms-sql-7-cartesian-product','How is a Theta Join (7.8) formally related to Cartesian Product?','["They are unrelated operations", "A Theta Join is formally defined as a Cartesian Product followed by a Selection that applies the join condition", "Theta Join always produces fewer rows than any Cartesian Product", "Cartesian Product is a special, restricted case of Theta Join"]'::jsonb,1,'Every join type builds conceptually on top of Cartesian Product plus a filtering condition.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-6','pt-dbms-sql-7-cartesian-product','Why is an accidental Cartesian Product on two large tables a real operational risk?','["It has no real risk, just a slightly odd result", "The row count explosion (m x n) can produce an enormous, memory-exhausting result even from moderately sized input tables", "It always causes an immediate syntax error before running", "Cartesian products are automatically capped at 1000 rows by every engine"]'::jsonb,1,'The logical m-by-n population can be very large. Exact memory, execution and intermediate materialization behaviour require plan and workload evidence.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-7','pt-dbms-sql-7-cartesian-product','Which SQL syntax explicitly requests a Cartesian Product?','["INNER JOIN ... ON", "CROSS JOIN (or a comma-separated FROM list with no condition)", "NATURAL JOIN", "LEFT OUTER JOIN"]'::jsonb,1,'CROSS JOIN is the explicit, intentional way to request a full Cartesian Product in SQL.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-cartesian-product-8','pt-dbms-sql-7-cartesian-product','Does the algebraic product-plus-selection definition require an engine to materialize the entire product for every ordinary join?','["Yes, always, for every join, regardless of size", "No; supported plans can avoid full materialization, but actual work depends on the query and engine rather than a universal never-product rule", "Only for joins on non-indexed columns", "This has no bearing on real engine implementation"]'::jsonb,1,'Logical definition and physical execution are distinct. Some plans or predicates can still process many combinations.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-cartesian-product-new-9','pt-dbms-sql-7-cartesian-product','Two rooms and three slots produce how many complete pairs?','["5", "6", "3", "2"]'::jsonb,1,'Every room pairs with every slot.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-cartesian-product-new-10','pt-dbms-sql-7-cartesian-product','What happens to the pair listing if slots is empty?','["Every room receives one invented NULL slot", "It returns every booking", "It has no rows", "The room schema disappears"]'::jsonb,2,'A product needs an actual tuple from each side.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-cartesian-product-application-new-1','pt-dbms-sql-7-cartesian-product-application','Does a candidate room-slot pair prove it is authorized and reservable?','["Yes; CROSS JOIN grants reservation rights", "Only if ids are sorted", "No; additional domain and trusted-operation rules apply", "Only if the pair is unique"]'::jsonb,2,'Candidate generation is not an accepted booking operation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-cartesian-product-application-new-2','pt-dbms-sql-7-cartesian-product-application','Must Room and Slot be union-compatible for a product?','["Yes; names and counts must match", "Only if both are empty", "Only if they use integers", "No; they can have different attribute structures"]'::jsonb,3,'Product combines structures rather than unioning corresponding tuples.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-cartesian-product-application-new-3','pt-dbms-sql-7-cartesian-product-application','Why can same-named id attributes need aliases?','["They represent different roles in the combined result", "Aliases make them the same identity", "Every id is globally unique", "A label automatically enforces a reference"]'::jsonb,0,'Source roles must remain distinguishable.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
