insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-cascading-actions-6','pt-dbms-sql-5-cascading-actions','Why might a team deliberately choose RESTRICT over CASCADE, despite the extra manual work?','["RESTRICT is always faster to execute", "It forces an explicit decision about dependent rows rather than risking accidental, far-reaching automatic deletion", "RESTRICT is required by the SQL standard in every case", "CASCADE is not supported by any real database"]'::jsonb,1,'Trading convenience for safety is a deliberate, common design choice, especially for high-stakes parent tables.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
