update public.learning_topics set short_description='Express row-domain predicates with explicit UNKNOWN handling, distinguish presence from comparison, and diagnose legacy invalid salaries without inventing repairs or cross-table guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Express row-domain predicates with explicit UNKNOWN handling, distinguish presence from comparison, and diagnose legacy invalid salaries without inventing repairs or cross-table guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for CHECK.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-10-check' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-10-check-application','MCQ Test 2',category,10,10,'Application and scenarios for CHECK.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-10-check' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-1','pt-dbms-sql-10-check','What happens to a row where a CHECK constraint''s boolean expression evaluates to UNKNOWN (e.g., due to a NULL operand)?','["The row is rejected, same as FALSE", "The row is accepted, since only a definite FALSE result blocks a row", "The row is accepted but flagged with a warning", "The behavior is undefined and engine-specific"]'::jsonb,1,'CHECK constraints use three-valued logic: only a definite FALSE evaluation rejects the row; UNKNOWN (typically from NULL) is treated as passing.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-2','pt-dbms-sql-10-check','Before which MySQL version did CHECK constraints parse successfully but get silently ignored at runtime?','["MySQL 5.0", "MySQL 8.0.16", "MySQL 8.0.30", "MySQL never had this issue"]'::jsonb,1,'MySQL versions prior to 8.0.16 (released 2019) accepted CHECK syntax but did not enforce it; 8.0.16 onward actually enforces CHECK constraints.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-3','pt-dbms-sql-10-check','Which column declaration checks that a supplied integer age is at least 18 without itself requiring presence?','["CHECK age >= 18", "age INT CHECK (age >= 18)", "age INT DEFAULT (age >= 18)", "CONSTRAINT age >= 18"]'::jsonb,1,'A separate NOT NULL rule is needed when missing age is forbidden.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-4','pt-dbms-sql-10-check','Why use a table-level MySQL CHECK for a relation between check_out and check_in?','["Because DATE columns cannot have column-level CHECK constraints", "The supported table-level form can express the required multi-column condition", "Because table-level CHECK constraints execute faster", "Because MySQL forbids column-level CHECK entirely"]'::jsonb,1,'Placement restrictions are product specific; do not generalize this to every engine.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-5','pt-dbms-sql-10-check','What happens when you run ALTER TABLE employees ADD CONSTRAINT chk_salary_positive CHECK (salary > 0); on a table that already has a row with salary = -100?','["The constraint is added and applies only to future rows", "The ALTER TABLE statement fails because the existing row violates the new constraint", "MySQL fixes the row automatically to salary = 0", "PostgreSQL ignores the violation silently"]'::jsonb,1,'Adding a CHECK constraint validates all existing rows; any row violating the new condition causes the ALTER TABLE to fail in standard-conforming engines.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-6','pt-dbms-sql-10-check','What should replace an unsupported cross-table CHECK proposal?','["Yes, in all major SQL engines", "A suitable supported integrity design, such as a foreign key for references, with concurrency reviewed", "Yes, but only in MySQL", "Yes, but only for foreign key columns"]'::jsonb,1,'A trigger is not a universal automatic solution for every cross-table invariant.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-7','pt-dbms-sql-10-check','Which of these is functionally redundant with a plain NOT NULL constraint, though technically valid as a CHECK?','["CHECK (salary > 0)", "CHECK (col IS NOT NULL)", "CHECK (age >= 18)", "CHECK (check_out > check_in)"]'::jsonb,1,'CHECK (col IS NOT NULL) duplicates what a dedicated NOT NULL constraint already does more directly and efficiently.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-check-8','pt-dbms-sql-10-check','A developer on an old MySQL 5.7 database declares CHECK (price >= 0) and then successfully inserts a row with price = -50 with no error. What is the most likely explanation?','["MySQL 5.7 rounds negative prices to zero automatically", "MySQL 5.7 predates CHECK enforcement, so the constraint was parsed but never enforced", "The column must not actually be of a numeric type", "The insert used a different connection without constraints enabled"]'::jsonb,1,'This is the well-known historical MySQL gotcha: versions before 8.0.16 accepted CHECK syntax without error but never enforced it at runtime.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
