if exists(select 1 from public.dsa_problems where (id='cx-check-optional-age' or slug='check-optional-age') and (id<>'cx-check-optional-age' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-check-optional-age'; end if;
if exists(select 1 from public.dsa_problems where id='cx-check-optional-age' and description is distinct from 'Create TEMPORARY activity_claims(claim_id INT PRIMARY KEY,age INT NULL,CHECK(age >= 18)). Copy the compatible claim_input rows and return claim_id,age. NULL is intentionally allowed; do not add NOT NULL or treat it as verified adulthood.

