if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-client-server-architecture-1' and (question_text,options,correct_index,explanation) is distinct from ('In Client-Server Architecture, what travels across the network when a client makes a request?','["The entire data file", "Only the query and the resulting data, not the whole file", "The server''s internal schema definition", "A copy of the server''s operating system"]'::jsonb,1,'Client-server architecture sends only queries to the server and only results back, unlike the older file-server model.') and (question_text,options,correct_index,explanation) is distinct from ('Which description best captures the usual database client-server exchange?','["The entire data file", "The client sends database operations and parameters; the server returns results, metadata, and status rather than requiring raw table-file processing", "The server''s internal schema definition", "A copy of the server''s operating system"]'::jsonb,1,'The protocol can include authentication, metadata, errors, and commands as well as queries and rows.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-client-server-architecture-1'; end if;
