if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-client-server-architecture-2' and (question_text,options,correct_index,explanation) is distinct from ('Who is responsible for enforcing security, integrity, and locking in a client-server architecture?','["Each individual client independently", "The server, centrally, for all clients", "The network router", "No one; it is left unmanaged"]'::jsonb,1,'The server centrally manages security, integrity constraints, and concurrency control in client-server architecture.') and (question_text,options,correct_index,explanation) is distinct from ('Where are configured database constraints, privileges, and concurrency mechanisms enforced for multiple clients?','["Each individual client independently", "On the database server; additional product authorization may also belong to a trusted application service", "The network router", "No one; it is left unmanaged"]'::jsonb,1,'Central database guarantees still require explicit configuration and do not replace all application rules.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-client-server-architecture-2'; end if;
