if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-client-server-architecture-3' and (question_text,options,correct_index,explanation) is distinct from ('What example query does a student''s laptop (client) send to the database server in the notes?','["CREATE INDEX ON Marks(StudentID)", "SELECT * FROM Marks WHERE StudentID = 101", "DROP TABLE Marks", "GRANT SELECT ON Marks TO student"]'::jsonb,1,'The example given is a client sending this SELECT query to retrieve one student''s marks.') and (question_text,options,correct_index,explanation) is distinct from ('What example query does a student''s laptop (client) send to the database server in the notes?','["CREATE INDEX ON Marks(StudentID)", "SELECT * FROM Marks WHERE StudentID = 101", "DROP TABLE Marks", "GRANT SELECT ON Marks TO student"]'::jsonb,1,'The example given is a client sending this SELECT query to retrieve one student''s marks.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-client-server-architecture-3'; end if;
