if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-client-server-architecture-4' and (question_text,options,correct_index,explanation) is distinct from ('How does the file-server model differ from client-server architecture in terms of network traffic?','["File-server sends only results; client-server sends whole files", "File-server ships entire data files to the client; client-server sends only queries and results", "Both models send identical amounts of data", "Neither model involves any network traffic"]'::jsonb,1,'The file-server model moves whole files across the network, causing much heavier traffic than client-server''s query/result exchange.') and (question_text,options,correct_index,explanation) is distinct from ('How does shared file access differ from database client-server processing?','["File-server sends only results; client-server sends whole files", "File-based clients interpret file content locally; a database server executes database operations and returns results", "Both models send identical amounts of data", "Neither model involves any network traffic"]'::jsonb,1,'File access may transfer portions or blocks; it does not always send an entire file.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-client-server-architecture-4'; end if;
