if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-client-server-architecture-7' and (question_text,options,correct_index,explanation) is distinct from ('A network connection drops while a client''s transaction is mid-execution on the server. Based on the notes, what must the system explicitly handle?','["Nothing; client-server architecture guarantees this never happens", "Retries and/or transaction rollback, since client and server are physically separate and the connection can fail", "The client must restart the entire database server", "The internal schema must be redesigned"]'::jsonb,1,'Because the client and server communicate over a network that can fail, mid-transaction network failures must be explicitly handled via retry or rollback logic.') and (question_text,options,correct_index,explanation) is distinct from ('A connection is lost around transaction commit. What must the application handle explicitly?','["Nothing; client-server architecture guarantees this never happens", "The outcome may be uncertain; retries must account for possible committed effects rather than assume rollback", "The client must restart the entire database server", "The internal schema must be redesigned"]'::jsonb,1,'A lost response is not proof that the write had no effect.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-client-server-architecture-7'; end if;
