update public.learning_topics set short_description='Trace requests and results between database clients and servers, distinguish file access from server-side query processing, and handle access checks, concurrency, and uncertain network failures.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Trace requests and results between database clients and servers, distinguish file access from server-side query processing, and handle access checks, concurrency, and uncertain network failures.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Client Server Architecture.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-client-server-architecture' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-client-server-architecture-application','MCQ Test 2',category,10,10,'Application and scenarios for Client Server Architecture.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-client-server-architecture' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-1','pt-dbms-sql-2-client-server-architecture','Which description best captures the usual database client-server exchange?','["The entire data file", "The client sends database operations and parameters; the server returns results, metadata, and status rather than requiring raw table-file processing", "The server''s internal schema definition", "A copy of the server''s operating system"]'::jsonb,1,'The protocol can include authentication, metadata, errors, and commands as well as queries and rows.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-2','pt-dbms-sql-2-client-server-architecture','Where are configured database constraints, privileges, and concurrency mechanisms enforced for multiple clients?','["Each individual client independently", "On the database server; additional product authorization may also belong to a trusted application service", "The network router", "No one; it is left unmanaged"]'::jsonb,1,'Central database guarantees still require explicit configuration and do not replace all application rules.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-3','pt-dbms-sql-2-client-server-architecture','What example query does a student''s laptop (client) send to the database server in the notes?','["CREATE INDEX ON Marks(StudentID)", "SELECT * FROM Marks WHERE StudentID = 101", "DROP TABLE Marks", "GRANT SELECT ON Marks TO student"]'::jsonb,1,'The example given is a client sending this SELECT query to retrieve one student''s marks.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-4','pt-dbms-sql-2-client-server-architecture','How does shared file access differ from database client-server processing?','["File-server sends only results; client-server sends whole files", "File-based clients interpret file content locally; a database server executes database operations and returns results", "Both models send identical amounts of data", "Neither model involves any network traffic"]'::jsonb,1,'File access may transfer portions or blocks; it does not always send an entire file.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-5','pt-dbms-sql-2-client-server-architecture','What coordination challenge can independently processing shared-file clients face compared with a central database service?','["They need a reliable shared agreement for validity and concurrent changes rather than automatically obtaining database-server guarantees", "Because file-server always uses faster networks", "Because client-server architecture has no concept of a server at all", "Because file-server systems do not allow multiple clients"]'::jsonb,0,'File systems can provide locks. The question concerns the richer coordination responsibility, not a claim that all file designs have no locking.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-6','pt-dbms-sql-2-client-server-architecture','What problem does a ''fat client'' (one with too much embedded business logic) create in a client-server system?','["It has no effect on the architecture", "It blurs the client-server boundary and creates scaling/maintenance problems that motivate three-tier architecture", "It automatically improves network performance", "It eliminates the need for a database server entirely"]'::jsonb,1,'Embedding too much logic in the client is exactly the issue that later motivates moving to a three-tier design with a separate middle tier.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-7','pt-dbms-sql-2-client-server-architecture','A connection is lost around transaction commit. What must the application handle explicitly?','["Nothing; client-server architecture guarantees this never happens", "The outcome may be uncertain; retries must account for possible committed effects rather than assume rollback", "The client must restart the entire database server", "The internal schema must be redesigned"]'::jsonb,1,'A lost response is not proof that the write had no effect.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-client-server-architecture-8','pt-dbms-sql-2-client-server-architecture','As the number of concurrent clients directly connecting to one database server grows very large, what architectural pressure does this create, according to the notes?','["None; client-server architecture scales infinitely by design", "Pressure on the server to manage locking/isolation for all clients, which motivates alternative designs like two-tier vs. three-tier architecture", "A requirement to switch back to the file-server model", "A requirement to remove all business logic from the server"]'::jsonb,1,'Scaling concerns from many concurrent direct connections are exactly what motivates the tiered architecture choices discussed in the following topics.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-new-9','pt-dbms-sql-2-client-server-architecture','Can one process be a server to a browser and a client to a database?','["No; every process has only one possible role", "Yes; client and server describe roles in an interaction", "Only if it reads raw disk sectors", "Only if no network is involved"]'::jsonb,1,'An application server receives browser requests and requests database work.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-new-10','pt-dbms-sql-2-client-server-architecture','Does a server-side query guarantee a small result transfer?','["Yes; every result contains one row", "Yes; servers never send metadata", "No; an overly broad query can still return substantial data", "Only query text affects traffic"]'::jsonb,2,'Filtering and projection still matter for network volume and exposure.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-1','pt-dbms-sql-2-client-server-architecture-application','StudentID = 101 appears in a request. What is still required before exposing that student''s results?','["Only hiding other IDs in the dropdown", "Only an index on the score", "A trusted check that the actor may read those records", "Only a successful TCP connection"]'::jsonb,2,'A supplied identifier does not prove authorization.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-2','pt-dbms-sql-2-client-server-architecture-application','A timeout occurs after the server may have committed a write. What is unsafe?','["Recording that the outcome is uncertain", "Checking the operation''s retry contract", "Distinguishing reads from writes", "Assuming no effect and blindly repeating the write"]'::jsonb,3,'Repeating an uncertain committed write can duplicate effects.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-3','pt-dbms-sql-2-client-server-architecture-application','A file-based application uses file locks. Does that contradict the accurate architecture comparison?','["No; file designs can coordinate, but their database guarantees must be assessed", "Yes; file systems can never lock", "Yes; every file client is automatically a database server", "Only SQL views can provide coordination"]'::jsonb,0,'The difference is not a blanket claim that file systems lack all locking.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-4','pt-dbms-sql-2-client-server-architecture-application','A query returns two rows after inspecting many pages. Who ordinarily performs that storage work?','["The student''s UI must decode table pages", "The database service and its engine", "The browser theme engine", "The file name itself"]'::jsonb,1,'The service translates logical requests into storage access.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-5','pt-dbms-sql-2-client-server-architecture-application','Two clients update the same result. Which property needs inspection?','["Only the client window size", "Only how many columns are visible", "The engine''s transaction, constraint, and isolation behavior", "Only which client connected first"]'::jsonb,2,'The architecture alone does not specify every concurrency guarantee.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-6','pt-dbms-sql-2-client-server-architecture-application','A client constructs SQL by concatenating untrusted text. What should the request path use instead?','["A longer connection timeout alone", "A smaller display font", "A second raw string concatenation", "The driver''s supported parameter-binding mechanism"]'::jsonb,3,'Binding values avoids treating untrusted values as SQL structure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-7','pt-dbms-sql-2-client-server-architecture-application','An application stops waiting locally. What cannot automatically be inferred?','["That remote execution has stopped", "That the local wait ended", "That cancellation behavior needs a contract", "That a response was not received in time"]'::jsonb,0,'Local cancellation and server-side cancellation are separate events.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-8','pt-dbms-sql-2-client-server-architecture-application','Thousands of direct clients hold idle sessions. Which pressure can a shared application tier help manage?','["The meaning of StudentID automatically changes", "Bounded reusable database connections", "All query predicates disappear", "Server constraints become unnecessary"]'::jsonb,1,'Pooling can reduce repeated setup and session demand under its own lifecycle.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-9','pt-dbms-sql-2-client-server-architecture-application','A modified client skips its score-range validation. What should still protect trusted shared state?','["The old dropdown alone", "The hidden UI label", "Configured server-side validity rules", "The client''s published screenshot"]'::jsonb,2,'Untrusted client checks cannot be the sole authority for integrity.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-client-server-architecture-application-new-10','pt-dbms-sql-2-client-server-architecture-application','All supported clients use the same logical request, but storage layout changes. Which separation helps them remain compatible?','["Every client stores the physical page address", "Every client decodes raw file records", "Every result is permanently cached", "Logical operations are translated by the service into physical work"]'::jsonb,3,'Keeping physical representation behind the service reduces consumer coupling.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
