if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-column-constraints-1' and (question_text,options,correct_index,explanation) is distinct from ('What defines a ''column constraint'' as opposed to a table constraint?','["It must always be named explicitly", "It is written inline as part of a single column''s definition and can only govern that one column", "It can only be a NOT NULL or DEFAULT clause", "It must be added via ALTER TABLE, never CREATE TABLE"]'::jsonb,1,'A column constraint is attached directly to one column''s definition and is inherently limited to referencing that single column.') and (question_text,options,correct_index,explanation) is distinct from ('What structurally identifies an inline column constraint?','["It must always be named explicitly", "It is written within a column definition under the target\u2019s supported grammar", "It can only be a NOT NULL or DEFAULT clause", "It must be added via ALTER TABLE, never CREATE TABLE"]'::jsonb,1,'Expression scope and meaning still depend on the rule kind and dialect.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-column-constraints-1'; end if;
