if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-column-constraints-2' and (question_text,options,correct_index,explanation) is distinct from ('Which of these CHECK conditions is IMPOSSIBLE to express as a column-level constraint?','["CHECK (salary > 0)", "CHECK (age >= 18)", "CHECK (check_out > check_in)", "CHECK (price BETWEEN 0 AND 100000)"]'::jsonb,2,'CHECK (check_out > check_in) references two different columns, which a column-level constraint attached to a single column cannot express; it requires table-level syntax.') and (question_text,options,correct_index,explanation) is distinct from ('Which illustrated multi-column condition belongs in a supported table-level MySQL CHECK?','["CHECK (salary > 0)", "CHECK (age >= 18)", "CHECK (check_out > check_in)", "CHECK (price BETWEEN 0 AND 100000)"]'::jsonb,2,'Do not generalize MySQL column-CHECK scope restrictions to every product.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-column-constraints-2'; end if;
