if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-column-constraints-3' and (question_text,options,correct_index,explanation) is distinct from ('Can a column constraint be given an explicit name, e.g. `salary NUMERIC(10,2) CONSTRAINT chk_salary_pos CHECK (salary > 0)`?','["No, only table-level constraints can be named", "Yes, being column-level and being named are independent, orthogonal choices", "Yes, but only for CHECK constraints", "No, naming forces it to become a table constraint"]'::jsonb,1,'A column constraint can still carry an explicit CONSTRAINT name inline; whether it''s column- or table-level is unrelated to whether it''s named.') and (question_text,options,correct_index,explanation) is distinct from ('Can a column constraint be given an explicit name, e.g. `salary NUMERIC(10,2) CONSTRAINT chk_salary_pos CHECK (salary > 0)`?','["No, only table-level constraints can be named", "Yes, being column-level and being named are independent, orthogonal choices", "Yes, but only for CHECK constraints", "No, naming forces it to become a table constraint"]'::jsonb,1,'A column constraint can still carry an explicit CONSTRAINT name inline; whether it''s column- or table-level is unrelated to whether it''s named.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-column-constraints-3'; end if;
