insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-1','pt-dbms-sql-10-column-constraints','What structurally identifies an inline column constraint?','["It must always be named explicitly", "It is written within a column definition under the target’s supported grammar", "It can only be a NOT NULL or DEFAULT clause", "It must be added via ALTER TABLE, never CREATE TABLE"]'::jsonb,1,'Expression scope and meaning still depend on the rule kind and dialect.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-2','pt-dbms-sql-10-column-constraints','Which illustrated multi-column condition belongs in a supported table-level MySQL CHECK?','["CHECK (salary > 0)", "CHECK (age >= 18)", "CHECK (check_out > check_in)", "CHECK (price BETWEEN 0 AND 100000)"]'::jsonb,2,'Do not generalize MySQL column-CHECK scope restrictions to every product.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-3','pt-dbms-sql-10-column-constraints','Can a column constraint be given an explicit name, e.g. `salary NUMERIC(10,2) CONSTRAINT chk_salary_pos CHECK (salary > 0)`?','["No, only table-level constraints can be named", "Yes, being column-level and being named are independent, orthogonal choices", "Yes, but only for CHECK constraints", "No, naming forces it to become a table constraint"]'::jsonb,1,'A column constraint can still carry an explicit CONSTRAINT name inline; whether it''s column- or table-level is unrelated to whether it''s named.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-4','pt-dbms-sql-10-column-constraints','In `email VARCHAR(150) UNIQUE NOT NULL`, how many separate column constraints are being applied?','["One", "Two: UNIQUE and NOT NULL", "Three, including an implicit CHECK", "Zero, because no CONSTRAINT keyword is used"]'::jsonb,1,'Multiple column constraints can be stacked on one column; here both UNIQUE and NOT NULL apply to the same email column.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-5','pt-dbms-sql-10-column-constraints','Which decision determines whether inline syntax is appropriate?','["Whether the rule involves a function call", "The rule’s complete roles and the actual target grammar", "Whether the rule is named", "Whether the table has a PRIMARY KEY already"]'::jsonb,1,'It is not one universal single-column test covering every SQL feature.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-6','pt-dbms-sql-10-column-constraints','Can a column constraint be added when adding a brand-new column via ALTER TABLE ... ADD COLUMN?','["No, ALTER TABLE ADD COLUMN cannot carry any constraints", "Yes, e.g. ALTER TABLE employees ADD COLUMN bonus NUMERIC(10,2) DEFAULT 0 CHECK (bonus >= 0);", "Only NOT NULL can be added this way", "Only if the table is empty"]'::jsonb,1,'The same inline column-constraint pattern used in CREATE TABLE applies when adding a new column to an existing table via ALTER TABLE ... ADD COLUMN.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-column-constraints-7','pt-dbms-sql-10-column-constraints','Is it reliable to write a CHECK column constraint whose logic depends on comparing values across different rows of the same table?','["Yes, this is standard, portable behavior across all engines", "No, cross-row CHECK logic is generally disallowed or unreliable, and not portable", "Yes, but only in PostgreSQL 14+", "Yes, as long as the column is also UNIQUE"]'::jsonb,1,'CHECK constraints are meant to validate a single row''s own column values; relying on cross-row comparisons is unsupported or unreliable across most engines.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
