update public.learning_topics set short_description='Distinguish sparse wide-column cells from typed Cassandra rows and analytical column storage, with query-first keys, bounded time partitions, and SQL representation exercises.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish sparse wide-column cells from typed Cassandra rows and analytical column storage, with query-first keys, bounded time partitions, and SQL representation exercises.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Column Family Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-column-family-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-column-family-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Column Family Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-column-family-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-1','pt-dbms-sql-3-column-family-model','What is the fundamental organizing structure of the column-family model?','["Rows identified by a row key, with columns grouped into families, where different rows can have different sets of populated columns", "A fixed schema table where every row has identical columns", "Nodes connected by labeled edges", "A single opaque value per key"]'::jsonb,0,'Column-family databases organize data as rows (keyed by a row key) whose columns are grouped into families, and rows are sparse — they need not share the same columns.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-2','pt-dbms-sql-3-column-family-model','Which research paper/system pioneered the column-family (wide-column) model?','["Google''s Bigtable", "IBM''s IMS", "CODASYL''s network model spec", "Codd''s relational model paper"]'::jsonb,0,'Google''s 2006 Bigtable paper introduced the wide-column storage design later implemented in systems like Cassandra and HBase.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-3','pt-dbms-sql-3-column-family-model','What can sparsity mean in a Bigtable-style cell representation?','["It stores very little data overall", "Different row keys can have different populated qualifiers without explicit cells for every absent value", "Only one column family is allowed per database", "Rows cannot contain more than one column"]'::jsonb,1,'Modern Cassandra CQL tables still have declared schemas; do not universalize dynamic qualifiers.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-4','pt-dbms-sql-3-column-family-model','Which of these systems is a widely used column-family database?','["Apache Cassandra", "Redis", "Neo4j", "MongoDB"]'::jsonb,0,'Apache Cassandra, along with Apache HBase, is a well-known column-family (wide-column) database implementing Bigtable-style concepts.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-5','pt-dbms-sql-3-column-family-model','Why choose Cassandra partition and clustering keys from required queries?','["Because Cassandra has no query language at all", "They determine supported keyed access scope and organization, so arbitrary predicates are not interchangeable", "Because arbitrary predicates are faster than key-based lookups in Cassandra", "Because Cassandra enforces strict relational normalization"]'::jsonb,1,'Exact query and indexing capabilities depend on the target product and version.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-6','pt-dbms-sql-3-column-family-model','What is the accurate way to discuss Cassandra consistency?','["Strict serializability with no configuration options", "Inspect configured operation levels, replication, and the full deployment rather than infer one guarantee from the model label", "No consistency guarantees whatsoever", "Full two-phase commit across all nodes for every write"]'::jsonb,1,'Relational products also have implementation-dependent transaction and isolation guarantees.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-column-family-model-7','pt-dbms-sql-3-column-family-model','How does a structured wide-column interface differ from the simplest opaque key-value interface?','["They are functionally identical opaque blobs", "It exposes the supported keyed and named-value organization, with product-specific schema and access rules", "A key-value store''s value supports nested JSON while column-family values do not", "Column-family stores do not use any key to identify rows"]'::jsonb,1,'It does not imply every product permits arbitrary qualifier scans.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
