if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-comments-4' and (question_text,options,correct_index,explanation) is distinct from ('Do standard SQL block comments support nesting (a comment inside a comment)?','["Yes, nesting is fully supported and safe", "No \u2014 the first closing */ ends the comment, so anything after it is parsed as real SQL", "Only in PostgreSQL", "Only if there are exactly two nested levels"]'::jsonb,1,'Standard SQL block comments are not nestable; the first */ closes the comment regardless of how many /* appeared before it.') and (question_text,options,correct_index,explanation) is distinct from ('Should ordinary nested block comments be relied on in MySQL?','["Yes, nesting is fully supported and safe", "No; avoid nesting because an inner closing marker can end the intended outer comment", "Only in PostgreSQL", "Only if there are exactly two nested levels"]'::jsonb,1,'Nesting behavior is dialect-specific. This topic explicitly targets MySQL rather than making a universal claim about every SQL product.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-comments-4'; end if;
