update public.learning_topics set short_description='Use MySQL line and block comments to document intent while avoiding delimiter mistakes, unsafe nesting, executable-comment surprises, and confusion between SQL text and string data.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use MySQL line and block comments to document intent while avoiding delimiter mistakes, unsafe nesting, executable-comment surprises, and confusion between SQL text and string data.';
