insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-1','pt-dbms-sql-8-comments','Which form is the clear double-dash line-comment opening used in MySQL examples?','["//", "#", "-- followed by a space", "<!--"]'::jsonb,2,'MySQL requires whitespace or a control character after the second dash.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-2','pt-dbms-sql-8-comments','Which comment style can span multiple lines?','["-- comment", "# comment", "/* comment */", "// comment"]'::jsonb,2,'/* ... */ block comments can span multiple lines, exactly like C-family block comments.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-3','pt-dbms-sql-8-comments','Which single-line comment marker is a MySQL-specific addition, not part of the SQL standard?','["--", "/* */", "#", "There is no such marker"]'::jsonb,2,'# is a MySQL-specific single-line comment marker; -- is the standard one, supported everywhere.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-4','pt-dbms-sql-8-comments','Should ordinary nested block comments be relied on in MySQL?','["Yes, nesting is fully supported and safe", "No; avoid nesting because an inner closing marker can end the intended outer comment", "Only in PostgreSQL", "Only if there are exactly two nested levels"]'::jsonb,1,'Nesting behavior is dialect-specific. This topic explicitly targets MySQL rather than making a universal claim about every SQL product.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-5','pt-dbms-sql-8-comments','What risk does an unfinished block comment create for a SQL script?','["No risk — the database automatically closes it at the end of the statement", "Later text or statement boundaries may be misinterpreted; the client may wait, reject input, or keep text inside a comment", "It causes an immediate, very clear syntax error at the exact missing spot", "Unterminated comments are automatically converted to line comments"]'::jsonb,1,'The outcome depends on the client and parser. Silent successful execution is not guaranteed.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-6','pt-dbms-sql-8-comments','Someone tries to comment out a block of SQL that already contains a `/* ... */` comment inside it, by wrapping the whole thing in another `/* ... */`. What actually happens?','["It works correctly and everything is commented out as intended", "The FIRST inner */ ends the outer comment early, so the remaining text becomes real (likely invalid) SQL", "SQL automatically detects the intent and nests correctly", "This always produces a silent, undetectable bug with no error"]'::jsonb,1,'Because block comments don''t nest, the inner */ prematurely closes the outer comment, and the rest is parsed as SQL — often producing a syntax error.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-7','pt-dbms-sql-8-comments','Can a single-line comment appear at the end of a line of real SQL code, like `ORDER BY salary DESC; -- highest paid first`?','["No, comments must always be on their own line", "Yes — a single-line comment can trail after real code on the same line", "Only block comments can trail after code", "This is only allowed in MySQL"]'::jsonb,1,'A trailing -- comment after real SQL on the same line is standard and common practice.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-comments-8','pt-dbms-sql-8-comments','Why are comments useful in a SQL script beyond just ''notes''?','["They have no real use beyond decoration", "They document non-obvious business logic or exclusions (e.g. why contractors are excluded from a query) that the SQL syntax itself can''t express", "They make queries execute faster", "They are required by the SQL standard for every statement"]'::jsonb,1,'Comments capture the ''why'' behind a query''s logic — context that pure SQL syntax has no way to express.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-new-9','pt-dbms-sql-8-comments','What should a useful SQL comment primarily explain?','["Only repeat SELECT as choose columns", "Non-obvious intent, assumptions, or reasons for a condition", "A secret connection password", "A second permanently hidden implementation"]'::jsonb,1,'Comments help maintainers understand why the executable logic is required.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-new-10','pt-dbms-sql-8-comments','Does an explanatory comment saying published only enforce that population?','["Yes; prose comments filter rows", "Only if the comment is uppercase", "No; the actual query predicate must enforce it", "Only if the table has a key"]'::jsonb,2,'Behavior is determined by executable SQL rather than descriptive text.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-1','pt-dbms-sql-8-comments-application','ORDER BY is moved onto the same line after a double-dash comment. What can happen?','["The comment forces a faster sort", "The clause automatically moves to the next line", "The ordering clause becomes part of the comment", "Every row is deleted"]'::jsonb,2,'A line comment continues to the end of its physical line.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-2','pt-dbms-sql-8-comments-application','A quoted value contains the text priority -- review. Are the dashes necessarily a SQL comment?','["Yes; every double dash starts a comment regardless of quotes", "Only if the text contains a space", "Only if the column is indexed", "No; inside the quoted string they are value data"]'::jsonb,3,'The parser distinguishes quoted data from statement structure.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-3','pt-dbms-sql-8-comments-application','A wrapper block surrounds text that already contains a block comment. What should a MySQL author avoid assuming?','["That the wrapper safely nests until its final closing marker", "That all line breaks become table rows", "That every string becomes NULL", "That a new transaction begins"]'::jsonb,0,'The inner closing marker can terminate the intended outer block early.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-4','pt-dbms-sql-8-comments-application','A script uses MySQL hash line comments and is copied to another product. What must be checked?','["Only whether the filename ends in sql", "Whether the target recognizes that dialect-specific marker", "Only whether the first query returns one row", "Only the screen width"]'::jsonb,1,'Comment syntax is not identical in every dialect.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-5','pt-dbms-sql-8-comments-application','A region begins with the MySQL executable-comment opening slash-star-exclamation. What must review recognize?','["It is guaranteed inert prose", "It is a string literal automatically", "Its contents can be interpreted as SQL under documented rules", "It authorizes production execution"]'::jsonb,2,'Special forms cannot be assessed as ordinary explanatory blocks.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-comments-application-new-6','pt-dbms-sql-8-comments-application','A comment begins with the optimizer-hint form. What evidence should support relying on it?','["Only a reassuring sentence beside it", "Only the size of the code block", "Only the number of examples", "Actual supported hint semantics and relevant plan behavior"]'::jsonb,3,'Hint comments can affect execution strategy and require technical evidence.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
