INSERT INTO courses VALUES (1,''A'',''Computing'',20,1),(2,''B'',''Computing'',10,1),(3,''C'',''Mechanics'',10,1),(4,''D'',''Electronics'',0,1),(5,''E'',''Hidden'',100,0);
