update public.learning_topics set short_description='Model meaningful property components without confusing them with multiple occurrences, and map structured addresses to explicit relational columns and queries.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Model meaningful property components without confusing them with multiple occurrences, and map structured addresses to explicit relational columns and queries.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Composite Attribute.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-composite-attribute' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-composite-attribute-application','MCQ Test 2',category,10,10,'Application and scenarios for Composite Attribute.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-composite-attribute' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-1','pt-dbms-sql-6-composite-attribute','What is a composite attribute?','["An attribute computed from other attributes", "An attribute that can be divided into smaller, independently meaningful sub-attributes", "An attribute that holds multiple independent values", "An attribute shared by two entity sets"]'::jsonb,1,'A composite attribute breaks down into meaningful component simple attributes, like Address into Street/City/State/Pincode.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-2','pt-dbms-sql-6-composite-attribute','Which Student attribute is the clearest example of a composite attribute?','["Roll_No", "Address, decomposing into Street, City, State, Pincode", "CGPA", "Gender"]'::jsonb,1,'Address naturally splits into independently useful sub-parts, the hallmark of a composite attribute.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-3','pt-dbms-sql-6-composite-attribute','What can the components of a composite attribute include before recursive decomposition reaches its leaves?','["Other entity sets", "Simple attributes or further composite components, with simple leaf roles at the end of the chosen decomposition", "Relationships", "Derived attributes only"]'::jsonb,1,'Composite structure can be nested; immediate components need not all be simple.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-4','pt-dbms-sql-6-composite-attribute','In a basic single-valued relational mapping, how are the required leaf roles of a composite attribute commonly represented?','["It becomes its own separate table always", "It is flattened — each component becomes its own column, and the composite grouping disappears at the table level", "It is dropped entirely and not stored", "It becomes a foreign key"]'::jsonb,1,'The mapping commonly uses component columns; more complex object, multiplicity or lifecycle mappings need their own explicit contract.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-5','pt-dbms-sql-6-composite-attribute','A student has exactly one Address, which is composed of Street/City/State/Pincode. Is this attribute multi-valued?','["Yes, because it has multiple sub-parts", "No — having multiple internal sub-parts (composite) is different from having multiple separate values (multi-valued); here there is only one address value per student", "Yes, all composite attributes are automatically multi-valued", "It cannot be determined"]'::jsonb,1,'Composite (internal structure) and multi-valued (number of occurrences) are independent properties; one address with sub-parts is composite but single-valued.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-6','pt-dbms-sql-6-composite-attribute','Which of the following combinations is valid for an attribute?','["Only simple attributes can be single-valued", "An attribute can be composite AND multi-valued at the same time (e.g., multiple structured addresses per student)", "Composite and derived are the same category and cannot be separated", "Multi-valued attributes can never be composite"]'::jsonb,1,'The composite/simple axis and single/multi-valued axis are independent, so all four combinations, including composite+multi-valued, are possible.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-7','pt-dbms-sql-6-composite-attribute','In the common Chen-style convention, how can a composite attribute and its components be drawn?','["As a rectangle with a double border", "As an oval connected to smaller ovals representing its component simple attributes", "As a diamond linked to two rectangles", "As a dashed oval"]'::jsonb,1,'An attribute oval connects to its component ovals, including nested components when modeled.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-composite-attribute-8','pt-dbms-sql-6-composite-attribute','Why might a designer choose NOT to decompose Name into First_Name and Last_Name?','["Because decomposition is impossible for names", "Because if the application never needs to query/sort by the sub-parts separately, treating Name as simple avoids unnecessary design complexity", "Because composite attributes are illegal in ER diagrams", "Because Name must always be derived"]'::jsonb,1,'Composite decomposition is a design choice justified only when sub-parts are independently useful.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-composite-attribute-new-9','pt-dbms-sql-6-composite-attribute','A student has one address with four components. How many complete addresses does that imply?','["Four", "One", "Zero if one component is optional", "One per character"]'::jsonb,1,'Internal components do not multiply occurrence count.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-composite-attribute-new-10','pt-dbms-sql-6-composite-attribute','Does a composite descriptive Address automatically form a composite student key?','["Yes; all address components identify students", "Only if city is short", "No; structure and identifying uniqueness are different roles", "Only if the address is stored"]'::jsonb,2,'Composite attribute and composite key are distinct concepts.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-composite-attribute-application-new-1','pt-dbms-sql-6-composite-attribute-application','Why store postal_code as an appropriate string in this example?','["All postal codes are amounts", "It proves deliverability", "Leading zeros are meaningful identifier representation", "It makes every address unique"]'::jsonb,2,'A code is not automatically a numeric quantity.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
