if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-composite-key-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a composite key?','["A key made of encrypted values", "A key made of two or more columns where the combination (not any single column) is unique", "A foreign key that references two tables at once", "A deprecated kind of key no longer used"]'::jsonb,1,'Composite key = multi-column key where uniqueness comes from the combination.') and (question_text,options,correct_index,explanation) is distinct from ('What is a composite key?','["A key made of encrypted values", "A minimal identifying combination of two or more attributes under the stated relation rules", "A foreign key that references two tables at once", "A deprecated kind of key no longer used"]'::jsonb,1,'A composite candidate key has multiple necessary components; a redundant multi-column uniqueness declaration is a different logical classification.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-composite-key-1'; end if;
