if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-composite-key-3' and (question_text,options,correct_index,explanation) is distinct from ('Which query correctly finds rows that would violate an intended composite key on (student_id, course_id, semester)?','["SELECT * FROM enrollments WHERE student_id IS NULL", "SELECT student_id, course_id, semester, COUNT(*) FROM enrollments GROUP BY student_id, course_id, semester HAVING COUNT(*) > 1", "SELECT DISTINCT student_id FROM enrollments", "SELECT * FROM enrollments ORDER BY student_id"]'::jsonb,1,'Grouping by exactly the composite key''s columns and filtering groups with more than one row finds exactly the duplicate/violating combinations.') and (question_text,options,correct_index,explanation) is distinct from ('For an unconstrained staging table with nonmissing proposed key components, which query finds repeated student-course-semester combinations?','["SELECT * FROM enrollments WHERE student_id IS NULL", "SELECT student_id, course_id, semester, COUNT(*) FROM enrollments GROUP BY student_id, course_id, semester HAVING COUNT(*) > 1", "SELECT DISTINCT student_id FROM enrollments", "SELECT * FROM enrollments ORDER BY student_id"]'::jsonb,1,'Grouping by exactly the composite key''s columns and filtering groups with more than one row finds exactly the duplicate/violating combinations.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-composite-key-3'; end if;
