insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-composite-key-application-new-10','pt-dbms-sql-5-composite-key-application','Which valid fixture challenges overly restrictive per-component uniqueness?','["Only one row", "A repeated full triple", "A missing required term", "One student taking two distinct courses in one term"]'::jsonb,3,'The intended combination permits repeated individual components.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
