if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-conceptual-schema-1' and (question_text,options,correct_index,explanation) is distinct from ('What best describes the Conceptual Schema in the three-schema architecture?','["A partial, user-specific view of the data", "The single, complete, organization-wide logical structure of the whole database, independent of storage details", "The physical file layout used to store records on disk", "A cache of frequently-run queries"]'::jsonb,1,'The conceptual schema is the one integrated logical model of all entities, attributes, and relationships, shared across the organization.') and (question_text,options,correct_index,explanation) is distinct from ('What best describes the Conceptual Schema in the three-schema architecture?','["A partial, user-specific view of the data", "The integrated logical structure and rules for the modeled database, independent of physical storage details", "The physical file layout used to store records on disk", "A cache of frequently-run queries"]'::jsonb,1,'Complete refers to the stated database scope, not a requirement that an entire organization use one database.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-conceptual-schema-1'; end if;
