if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-conceptual-schema-2' and (question_text,options,correct_index,explanation) is distinct from ('In the college database example, which constraint is described as part of the conceptual schema?','["That the Student table is stored as a B+-tree", "That every Student.DeptID must reference an existing Department row", "That the Result Portal only shows Name and Marks", "That queries must go through a connection pool"]'::jsonb,1,'The referential integrity rule linking Student to Department is a logical-level constraint, which belongs to the conceptual schema.') and (question_text,options,correct_index,explanation) is distinct from ('In the college database example, which constraint is described as part of the conceptual schema?','["That the Student table is stored as a B+-tree", "That every Student.DeptID must reference an existing Department row", "That the Result Portal only shows Name and Marks", "That queries must go through a connection pool"]'::jsonb,1,'The referential integrity rule linking Student to Department is a logical-level constraint, which belongs to the conceptual schema.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-conceptual-schema-2'; end if;
