insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-1','pt-dbms-sql-2-conceptual-schema','What best describes the Conceptual Schema in the three-schema architecture?','["A partial, user-specific view of the data", "The integrated logical structure and rules for the modeled database, independent of physical storage details", "The physical file layout used to store records on disk", "A cache of frequently-run queries"]'::jsonb,1,'Complete refers to the stated database scope, not a requirement that an entire organization use one database.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-2','pt-dbms-sql-2-conceptual-schema','In the college database example, which constraint is described as part of the conceptual schema?','["That the Student table is stored as a B+-tree", "That every Student.DeptID must reference an existing Department row", "That the Result Portal only shows Name and Marks", "That queries must go through a connection pool"]'::jsonb,1,'The referential integrity rule linking Student to Department is a logical-level constraint, which belongs to the conceptual schema.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-3','pt-dbms-sql-2-conceptual-schema','Within the three-schema model for one database, how do conceptual and external descriptions relate?','["Many conceptual schemas and exactly one external schema", "Exactly one conceptual schema, with potentially many external schemas derived from it", "The same number of each, always one-to-one", "Neither has a fixed count; both vary independently"]'::jsonb,1,'The architecture uses one coherent conceptual model for the stated database scope and allows multiple task-specific external descriptions.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-4','pt-dbms-sql-2-conceptual-schema','Which of these belongs to the internal schema rather than the conceptual schema?','["The rule that Student.DeptID must exist in Department", "The definition of the Enrollment table''s Marks attribute", "The choice of B+-tree indexing and block size for storing Student records", "The list of entities: Student, Department, Course, Enrollment"]'::jsonb,2,'Indexing structure and block size are physical storage details, which belong strictly to the internal schema, not the conceptual schema.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-5','pt-dbms-sql-2-conceptual-schema','How can two implementations share equivalent conceptual structures yet differ in physical performance?','["Because conceptual schemas are always unique per database and cannot be identical", "Because their internal schemas (storage engine, indexing, file format) can differ even though the logical structure is the same", "Because their external schemas must also be identical if the conceptual schema matches", "Because conceptual schemas include the storage engine choice"]'::jsonb,1,'Equivalent logical meaning does not specify the same physical representation. Actual product types and guarantees still need review.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
