insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-conceptual-schema-7','pt-dbms-sql-2-conceptual-schema','The DBA splits the single `Student` table into `Student` and `StudentContact` at the conceptual level. What is the likely consequence, based on how the conceptual schema relates to external schemas?','["No consequence at all, since conceptual changes never affect external schemas", "Every external schema that referenced the old unified Student structure may need to be updated, since they are derived from the conceptual schema", "Only the internal schema needs updating, external schemas are unaffected", "The change is invalid because the conceptual schema can never be restructured"]'::jsonb,1,'Dependent mappings need review; they may be changed to preserve a compatible external contract when the new relationships permit it.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
