if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-connection-pooling-3' and (question_text,options,correct_index,explanation) is distinct from ('What costly steps does connection pooling help an application avoid repeating for every request?','["Running the SQL query itself", "A fresh TCP handshake, database authentication, and session setup for each request", "Rendering the user interface", "Compiling the application code"]'::jsonb,1,'Pooling avoids repeatedly paying the overhead of establishing a brand-new physical connection (handshake, auth, session setup) per request.') and (question_text,options,correct_index,explanation) is distinct from ('What costly steps does connection pooling help an application avoid repeating for every request?','["Running the SQL query itself", "A fresh TCP handshake, database authentication, and session setup for each request", "Rendering the user interface", "Compiling the application code"]'::jsonb,1,'Pooling avoids repeatedly paying the overhead of establishing a brand-new physical connection (handshake, auth, session setup) per request.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-connection-pooling-3'; end if;
