if exists(select 1 from public.test_questions where id='pt-dbms-sql-2-connection-pooling-application-new-8' and test_id<>'pt-dbms-sql-2-connection-pooling-application') then raise exception 'Question ID collision: %', 'pt-dbms-sql-2-connection-pooling-application-new-8'; end if;
if exists(select 1 from public.test_questions where id='pt-dbms-sql-2-connection-pooling-application-new-8' and (question_text,options,correct_index,explanation) is distinct from ('A previous borrower changed a session variable. What does the next borrower require?','["The same variable value by coincidence", "Documented cleanup or reset behavior for the session", "A larger result table", "A different SQL dialect for each query"]'::jsonb,1,'State can outlive one request unless the lifecycle removes or controls it.') and (question_text,options,correct_index,explanation) is distinct from ('A previous borrower changed a session variable. What does the next borrower require?','["The same variable value by coincidence", "Documented cleanup or reset behavior for the session", "A larger result table", "A different SQL dialect for each query"]'::jsonb,1,'State can outlive one request unless the lifecycle removes or controls it.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-2-connection-pooling-application-new-8'; end if;
