if exists(select 1 from public.test_questions where id='pt-dbms-sql-2-connection-pooling-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('A pool is created afresh for every invocation. What should be investigated?','["Whether all invocations share one physical session automatically", "Whether SQL now needs no authentication", "Whether this defeats reuse and multiplies connection demand", "Whether user count is exactly pool size"]'::jsonb,2,'Pool ownership and runtime lifecycle determine actual reuse.') and (question_text,options,correct_index,explanation) is distinct from ('A pool is created afresh for every invocation. What should be investigated?','["Whether all invocations share one physical session automatically", "Whether SQL now needs no authentication", "Whether this defeats reuse and multiplies connection demand", "Whether user count is exactly pool size"]'::jsonb,2,'Pool ownership and runtime lifecycle determine actual reuse.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-2-connection-pooling-application-new-9'; end if;
