update public.learning_topics set short_description='Follow connection acquisition, exclusive borrowing, transaction cleanup, release, queueing, and bounded capacity, while distinguishing user concurrency from active database work.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Follow connection acquisition, exclusive borrowing, transaction cleanup, release, queueing, and bounded capacity, while distinguishing user concurrency from active database work.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Connection Pooling.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-connection-pooling' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-connection-pooling-application','MCQ Test 2',category,10,10,'Application and scenarios for Connection Pooling.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-connection-pooling' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-1','pt-dbms-sql-2-connection-pooling','What does Connection Pooling maintain to avoid opening a new database connection for every request?','["A cache of query results", "A reusable pool of already-open database connections", "A backup copy of the entire database", "A list of all registered application users"]'::jsonb,1,'Connection pooling keeps a set of open connections ready to be borrowed and reused, rather than opening a fresh one per request.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-2','pt-dbms-sql-2-connection-pooling','In the illustrative portal, what configured pool capacity serves requests over time from 500 concurrent users?','["500, one per user", "20 shared, reusable connections", "1 single connection for everyone", "5,000 pre-opened connections"]'::jsonb,1,'The example uses twenty reusable sessions. It does not claim five hundred independent transactions run simultaneously on them.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-3','pt-dbms-sql-2-connection-pooling','What costly steps does connection pooling help an application avoid repeating for every request?','["Running the SQL query itself", "A fresh TCP handshake, database authentication, and session setup for each request", "Rendering the user interface", "Compiling the application code"]'::jsonb,1,'Pooling avoids repeatedly paying the overhead of establishing a brand-new physical connection (handshake, auth, session setup) per request.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-4','pt-dbms-sql-2-connection-pooling','Which capacity pressure can a shared pool reduce compared with opening a new database session for each request?','["The abstraction-leaking problem from Data Abstraction", "The two-tier connection-scaling bottleneck, where each client opened its own direct connection to the database", "The naming conflict problem between external schemas", "The lack of a conceptual schema in file-server systems"]'::jsonb,1,'A bounded reusable set can reduce repeated setup and direct session demand, while active work still needs capacity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-5','pt-dbms-sql-2-connection-pooling','Does connection pooling require a three-tier application with a shared middle tier?','["No; a local client process, an application server, or a supported proxy can manage pooling", "Yes; pooling is impossible inside a desktop process", "Yes; only browser interfaces can pool connections", "No; pooling is merely caching SQL result rows"]'::jsonb,0,'A shared middle tier is common but not necessary. Ownership, lifecycle, and supported semantics define the pool.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-6','pt-dbms-sql-2-connection-pooling','What happens when all connections in the pool are currently busy and a new request arrives?','["The request is always immediately and silently dropped with no configuration options", "The request must wait or fail depending on configuration — this is called pool exhaustion, requiring careful pool-size tuning", "A brand-new unlimited number of connections is automatically created", "The database server shuts down"]'::jsonb,1,'Pool exhaustion occurs when no pooled connection is free; behavior (wait vs. fail) depends on configuration, and correct pool sizing helps avoid it.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-7','pt-dbms-sql-2-connection-pooling','A connection is returned to the pool while it still has an uncommitted transaction open from the previous request. The next request borrows this same connection. What subtle bug can result?','["No bug is possible; pools always fully reset connections automatically", "The leftover uncommitted transaction or session state can silently affect the next request''s behavior", "The database server automatically detects and blocks this scenario in all cases", "The connection pool size automatically increases to compensate"]'::jsonb,1,'An unfinished transaction or stale session setting can affect later borrowers unless cleanup/reset semantics prevent it.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-connection-pooling-8','pt-dbms-sql-2-connection-pooling','A team sets their connection pool size extremely high, assuming ''more connections is always better'' for handling load. What real risk does this create?','["No risk; larger pools are always strictly better with no downside", "Each pooled connection consumes real server-side resources even while idle, so an oversized pool can overwhelm the database server itself", "It automatically fixes the leftover session state problem", "It converts the architecture from two-tier back to a file-server model"]'::jsonb,1,'Pooled connections still consume server memory and session resources even when idle, so oversized pools risk overwhelming the database server rather than only helping performance.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-new-9','pt-dbms-sql-2-connection-pooling','What is reused by a connection pool rather than a result cache?','["Only the rows from the last SELECT", "Database connection/session resources", "Only application HTML", "Only database backups"]'::jsonb,1,'Pooling avoids repeated connection setup; it does not automatically cache query results.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-new-10','pt-dbms-sql-2-connection-pooling','Why must ordinary transaction statements stay on the same borrowed connection?','["Every SQL statement must use a different user", "Pooling disables all transactions", "The transaction belongs to the session executing it", "Consecutive application calls always use one session automatically"]'::jsonb,2,'Independent pool convenience calls can select different sessions.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-1','pt-dbms-sql-2-connection-pooling-application','Four application instances each allow twenty pooled connections. What is their combined configured potential?','["Twenty connections in total", "Five connections in total", "Eighty connections before other clients", "Five hundred connections per user"]'::jsonb,2,'Per-instance limits add across the deployment.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-2','pt-dbms-sql-2-connection-pooling-application','A request acquires a connection and throws before release. What failure path needs correction?','["Changing the user''s display name", "Adding a second SELECT projection", "Deleting the database constraints", "Guaranteed cleanup of the borrowed resource"]'::jsonb,3,'Unreleased resources can exhaust the pool.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-3','pt-dbms-sql-2-connection-pooling-application','A request spends 900 ms waiting for acquisition and 10 ms running SQL. What does query time alone miss?','["Pool waiting dominates its latency", "The SQL necessarily took 910 ms", "The database returned no rows", "The connection must have been newly authenticated"]'::jsonb,0,'Measure acquisition separately from active query execution.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-4','pt-dbms-sql-2-connection-pooling-application','A transfer issues BEGIN and updates through independent pool.query calls. What must be verified?','["That each statement uses a new connection", "That all transaction statements use the intended single session", "That every account name is unique", "That the pool has no upper limit"]'::jsonb,1,'Sequential calls do not establish session affinity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-5','pt-dbms-sql-2-connection-pooling-application','All twenty connections are borrowed and a new acquisition arrives. What determines its behavior?','["The alphabetical order of table names", "The account balance column type alone", "The pool''s queue, timeout, and failure policy", "The browser''s screen width"]'::jsonb,2,'Exhaustion must have a configured, bounded handling policy.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-6','pt-dbms-sql-2-connection-pooling-application','A larger pool reduces waiting but overloads database CPU. What assumption failed?','["Idle connections can be reused", "Transactions have boundaries", "Queries consume server resources", "More concurrent sessions always improve throughput"]'::jsonb,3,'Concurrency competes for finite resources; tune total workload capacity.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-7','pt-dbms-sql-2-connection-pooling-application','A connection is lost around COMMIT. Why is blind retry unsafe?','["The caller may not know whether the first operation committed", "The new connection automatically restores the exact old session", "Every lost connection proves rollback", "A pool permanently disables commits"]'::jsonb,0,'Uncertain outcomes need a separate retry and deduplication strategy.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-8','pt-dbms-sql-2-connection-pooling-application','A previous borrower changed a session variable. What does the next borrower require?','["The same variable value by coincidence", "Documented cleanup or reset behavior for the session", "A larger result table", "A different SQL dialect for each query"]'::jsonb,1,'State can outlive one request unless the lifecycle removes or controls it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-9','pt-dbms-sql-2-connection-pooling-application','A pool is created afresh for every invocation. What should be investigated?','["Whether all invocations share one physical session automatically", "Whether SQL now needs no authentication", "Whether this defeats reuse and multiplies connection demand", "Whether user count is exactly pool size"]'::jsonb,2,'Pool ownership and runtime lifecycle determine actual reuse.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-connection-pooling-application-new-10','pt-dbms-sql-2-connection-pooling-application','A pool replaces a dead connection with a healthy new one. What is not automatically restored?','["The ability to send a new supported query", "The configured pool limit", "The existence of the database endpoint", "The old transaction and knowledge of an uncertain commit outcome"]'::jsonb,3,'A reconnect creates a new session; it does not resume arbitrary interrupted work.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- constraint-validation
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-10-sql-constraints/constraint-validation' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'constraint-validation'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'constraint-validation'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('efc8688464db3aee870982feaddf3872','eb43a483f1c8aa6a1babe3887a400cf7')) then raise exception 'Notes changed since seed; review before applying: %', 'constraint-validation'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-10-constraint-validation' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'constraint-validation'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-10-constraint-validation' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'constraint-validation'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-10-constraint-validation','pt-dbms-sql-10-constraint-validation-application')) then raise exception 'Extra topic tests require manual integration: %', 'constraint-validation'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-10-constraint-validation-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'constraint-validation'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Legacy inspection, ongoing enforcement and native staged validation are different claims", "description": "A clean report is an observation, while a constraint protects accepted writes; PostgreSQL backlog validation is a separately scoped feature.", "columns": ["Mechanism", "What is established", "What is not established"], "rows": [["Preflight SELECT", "Observed violations in the queried population", "Future write protection"], ["Enforced constraint", "Applicable accepted-state boundary", "Universal production performance"], ["PostgreSQL NOT VALID", "Applicable new-write checks with backlog not yet proven", "Transaction-end deferral"], ["Later validation", "Supported existing-state verification", "Automatic repair of incorrect facts"], ["Recorded local cases", "Synthetic results on the named engine", "Exact provider or applied-migration success"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'constraint-validation'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Legacy inspection, ongoing enforcement and native staged validation are different claims", "description": "A clean report is an observation, while a constraint protects accepted writes; PostgreSQL backlog validation is a separately scoped feature.", "columns": ["Mechanism", "What is established", "What is not established"], "rows": [["Preflight SELECT", "Observed violations in the queried population", "Future write protection"], ["Enforced constraint", "Applicable accepted-state boundary", "Universal production performance"], ["PostgreSQL NOT VALID", "Applicable new-write checks with backlog not yet proven", "Transaction-end deferral"], ["Later validation", "Supported existing-state verification", "Automatic repair of incorrect facts"], ["Recorded local cases", "Synthetic results on the named engine", "Exact provider or applied-migration success"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Legacy inspection, ongoing enforcement and native staged validation are different claims", "description": "A clean report is an observation, while a constraint protects accepted writes; PostgreSQL backlog validation is a separately scoped feature.", "columns": ["Mechanism", "What is established", "What is not established"], "rows": [["Preflight SELECT", "Observed violations in the queried population", "Future write protection"], ["Enforced constraint", "Applicable accepted-state boundary", "Universal production performance"], ["PostgreSQL NOT VALID", "Applicable new-write checks with backlog not yet proven", "Transaction-end deferral"], ["Later validation", "Supported existing-state verification", "Automatic repair of incorrect facts"], ["Recorded local cases", "Synthetic results on the named engine", "Exact provider or applied-migration success"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-10-constraint-validation' and id not in ('tq-dbms-sql-10-constraint-validation-1','tq-dbms-sql-10-constraint-validation-2','tq-dbms-sql-10-constraint-validation-3','tq-dbms-sql-10-constraint-validation-4','tq-dbms-sql-10-constraint-validation-5','tq-dbms-sql-10-constraint-validation-6','tq-dbms-sql-10-constraint-validation-7','tq-dbms-sql-10-constraint-validation-8','pt-dbms-sql-10-constraint-validation-new-9','pt-dbms-sql-10-constraint-validation-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-10-constraint-validation'; end if;
