if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-1' and test_id<>'pt-dbms-sql-10-constraint-validation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-10-constraint-validation-1'; end if;
