if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-1' and (question_text,options,correct_index,explanation) is distinct from ('By default, when is a CHECK constraint evaluated for a normal INSERT statement?','["Only when the table is queried afterward", "Immediately, at the moment the INSERT statement executes", "Only at the end of the transaction, regardless of constraint type", "Only when explicitly requested via VALIDATE CONSTRAINT"]'::jsonb,1,'Unless a constraint is explicitly declared deferrable and deferred (see PostgreSQL''s DEFERRABLE), every constraint is checked immediately at statement execution time by default.') and (question_text,options,correct_index,explanation) is distinct from ('By default, when is a CHECK constraint evaluated for a normal INSERT statement?','["Only when the table is queried afterward", "Immediately, at the moment the INSERT statement executes", "Only at the end of the transaction, regardless of constraint type", "Only when explicitly requested via VALIDATE CONSTRAINT"]'::jsonb,1,'Unless a constraint is explicitly declared deferrable and deferred (see PostgreSQL''s DEFERRABLE), every constraint is checked immediately at statement execution time by default.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-constraint-validation-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-2' and test_id<>'pt-dbms-sql-10-constraint-validation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-10-constraint-validation-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-2' and test_id='pt-dbms-sql-10-constraint-validation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-10-constraint-validation-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-2' and (question_text,options,correct_index,explanation) is distinct from ('What must be true before ALTER TABLE ... ADD CONSTRAINT succeeds on a table that already contains rows?','["The table must first be truncated", "Every existing row must already satisfy the new constraint''s rule", "The table must have fewer than 1000 rows", "Nothing; the constraint always applies only to future rows"]'::jsonb,1,'Adding a constraint to a populated table triggers an implicit validation scan of existing data; if any row violates the new rule, the ALTER TABLE fails.') and (question_text,options,correct_index,explanation) is distinct from ('What does ordinary validated constraint addition require of relevant current state?','["The table must first be truncated", "Compatibility with the intended rule under the actual engine\u2019s validation semantics", "The table must have fewer than 1000 rows", "Nothing; the constraint always applies only to future rows"]'::jsonb,1,'Rule kinds, NULL and supported staged forms need precise scope.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-constraint-validation-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-3' and test_id<>'pt-dbms-sql-10-constraint-validation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-10-constraint-validation-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-3' and test_id='pt-dbms-sql-10-constraint-validation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-10-constraint-validation-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-3' and (question_text,options,correct_index,explanation) is distinct from ('In PostgreSQL, what does adding a constraint with the NOT VALID option actually mean?','["The constraint is completely inactive until manually enabled", "The constraint is fully enforced for all new INSERT/UPDATE statements, but existing rows have not yet been checked", "The constraint only applies to SELECT statements", "NOT VALID constraints are automatically dropped after 24 hours"]'::jsonb,1,'NOT VALID skips the initial full-table scan of pre-existing rows for performance, but the constraint immediately governs all new writes; VALIDATE CONSTRAINT later confirms old rows comply.') and (question_text,options,correct_index,explanation) is distinct from ('What does PostgreSQL NOT VALID separate for an applicable constraint?','["The constraint is completely inactive until manually enabled", "The existing backlog validation from applicable ongoing checks for new writes", "The constraint only applies to SELECT statements", "NOT VALID constraints are automatically dropped after 24 hours"]'::jsonb,1,'It does not mean disabled enforcement or transaction-end deferral.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-constraint-validation-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-4' and test_id<>'pt-dbms-sql-10-constraint-validation') then raise exception 'Question ID collision: %', 'tq-dbms-sql-10-constraint-validation-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-4' and test_id='pt-dbms-sql-10-constraint-validation') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-10-constraint-validation-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-4' and (question_text,options,correct_index,explanation) is distinct from ('Why might a large production table use the ADD CONSTRAINT ... NOT VALID followed by VALIDATE CONSTRAINT pattern instead of a plain ADD CONSTRAINT?','["Because NOT VALID constraints run faster forever", "To avoid a long table lock caused by scanning every existing row in a single blocking operation", "Because plain ADD CONSTRAINT is deprecated", "Because VALIDATE CONSTRAINT is required by the SQL standard"]'::jsonb,1,'Splitting the operation lets the initial attach be fast with a brief lock, while the potentially slow full-table validation scan happens separately, reducing disruption on large, busy tables.') and (question_text,options,correct_index,explanation) is distinct from ('Why consider supported staged validation for a large table?','["Because NOT VALID constraints run faster forever", "To separate operational work under the documented locking and validation rules", "Because plain ADD CONSTRAINT is deprecated", "Because VALIDATE CONSTRAINT is required by the SQL standard"]'::jsonb,1,'It does not guarantee zero locks or eliminate all scans.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-constraint-validation-4'; end if;
