if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-constraint-validation-5' and (question_text,options,correct_index,explanation) is distinct from ('What kind of internal check does the engine effectively perform when adding a UNIQUE constraint to a populated table?','["A full table scan checking for NULLs only", "A duplicate-detection scan, conceptually similar to GROUP BY ... HAVING COUNT(*) > 1", "No check; UNIQUE constraints are never validated against existing data", "A check that the table has an index already"]'::jsonb,1,'Adding UNIQUE requires confirming no existing duplicate values are present, which is effectively a group-and-count duplicate detection scan performed internally by the engine.') and (question_text,options,correct_index,explanation) is distinct from ('What kind of internal check does the engine effectively perform when adding a UNIQUE constraint to a populated table?','["A full table scan checking for NULLs only", "A duplicate-detection scan, conceptually similar to GROUP BY ... HAVING COUNT(*) > 1", "No check; UNIQUE constraints are never validated against existing data", "A check that the table has an index already"]'::jsonb,1,'Adding UNIQUE requires confirming no existing duplicate values are present, which is effectively a group-and-count duplicate detection scan performed internally by the engine.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-constraint-validation-5'; end if;
