update public.learning_topics set short_description='Create a MySQL database with deliberate text defaults, understand session targeting and privileges, and detect configuration drift without assuming IF NOT EXISTS repairs it.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Create a MySQL database with deliberate text defaults, understand session targeting and privileges, and detect configuration drift without assuming IF NOT EXISTS repairs it.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for CREATE DATABASE.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-9-create-database' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-9-create-database-application','MCQ Test 2',category,10,10,'Application and scenarios for CREATE DATABASE.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-9-create-database' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-1','pt-dbms-sql-9-create-database','What does CREATE DATABASE establish in MySQL?','["To add a new column to an existing table", "A named database container with defaults for objects created within it", "To generate a new row of data", "To create an index on a table"]'::jsonb,1,'MySQL database and schema are synonymous; there is no extra required inner schema level.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-2','pt-dbms-sql-9-create-database','Which execution restriction applies to PostgreSQL CREATE DATABASE?','["It requires two-phase commit", "It cannot execute inside a transaction block", "It is deprecated syntax", "It always requires superuser privileges"]'::jsonb,1,'This is a product-defined execution restriction, not a general claim about every DDL implementation.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-3','pt-dbms-sql-9-create-database','What should precede a database-removal decision after a defaults mismatch?','["The database must contain at least one table", "A separate explicit review of the target, dependent data and operation consequences", "The database must be renamed first", "All tables must be truncated first"]'::jsonb,1,'A configuration mismatch does not authorize deletion; active-session restrictions differ by engine.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-4','pt-dbms-sql-9-create-database','In MySQL, what is the relationship between CREATE DATABASE and CREATE SCHEMA?','["CREATE SCHEMA creates a namespace inside a database created by CREATE DATABASE", "They are unrelated commands", "CREATE SCHEMA is only used for views", "They are exact synonyms — both create the same kind of object"]'::jsonb,3,'MySQL treats ''schema'' and ''database'' as synonyms, unlike PostgreSQL/SQL Server/Oracle where schema is a namespace inside a database.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-5','pt-dbms-sql-9-create-database','How can a MySQL connection target a newly created database for table creation?','["Nothing, tables can be created from any connection", "Restart the database server", "Select it with USE or use an appropriately qualified object name with the required privileges", "Grant themselves superuser rights"]'::jsonb,2,'CREATE DATABASE does not change the default database; a new connection is not inherently necessary.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-6','pt-dbms-sql-9-create-database','In MySQL, which clause avoids the already-existing-database error for guarded creation?','["CASCADE", "IF NOT EXISTS", "WITH CHECK OPTION", "ON CONFLICT"]'::jsonb,1,'The existing database is not reconciled with a changed proposed definition.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-7','pt-dbms-sql-9-create-database','Can MySQL join permitted tables in two databases on the same server using qualified names?','["JOIN syntax does not support more than one table", "Yes; appropriate database-qualified names and access can support this directly", "Databases cannot contain more than one table each", "SQL does not support JOIN at all"]'::jsonb,1,'Do not confuse MySQL database namespaces with PostgreSQL cross-database connectivity.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-create-database-8','pt-dbms-sql-9-create-database','A team creates a database on a case-insensitive Windows file system and later deploys the same script on a Linux server. What subtle issue can arise?','["Linux does not support CREATE DATABASE", "Database name case sensitivity differs between operating systems, potentially causing name-mismatch bugs", "SQL syntax differs entirely between operating systems", "Windows does not allow more than one database"]'::jsonb,1,'Case sensitivity of database names can differ by OS/file system, which is a real cross-environment migration pitfall.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-create-database-new-9','pt-dbms-sql-9-create-database','Does CREATE DATABASE also create a students table automatically?','["Yes, with default columns", "No", "Only if the name contains campus", "Only with utf8mb4"]'::jsonb,1,'Container creation and table definition are separate operations.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
