update public.learning_topics set short_description='Use view, logical, and physical abstraction to simplify database interfaces while preserving identity, units, missing-value meaning, access checks, and useful error information.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use view, logical, and physical abstraction to simplify database interfaces while preserving identity, units, missing-value meaning, access checks, and useful error information.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Data Abstraction.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-data-abstraction' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-data-abstraction-application','MCQ Test 2',category,10,10,'Application and scenarios for Data Abstraction.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-data-abstraction' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-1','pt-dbms-sql-2-data-abstraction','What is the general principle that Data Abstraction describes?','["Encrypting all stored data for security", "Hiding details not relevant at a given level and showing each audience only what it needs", "Compressing data to save disk space", "Replicating data across multiple servers"]'::jsonb,1,'Data abstraction is about controlling what level of detail is exposed to different audiences, hiding irrelevant complexity.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-2','pt-dbms-sql-2-data-abstraction','Which abstraction level presents task-specific information closest to the application consumer?','["Physical level", "Logical level", "View level", "Internal storage level"]'::jsonb,2,'The view level tailors information to a task; it should retain all distinctions the consumer needs.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-3','pt-dbms-sql-2-data-abstraction','In the bank account example, at which level is `Account(AccNo, Balance, CustomerID, BranchID, InterestRate)` with its constraints defined?','["View level", "Logical level", "Physical level", "Middleware level"]'::jsonb,1,'The full structural definition with constraints is a logical-level (conceptual schema) concern, sitting between view and physical detail.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-4','pt-dbms-sql-2-data-abstraction','How does the three-schema architecture (external/conceptual/internal) relate to the three levels of data abstraction (view/logical/physical)?','["They are unrelated concepts from different fields", "External corresponds to view, conceptual to logical, and internal to physical; the architecture applies the abstraction principle", "The three-schema architecture replaces the need for data abstraction entirely", "Data abstraction only applies to the internal schema"]'::jsonb,1,'The correspondences describe responsibilities, not a requirement for exactly three isolated software components.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-5','pt-dbms-sql-2-data-abstraction','Assuming routing and logical guarantees stay hidden behind the same account interface, why is hash-based shard placement a physical concern?','["Because sharding is a customer-facing feature that must be visible in the app", "Because sharding is a storage implementation detail irrelevant to what the customer needs to see, so it is abstracted away at the view level", "Because sharding changes the logical structure of the Account table", "Because sharding is only relevant to external schemas"]'::jsonb,1,'The scenario explicitly assumes transparent routing and preserved semantics; actual sharding requires product-specific review.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-6','pt-dbms-sql-2-data-abstraction','What would it mean for abstraction to ''leak through'' at the view level, based on the notes?','["A customer sees a clean, simple balance screen as intended", "A raw internal error code or a physical shard ID is shown directly to an end user", "The logical schema correctly hides physical storage details", "A DBA adjusts an index without notifying users"]'::jsonb,1,'Abstraction leaking is when detail meant to stay hidden at a lower level surfaces at a higher, less-detailed level, defeating the purpose of abstraction.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-7','pt-dbms-sql-2-data-abstraction','A mobile banking view shows ''0'' for an account balance regardless of whether the true stored value is 0 or NULL (no balance recorded yet). What problem does this illustrate?','["Correct abstraction, since users should never see NULL", "Over-abstracting: hiding the NULL-vs-zero distinction can mislead users into misinterpreting missing data as an actual zero balance", "A physical-level storage bug unrelated to abstraction", "A violation of the three-schema architecture''s mapping rules"]'::jsonb,1,'The notes explicitly warn that over-abstracting can hide meaningful distinctions, like NULL versus 0, that users legitimately need to see correctly.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-data-abstraction-8','pt-dbms-sql-2-data-abstraction','A junior developer argues that since the three-schema architecture already handles all necessary separation, the concept of ''data abstraction'' is redundant and can be ignored when designing a new external schema. What is the flaw in this reasoning?','["There is no flaw; abstraction and the three-schema architecture are unrelated", "Data abstraction is the underlying principle that justifies and guides how each schema level should hide detail; ignoring it risks designing schemas that leak irrelevant complexity to the wrong audience", "The three-schema architecture only applies to internal schemas, so abstraction is irrelevant to external schema design", "Data abstraction only matters for physical-level design, not external schemas"]'::jsonb,1,'Since each schema level is a direct application of data abstraction, ignoring the principle risks poor design choices, like exposing physical or logical detail that a given external schema''s audience does not need.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-new-9','pt-dbms-sql-2-data-abstraction','What is the danger of simplifying away currency labels?','["The database necessarily loses every index", "Consumers may combine amounts with incompatible units", "Account identifiers become dates", "NULL automatically becomes a currency"]'::jsonb,1,'A usable abstraction preserves units needed to interpret values.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-new-10','pt-dbms-sql-2-data-abstraction','Which distinction should an account perspective preserve in this example?','["The storage page address for every customer", "The raw internal exception name in every response", "Recorded zero versus no recorded balance", "The exact physical file offset"]'::jsonb,2,'A known zero and an absent measurement have different meanings.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-1','pt-dbms-sql-2-data-abstraction-application','Account 601 has Balance = 0; account 602 has Balance = NULL. Which status mapping is faithful?','["Both recorded zero", "Both not recorded", "601 recorded; 602 not recorded", "601 not recorded; 602 recorded"]'::jsonb,2,'IS NULL detects absence without confusing it with numeric zero.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-2','pt-dbms-sql-2-data-abstraction-application','A summary adds 100 INR to 20 USD and labels the total INR without conversion. What is wrong?','["It should have hidden both currencies", "Every addition is forbidden in SQL", "Only the index order is wrong", "It combined different units without a defined conversion"]'::jsonb,3,'A numeric sum across currencies lacks the claimed single-currency meaning.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-3','pt-dbms-sql-2-data-abstraction-application','A customer sees raw shard IDs in a storage failure message. What design issue is illustrated?','["Irrelevant implementation detail leaked into the task-facing interface", "The balance has necessarily changed", "A conceptual key was automatically deleted", "The customer has become a DBA"]'::jsonb,0,'The customer needs a useful failure description; authorized diagnostics can retain technical details.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-4','pt-dbms-sql-2-data-abstraction-application','A client supplies CustomerID and receives any requested customer''s accounts. Does projection alone enforce ownership?','["Yes; omitting InterestRate proves access", "No; actor-to-record access must be checked at a trusted boundary", "Yes; CustomerID is always secret", "Only page layout determines ownership"]'::jsonb,1,'A caller-controlled identifier is not evidence of authorization.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-5','pt-dbms-sql-2-data-abstraction-application','Two customers share a name. Which mapping avoids merging their accounts?','["Join all accounts on display name", "Group all rows by name and discard identity", "Relate accounts using the defined customer identifier", "Use name length as a key"]'::jsonb,2,'Identifiers preserve separate people even when labels repeat.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-6','pt-dbms-sql-2-data-abstraction-application','A report changes from one row per account to one row per customer and currency. What must the consumer understand?','["Only the background color", "Only the physical page count", "That accounts no longer have identifiers", "The new grain and aggregation meaning"]'::jsonb,3,'A summary row represents a different fact from an individual account row.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-7','pt-dbms-sql-2-data-abstraction-application','An operation fails a meaningful input rule. Should abstraction always replace the explanation with Unknown error?','["No; task-relevant rule feedback can remain actionable", "Yes; all error distinctions are implementation secrets", "Yes; validation must never be described", "Only raw stack traces are acceptable"]'::jsonb,0,'Abstraction hides irrelevant internals without suppressing useful explanations.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-8','pt-dbms-sql-2-data-abstraction-application','A new index changes encounter order for an unordered account query. Which requirement should the consumer make explicit?','["The disk sector for the first account", "The desired ORDER BY and any necessary tie-breaker", "The original insertion timestamp of every page", "The exact index name in every response"]'::jsonb,1,'Specify the logical sequence instead of depending on physical access.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-9','pt-dbms-sql-2-data-abstraction-application','An operator needs plan diagnostics while a customer needs an account summary. What does good abstraction allow?','["Only the customer can see every internal detail", "Diagnostics must be permanently deleted", "Different task-appropriate information under suitable access", "Every consumer must receive identical responses"]'::jsonb,2,'Different responsibilities justify different perspectives and access.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-data-abstraction-application-new-10','pt-dbms-sql-2-data-abstraction-application','After sharding, application code must choose a server for every account. Which original assumption no longer holds?','["Every account has an identifier", "The customer can read a name", "The model contains a balance attribute", "Placement is fully hidden behind the logical interface"]'::jsonb,3,'Server selection has become an application dependency rather than an invisible physical choice.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
