if exists(select 1 from public.dsa_problems where (id='dsa-dbms-sql-data-abstraction-balance-status' or slug='data-abstraction-balance-status') and (id<>'dsa-dbms-sql-data-abstraction-balance-status' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'dsa-dbms-sql-data-abstraction-balance-status'; end if;
if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-data-abstraction-balance-status' and description is distinct from 'Return account_id, balance, currency, balance_status. Use ''not recorded'' for NULL balances and ''recorded'' otherwise. Preserve the original balance and order by account_id. This is a teaching projection, not a banking ledger or an authorization policy.

**MySQL dialect.**

```sql
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);
INSERT INTO accounts VALUES (602,2,NULL,''INR''),(601,1,0.00,''INR''),(603,1,25.50,''USD'');
```

**Required ordering:** account_id ascending

**Edge cases:**
- Zero is recorded
- Negative balances remain recorded
- NULL stays NULL') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-data-abstraction-balance-status'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-data-abstraction-balance-status',null::text,'Preserve missing and zero balances','Easy','data-abstraction-balance-status','Return account_id, balance, currency, balance_status. Use ''not recorded'' for NULL balances and ''recorded'' otherwise. Preserve the original balance and order by account_id. This is a teaching projection, not a banking ledger or an authorization policy.

**MySQL dialect.**

```sql
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);
INSERT INTO accounts VALUES (602,2,NULL,''INR''),(601,1,0.00,''INR''),(603,1,25.50,''USD'');
```

**Required ordering:** account_id ascending

**Edge cases:**
- Zero is recorded
- Negative balances remain recorded
- NULL stays NULL','[{"input": "INSERT INTO accounts VALUES (602,2,NULL,''INR''),(601,1,0.00,''INR''),(603,1,25.50,''USD'');", "output": "account_id\tbalance\tcurrency\tbalance_status\n601\t0.00\tINR\trecorded\n602\tNULL\tINR\tnot recorded\n603\t25.50\tUSD\trecorded", "explanation": "The status describes missingness without replacing NULL or zero. Keeping currency preserves the unit needed to interpret each amount."}]'::jsonb,'[{"seed_sql": "INSERT INTO accounts VALUES (1,1,-4.25,''USD'');", "expected": "account_id\tbalance\tcurrency\tbalance_status\n1\t-4.25\tUSD\trecorded", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["account_id is unique", "NULL means no balance recorded in this teaching dataset", "Balances of zero and negative amounts are allowed"]'::jsonb,'["Use CASE with IS NULL", "Do not use balance = NULL"]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The status describes missingness without replacing NULL or zero. Keeping currency preserves the unit needed to interpret each amount.','{"sql": "SELECT account_id, balance, currency, CASE WHEN balance IS NULL THEN ''not recorded'' ELSE ''recorded'' END AS balance_status FROM accounts ORDER BY account_id;"}'::jsonb,'The status describes missingness without replacing NULL or zero. Keeping currency preserves the unit needed to interpret each amount.',array['sql'],'CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);','INSERT INTO accounts VALUES (602,2,NULL,''INR''),(601,1,0.00,''INR''),(603,1,25.50,''USD'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-2-data-abstraction' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='dsa-dbms-sql-data-abstraction-currency-summary' or slug='data-abstraction-currency-summary') and (id<>'dsa-dbms-sql-data-abstraction-currency-summary' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'dsa-dbms-sql-data-abstraction-currency-summary'; end if;
if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-data-abstraction-currency-summary' and description is distinct from 'Return one row per customer_id and currency with columns customer_id, currency, account_count, recorded_count, recorded_total. Count all accounts, count non-NULL balances, and sum only recorded balances. Keep recorded_total NULL when every balance is missing. Do not convert currencies or treat this teaching sum as an authoritative banking balance. Order by customer_id then currency.

**MySQL dialect.**

```sql
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);
INSERT INTO accounts VALUES (1,1,100.00,''INR''),(2,1,20.00,''USD''),(3,1,NULL,''INR''),(4,2,NULL,''USD''),(5,1,0.00,''USD'');
```

**Required ordering:** customer_id ascending, currency ascending

**Edge cases:**
- Do not combine different currencies
- All-missing groups retain a NULL total
- Zero counts as a recorded balance
- Multiple accounts contribute separately') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-data-abstraction-currency-summary'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-data-abstraction-currency-summary',null::text,'Summarize recorded amounts without mixing currencies','Medium','data-abstraction-currency-summary','Return one row per customer_id and currency with columns customer_id, currency, account_count, recorded_count, recorded_total. Count all accounts, count non-NULL balances, and sum only recorded balances. Keep recorded_total NULL when every balance is missing. Do not convert currencies or treat this teaching sum as an authoritative banking balance. Order by customer_id then currency.

**MySQL dialect.**

```sql
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);
INSERT INTO accounts VALUES (1,1,100.00,''INR''),(2,1,20.00,''USD''),(3,1,NULL,''INR''),(4,2,NULL,''USD''),(5,1,0.00,''USD'');
```

**Required ordering:** customer_id ascending, currency ascending

**Edge cases:**
- Do not combine different currencies
- All-missing groups retain a NULL total
- Zero counts as a recorded balance
- Multiple accounts contribute separately','[{"input": "INSERT INTO accounts VALUES (1,1,100.00,''INR''),(2,1,20.00,''USD''),(3,1,NULL,''INR''),(4,2,NULL,''USD''),(5,1,0.00,''USD'');", "output": "customer_id\tcurrency\taccount_count\trecorded_count\trecorded_total\n1\tINR\t2\t1\t100.00\n1\tUSD\t2\t2\t20.00\n2\tUSD\t1\t0\tNULL", "explanation": "The grouping preserves currency units. The two counts distinguish how many accounts exist from how many have recorded amounts, while SUM retains an all-missing total as NULL."}]'::jsonb,'[{"seed_sql": "INSERT INTO accounts VALUES (1,3,-5.00,''INR''),(2,3,0.00,''INR'');", "expected": "customer_id\tcurrency\taccount_count\trecorded_count\trecorded_total\n3\tINR\t2\t2\t-5.00", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["Each row is an account", "Currencies are explicit three-letter codes", "NULL denotes an unrecorded balance"]'::jsonb,'["Group by both customer_id and currency", "COUNT(*) and COUNT(balance) answer different questions", "SUM preserves NULL for an all-missing group"]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The grouping preserves currency units. The two counts distinguish how many accounts exist from how many have recorded amounts, while SUM retains an all-missing total as NULL.','{"sql": "SELECT customer_id, currency, COUNT(*) AS account_count, COUNT(balance) AS recorded_count, SUM(balance) AS recorded_total FROM accounts GROUP BY customer_id, currency ORDER BY customer_id, currency;"}'::jsonb,'The grouping preserves currency units. The two counts distinguish how many accounts exist from how many have recorded amounts, while SUM retains an all-missing total as NULL.',array['sql'],'CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT NOT NULL, balance DECIMAL(10,2) NULL, currency CHAR(3) NOT NULL);','INSERT INTO accounts VALUES (1,1,100.00,''INR''),(2,1,20.00,''USD''),(3,1,NULL,''INR''),(4,2,NULL,''USD''),(5,1,0.00,''USD'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-2-data-abstraction' on conflict(id) do nothing;
