if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-data-information-metadata-and-knowledge-3' and (question_text,options,correct_index,explanation) is distinct from ('Where is metadata typically stored in a relational DBMS?','["In system catalog tables such as information_schema", "Inside the application''s source code only", "In a separate spreadsheet maintained manually by end users", "It is never stored; it is recomputed each time it is needed"]'::jsonb,0,'Relational DBMSs store metadata in system catalog tables (like information_schema.columns) which the engine itself consults when parsing and optimizing queries.') and (question_text,options,correct_index,explanation) is distinct from ('Where is metadata typically stored in a relational DBMS?','["In system catalog tables such as information_schema", "Inside the application''s source code only", "In a separate spreadsheet maintained manually by end users", "It is never stored; it is recomputed each time it is needed"]'::jsonb,0,'Relational DBMSs store metadata in system catalog tables (like information_schema.columns) which the engine itself consults when parsing and optimizing queries.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-data-information-metadata-and-knowledge-3'; end if;
