if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-data-information-metadata-and-knowledge-7' and (question_text,options,correct_index,explanation) is distinct from ('A junior developer directly edits a row in a system catalog table instead of using ALTER TABLE to change a column''s type. What is the main risk?','["It can corrupt the database''s internal consistency because the catalog is special, DBMS-managed metadata, not ordinary application data", "There is no risk, since catalog tables are identical to regular tables", "It will automatically be reverted by the DBMS on the next commit", "It only affects the developer''s own session and no other users"]'::jsonb,0,'The notes warn against treating metadata like ordinary data — system catalogs are internally managed by the DBMS, and editing them directly can corrupt consistency between the schema and the engine''s understanding of it.') and (question_text,options,correct_index,explanation) is distinct from ('A junior developer directly edits a row in a system catalog table instead of using ALTER TABLE to change a column''s type. What is the main risk?','["It can corrupt the database''s internal consistency because the catalog is special, DBMS-managed metadata, not ordinary application data", "There is no risk, since catalog tables are identical to regular tables", "It will automatically be reverted by the DBMS on the next commit", "It only affects the developer''s own session and no other users"]'::jsonb,0,'The notes warn against treating metadata like ordinary data — system catalogs are internally managed by the DBMS, and editing them directly can corrupt consistency between the schema and the engine''s understanding of it.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-data-information-metadata-and-knowledge-7'; end if;
