update public.learning_topics set short_description='Distinguish data, information, metadata, and knowledge using a marks report; learn how definitions, data quality, and metadata drift affect interpretation.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish data, information, metadata, and knowledge using a marks report; learn how definitions, data quality, and metadata drift affect interpretation.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Data, Information, Metadata and Knowledge.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-data-information-metadata-and-knowledge' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-data-information-metadata-and-knowledge-application','MCQ Test 2',category,10,10,'Application and scenarios for Data, Information, Metadata and Knowledge.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-data-information-metadata-and-knowledge' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-1','pt-dbms-sql-1-data-information-metadata-and-knowledge','Which of the following is the best example of raw ''data'' with no context attached?','["The number 91 by itself", "\"Neha scored 91 marks in Computer Science\"", "A rule that low-attendance students fail more often", "The system catalog entry describing the marks column"]'::jsonb,0,'Data is an uninterpreted fact with no context; the number 91 alone carries no meaning until it is labeled or organized into information.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-2','pt-dbms-sql-1-data-information-metadata-and-knowledge','What best defines ''metadata'' in a DBMS?','["Data about data, describing structure, type, and rules of the stored data", "A processed and organized version of raw data", "A derived insight used to make a decision", "Any report generated from a database query"]'::jsonb,0,'Metadata describes the structure and constraints of data itself (e.g., column types and CHECK constraints), not the data values.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-3','pt-dbms-sql-1-data-information-metadata-and-knowledge','Where is metadata typically stored in a relational DBMS?','["In system catalog tables such as information_schema", "Inside the application''s source code only", "In a separate spreadsheet maintained manually by end users", "It is never stored; it is recomputed each time it is needed"]'::jsonb,0,'Relational DBMSs store metadata in system catalog tables (like information_schema.columns) which the engine itself consults when parsing and optimizing queries.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-4','pt-dbms-sql-1-data-information-metadata-and-knowledge','In the college example, what turns the class average of 81.6 into ''knowledge'' rather than just ''information''?','["Interpreting the number into an actionable insight, such as deciding to allocate more tutors", "Rounding the number to one decimal place", "Storing the number in a database instead of a spreadsheet", "Displaying the number on a dashboard"]'::jsonb,0,'Knowledge requires combining information with experience or rules to support a decision; merely displaying or storing a number keeps it at the level of information.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-5','pt-dbms-sql-1-data-information-metadata-and-knowledge','Why can ''garbage in, garbage out'' affect information but not the definition of data itself?','["Because information is derived from data, so inconsistent source data produces misleading reports even if well-formatted", "Because data is always automatically validated by the DBMS before use", "Because information is stored separately from data and cannot be affected by it", "Because metadata corrects any errors present in the underlying data"]'::jsonb,0,'Information is built from data, so if the underlying data is inconsistent or duplicated, the resulting information will be misleading even though it looks organized.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-6','pt-dbms-sql-1-data-information-metadata-and-knowledge','What is ''metadata drift'' as described in the notes?','["A schema change (renamed column, changed type) that is not reflected in documentation or downstream reports, causing silent misinterpretation", "A gradual increase in the number of rows in a metadata table", "The process of migrating metadata from one DBMS vendor to another", "A performance issue caused by too many indexes on a table"]'::jsonb,0,'Metadata drift occurs when the schema evolves but the metadata describing it (documentation, downstream assumptions) is not updated, so applications keep running but misinterpret meaning.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-7','pt-dbms-sql-1-data-information-metadata-and-knowledge','A junior developer directly edits a row in a system catalog table instead of using ALTER TABLE to change a column''s type. What is the main risk?','["It can corrupt the database''s internal consistency because the catalog is special, DBMS-managed metadata, not ordinary application data", "There is no risk, since catalog tables are identical to regular tables", "It will automatically be reverted by the DBMS on the next commit", "It only affects the developer''s own session and no other users"]'::jsonb,0,'The notes warn against treating metadata like ordinary data — system catalogs are internally managed by the DBMS, and editing them directly can corrupt consistency between the schema and the engine''s understanding of it.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-data-information-metadata-and-knowledge-8','pt-dbms-sql-1-data-information-metadata-and-knowledge','A dashboard shows "average marks: 81.6" with no interpretation of its significance. At which level is that displayed report?','["Information — it is organized and meaningful but has not yet been interpreted into an actionable decision", "Data — because averages are technically raw numbers", "Knowledge — because it is displayed on a dashboard", "Metadata — because it describes a column"]'::jsonb,0,'The notes distinguish information (organized, meaningful data) from knowledge (information interpreted into an action); an unacted-upon report is information, not yet knowledge.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-1-9','pt-dbms-sql-1-data-information-metadata-and-knowledge','Which detail is business metadata rather than a recorded exam result?','["One student''s attendance value of 82", "A mark of 91 in an exam row", "The rule that attendance is stored as a percentage", "The recorded submission timestamp for one answer"]'::jsonb,2,'The rule explains the meaning and unit of stored values rather than reporting one observation.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-1-10','pt-dbms-sql-1-data-information-metadata-and-knowledge','Must a decision already have been carried out before an interpreted insight can count as knowledge?','["Yes; only completed actions count", "No; a justified understanding can guide a future decision", "Yes; every chart is automatically knowledge", "No; every unexplained number is knowledge"]'::jsonb,1,'Interpretation and justified understanding matter; executing the resulting action is a separate step.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-1','pt-dbx2-data-information-metadata-and-knowledge-application','Five recorded marks are 80, 82, 78, 88, and 80. Which reported mean is correct?','["80.0", "81.6", "82.0", "408.0"]'::jsonb,1,'The sum is 408. Dividing by the five observations gives 81.6.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-2','pt-dbx2-data-information-metadata-and-knowledge-application','Three absent students have no recorded marks. What can the mean 81.6 safely describe?','["Every enrolled student without qualification", "The five recorded marks used in the calculation", "The marks the absent students would have received", "A guaranteed future class result"]'::jsonb,1,'The calculation describes its input population. Missing observations do not automatically become known scores.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-3','pt-dbx2-data-information-metadata-and-knowledge-application','A report still labels values as minutes after the application starts writing seconds. What failed?','["The producers and consumers no longer share the same measurement definition", "The numeric type necessarily rejected the data", "The average formula must always be wrong", "All values became NULL automatically"]'::jsonb,0,'A unit mismatch is metadata drift even when queries execute and values fit the column type.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-4','pt-dbx2-data-information-metadata-and-knowledge-application','A constraint accepts the value 88, but it was entered against the wrong student. What does this show?','["Range constraints never work", "The database established the observation as true", "A valid range does not prove the observation belongs to the correct person", "Metadata is irrelevant to quality"]'::jsonb,2,'Structural validation checks declared rules. It cannot independently establish every real-world fact.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-5','pt-dbx2-data-information-metadata-and-knowledge-application','An inventory tool counts column definitions as its input records. How should those definitions be classified?','["They are metadata about the application and data for the inventory task", "They cannot be stored anywhere", "They must be examination marks", "They are automatically managerial decisions"]'::jsonb,0,'Classification depends on the task: a description can itself be observed and processed as data.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-6','pt-dbx2-data-information-metadata-and-knowledge-application','A developer wants to change a column definition. Which approach matches the notes?','["Edit internal catalog rows directly", "Rename only the report label and assume the schema changed", "Use a supported schema-definition command", "Change an unrelated student mark"]'::jsonb,2,'Supported definition commands coordinate the database''s internal structures; direct catalog edits are unsafe or prohibited.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-7','pt-dbx2-data-information-metadata-and-knowledge-application','A correctly calculated average is based on duplicated observations. Which statement is justified?','["Correct arithmetic removes duplicates automatically", "A formatted dashboard guarantees reliable inputs", "Duplication never affects averages", "The arithmetic can be correct while the report is misleading"]'::jsonb,3,'Calculation correctness and source-data quality are separate concerns. Duplicate observations can change the result.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-8','pt-dbx2-data-information-metadata-and-knowledge-application','A chart displays the five-student mean but gives no explanation of its significance. What has it supplied?','["Information organized around the recorded marks", "A demonstrated causal explanation", "A new column constraint", "Proof that every student mastered the subject"]'::jsonb,0,'A chart communicates organized data. Conclusions about meaning require additional reasoning and evidence.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-9','pt-dbx2-data-information-metadata-and-knowledge-application','Two exports both contain a column called attendance. What should a reader check before comparing them?','["Only whether their filenames have equal length", "Whether the numbers are printed in bold", "Whether both exports use the same background color", "Their units, populations, dates, and measurement definitions"]'::jsonb,3,'Matching names do not establish matching meanings. Comparable measurements need compatible definitions.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-data-information-metadata-and-knowledge-2-10','pt-dbx2-data-information-metadata-and-knowledge-application','An analyst finds a recurring assessment difficulty and explains why extra practice may help. What distinguishes this from a bare average?','["The report has a larger font", "The analyst has interpreted information into a reasoned, usable understanding", "The values are now integers", "The data no longer needs quality checks"]'::jsonb,1,'Knowledge adds a justified interpretation that can guide action. It does not eliminate uncertainty or data-quality work.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- data-types
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-8-sql-fundamentals/data-types' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'data-types'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'data-types'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('c0ef5e50bea1c9fd418fb523ee5d415c','6fb1c2413a5a8ef0fced467a02f9d5dc')) then raise exception 'Notes changed since seed; review before applying: %', 'data-types'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-data-types' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'data-types'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-data-types' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'data-types'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-8-data-types','pt-dbms-sql-8-data-types-application')) then raise exception 'Extra topic tests require manual integration: %', 'data-types'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-data-types-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'data-types'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Supply attributes and the facts their types preserve", "description": "Type choices work with explicit domain rules. Exact decimals do not establish currency, and a numeric-looking code can still be a text identifier.", "columns": ["Attribute", "Representation", "Meaning to preserve"], "rows": [["product_id", "Integer key", "Stable identity, not an amount"], ["product_code", "VARCHAR", "Leading zeros are part of a label"], ["unit_price", "DECIMAL with stated scale", "Exact amount in the defined currency"], ["stock_qty", "Integer, optionally NULL", "Whole count; unrecorded differs from zero"], ["introduced_on", "Appropriate temporal type", "Calendar/time meaning under a defined policy"], ["active", "Small integer plus 0/1 rule", "Only the intended two-state domain"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'data-types'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Supply attributes and the facts their types preserve", "description": "Type choices work with explicit domain rules. Exact decimals do not establish currency, and a numeric-looking code can still be a text identifier.", "columns": ["Attribute", "Representation", "Meaning to preserve"], "rows": [["product_id", "Integer key", "Stable identity, not an amount"], ["product_code", "VARCHAR", "Leading zeros are part of a label"], ["unit_price", "DECIMAL with stated scale", "Exact amount in the defined currency"], ["stock_qty", "Integer, optionally NULL", "Whole count; unrecorded differs from zero"], ["introduced_on", "Appropriate temporal type", "Calendar/time meaning under a defined policy"], ["active", "Small integer plus 0/1 rule", "Only the intended two-state domain"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Supply attributes and the facts their types preserve", "description": "Type choices work with explicit domain rules. Exact decimals do not establish currency, and a numeric-looking code can still be a text identifier.", "columns": ["Attribute", "Representation", "Meaning to preserve"], "rows": [["product_id", "Integer key", "Stable identity, not an amount"], ["product_code", "VARCHAR", "Leading zeros are part of a label"], ["unit_price", "DECIMAL with stated scale", "Exact amount in the defined currency"], ["stock_qty", "Integer, optionally NULL", "Whole count; unrecorded differs from zero"], ["introduced_on", "Appropriate temporal type", "Calendar/time meaning under a defined policy"], ["active", "Small integer plus 0/1 rule", "Only the intended two-state domain"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-8-data-types' and id not in ('tq-dbms-sql-8-data-types-1','tq-dbms-sql-8-data-types-2','tq-dbms-sql-8-data-types-3','tq-dbms-sql-8-data-types-4','tq-dbms-sql-8-data-types-5','tq-dbms-sql-8-data-types-6','tq-dbms-sql-8-data-types-7','tq-dbms-sql-8-data-types-8','pt-dbms-sql-8-data-types-new-9','pt-dbms-sql-8-data-types-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-8-data-types'; end if;
