if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-1' and (question_text,options,correct_index,explanation) is distinct from ('Which data type family is correct for storing monetary amounts that must be exact?','["FLOAT", "DOUBLE", "DECIMAL/NUMERIC", "BOOLEAN"]'::jsonb,2,'DECIMAL/NUMERIC provide exact fixed-point arithmetic, avoiding the rounding errors inherent to binary floating point.') and (question_text,options,correct_index,explanation) is distinct from ('Which data type family is correct for storing monetary amounts that must be exact?','["FLOAT", "DOUBLE", "DECIMAL/NUMERIC", "BOOLEAN"]'::jsonb,2,'DECIMAL/NUMERIC provide exact fixed-point arithmetic, avoiding the rounding errors inherent to binary floating point.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-data-types-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-2' and test_id<>'pt-dbms-sql-8-data-types') then raise exception 'Question ID collision: %', 'tq-dbms-sql-8-data-types-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-2' and test_id='pt-dbms-sql-8-data-types') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-8-data-types-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-2' and (question_text,options,correct_index,explanation) is distinct from ('What is the key difference between CHAR(n) and VARCHAR(n)?','["They are exactly identical in every way", "CHAR is fixed-length and pads shorter values with trailing spaces; VARCHAR is variable-length up to n", "VARCHAR always uses more storage than CHAR for any value", "CHAR can only store numbers"]'::jsonb,1,'CHAR(n) always occupies n characters, space-padding shorter values; VARCHAR(n) stores only what''s needed, up to n.') and (question_text,options,correct_index,explanation) is distinct from ('Which description is accurate for MySQL CHAR and VARCHAR?','["They are exactly identical in every way", "CHAR has fixed-length/padding semantics; VARCHAR stores variable-length values within its declared limit", "VARCHAR always uses more storage than CHAR for any value", "CHAR can only store numbers"]'::jsonb,1,'Byte storage and trailing-space behavior require the actual type, character set, and collation context.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-data-types-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-3' and test_id<>'pt-dbms-sql-8-data-types') then raise exception 'Question ID collision: %', 'tq-dbms-sql-8-data-types-3'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-3' and test_id='pt-dbms-sql-8-data-types') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-8-data-types-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-3' and (question_text,options,correct_index,explanation) is distinct from ('Why is FLOAT/DOUBLE considered risky for storing currency?','["They cannot store numbers larger than 100", "Binary floating-point representation causes rounding errors (e.g. 0.1 + 0.2 not being exactly 0.3), which is unacceptable for money", "They are slower than DECIMAL in every single database", "FLOAT columns cannot be compared with WHERE clauses"]'::jsonb,1,'Floating-point''s binary approximation of decimal fractions causes small but real rounding errors that compound in financial calculations.') and (question_text,options,correct_index,explanation) is distinct from ('Why is FLOAT/DOUBLE considered risky for storing currency?','["They cannot store numbers larger than 100", "Binary floating-point representation causes rounding errors (e.g. 0.1 + 0.2 not being exactly 0.3), which is unacceptable for money", "They are slower than DECIMAL in every single database", "FLOAT columns cannot be compared with WHERE clauses"]'::jsonb,1,'Floating-point''s binary approximation of decimal fractions causes small but real rounding errors that compound in financial calculations.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-data-types-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-4' and test_id<>'pt-dbms-sql-8-data-types') then raise exception 'Question ID collision: %', 'tq-dbms-sql-8-data-types-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-4' and test_id='pt-dbms-sql-8-data-types') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-8-data-types-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-data-types-4' and (question_text,options,correct_index,explanation) is distinct from ('What is lost by storing a date as a plain VARCHAR string instead of a DATE type?','["Nothing is lost; strings and DATE behave identically in every respect", "Correct chronological sorting (if formats/lengths vary) and the ability to use date-arithmetic functions", "The ability to display the date at all", "The column becomes impossible to index"]'::jsonb,1,'String sorting is lexicographic, not chronological, once formats vary, and string columns don''t support date-arithmetic functions.') and (question_text,options,correct_index,explanation) is distinct from ('What risk arises when calendar dates are stored as inconsistently formatted VARCHAR values?','["Nothing is lost; strings and DATE behave identically in every respect", "Text ordering may not be chronological, and date operations require additional conversion assumptions", "The ability to display the date at all", "The column becomes impossible to index"]'::jsonb,1,'Date functions can convert suitable text. The problem is an unclear typed contract and mixed-format conversion risk, not a universal inability to calculate dates.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-data-types-4'; end if;
