 DECIMAL(8,2) NOT NULL CHECK (unit_price >= 0), stock_qty INT NULL CHECK (stock_qty >= 0)) DEFAULT CHARACTER SET utf8mb4;','INSERT INTO supplies VALUES (1,''0017'',''Café'',12.50,3),(2,''0002'',''工具'',2.00,0),(3,''0003'',''Box'',5.00,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-8-data-types' on conflict(id) do nothing;
