insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-administrator-2-9','pt-dbx2-database-administrator-application','A temporary administrative task finishes. What should be reviewed?','["Whether every temporary grant should be permanent", "Whether its access grant is still needed", "Whether all users now need identical privileges", "Whether the application should stop validating requests"]'::jsonb,1,'Access should follow the continuing responsibility and end when the purpose no longer justifies it.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
