update public.learning_topics set short_description='Understand the difference between a database and DBMS, shared constraints, transactions, server instances, replicas, and the limits of automatic correctness.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand the difference between a database and DBMS, shared constraints, transactions, server instances, replicas, and the limits of automatic correctness.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Database and DBMS.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-database-and-dbms' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-database-and-dbms-application','MCQ Test 2',category,10,10,'Application and scenarios for Database and DBMS.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-database-and-dbms' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-1','pt-dbms-sql-1-database-and-dbms','Which statement correctly distinguishes a database from a DBMS?','["The database is the organized collection of data; the DBMS is the software that manages and controls access to it", "The database and DBMS are two names for the exact same thing", "The DBMS is the data; the database is the software", "A database can only exist if it is stored in a spreadsheet"]'::jsonb,0,'The notes define the database as the data itself and the DBMS as the software layer used to define, query, update, and protect that data.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-2','pt-dbms-sql-1-database-and-dbms','According to the college example, what capability does introducing a DBMS like PostgreSQL add over a folder of CSV files?','["Constraint enforcement, such as rejecting an invalid department_id via a foreign key", "Automatic translation of English text into SQL", "Removal of the need for any schema at all", "Guaranteed elimination of all future business rule changes"]'::jsonb,0,'The notes describe how a DBMS enforces constraints like FOREIGN KEY and UNIQUE automatically, which plain CSV files cannot do on their own.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-3','pt-dbms-sql-1-database-and-dbms','Which of these is given as an example of DBMS software in the notes?','["PostgreSQL", "Microsoft Word", "A folder of CSV files", "A printed library catalog card"]'::jsonb,0,'The notes explicitly list PostgreSQL, MySQL, Oracle, and SQL Server as examples of DBMS software.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-4','pt-dbms-sql-1-database-and-dbms','Why is a folder of CSV files not considered a reliable substitute for a DBMS-managed database?','["It offers no built-in protection against concurrent writers corrupting a file and no real query language", "CSV files cannot store numbers, only text", "CSV files are always slower than any DBMS regardless of size", "CSV files require a paid license to use"]'::jsonb,0,'The notes state that flat files lack concurrency protection and a proper query language, unlike a DBMS which manages both.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-5','pt-dbms-sql-1-database-and-dbms','Which statement accurately describes a document-store DBMS such as MongoDB?','["It organizes records as documents, often with flexible schemas; consistency and transaction support depend on the product and configuration", "MongoDB is not considered a DBMS at all", "Relational DBMSs cannot enforce any constraints", "Document stores always run faster than relational databases in every scenario"]'::jsonb,0,'A document data model does not by itself determine consistency, validation or transaction guarantees. Evaluate those properties for the actual product and configuration.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-6','pt-dbms-sql-1-database-and-dbms','In a replication setup where one logical database is served by a primary server and a replica server, what pitfall do the notes warn about?','["Confusing ''the database'' (the data) with ''the DBMS instance'' (the running server process), which can cause confusion during backup or failover planning", "The replica server can never contain any of the same data as the primary", "Replication is only possible with document-oriented DBMSs", "A DBMS instance cannot be restarted once it is running"]'::jsonb,0,'The notes specifically warn against conflating the logical database with a particular running DBMS instance, since one database can be served by multiple instances.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-7','pt-dbms-sql-1-database-and-dbms','A team enforces no foreign keys or check constraints in their schema, then complains that ''the DBMS let bad data in.'' What does the notes'' final pitfall say about this situation?','["A DBMS enforces only the rules it is explicitly told about; it cannot invent missing business rules that were never modeled as constraints", "This is impossible, since all DBMSs enforce every business rule automatically", "The DBMS is broken and should be replaced", "Only NoSQL databases have this limitation, not relational ones"]'::jsonb,0,'The notes explicitly state that a DBMS cannot guarantee correctness of rules that were never defined as constraints; it only enforces what it has been told.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-and-dbms-8','pt-dbms-sql-1-database-and-dbms','Which analogy does the notes use to explain the database-versus-DBMS relationship?','["The database is like a library''s collection of books; the DBMS is like the librarian and catalog system that manages access to them", "The database is the building; the DBMS is the electricity powering it", "The database is the customer; the DBMS is the product", "The database is the internet; the DBMS is a web browser"]'::jsonb,0,'The notes use the library analogy: the collection of books represents the database, and the librarian plus catalog system represents the DBMS managing it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-1-9','pt-dbms-sql-1-database-and-dbms','Which statement about a declared foreign key is accurate?','["It infers every admission policy automatically", "It can enforce a stored relationship but cannot prove the real-world assignment is factually correct", "It removes the need for application validation", "It guarantees all reports use current definitions"]'::jsonb,1,'The DBMS enforces the modeled relationship. Assigning an existing but wrong department can still satisfy that relationship.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-1-10','pt-dbms-sql-1-database-and-dbms','Which item belongs to the operational responsibilities of a DBMS-managed application?','["Assuming replicas replace all backups", "Avoiding all error handling", "Letting every reader modify marks", "Testing its backup and recovery process"]'::jsonb,3,'Recovery must be configured and tested. A product offering recovery facilities does not establish that a deployment can recover correctly.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-1','pt-dbx2-database-and-dbms-application','A student row references a department identifier that does not exist. Which declared rule directly addresses this?','["A larger font in the student form", "A foreign key to the department identifier", "An index on an unrelated comment", "An export filename containing today''s date"]'::jsonb,1,'A foreign key checks that a referenced key exists, subject to its declared NULL rules.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-2','pt-dbx2-database-and-dbms-application','Two teachers overwrite each other''s updates to a shared CSV. What responsibility is missing from the file format itself?','["Coordinated concurrent updates", "The ability to represent text", "The ability to store commas", "An obligatory paid license"]'::jsonb,0,'CSV specifies a data representation, not a concurrency-control protocol.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-3','pt-dbx2-database-and-dbms-application','A MySQL server process is restarted without restoring files from backup. What has happened?','["A new business policy was inferred", "The DBMS instance has restarted using its persistent data and recovery facilities", "Every logical database was necessarily deleted", "A backup restore was necessarily completed"]'::jsonb,1,'Restarting running software differs from reconstructing a database from a backup.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-4','pt-dbx2-database-and-dbms-application','A team replaces a relational DBMS with a document DBMS. Which conclusion is justified without further details?','["Transactions are now always impossible", "The logical organization and supported facilities must be evaluated for that product", "All data is now eventually consistent in every operation", "The application no longer expects any record structure"]'::jsonb,1,'Data model, consistency, validation and transactions are separate properties that require product-specific evaluation.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-5','pt-dbx2-database-and-dbms-application','A registration number must occur at most once in the student table. Which facility expresses that rule?','["A replica on another machine alone", "A report sorted by registration number", "A unique constraint on the registration number", "A second CSV containing the same records"]'::jsonb,2,'Uniqueness is a declared integrity rule. Replication and sorting do not establish it.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-6','pt-dbx2-database-and-dbms-application','A replica serves a slightly older course list than the primary. Which explanation is plausible?','["Replicas cannot hold any copy of primary data", "All DBMS products forbid replication", "A logical database must occupy exactly one server", "Replication lag can delay the replica''s view of committed changes"]'::jsonb,3,'A replicated dataset can be served by multiple instances with freshness depending on the replication setup.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-7','pt-dbx2-database-and-dbms-application','A database rejects invalid department references but accepts a valid department chosen for the wrong student. Why?','["The structural constraint cannot independently determine the correct real-world choice", "The constraint necessarily failed", "A department key proves the student''s whole history", "The DBMS automatically verified the choice with staff"]'::jsonb,0,'Existence and factual correctness are different. Additional validation or review may be required.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-8','pt-dbx2-database-and-dbms-application','A team wants to replace its database backup with a live replica. Which response matches the notes?','["Any replica is automatically a complete backup strategy", "Backups are unnecessary once SQL is used", "A DBMS cannot support either facility", "Replication and backup address different risks and must be evaluated separately"]'::jsonb,3,'A replica can also receive unwanted changes. Recovery requirements need a suitable, tested backup process.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-9','pt-dbx2-database-and-dbms-application','A tiny list has one editor and no shared-update requirements. What is the sensible tool-selection approach?','["Always require the largest possible database cluster", "Always forbid files regardless of requirements", "Compare its responsibilities and costs before choosing a file or DBMS", "Choose only by the length of the product name"]'::jsonb,2,'A DBMS is useful when its facilities match the workload. Simpler tools can be appropriate for simpler responsibilities.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-and-dbms-2-10','pt-dbx2-database-and-dbms-application','A portal needs to reserve a seat and record a related payment reference together. What should the application design specify?','["Appropriate transaction boundaries and failure handling", "Only the color of the confirmation message", "An assumption that the DBMS guesses the intended grouping", "A rule permitting every user to alter payments"]'::jsonb,0,'Transactions group changes, but the application must define the grouping and handle failures correctly.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- database-apis
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-2-dbms-architecture/database-apis' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'database-apis'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'database-apis'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('71c7e09b37be87da892c604502a63d71','f5bf8b18e1469ae14e28b100a17af99e')) then raise exception 'Notes changed since seed; review before applying: %', 'database-apis'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-2-database-apis' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'database-apis'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-2-database-apis' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'database-apis'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-2-database-apis','pt-dbms-sql-2-database-apis-application')) then raise exception 'Extra topic tests require manual integration: %', 'database-apis'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-2-database-apis-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'database-apis'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Database API calls and the contracts behind them", "description": "These are responsibilities, not a mandatory five-process stack. Exact methods and supported behavior depend on the selected API implementation.", "columns": ["Operation", "Caller responsibility", "Common confusion"], "rows": [["Connect / borrow", "Own or release the resource through the supported lifecycle", "A context always physically closes a pooled connection"], ["Execute", "Bind values and preserve trusted authorization", "Parameters prove record ownership"], ["Fetch", "Distinguish empty rows, NULL values, and failures", "No row means a zero score"], ["Commit / rollback", "Use the intended session and handle uncertainty", "A lost commit response proves no effect"], ["Cleanup", "Release cursors and connections on every path", "Pooling repairs every leaked borrower"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'database-apis'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Database API calls and the contracts behind them", "description": "These are responsibilities, not a mandatory five-process stack. Exact methods and supported behavior depend on the selected API implementation.", "columns": ["Operation", "Caller responsibility", "Common confusion"], "rows": [["Connect / borrow", "Own or release the resource through the supported lifecycle", "A context always physically closes a pooled connection"], ["Execute", "Bind values and preserve trusted authorization", "Parameters prove record ownership"], ["Fetch", "Distinguish empty rows, NULL values, and failures", "No row means a zero score"], ["Commit / rollback", "Use the intended session and handle uncertainty", "A lost commit response proves no effect"], ["Cleanup", "Release cursors and connections on every path", "Pooling repairs every leaked borrower"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Database API calls and the contracts behind them", "description": "These are responsibilities, not a mandatory five-process stack. Exact methods and supported behavior depend on the selected API implementation.", "columns": ["Operation", "Caller responsibility", "Common confusion"], "rows": [["Connect / borrow", "Own or release the resource through the supported lifecycle", "A context always physically closes a pooled connection"], ["Execute", "Bind values and preserve trusted authorization", "Parameters prove record ownership"], ["Fetch", "Distinguish empty rows, NULL values, and failures", "No row means a zero score"], ["Commit / rollback", "Use the intended session and handle uncertainty", "A lost commit response proves no effect"], ["Cleanup", "Release cursors and connections on every path", "Pooling repairs every leaked borrower"]]}]'::jsonb;
