if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-1' and test_id<>'pt-dbms-sql-2-database-apis') then raise exception 'Question ID collision: %', 'tq-dbms-sql-2-database-apis-1'; end if;
