if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a Database API?','["The physical file format used to store table data", "A standardized set of functions applications call to connect, query, fetch results, and manage transactions without knowing the vendor''s native protocol", "A specific vendor''s wire protocol implementation", "A tool for physically indexing database records"]'::jsonb,1,'A database API is the standardized interface layer applications use, independent of the underlying vendor protocol.') and (question_text,options,correct_index,explanation) is distinct from ('What is a database API?','["The physical file format used to store table data", "A defined calling contract for database access operations such as connections, statements, results, transactions, and cleanup", "A specific vendor''s wire protocol implementation", "A tool for physically indexing database records"]'::jsonb,1,'APIs can support remote services or embedded databases; not all are identical standards.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-2' and test_id<>'pt-dbms-sql-2-database-apis') then raise exception 'Question ID collision: %', 'tq-dbms-sql-2-database-apis-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-2' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-2' and (question_text,options,correct_index,explanation) is distinct from ('Which of these is given as an example of a database API?','["B+-tree indexing", "Python''s DB-API (e.g., via psycopg2)", "TCP/IP", "A connection pool"]'::jsonb,1,'Python''s DB-API is explicitly listed as an example of a standardized database API, alongside ODBC, JDBC, and ADO.NET.') and (question_text,options,correct_index,explanation) is distinct from ('Which of these is given as an example of a database API?','["B+-tree indexing", "Python''s DB-API (e.g., via psycopg2)", "TCP/IP", "A connection pool"]'::jsonb,1,'Python''s DB-API is explicitly listed as an example of a standardized database API, alongside ODBC, JDBC, and ADO.NET.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-2'; end if;
