if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-3' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-3' and (question_text,options,correct_index,explanation) is distinct from ('In the layered stack described, what sits directly beneath the Database API and does the actual vendor-specific translation?','["The application''s user interface", "The Driver", "The conceptual schema", "The external schema"]'::jsonb,1,'The driver (2.13) is the layer directly beneath the API responsible for vendor-specific protocol translation.') and (question_text,options,correct_index,explanation) is distinct from ('In the layered stack described, what sits directly beneath the Database API and does the actual vendor-specific translation?','["The application''s user interface", "The Driver", "The conceptual schema", "The external schema"]'::jsonb,1,'The driver (2.13) is the layer directly beneath the API responsible for vendor-specific protocol translation.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-4' and test_id<>'pt-dbms-sql-2-database-apis') then raise exception 'Question ID collision: %', 'tq-dbms-sql-2-database-apis-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-4' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-4' and (question_text,options,correct_index,explanation) is distinct from ('In the layered stack Application → API → Driver → Middleware → Database Server, what does the API standardize, specifically?','["Which physical disk the data is stored on", "What functions the application calls (e.g., execute, fetchall), regardless of which database is underneath", "How many connections are pooled at once", "The specific wire protocol bytes sent to the database"]'::jsonb,1,'The API standardizes the calling contract (what functions exist and how they''re used); the driver handles how those calls become vendor-specific protocol messages.') and (question_text,options,correct_index,explanation) is distinct from ('Do Application, API, Driver, Middleware, and Database always form one mandatory fixed deployment order?','["Which physical disk the data is stored on", "No; the API specifies calls, implementations provide access, and optional middleware can occupy different positions", "How many connections are pooled at once", "The specific wire protocol bytes sent to the database"]'::jsonb,1,'Some layers are specifications or libraries rather than separate processes. An embedded database may have no remote server.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-5' and test_id<>'pt-dbms-sql-2-database-apis') then raise exception 'Question ID collision: %', 'tq-dbms-sql-2-database-apis-5'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-5' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-5'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-5' and (question_text,options,correct_index,explanation) is distinct from ('Why does the same Python DB-API pattern (connect/cursor/execute/fetchall) work whether the backend is PostgreSQL, MySQL, or SQLite?','["Because all three databases use identical internal storage", "Because the API is a stable, standardized contract, while the driver underneath handles the vendor-specific translation for each backend", "Because SQLite, MySQL, and PostgreSQL are actually the same software", "Because middleware is required for this pattern to work at all"]'::jsonb,1,'The API layer''s stability across vendors comes from drivers absorbing the vendor-specific differences beneath it.') and (question_text,options,correct_index,explanation) is distinct from ('What can remain familiar across Python DB-API implementations despite backend differences?','["Because all three databases use identical internal storage", "The general connection/cursor/execution/fetching pattern, while implementation details still need review", "Because SQLite, MySQL, and PostgreSQL are actually the same software", "Because middleware is required for this pattern to work at all"]'::jsonb,1,'A similar pattern does not guarantee identical placeholders, SQL, types, or optional features.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-5'; end if;
