if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-6' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-6' and (question_text,options,correct_index,explanation) is distinct from ('What resource-management problem can occur if an application obtains cursors/connections through the API but never closes them?','["No problem; the API automatically closes everything instantly", "Resource leaks on the server side, which connection pooling is designed to help mitigate", "The conceptual schema becomes corrupted", "The driver is automatically uninstalled"]'::jsonb,1,'Failing to close cursors/connections leaks server-side resources; pooling helps manage and reclaim connections more centrally than leaving it purely to caller discipline.') and (question_text,options,correct_index,explanation) is distinct from ('What can happen when borrowed connections and cursor resources are never released?','["No problem; the API automatically closes everything instantly", "Resources can leak and pool acquisitions can exhaust; pooling does not automatically repair the leak", "The conceptual schema becomes corrupted", "The driver is automatically uninstalled"]'::jsonb,1,'Cleanup must cover success, exceptions, and early returns.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-6'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-7' and test_id<>'pt-dbms-sql-2-database-apis') then raise exception 'Question ID collision: %', 'tq-dbms-sql-2-database-apis-7'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-7' and test_id='pt-dbms-sql-2-database-apis') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-database-apis-7'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-apis-7' and (question_text,options,correct_index,explanation) is distinct from ('A developer uses a standard DB-API `execute()` call, but embeds a vendor-specific SQL function (only supported by one database) inside the query string. Is this application fully portable across database vendors?','["Yes, because the API call itself is standard, so portability is guaranteed", "No, because while the API call is portable, the vendor-specific SQL syntax inside the query string is not, so true portability requires both a standard API and portable SQL", "No, because DB-API only works with one specific vendor", "Yes, but only if middleware is also used"]'::jsonb,1,'The notes explicitly warn that a standard API call does not make arbitrary embedded vendor-specific SQL portable — both the API and the SQL itself need to be portable.') and (question_text,options,correct_index,explanation) is distinct from ('A developer uses a standard DB-API `execute()` call, but embeds a vendor-specific SQL function (only supported by one database) inside the query string. Is this application fully portable across database vendors?','["Yes, because the API call itself is standard, so portability is guaranteed", "No, because while the API call is portable, the vendor-specific SQL syntax inside the query string is not, so true portability requires both a standard API and portable SQL", "No, because DB-API only works with one specific vendor", "Yes, but only if middleware is also used"]'::jsonb,1,'The notes explicitly warn that a standard API call does not make arbitrary embedded vendor-specific SQL portable — both the API and the SQL itself need to be portable.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-apis-7'; end if;
