insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-apis-1','pt-dbms-sql-2-database-apis','What is a database API?','["The physical file format used to store table data", "A defined calling contract for database access operations such as connections, statements, results, transactions, and cleanup", "A specific vendor''s wire protocol implementation", "A tool for physically indexing database records"]'::jsonb,1,'APIs can support remote services or embedded databases; not all are identical standards.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-apis-2','pt-dbms-sql-2-database-apis','Which of these is given as an example of a database API?','["B+-tree indexing", "Python''s DB-API (e.g., via psycopg2)", "TCP/IP", "A connection pool"]'::jsonb,1,'Python''s DB-API is explicitly listed as an example of a standardized database API, alongside ODBC, JDBC, and ADO.NET.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-apis-3','pt-dbms-sql-2-database-apis','In the layered stack described, what sits directly beneath the Database API and does the actual vendor-specific translation?','["The application''s user interface", "The Driver", "The conceptual schema", "The external schema"]'::jsonb,1,'The driver (2.13) is the layer directly beneath the API responsible for vendor-specific protocol translation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-apis-4','pt-dbms-sql-2-database-apis','Do Application, API, Driver, Middleware, and Database always form one mandatory fixed deployment order?','["Which physical disk the data is stored on", "No; the API specifies calls, implementations provide access, and optional middleware can occupy different positions", "How many connections are pooled at once", "The specific wire protocol bytes sent to the database"]'::jsonb,1,'Some layers are specifications or libraries rather than separate processes. An embedded database may have no remote server.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-apis-5','pt-dbms-sql-2-database-apis','What can remain familiar across Python DB-API implementations despite backend differences?','["Because all three databases use identical internal storage", "The general connection/cursor/execution/fetching pattern, while implementation details still need review", "Because SQLite, MySQL, and PostgreSQL are actually the same software", "Because middleware is required for this pattern to work at all"]'::jsonb,1,'A similar pattern does not guarantee identical placeholders, SQL, types, or optional features.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
