update public.learning_topics set short_description='Learn how database designers translate requirements into entities, keys, relationships, constraints, and compatible schemas, using course enrollment as a worked model.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Learn how database designers translate requirements into entities, keys, relationships, constraints, and compatible schemas, using course enrollment as a worked model.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Database Designer.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-database-designer' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-database-designer-application','MCQ Test 2',category,10,10,'Application and scenarios for Database Designer.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-database-designer' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-1','pt-dbms-sql-1-database-designer','What is the primary responsibility of the Database Designer?','["Identifying the data to be stored and designing the conceptual/logical schema, such as ER diagrams and relationships", "Managing backups and tuning performance of the running database", "Writing the front-end code that displays student grades", "Consuming the finished application as a naive user"]'::jsonb,0,'The notes define the Designer''s role as identifying data and designing the schema, entities, and relationships.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-2','pt-dbms-sql-1-database-designer','In the enrollment example, why does the Designer introduce a junction table `enrollments(student_id, course_id)`?','["To correctly model the many-to-many relationship between students and courses without redundant columns", "Because junction tables are required for every one-to-one relationship", "To give the DBA something to back up separately", "Because course columns cannot be stored anywhere else"]'::jsonb,0,'The notes explain the junction table is introduced specifically to model the many-to-many relationship correctly and avoid redundancy.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-3','pt-dbms-sql-1-database-designer','Which of the following is listed as a typical Designer responsibility?','["Choosing primary keys, foreign keys, and relationship cardinality", "Applying software patches to the DBMS engine", "Handling connection pooling in application code", "Checking grades through a student portal"]'::jsonb,0,'The notes list choosing keys and cardinality among the Designer''s core responsibilities, distinct from DBA or Developer tasks.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-4','pt-dbms-sql-1-database-designer','How does the Designer''s role differ from the Application Developer''s, according to the notes?','["The Designer decides what tables and relationships should exist; the Developer writes code that uses those tables", "The Designer writes all application business logic while the Developer designs the ER diagram", "They are identical roles with different job titles", "The Developer decides table structure and the Designer only tests the application"]'::jsonb,0,'The notes state this distinction directly: Designer decides schema shape, Developer writes code using it.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-5','pt-dbms-sql-1-database-designer','Why must a one-department-per-student policy be reviewed if students may later hold multiple department assignments?','["The new requirement can need a junction relationship and a compatible migration from the former many-to-one arrangement", "One department per student always means one-to-one with departments", "Existing single references automatically represent unlimited assignments", "Schema changes never affect applications"]'::jsonb,0,'Many students may share one department, so the original relationship is many-to-one from student to department. Multiple assignments change the requirement and may need a junction relation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-6','pt-dbms-sql-1-database-designer','According to the notes, why might a Designer sometimes deliberately choose NOT to fully normalize a schema?','["Because over-normalizing without considering query needs can require excessive joins for common reports, so a documented denormalization can be the right trade-off", "Because normalization is only a theoretical concept with no real effect on queries", "Because normalization is illegal in relational databases", "Because only the DBA is allowed to normalize a schema"]'::jsonb,0,'The notes explicitly mention that over-normalization can hurt query performance, making deliberate denormalization a valid trade-off in some cases.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-7','pt-dbms-sql-1-database-designer','A Designer builds a schema without consulting the professors who will actually use the course-management system, and later discovers courses can have multiple sections taught by different instructors. What pitfall does this illustrate?','["Skipping stakeholder review, which risks missing real-world relationships during design", "Over-granting SQL privileges to end users", "A crash-recovery failure caused by asynchronous commit", "A metadata drift issue caused by an undocumented schema change"]'::jsonb,0,'The notes specifically warn that skipping proper stakeholder review risks missing real relationships like multi-section, multi-instructor courses.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-designer-8','pt-dbms-sql-1-database-designer','Which statement best distinguishes when the Designer role is most active compared to the DBA role, per the notes?','["The Designer is primarily active at design time or when the schema evolves, while the DBA operates the already-built system day to day", "The Designer is active only after the DBA finishes managing backups", "Both roles are active only when an End User submits a support ticket", "The DBA is only active during initial schema design, and the Designer only during runtime operations"]'::jsonb,0,'The notes describe the Designer''s work as design-time and schema-evolution focused, in contrast to the DBA''s ongoing operational role.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-1-9','pt-dbms-sql-1-database-designer','What does the grain of a table describe?','["The color used in its diagram", "Only the maximum text length", "The physical age of the server", "What one record in that table represents"]'::jsonb,3,'A course and a course offering represent different units. Choosing the correct unit is essential before defining relationships.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-1-10','pt-dbms-sql-1-database-designer','Why record an unresolved modeling assumption?','["Because writing it down proves it is true", "Because every possible future feature must be implemented immediately", "So stakeholders can review it before callers depend on it", "Because it eliminates the need for a model"]'::jsonb,2,'An explicit assumption is reviewable. It must still be distinguished from a confirmed rule.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-1','pt-dbx2-database-designer-application','A student can take several courses and a course can contain several students. Which simplified structure represents the links?','["A junction relation enrollments with student and course references", "A single fixed course column on each student", "A rule allowing only one student per course", "One table for every possible student-course pair"]'::jsonb,0,'Each enrollment row records an individual link in the many-to-many relationship.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-2','pt-dbx2-database-designer-application','The model permits at most one enrollment for each student/course pair. Which candidate primary key expresses that rule?','["The student name alone", "A nonunique course title alone", "The pair student_id and course_id", "The current display order of records"]'::jsonb,2,'The pair identifies one permitted membership link under the stated simplified rule.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-3','pt-dbx2-database-designer-application','Two students share the same name. What should the model avoid assuming?','["That students can ever have identifiers", "That duplicate names require deleting a person", "That a unique key must be a display label", "That name alone necessarily identifies one student"]'::jsonb,3,'Human names are not guaranteed unique or stable. The identifier policy must fit the represented entities.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-4','pt-dbx2-database-designer-application','A course runs in two terms with different instructors. What must the designer investigate?','["Whether every course title must become a password", "Whether terms can be ignored without stakeholder review", "Whether every student must have the same instructor", "Whether a separate course-offering entity is required"]'::jsonb,3,'The system may need to distinguish actual occurrences rather than only the abstract course.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-5','pt-dbx2-database-designer-application','Many students belong to one department, and each student currently has one department. What relationship is this from students to departments?','["Automatically one-to-one", "Many-to-one", "Many-to-many by definition", "A relationship that cannot be modeled"]'::jsonb,1,'Several student records can reference the same department even when each student has only one such reference.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-6','pt-dbx2-database-designer-application','The institution begins allowing multiple department assignments per student. What should happen?','["Assume the old single reference can represent every assignment", "Review the new requirement and plan a compatible relationship change", "Change production data without inspecting callers", "Claim the original policy was always many-to-many"]'::jsonb,1,'A confirmed policy change can require a junction relationship and migration/caller planning.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-7','pt-dbx2-database-designer-application','An enrollment row references existing student and course keys. What do those references not prove by themselves?','["That the referenced keys exist under the declared rule", "That all capacity, prerequisite, and approval rules were satisfied", "That relationships can be represented relationally", "That the database can check a reference"]'::jsonb,1,'Foreign keys enforce their declared relationships, not every business condition of registration.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-8','pt-dbx2-database-designer-application','A department name is copied into thousands of student records. What design concern should be examined?','["The dependency and update anomalies created by multiple copies of one fact", "Whether every student must now have a unique department", "Whether copying automatically makes every rename atomic", "Whether data meanings no longer matter"]'::jsonb,0,'A single logical department record can reduce the need to coordinate repeated copies of the current name.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-9','pt-dbx2-database-designer-application','A maintained summary makes a measured report cheaper. Which responsibility accompanies that design?','["Assume the summary never needs updating", "Discard all source records automatically", "Define its authoritative source, maintenance rule, and permitted staleness", "Claim every normalized design is wrong"]'::jsonb,2,'Controlled additional representations require explicit consistency and ownership rules.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-designer-2-10','pt-dbx2-database-designer-application','Which review most directly tests whether the model fits ordinary college work?','["Walking through realistic enrollment, missing-reference, and repeat-offering cases", "Approving only the diagram''s visual style", "Choosing the shortest possible table names", "Ignoring the people who use the service"]'::jsonb,0,'Concrete allowed and denied scenarios expose requirements that a tidy picture can omit.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
