if exists(select 1 from public.practice_tests where id='pt-dbms-sql-2-database-drivers' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'database-drivers'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-2-database-drivers','pt-dbms-sql-2-database-drivers-application')) then raise exception 'Extra topic tests require manual integration: %', 'database-drivers'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-2-database-drivers-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'database-drivers'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Responsibilities around a database driver", "description": "A standard API can stabilize call patterns while concrete drivers and backends retain feature and representation contracts that require verification.", "columns": ["Layer", "Owns", "Does not prove by itself"], "rows": [["Application API usage", "Calls, values, cleanup, interpretation", "Automatic SQL portability"], ["Driver implementation", "Supported protocol and value conversions", "Every future server feature is supported"], ["Database service", "Configured query execution and shared guarantees", "Every application access rule was implemented"], ["Optional middleware/pool", "Routing and resource lifecycle as documented", "Arbitrary transaction affinity or retry safety"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'database-drivers'; end if;
