if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-drivers-1' and (question_text,options,correct_index,explanation) is distinct from ('What does a Database Driver do?','["It stores the database''s physical data files", "It implements a standard API for one specific database vendor, translating generic calls into that vendor''s native protocol", "It defines the conceptual schema for an organization", "It manages the pool of open connections across all vendors"]'::jsonb,1,'A driver is the vendor-specific software that translates standard API calls into one particular database''s own wire protocol.') and (question_text,options,correct_index,explanation) is distinct from ('Which description best fits a database driver?','["It stores the database''s physical data files", "Software implementing a supported database access interface and the corresponding protocol and value handling", "It defines the conceptual schema for an organization", "It manages the pool of open connections across all vendors"]'::jsonb,1,'Drivers may implement standard or vendor-specific interfaces and can support a product family.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-drivers-1'; end if;
