if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-drivers-2' and (question_text,options,correct_index,explanation) is distinct from ('In the Java example, what generally has to change when switching from the PostgreSQL JDBC driver to the MySQL JDBC driver?','["The entire application must be rewritten from scratch", "Mainly just the driver class loaded and the connection URL, since the JDBC API calls stay the same", "Nothing at all changes, including configuration", "The conceptual schema of the database"]'::jsonb,1,'Because JDBC is a standard API, swapping the driver mostly just requires changing which driver is loaded and the connection details.') and (question_text,options,correct_index,explanation) is distinct from ('When replacing one JDBC implementation with another, which change is necessary but not sufficient to prove compatibility?','["The entire application must be rewritten from scratch", "Selecting the correct dependency and connection URL while reviewing SQL and behavioral contracts", "Nothing at all changes, including configuration", "The conceptual schema of the database"]'::jsonb,1,'Common API shapes do not guarantee equivalent SQL, type conversion, transactions, or error handling.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-drivers-2'; end if;
