if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-drivers-3' and (question_text,options,correct_index,explanation) is distinct from ('Which standard APIs are given as examples that a database driver implements?','["HTTP and FTP", "ODBC and JDBC", "TCP and UDP", "HTML and CSS"]'::jsonb,1,'ODBC and JDBC are the standard APIs mentioned that database drivers implement for specific vendors.') and (question_text,options,correct_index,explanation) is distinct from ('Which standard APIs are given as examples that a database driver implements?','["HTTP and FTP", "ODBC and JDBC", "TCP and UDP", "HTML and CSS"]'::jsonb,1,'ODBC and JDBC are the standard APIs mentioned that database drivers implement for specific vendors.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-drivers-3'; end if;
