if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-database-drivers-5' and (question_text,options,correct_index,explanation) is distinct from ('In the Oracle/SQL Server middleware example from 2.11, what role would individual drivers play internally?','["The middleware would need no drivers at all", "The middleware would rely on an Oracle driver for the Oracle connection and a SQL Server driver for the SQL Server connection", "A single driver would handle both Oracle and SQL Server identically", "Drivers are only relevant to two-tier architecture, not middleware"]'::jsonb,1,'Middleware coordinating multiple backends typically relies internally on the vendor-specific driver appropriate to each backend it connects to.') and (question_text,options,correct_index,explanation) is distinct from ('In the Oracle/SQL Server middleware example from 2.11, what role would individual drivers play internally?','["The middleware would need no drivers at all", "The middleware would rely on an Oracle driver for the Oracle connection and a SQL Server driver for the SQL Server connection", "A single driver would handle both Oracle and SQL Server identically", "Drivers are only relevant to two-tier architecture, not middleware"]'::jsonb,1,'Middleware coordinating multiple backends typically relies internally on the vendor-specific driver appropriate to each backend it connects to.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-database-drivers-5'; end if;
