insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-database-engine-application','MCQ Test 2',category,10,10,'Application and scenarios for Database Engine.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-database-engine' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-1','pt-dbms-sql-1-database-engine','In the broad sense used in this chapter, what is the Database Engine?','["The core DBMS runtime that ties together the query processor, storage manager, transaction manager, and buffer manager", "A single SQL statement executed by an end user", "A synonym for the Database Administrator", "A tool used only for generating ER diagrams"]'::jsonb,0,'The notes define the Database Engine as the runtime coordinating all the other subsystems and exposing the unified SQL interface.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-2','pt-dbms-sql-1-database-engine','What does the Database Engine''s connection handler do when a client connects?','["Establishes the connection identity using configured authentication facilities and account information", "Automatically grants every privilege to any connected identity", "Changes every table to the same storage engine", "Eliminates all later authorization checks"]'::jsonb,0,'Connection verification establishes the relevant identity through the configured mechanism. Later operations still require their applicable authorization checks.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-3','pt-dbms-sql-1-database-engine','In MySQL, what does choosing ENGINE=InnoDB versus ENGINE=MyISAM affect?','["Whether the table supports transactions, row-level locking, and foreign-key constraints", "Only the color of the table in a GUI tool", "Whether the table can store text data at all", "Whether the table can be queried using SELECT"]'::jsonb,0,'The notes state InnoDB supports transactions, row-level locking, and foreign keys, while MyISAM historically lacked these.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-4','pt-dbms-sql-1-database-engine','What does the Database Engine own and maintain that the Query Processor constantly consults while planning queries?','["The system catalog, containing metadata about tables, columns, constraints, and indexes", "The end user''s personal login history only", "A copy of every query ever executed, with no other metadata", "The physical disk drive''s manufacturer information"]'::jsonb,0,'The notes explain the engine owns the system catalog/metadata that the Query Processor relies on for planning.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-5','pt-dbms-sql-1-database-engine','Why can a foreign key from an InnoDB table referencing a MyISAM table be problematic, per the notes?','["An enabled InnoDB foreign-key definition against a MyISAM parent is unsupported and can be rejected; do not assume an enforced cross-engine relationship", "MyISAM automatically provides all InnoDB transaction guarantees", "A shared server proves every table relationship is enforced", "The parent must always be converted silently"]'::jsonb,0,'MySQL documents a same-storage-engine requirement for parent and child in supported foreign-key definitions. This differs from merely writing syntax for an engine that does not implement enforcement.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-6','pt-dbms-sql-1-database-engine','What is described as a ''common architecture mistake'' related to engine choice, according to the notes?','["Choosing an engine or configuration optimized for read-heavy analytics for a high-write OLTP workload, or vice versa", "Ever using more than one table in a single database", "Allowing an end user to log into the application", "Storing metadata in the system catalog instead of a separate file"]'::jsonb,0,'The notes identify mismatching engine/replication choice to workload type (analytics vs. OLTP) as a common architecture mistake.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-7','pt-dbms-sql-1-database-engine','A team creates some tables as InnoDB and others as MyISAM within the same database, assuming all tables behave uniformly regarding constraints. What specific risk does the notes highlight?','["The actual engines differ in supported guarantees; MyISAM lacks the intended foreign-key support and an InnoDB cross-engine definition must not be assumed valid", "Sharing a database name proves every relationship is enforced", "Every operation becomes atomic regardless of engine", "Every parent is automatically converted to a transactional engine"]'::jsonb,0,'Inspect actual engine capabilities and enforced definitions. Unsupported cross-engine references can be rejected rather than silently becoming valid constraints.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-database-engine-8','pt-dbms-sql-1-database-engine','Why does the notes describe the engine''s authentication/catalog layer as ''a single point of trust''?','["Because if the engine''s own privilege metadata is misconfigured, it can silently under- or over-grant access regardless of how well individual tables were designed", "Because the catalog layer has no connection to security at all", "Because only End Users interact with the catalog layer directly", "Because the catalog layer is optional and can be disabled without consequence"]'::jsonb,0,'The notes state that misconfigured engine-level privilege metadata can silently affect access control regardless of table-level design quality.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-1-9','pt-dbms-sql-1-database-engine','Does a successful connection establish permission for every later operation?','["Yes; connection success grants every privilege", "Yes; structural constraints replace authorization", "No; connection identity can never be established", "No; operations still face the applicable authorization checks"]'::jsonb,3,'Authentication/connection verification and authorization are different concerns.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-1-10','pt-dbms-sql-1-database-engine','Why must an explanation identify which meaning of engine it uses?','["Every product uses all architecture terms identically", "Every engine name refers only to a network socket", "The broad core runtime and a MySQL table storage engine have different scopes", "No DBMS can support more than one storage implementation"]'::jsonb,2,'Product-specific storage plugins are not equivalent to the entire runtime in a generic teaching diagram.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-1','pt-dbx2-database-engine-application','A MySQL table uses InnoDB while another uses MyISAM. What should the team avoid assuming?','["That the server can contain tables", "Identical transaction and foreign-key capabilities merely because both tables share a server", "That queries can reference table definitions", "That workload requirements matter"]'::jsonb,1,'Storage-engine capabilities differ. Shared server placement does not prove uniform guarantees.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-2','pt-dbx2-database-engine-application','An enabled InnoDB foreign key is proposed against a MyISAM parent. Which claim is accurate?','["The unsupported cross-engine definition must not be assumed to work; it can be rejected", "It automatically becomes a guaranteed enforced relationship", "The server must silently convert every parent to InnoDB", "The relationship is proved by a diagram alone"]'::jsonb,0,'MySQL documents compatible supported engine requirements, including the same-engine rule for parent and child.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-3','pt-dbx2-database-engine-application','A team writes foreign-key-looking syntax for a table engine without the intended enforcement. What must be checked?','["The actual supported engine and resulting enforced definition", "Only whether the text contains FOREIGN KEY", "Only the form''s visual appearance", "Whether every account has a short name"]'::jsonb,0,'Writing a declaration is not evidence that the chosen object/engine provides the intended constraint.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-4','pt-dbx2-database-engine-application','A query names a missing column. Why can a faster storage device not resolve the underlying error?','["Every missing name is a slow disk read", "The engine can infer arbitrary undeclared columns", "The statement does not resolve against the actual object definitions", "An index grants permission to create the column"]'::jsonb,2,'The catalog defines the available objects. More physical access speed does not change their logical definitions.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-5','pt-dbx2-database-engine-application','A reporting account connects successfully but cannot update marks. Is that necessarily a connection failure?','["Yes; every connected account must update all tables", "Yes; a successful login disables later checks", "No; it may be the correct separation between connection identity and update privileges", "No; the account must therefore be an administrator"]'::jsonb,2,'An operation can be denied even after connection verification succeeds.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-6','pt-dbx2-database-engine-application','A table has a well-chosen primary key but an application identity has excessive privileges. Which claim is justified?','["The key automatically revokes unrelated privileges", "The primary key does not correct the access configuration", "The privilege issue cannot affect any data", "The index layout grants the intended ownership policy"]'::jsonb,1,'Integrity and authorization are separate properties requiring appropriate configuration and enforcement.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-7','pt-dbx2-database-engine-application','A configuration fits read-heavy analysis. What must be evaluated before using it for frequent concurrent updates?','["Only whether the product logo matches", "A guarantee that read performance proves all write behavior", "Whether every transaction command has the same spelling", "The new workload, required guarantees, write costs, and coordination behavior"]'::jsonb,3,'A workload-specific choice must be reviewed when the required operations and guarantees change.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-8','pt-dbx2-database-engine-application','A developer manually edits internal catalog storage to bypass the supported interface. What is wrong with the approach?','["The catalog is always an ordinary writable application table", "It can violate internal consistency or be prohibited and bypasses the intended definition process", "It automatically preserves all privileges and definitions", "It is the universal way to change database objects"]'::jsonb,1,'Use supported inspection and definition facilities under the appropriate authorization and change process.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-9','pt-dbx2-database-engine-application','Does transaction support in a product name prove atomicity for every actual table arrangement?','["No; the objects, storage capabilities, and operation boundaries must be checked", "Yes; all storage arrangements become equivalent", "Yes; every external service is automatically included", "No; transactions can never group local changes"]'::jsonb,0,'The actual components and algorithm determine the available guarantees.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-database-engine-2-10','pt-dbx2-database-engine-application','Which evidence is strongest for an engine-related explanation?','["Only the word engine in a diagram", "Only a fast-looking screen", "A claim that all DBMS internals are identical", "A stated term scope, actual product/object capabilities, and verified behavior"]'::jsonb,3,'Separating terminology, capabilities and observations prevents unsupported architectural and operational conclusions.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
