if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-database-instance' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'database-instance'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-database-instance' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'database-instance'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-4-database-instance','pt-dbms-sql-4-database-instance-application')) then raise exception 'Extra topic tests require manual integration: %', 'database-instance'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-4-database-instance-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'database-instance'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "An unchanged schema can describe different database states", "description": "Identifiers align facts across the recorded states. Matching counts alone would miss that student 2 was replaced by student 3.", "columns": ["State", "Student facts", "Student count", "Schema"], "rows": [["Before", "1 active; 2 active", "2", "Student(student_id, status)"], ["After", "1 inactive; 3 active", "2", "Student(student_id, status)"], ["Difference", "1 changed; 2 removed; 3 inserted", "Counts alone hide changes", "Same structure"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'database-instance'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "An unchanged schema can describe different database states", "description": "Identifiers align facts across the recorded states. Matching counts alone would miss that student 2 was replaced by student 3.", "columns": ["State", "Student facts", "Student count", "Schema"], "rows": [["Before", "1 active; 2 active", "2", "Student(student_id, status)"], ["After", "1 inactive; 3 active", "2", "Student(student_id, status)"], ["Difference", "1 changed; 2 removed; 3 inserted", "Counts alone hide changes", "Same structure"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "An unchanged schema can describe different database states", "description": "Identifiers align facts across the recorded states. Matching counts alone would miss that student 2 was replaced by student 3.", "columns": ["State", "Student facts", "Student count", "Schema"], "rows": [["Before", "1 active; 2 active", "2", "Student(student_id, status)"], ["After", "1 inactive; 3 active", "2", "Student(student_id, status)"], ["Difference", "1 changed; 2 removed; 3 inserted", "Counts alone hide changes", "Same structure"]]}]'::jsonb;
