if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-instance-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a database instance?','["The structural design of the database", "The actual data (all current relations) stored in the database at a given point in time", "The name of the database", "A single attribute''s domain"]'::jsonb,1,'A database instance is the real, current data across every relation, as opposed to the structural schema.') and (question_text,options,correct_index,explanation) is distinct from ('What is a database instance?','["The structural design of the database", "The actual data (all current relations) stored in the database at a given point in time", "The name of the database", "A single attribute''s domain"]'::jsonb,1,'A database instance is the real, current data across every relation, as opposed to the structural schema.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-instance-1'; end if;
