if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-instance-2' and (question_text,options,correct_index,explanation) is distinct from ('If Students goes from 4 rows to 5 rows after a new admission, what has changed?','["The database schema", "The database instance (the data), while the schema stays the same", "The relation schema''s degree", "Nothing has changed"]'::jsonb,1,'Adding a row changes only the current data (the instance); the underlying structure (schema) is unaffected.') and (question_text,options,correct_index,explanation) is distinct from ('If Students goes from 4 rows to 5 rows after a new admission, what has changed?','["The database schema", "The database instance (the data), while the schema stays the same", "The relation schema''s degree", "Nothing has changed"]'::jsonb,1,'Adding a row changes only the current data (the instance); the underlying structure (schema) is unaffected.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-instance-2'; end if;
