if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-instance-3' and (question_text,options,correct_index,explanation) is distinct from ('Which of these best captures the difference between Database Schema and Database Instance?','["Schema = structure (mostly fixed); Instance = actual data at a moment (changes constantly)", "Schema = data; Instance = structure", "They mean the same thing", "Instance only applies to a single table, schema applies to the whole database"]'::jsonb,0,'This is exactly the structure-vs-data distinction, scaled to the whole database.') and (question_text,options,correct_index,explanation) is distinct from ('Which of these best captures the difference between Database Schema and Database Instance?','["Schema describes structure; instance describes the actual data state at a particular moment", "Schema = data; Instance = structure", "They mean the same thing", "Instance only applies to a single table, schema applies to the whole database"]'::jsonb,0,'Schemas can evolve and data can remain unchanged; the distinction is structure versus current facts, not an absolute frequency rule.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-instance-3'; end if;
