if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-instance-4' and (question_text,options,correct_index,explanation) is distinct from ('How does a Database Instance relate to individual Relations?','["A database instance is smaller than any single relation", "A database instance is the union of the current relation (data) for every relation schema in the database", "A relation contains many database instances", "They are unrelated concepts"]'::jsonb,1,'The database instance is the combined current state of ALL the individual relations together.') and (question_text,options,correct_index,explanation) is distinct from ('How does a Database Instance relate to individual Relations?','["A database instance is smaller than any single relation", "A database instance is the collection of current named relation instances for the database schema", "A relation contains many database instances", "They are unrelated concepts"]'::jsonb,1,'It is a collection of relation states, not a relational union across incompatible schemas.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-instance-4'; end if;
