update public.learning_topics set short_description='Distinguish a database state from its design, follow valid state changes, and compare recorded snapshots without confusing them with transaction guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish a database state from its design, follow valid state changes, and compare recorded snapshots without confusing them with transaction guarantees.';
