insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-1','pt-dbms-sql-4-database-instance','What is a database instance?','["The structural design of the database", "The actual data (all current relations) stored in the database at a given point in time", "The name of the database", "A single attribute''s domain"]'::jsonb,1,'A database instance is the real, current data across every relation, as opposed to the structural schema.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-2','pt-dbms-sql-4-database-instance','If Students goes from 4 rows to 5 rows after a new admission, what has changed?','["The database schema", "The database instance (the data), while the schema stays the same", "The relation schema''s degree", "Nothing has changed"]'::jsonb,1,'Adding a row changes only the current data (the instance); the underlying structure (schema) is unaffected.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-3','pt-dbms-sql-4-database-instance','Which of these best captures the difference between Database Schema and Database Instance?','["Schema describes structure; instance describes the actual data state at a particular moment", "Schema = data; Instance = structure", "They mean the same thing", "Instance only applies to a single table, schema applies to the whole database"]'::jsonb,0,'Schemas can evolve and data can remain unchanged; the distinction is structure versus current facts, not an absolute frequency rule.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-4','pt-dbms-sql-4-database-instance','How does a Database Instance relate to individual Relations?','["A database instance is smaller than any single relation", "A database instance is the collection of current named relation instances for the database schema", "A relation contains many database instances", "They are unrelated concepts"]'::jsonb,1,'It is a collection of relation states, not a relational union across incompatible schemas.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-5','pt-dbms-sql-4-database-instance','Assuming the operation succeeds, which action changes data without changing the database schema?','["Adding a new column to Students", "Deleting a graduated student''s row from Students", "Dropping the Enrollments table", "Adding a new foreign key constraint"]'::jsonb,1,'Deleting a row only changes the current data (instance); the other options are structural (schema) changes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-6','pt-dbms-sql-4-database-instance','For a database instance to be considered legal/valid, what must it satisfy?','["It must have at least 1000 rows in every relation", "All integrity constraints declared in the database schema (keys, foreign keys, domain constraints)", "It must be identical to some prior backup", "It must contain no NULL values anywhere"]'::jsonb,1,'A legal instance is one that conforms to every constraint the schema defines; violating any constraint makes it an illegal instance.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-7','pt-dbms-sql-4-database-instance','Can a ''staging'' database and a ''production'' database share an identical database schema but hold different database instances?','["No, identical schemas always imply identical data", "Yes — the same schema can be populated with completely different data in each environment", "Only if both databases are read-only", "No, this would violate referential integrity"]'::jsonb,1,'Schema and instance are independent: the same structural design can be filled with entirely different data sets.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-instance-8','pt-dbms-sql-4-database-instance','If an authorized DROP TABLE Enrollments succeeds, what does it affect?','["Only the database instance, since data is removed", "Both the database schema (the relation schema is removed) and, consequently, its instance data", "Neither the schema nor the instance", "Only the Courses relation schema"]'::jsonb,1,'Dropping a table removes its relation schema entirely (a structural/schema change), which necessarily also wipes out its data (instance).',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-database-instance-new-9','pt-dbms-sql-4-database-instance','An update changes a programme but preserves every row count. Has the logical instance changed?','["No; only counts define an instance", "Yes; recorded values changed", "Only if degree changes", "Only if a server restarts"]'::jsonb,1,'Facts can change without a cardinality change.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-database-instance-new-10','pt-dbms-sql-4-database-instance','Why is a database instance not normally a relational union of all its tables?','["All tables must have one column", "UNION defines all foreign keys", "Different relations can have incompatible attribute schemas", "Names are always unique across all tables"]'::jsonb,2,'The whole state is a collection of named relation instances.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
