update public.learning_topics set short_description='Understand database middleware as a request, adaptation, and coordination layer while examining type fidelity, transaction limits, routing, pooling, authorization, and operational dependencies.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand database middleware as a request, adaptation, and coordination layer while examining type fidelity, transaction limits, routing, pooling, authorization, and operational dependencies.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Database Middleware.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-database-middleware' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-database-middleware-application','MCQ Test 2',category,10,10,'Application and scenarios for Database Middleware.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-database-middleware' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-1','pt-dbms-sql-2-database-middleware','What is the primary role of Database Middleware?','["To physically store the database''s data files", "To sit between applications and one or more database servers, translating/routing requests and hiding heterogeneity", "To render the user interface for end users", "To replace the need for a conceptual schema"]'::jsonb,1,'Middleware''s defining role is mediating between applications and database servers, especially across different vendors or protocols.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-2','pt-dbms-sql-2-database-middleware','In the notes'' example, what two systems does an enterprise application need to query, motivating the use of middleware?','["Two identical Oracle instances", "An Oracle database and a SQL Server database", "A file server and a web server", "Two different external schemas of the same database"]'::jsonb,1,'The example describes an application needing to query both Oracle and SQL Server through one uniform middleware interface.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-3','pt-dbms-sql-2-database-middleware','Which of these is listed as an example of database middleware?','["A B+-tree index", "An ODBC/JDBC bridge", "A conceptual schema", "A primary key constraint"]'::jsonb,1,'ODBC/JDBC bridges are explicitly named as examples of database middleware.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-4','pt-dbms-sql-2-database-middleware','Where can database middleware be located?','["Inside or as part of the presentation tier (Tier 1)", "Commonly in the application tier, but also in a proxy or client library depending on its responsibility", "Inside the database server tier (Tier 3) only", "It replaces all three tiers"]'::jsonb,1,'The term describes an integration role, not a mandatory deployment tier.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-5','pt-dbms-sql-2-database-middleware','What can middleware help with when an application accesses Oracle and SQL Server?','["It forces both databases to merge into a single physical database", "Provide a shared access pattern while adapting supported backend-specific calls and exposing remaining differences", "It removes the need for either database to store data", "It converts SQL Server into Oracle automatically"]'::jsonb,1,'A uniform interface does not guarantee portable SQL, types, or transaction semantics.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-6','pt-dbms-sql-2-database-middleware','Why can a single, non-redundant middleware instance become a serious operational risk?','["Because middleware never fails", "Because if it is the only instance handling traffic to production databases, it becomes a bottleneck or single point of failure", "Because middleware only supports one query at a time by design", "Because middleware cannot be scaled at all"]'::jsonb,1,'A single middleware instance without redundancy risks becoming a bottleneck or point of failure for all traffic routed through it.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-7','pt-dbms-sql-2-database-middleware','A new backend type is unsupported by an older adapter. What behavior must be verified?','["The middleware will immediately crash with an obvious error every time", "Whether it fails clearly or converts values without unacceptable information loss", "The new data type will be automatically upgraded across all databases", "Nothing; middleware versions never affect data type support"]'::jsonb,1,'The outcome depends on the adapter. Silent truncation is a risk to test, not an inevitable result.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-database-middleware-8','pt-dbms-sql-2-database-middleware','How does database middleware commonly differ in scope from a driver?','["They are identical concepts with different names", "It can coordinate routing, adaptation, or policy above drivers, while a driver implements its database access contract", "A driver always sits above middleware in the stack", "Middleware only works with a single database vendor, unlike drivers"]'::jsonb,1,'Capabilities can overlap; not every driver is limited to one narrowly packaged product.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-new-9','pt-dbms-sql-2-database-middleware','Does a common database API guarantee identical SQL semantics across backends?','["Yes; all SQL becomes interchangeable", "No; syntax, types, and guarantees can still differ", "Yes; connection success proves portability", "Only if both products store strings"]'::jsonb,1,'An interface abstracts some mechanics without erasing every backend-specific contract.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-new-10','pt-dbms-sql-2-database-middleware','What must a result conversion preserve for a high-precision amount?','["Only its column position", "Only the number of rows", "The precision and meaning promised by the application contract", "Only the database server name"]'::jsonb,2,'A neat uniform shape is not enough when conversion changes values.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-1','pt-dbms-sql-2-database-middleware-application','An identifier is converted to a number that cannot represent its full range exactly. What is at risk?','["Only a tooltip color", "Only the pool name", "Distinct identifiers may lose their identity distinction", "The number of database tiers necessarily changes"]'::jsonb,2,'Lossy representation can make different records appear to have the same identifier.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-2','pt-dbms-sql-2-database-middleware-application','A write succeeds in one backend and fails in another. What does a shared API alone not provide?','["A way to call a driver", "A defined method name", "A place to return an error", "Atomic rollback across both databases"]'::jsonb,3,'Cross-database atomicity requires a verified mechanism, not a common object interface.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-3','pt-dbms-sql-2-database-middleware-application','A post-write read is routed to a delayed replica. What contract must be reviewed?','["The consistency level the caller expects", "Only whether the column names match", "Only whether the result contains JSON", "Only how many middleware files exist"]'::jsonb,0,'Replica freshness can differ from the writer''s current state.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-4','pt-dbms-sql-2-database-middleware-application','A driver error prints an entire connection string into logs. What must be corrected?','["The student''s preferred heading", "Secret-safe bounded diagnostics", "The number of SQL result columns", "The order of unrelated imports"]'::jsonb,1,'Integration diagnostics must not expose credentials or private values.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-5','pt-dbms-sql-2-database-middleware-application','All production access passes through one middleware process. Which operational risk is introduced?','["Guaranteed distributed atomicity", "Automatic removal of every backend limit", "A bottleneck or single point of failure", "Guaranteed type portability"]'::jsonb,2,'A shared dependency needs capacity and availability review.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-6','pt-dbms-sql-2-database-middleware-application','A proxy changes sessions between statements in one intended transaction. What requires verification?','["Only the report title", "Only the database brand logo", "Only the timestamp display format", "Session affinity and supported transaction semantics"]'::jsonb,3,'Transaction state cannot be assumed to follow arbitrary session routing.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-7','pt-dbms-sql-2-database-middleware-application','A developer builds a second adapter without inspecting the existing data-access layer. What should happen first?','["Trace existing callers and contracts to establish a demonstrated need", "Install every possible driver", "Duplicate all route handlers", "Remove the database checks"]'::jsonb,0,'Reusing established boundaries avoids unnecessary parallel implementations.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-8','pt-dbms-sql-2-database-middleware-application','An unsupported type fails explicitly rather than truncating data. Is silent corruption inevitable?','["Yes; every old adapter silently corrupts", "No; behavior depends on the actual adapter and must be tested", "Only if there are two tiers", "Only Oracle can report errors"]'::jsonb,1,'Unsupported features can fail clearly; review must establish the actual result.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-9','pt-dbms-sql-2-database-middleware-application','Several middleware instances share the same erroneous conversion. Does redundancy repair it?','["Yes; more instances guarantee precision", "Yes; load balancing changes data types", "No; it replicates the same correctness defect", "Only adding a second database fixes all conversions"]'::jsonb,2,'Availability and correctness are separate concerns.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-database-middleware-application-new-10','pt-dbms-sql-2-database-middleware-application','A request is slow before reaching the backend. What should diagnostics distinguish?','["Only the total table count", "Only the database''s marketing name", "Only the response font", "Middleware queueing and adaptation from backend execution"]'::jsonb,3,'Separate timings help locate the actual bottleneck without guessing.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
