if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Enrollment connects two parent identities", "description": "The association references student and course identities; the labels are descriptive. This is a logical map, not evidence that deployed constraints were executed.", "columns": ["Relation", "Identity", "Relationship role"], "rows": [["Student", "student_id", "Parent identity for a student"], ["Course", "course_id", "Parent identity for a course"], ["Enrollment", "student_id + course_id for one enrollment per pair", "student_id references Student; course_id references Course"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'database-schema'; end if;
