if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-schema-1' and (question_text,options,correct_index,explanation) is distinct from ('What does a database schema represent?','["The data currently stored in one table", "The complete structural design of the entire database: all relation schemas plus cross-relation constraints", "A single relation''s set of tuples", "The physical hard-disk layout of the DBMS"]'::jsonb,1,'The database schema is the full structural blueprint spanning every relation and the constraints between them.') and (question_text,options,correct_index,explanation) is distinct from ('What does a database schema represent?','["The data currently stored in one table", "The complete structural design of the entire database: all relation schemas plus cross-relation constraints", "A single relation''s set of tuples", "The physical hard-disk layout of the DBMS"]'::jsonb,1,'The database schema is the full structural blueprint spanning every relation and the constraints between them.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-schema-1'; end if;
