if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-schema-3' and (question_text,options,correct_index,explanation) is distinct from ('How does a Database Schema differ from a single Relation Schema?','["A database schema is one relation''s structure; a relation schema covers the whole database", "A database schema aggregates ALL relation schemas plus inter-relation constraints; a relation schema describes just one relation", "They are identical terms for the same concept", "A relation schema always has more attributes than a database schema"]'::jsonb,1,'The database schema is the union of every relation schema in the system, plus constraints spanning them, such as foreign keys.') and (question_text,options,correct_index,explanation) is distinct from ('How does a Database Schema differ from a single Relation Schema?','["A database schema is one relation''s structure; a relation schema covers the whole database", "A database schema aggregates ALL relation schemas plus inter-relation constraints; a relation schema describes just one relation", "They are identical terms for the same concept", "A relation schema always has more attributes than a database schema"]'::jsonb,1,'The database schema is the union of every relation schema in the system, plus constraints spanning them, such as foreign keys.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-schema-3'; end if;
