if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-schema-4' and (question_text,options,correct_index,explanation) is distinct from ('A foreign key linking Enrollments.student_id to Students.id is best understood as part of:','["Only the Enrollments relation schema, with no bearing on the database schema", "The overall database schema, since it expresses a relationship BETWEEN two relation schemas", "The database instance, since it involves actual ID values", "Neither the relation schema nor the database schema"]'::jsonb,1,'Although declared syntactically inside one table''s definition, a foreign key constraint expresses a cross-relation relationship and is conceptually part of the database schema.') and (question_text,options,correct_index,explanation) is distinct from ('A foreign key linking Enrollments.student_id to Students.id is best understood as part of:','["Only the Enrollments relation schema, with no bearing on the database schema", "The overall database schema, since it expresses a relationship BETWEEN two relation schemas", "The database instance, since it involves actual ID values", "Neither the relation schema nor the database schema"]'::jsonb,1,'Although declared syntactically inside one table''s definition, a foreign key constraint expresses a cross-relation relationship and is conceptually part of the database schema.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-schema-4'; end if;
