if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-database-schema-5' and (question_text,options,correct_index,explanation) is distinct from ('Is it valid for a database schema to be considered complete even if all its relations currently hold zero rows?','["No, a database schema requires at least some data to be valid", "Yes \u2014 the schema (structure + constraints) is complete as soon as it is defined, regardless of whether data has been inserted", "Only if there is exactly one relation in the schema", "No, this would violate referential integrity"]'::jsonb,1,'A database schema is a structural definition; it can be fully valid with every relation instance still empty.') and (question_text,options,correct_index,explanation) is distinct from ('Is it valid for a database schema to be considered complete even if all its relations currently hold zero rows?','["No, a database schema requires at least some data to be valid", "Yes \u2014 the schema (structure + constraints) is complete as soon as it is defined, regardless of whether data has been inserted", "Only if there is exactly one relation in the schema", "No, this would violate referential integrity"]'::jsonb,1,'A database schema is a structural definition; it can be fully valid with every relation instance still empty.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-database-schema-5'; end if;
