insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-1','pt-dbms-sql-4-database-schema','What does a database schema represent?','["The data currently stored in one table", "The complete structural design of the entire database: all relation schemas plus cross-relation constraints", "A single relation''s set of tuples", "The physical hard-disk layout of the DBMS"]'::jsonb,1,'The database schema is the full structural blueprint spanning every relation and the constraints between them.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-2','pt-dbms-sql-4-database-schema','Which of the following would be part of the database schema for a college database?','["The specific 4 rows currently in Students", "The Students, Courses, and Enrollments relation schemas plus their foreign-key links", "Today''s date", "The number of students who enrolled last semester"]'::jsonb,1,'The relation schemas and the constraints (including foreign keys) linking them together constitute the database schema.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-3','pt-dbms-sql-4-database-schema','How does a Database Schema differ from a single Relation Schema?','["A database schema is one relation''s structure; a relation schema covers the whole database", "A database schema aggregates ALL relation schemas plus inter-relation constraints; a relation schema describes just one relation", "They are identical terms for the same concept", "A relation schema always has more attributes than a database schema"]'::jsonb,1,'The database schema is the union of every relation schema in the system, plus constraints spanning them, such as foreign keys.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-4','pt-dbms-sql-4-database-schema','A foreign key linking Enrollments.student_id to Students.id is best understood as part of:','["Only the Enrollments relation schema, with no bearing on the database schema", "The overall database schema, since it expresses a relationship BETWEEN two relation schemas", "The database instance, since it involves actual ID values", "Neither the relation schema nor the database schema"]'::jsonb,1,'Although declared syntactically inside one table''s definition, a foreign key constraint expresses a cross-relation relationship and is conceptually part of the database schema.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-5','pt-dbms-sql-4-database-schema','Is it valid for a database schema to be considered complete even if all its relations currently hold zero rows?','["No, a database schema requires at least some data to be valid", "Yes — the schema (structure + constraints) is complete as soon as it is defined, regardless of whether data has been inserted", "Only if there is exactly one relation in the schema", "No, this would violate referential integrity"]'::jsonb,1,'A database schema is a structural definition; it can be fully valid with every relation instance still empty.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-6','pt-dbms-sql-4-database-schema','Adding a brand-new table ''Instructors'' to the college database is an example of a change to:','["The database instance only", "The database schema, since a new relation schema is being introduced", "Neither the schema nor the instance", "Only the Students relation schema"]'::jsonb,1,'Introducing a new relation schema changes the overall structural design, i.e., the database schema.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-7','pt-dbms-sql-4-database-schema','Circular foreign keys between two relations (each referencing the other) must be validated:','["Independently, one relation schema at a time, ignoring the other", "Together, considering the referenced identities, allowed states and supported insertion or deletion transitions", "Only at the database instance level, never at schema design time", "They are not allowed to exist in any relational database schema"]'::jsonb,1,'Circular dependencies require joint design reasoning; the permitted transitions depend on actual engine and constraint behaviour.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-database-schema-8','pt-dbms-sql-4-database-schema','Which pair of terms mirrors the Relation Schema vs. Relation distinction, but at the whole-database level?','["Attribute vs. Domain", "Database Schema vs. Database Instance", "Degree vs. Cardinality", "Tuple vs. Attribute"]'::jsonb,1,'Just as Relation Schema (structure) contrasts with Relation (data), Database Schema (structure) contrasts with Database Instance (data), scaled to the entire database.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
