update public.learning_topics set short_description='Evaluate DBMS benefits and costs through shared records, access control, concurrency, recovery, administration, licensing, embedded storage, and workload-specific trade-offs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Evaluate DBMS benefits and costs through shared records, access control, concurrency, recovery, administration, licensing, embedded storage, and workload-specific trade-offs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for DBMS Advantages and Trade-offs.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-dbms-advantages-and-trade-offs' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-dbms-advantages-and-trade-offs-application','MCQ Test 2',category,10,10,'Application and scenarios for DBMS Advantages and Trade-offs.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-dbms-advantages-and-trade-offs' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-1','pt-dbms-sql-1-dbms-advantages-and-trade-offs','Which of the following is listed as an advantage of using a DBMS over flat files?','["Centralized security and controlled concurrent access", "Guaranteed zero licensing cost in every case", "Elimination of the need for any administrator", "Automatic conversion of SQL into a spreadsheet"]'::jsonb,0,'The notes list centralized security and controlled concurrent access as core DBMS advantages over ad-hoc file-based storage.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-2','pt-dbms-sql-1-dbms-advantages-and-trade-offs','According to the notes, why might a small club with 50 members tracked in a spreadsheet not need a DBMS?','["The complexity and setup cost of a DBMS would outweigh the benefit for such a small, single-user, low-risk dataset", "Spreadsheets are technically a type of DBMS", "DBMSs cannot store fewer than 1,000 rows", "Clubs are legally prohibited from using a DBMS"]'::jsonb,0,'The notes explicitly state that for a small, low-risk dataset, the DBMS''s complexity/setup cost outweighs its benefits.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-3','pt-dbms-sql-1-dbms-advantages-and-trade-offs','What ongoing cost does the notes say a college takes on once it adopts a DBMS instead of a spreadsheet?','["The need for a skilled administrator to manage backups, tuning, and security patches", "The requirement to hire a new registrar for every department", "A mandatory annual audit by the government", "The complete loss of the ability to run reports"]'::jsonb,0,'The notes state the trade-off of adopting a DBMS is needing a DBA to handle backups, performance tuning, and security patches.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-4','pt-dbms-sql-1-dbms-advantages-and-trade-offs','In what scenario does the notes say a hand-rolled binary file format could actually outperform a general-purpose DBMS?','["A narrow, read-only, single-user workload that doesn''t need transactions, concurrency, or SQL parsing overhead", "Any workload involving more than one table", "Whenever more than one user needs to read the data", "Only when the DBMS is a NoSQL database"]'::jsonb,0,'The notes point out that for narrow read-only single-user use cases, a DBMS''s general-purpose overhead (transactions, concurrency, SQL parsing) can make it slower than a specialized binary format.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-5','pt-dbms-sql-1-dbms-advantages-and-trade-offs','What trade-off does the notes highlight when comparing Oracle to PostgreSQL/MySQL?','["Commercial DBMS products can carry significant licensing costs compared to open-source alternatives", "Oracle cannot store relational data", "PostgreSQL and MySQL do not support SQL", "Open-source databases cannot be used by colleges"]'::jsonb,0,'The notes specifically name licensing cost as a hidden trade-off, contrasting commercial products like Oracle with open-source options like PostgreSQL and MySQL.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-6','pt-dbms-sql-1-dbms-advantages-and-trade-offs','Why is choosing a full client-server RDBMS for a mobile app''s local settings considered a poor trade-off in the notes?','["It is an unnecessary case of over-provisioning; a lightweight embedded database like SQLite fits the use case better", "Mobile apps are technically incapable of connecting to any DBMS", "Client-server RDBMSs cannot store settings data at all", "SQLite is a client-server database, not an embedded one"]'::jsonb,0,'The notes explicitly call this over-provisioning and recommend an embedded database like SQLite for such a small, local use case.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-7','pt-dbms-sql-1-dbms-advantages-and-trade-offs','A college adopts PostgreSQL but does not budget for anyone to manage backups or tune performance. According to the notes'' pitfalls, what is the likely outcome?','["The system often fails to realize the advantages that exist on paper, because administrative complexity does not disappear on its own", "The DBMS will automatically administer itself with no negative consequences", "This has no effect since PostgreSQL is open source", "The database will convert itself back into flat files automatically"]'::jsonb,0,'The notes state that adopting a DBMS without budgeting for skilled administration often leads to poorly tuned systems that fail to realize the advantages on paper.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-advantages-and-trade-offs-8','pt-dbms-sql-1-dbms-advantages-and-trade-offs','A college scales from a single-user spreadsheet to thousands of students with concurrent staff edits. Which specific advantage from the notes most directly prevents two staff members from corrupting the same grade record at the same time?','["Concurrency control", "Standardized SQL interface", "Reduced licensing cost", "Data independence"]'::jsonb,0,'The notes attribute the prevention of simultaneous record corruption specifically to the DBMS''s concurrency control, distinct from the other listed advantages.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-1-9','pt-dbms-sql-1-dbms-advantages-and-trade-offs','Does choosing an embedded database such as SQLite mean no DBMS is being used?','["Yes; every DBMS requires a separate network server", "Yes; embedded storage can never persist records", "No; every embedded database automatically supplies a central network service", "No; an embedded database is still a DBMS with a different deployment model"]'::jsonb,3,'A DBMS can run within an application. A separate server process is a deployment choice, not a universal requirement.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-1-10','pt-dbms-sql-1-dbms-advantages-and-trade-offs','What should a useful cost comparison include besides a software license?','["Only the number of letters in a product name", "Operations, infrastructure, support, backups, and application maintenance", "An assumption that all open-source operation is free", "Only the first successful connection"]'::jsonb,1,'Total cost includes the effort and resources needed to operate the required service reliably.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-1','pt-dbx2-dbms-advantages-and-trade-offs-application','Separate college spreadsheets disagree about a department name. Which potential DBMS benefit addresses the underlying coordination problem?','["Automatic correction of every imported real-world fact", "A guarantee that no application will ever keep a copy", "A requirement that every record occupy one machine", "Shared definitions and a common controlled representation"]'::jsonb,3,'Shared data and definitions reduce uncontrolled duplication when applications actually use and maintain them consistently.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-2','pt-dbx2-dbms-advantages-and-trade-offs-application','A team copies inconsistent files into tables without reconciling student identities. What should it expect?','["The DBMS necessarily resolves every identity conflict", "The inconsistencies still need explicit cleaning and modeling work", "Table storage proves all records are accurate", "SQL removes the need for data ownership"]'::jsonb,1,'A DBMS supplies mechanisms, not automatic knowledge of which conflicting source fact is correct.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-3','pt-dbx2-dbms-advantages-and-trade-offs-application','A transaction is rejected because another request reserved the last seat. How should this be assessed?','["It may be a necessary correctness outcome that the application must handle", "Every rejection proves the DBMS is defective", "The application should disable all coordination", "The denied transaction must silently be reported as successful"]'::jsonb,0,'Coordination can require waiting or rejection. The user-facing response and any eligible retry must respect the actual outcome.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-4','pt-dbx2-dbms-advantages-and-trade-offs-application','A benchmark reads one fixed binary file with one reader and no updates. What can a fast result establish?','["Superiority for every future concurrent workload", "Working backups for a college portal", "Performance for that narrow measured workload", "Correct permissions for thousands of students"]'::jsonb,2,'A measurement supports the conditions it exercised. New responsibilities can change both costs and the appropriate design.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-5','pt-dbx2-dbms-advantages-and-trade-offs-application','A college deploys a DBMS but never tests restoration. What remains unproven?','["Whether the product name contains SQL", "Whether a login screen exists", "Whether all data must be stored in a spreadsheet", "Whether its backup and recovery process can meet its needs"]'::jsonb,3,'Having recovery features available does not demonstrate a working recovery process for the deployment.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-6','pt-dbx2-dbms-advantages-and-trade-offs-application','A hosted database service manages some server operations. What should the application team still determine?','["That every responsibility has disappeared", "Which guarantees and operational duties remain its responsibility", "That no access checks are needed", "That every data model is automatically compatible"]'::jsonb,1,'A service changes responsibility boundaries. Application design, permissions and recovery requirements still need explicit ownership.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-7','pt-dbx2-dbms-advantages-and-trade-offs-application','A fifty-member club adds concurrent editors and sensitive records. Should its original spreadsheet decision be reconsidered?','["Yes; changed responsibilities can change the trade-off even at the same member count", "No; fifty members permanently forbids a DBMS", "No; record sensitivity never affects storage decisions", "Yes; every small workload must use a large server cluster"]'::jsonb,0,'Workload, access and concurrency requirements matter more than a fixed size threshold.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-8','pt-dbx2-dbms-advantages-and-trade-offs-application','A mobile application needs a small local structured dataset. Which evaluation is appropriate?','["Assume a full remote RDBMS is always necessary", "Assume SQLite is not database software", "Compare an embedded DBMS or local store with the actual local requirements", "Choose solely from a vendor logo"]'::jsonb,2,'Local deployment and a limited workload can favor embedded facilities, while requirements still determine the choice.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-9','pt-dbx2-dbms-advantages-and-trade-offs-application','A commercial database edition and an open-source deployment are compared. Which cost statement is justified?','["Evaluate actual terms and operational costs rather than assuming a complete price from the brand name", "Every commercial edition has the same fee", "Every open-source deployment has zero ongoing cost", "A license fee proves workload suitability"]'::jsonb,0,'Offerings, terms, support arrangements and operational work differ. Avoid universal or invented price claims.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-advantages-and-trade-offs-2-10','pt-dbx2-dbms-advantages-and-trade-offs-application','A team adopts a vendor-specific function that greatly simplifies a report. What is a balanced decision process?','["Ban all useful features regardless of benefit", "Evaluate its present benefit and document the future compatibility dependency", "Assume migration will never require work", "Claim the function is portable without checking"]'::jsonb,1,'A deliberate feature choice can be sensible when its benefits and compatibility costs are understood.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
