if exists(select 1 from public.practice_tests where id='pt-dbx2-dbms-components-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'dbms-components'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Cooperating responsibilities in a DBMS read", "description": "This responsibility map is deliberately not a universal execution sequence. A real request can revisit these facilities, and products can combine their implementation boundaries.", "columns": ["Responsibility", "Illustrative work", "Important interaction"], "rows": [["Query processor", "Resolve names and plan execution", "Consults catalog definitions and requests data"], ["Transaction facilities", "Apply visibility and coordination rules", "Interact with reads, writes and recovery"], ["Buffer manager", "Manage cached and dirty pages", "Coordinates memory replacement and persistence"], ["Storage manager", "Access persistent representation and indexes", "Cooperates with buffers and recovery protocols"], ["Broad runtime / engine", "Coordinate the overall request", "Product-specific boundaries; not synonymous with every storage plugin"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'dbms-components'; end if;
