if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-dbms-components-1' and (question_text,options,correct_index,explanation) is distinct from ('Which five components does this chapter identify as the cooperating subsystems of a DBMS?','["Database Engine, Storage Manager, Query Processor, Transaction Manager, Buffer Manager", "Database Engine, Application Developer, End User, Designer, DBA", "Data, Information, Metadata, Knowledge, and the Query Processor", "Storage Manager, Buffer Manager, and three copies of the Query Processor"]'::jsonb,0,'The notes name exactly these five components as the DBMS subsystems covered in the chapter.') and (question_text,options,correct_index,explanation) is distinct from ('Which five responsibility labels does this introductory model use?','["Database Engine, Storage Manager, Query Processor, Transaction Manager, Buffer Manager", "Database Engine, Application Developer, End User, Designer, DBA", "Data, Information, Metadata, Knowledge, and the Query Processor", "Storage Manager, Buffer Manager, and three copies of the Query Processor"]'::jsonb,0,'The notes name exactly these five components as the DBMS subsystems covered in the chapter.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-dbms-components-1'; end if;
