if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-dbms-components-2' and (question_text,options,correct_index,explanation) is distinct from ('In the query pipeline example, which component is responsible for parsing the SQL and choosing an execution plan?','["The Query Processor", "The Buffer Manager", "The Storage Manager", "The Transaction Manager"]'::jsonb,0,'The notes state the Query Processor parses, validates, and chooses the execution plan for a query.') and (question_text,options,correct_index,explanation) is distinct from ('In the query pipeline example, which component is responsible for parsing the SQL and choosing an execution plan?','["The Query Processor", "The Buffer Manager", "The Storage Manager", "The Transaction Manager"]'::jsonb,0,'The notes state the Query Processor parses, validates, and chooses the execution plan for a query.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-dbms-components-2'; end if;
