if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-dbms-components-4' and (question_text,options,correct_index,explanation) is distinct from ('According to the pipeline described in the notes, what is the correct order of components a read query passes through?','["Query Processor -> Transaction Manager supervision -> Buffer Manager -> Storage Manager", "Storage Manager -> Query Processor -> Database Engine -> Buffer Manager", "Buffer Manager -> Storage Manager -> Transaction Manager -> Query Processor", "Transaction Manager -> Storage Manager -> Query Processor -> Buffer Manager"]'::jsonb,0,'The notes describe the pipeline as Client -> Query Processor -> (wrapped by Transaction Manager) -> Buffer Manager -> Storage Manager.') and (question_text,options,correct_index,explanation) is distinct from ('Which responsibilities cooperate in this topic''s conceptual read trace, rather than forming a universal once-only pipeline?','["Query interpretation/planning, transaction visibility, buffer access, and persistent-data access", "Only drawing the user interface", "Only the administrator''s job title", "Only copying an arbitrary file"]'::jsonb,0,'These are interacting responsibilities. A real product can combine them or revisit them during execution.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-dbms-components-4'; end if;
