insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-components-2-5','pt-dbx2-dbms-components-application','Why can a write-ahead logging protocol constrain when a dirty data page is persisted?','["Required log information must be durable before the corresponding data-page write under the protocol", "Log information must always be discarded first", "Every page must bypass all buffers", "Transaction recovery never uses persistent information"]'::jsonb,0,'The log/data ordering supports recovery; it is not a requirement to flush every page immediately after every change.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-components-2-6','pt-dbx2-dbms-components-application','A query is slow because it waits on conflicting work. Would a shorter SQL string necessarily fix it?','["Yes; statement length determines every wait", "No; the wait and transaction interaction need investigation", "Yes; every index removes every conflict", "No; query observations can never reveal waits"]'::jsonb,1,'A visible query symptom can be caused by coordination rather than the length of the statement.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
