update public.learning_topics set short_description='Connect DBMS goals to course registration: data independence, integrity, concurrency, security, controlled redundancy, performance, recovery, and explicit trade-offs.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Connect DBMS goals to course registration: data independence, integrity, concurrency, security, controlled redundancy, performance, recovery, and explicit trade-offs.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for DBMS Goals.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-dbms-goals' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-dbms-goals-application','MCQ Test 2',category,10,10,'Application and scenarios for DBMS Goals.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-dbms-goals' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-1','pt-dbms-sql-1-dbms-goals','Which of the following is listed as a core goal of a DBMS in the notes?','["Concurrent access control", "Maximizing uncontrolled redundancy", "Eliminating the need for any query language", "Preventing all users from ever seeing the same data"]'::jsonb,0,'The notes list concurrent access control as one of the core DBMS goals, alongside data independence, integrity, security, efficiency, and recovery.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-2','pt-dbms-sql-1-dbms-goals','What does ''physical data independence'' mean according to the notes?','["Changing the storage layout, such as adding an index, should not require rewriting application queries", "The database must be stored on physically separate hard drives", "Applications must never store any data physically", "Every table must be stored in its own separate file"]'::jsonb,0,'The notes define physical data independence as the ability to change physical storage (like adding an index) without needing to rewrite application queries.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-3','pt-dbms-sql-1-dbms-goals','Which constraint type is given as an example of enforcing the ''data integrity'' goal?','["CHECK (marks BETWEEN 0 AND 100)", "SELECT * FROM students", "GRANT SELECT TO analyst", "CREATE INDEX ON students(marks)"]'::jsonb,0,'The notes cite CHECK constraints (along with PRIMARY KEY and FOREIGN KEY) as mechanisms that automatically enforce data integrity.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-4','pt-dbms-sql-1-dbms-goals','Which DBMS capability supports a transaction that atomically checks and updates the last available seat?','["Concurrency control with suitable locking or conflict detection", "Data independence", "Controlled redundancy", "The GRANT/REVOKE security system"]'::jsonb,0,'The application must use a correct transaction and capacity update; the DBMS then supplies the required coordination. MVCC alone is not proof that the algorithm is safe.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-5','pt-dbms-sql-1-dbms-goals','Why does the DBMS aim for ''controlled'' redundancy instead of eliminating redundancy entirely?','["A small amount of deliberate, tracked redundancy can improve read performance, as long as it doesn''t cause inconsistency", "Redundancy is always harmful and the goal is to reach exactly zero", "Redundancy has nothing to do with performance", "Controlled redundancy refers only to backup copies of the entire database"]'::jsonb,0,'The notes explain that some redundancy, like a cached total_marks column, can be kept deliberately for performance as long as it is controlled rather than accidental.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-6','pt-dbms-sql-1-dbms-goals','According to the pitfalls section, how can minimizing redundancy conflict with another DBMS goal?','["Fully normalizing to minimize redundancy can require more joins, which can hurt query efficiency", "Minimizing redundancy always improves every other goal with no trade-offs", "It has no relationship to any other DBMS goal", "It only affects the security goal, not efficiency"]'::jsonb,0,'The notes explicitly state that minimizing redundancy through normalization can increase the number of joins needed, conflicting with the efficient query processing goal.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-7','pt-dbms-sql-1-dbms-goals','A developer writes ''SELECT *'' in a report query, and the report breaks after an unrelated new column is added to the table. Which DBMS goal does this scenario undermine, and why?','["Logical data independence is weakened because SELECT * ties the report to the current logical column set", "Security and authorization, because SELECT * exposes passwords", "Crash recovery, because SELECT * disables the transaction log", "Concurrency control, because SELECT * locks the entire table permanently"]'::jsonb,0,'Adding a column changes the logical result shape of SELECT *. An index or page-layout change is a different, physical concern.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-dbms-goals-8','pt-dbms-sql-1-dbms-goals','A DBA configures the database to use asynchronous commit for higher write throughput. What does the notes'' pitfall about crash recovery imply about this configuration?','["Recovery guarantees only hold as strongly as the durability settings actually configured, so asynchronous commit trades some durability for speed", "Crash recovery is completely unaffected by any commit or durability settings", "Asynchronous commit makes crash recovery impossible under any circumstances", "This setting only affects the security and authorization goal"]'::jsonb,0,'The notes warn that some settings, such as asynchronous commit, trade durability for speed, so recovery guarantees are only as strong as the actual configuration.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-1-9','pt-dbms-sql-1-dbms-goals','Which result is needed to demonstrate a declared integrity rule beyond one successful example?','["Every user must become an administrator", "All indexes must be removed", "Every operation must run sequentially forever", "A relevant invalid case must also be rejected"]'::jsonb,3,'A permitted example establishes acceptance only. Rejection tests show whether the rule also prevents invalid states.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-1-10','pt-dbms-sql-1-dbms-goals','Why is hiding an edit button insufficient to protect marks?','["Hidden buttons always modify the database directly", "The trusted boundary must reject unauthorized requests from any client", "Authorization depends only on font color", "A hidden control grants a database privilege"]'::jsonb,1,'A caller can bypass the interface. Authorization belongs at the server or database boundary handling the request.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-1','pt-dbx2-dbms-goals-application','Adding an index lets a query use a faster access path without changing its requested columns. Which goal does this illustrate?','["Automatic invention of business rules", "Elimination of every stored copy", "A change to the meaning of a student record", "Physical data independence"]'::jsonb,3,'The storage/access implementation changed while the logical query remained compatible.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-2','pt-dbx2-dbms-goals-application','A report using SELECT * breaks when a column is added. Which coupling caused the problem?','["Dependence on the exact disk block address", "Dependence on an index traversal instruction", "Dependence on the machine''s power cable", "Dependence on the current logical output shape"]'::jsonb,3,'The report tied its result contract to the table''s full column set, which is a logical-definition dependency.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-3','pt-dbx2-dbms-goals-application','Two students both read one remaining seat before either writes. What should be reviewed first?','["The reservation transaction and its atomic capacity check/update", "Only the welcome-message wording", "Whether marks use a larger integer type", "Whether the page has more illustrations"]'::jsonb,0,'Reading availability and later making a separate decision can race. The reservation algorithm must coordinate the relevant changes.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-4','pt-dbx2-dbms-goals-application','Does enabling multiversion concurrency control prove every registration algorithm is safe?','["Yes; all application anomalies become impossible", "Yes; constraints and error handling become unnecessary", "No; isolation, statements, boundaries, and conflict handling still matter", "No; multiversion control cannot ever support readers"]'::jsonb,2,'Multiple versions support concurrency, but do not automatically enforce every cross-operation business invariant.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-5','pt-dbx2-dbms-goals-application','A report summary duplicates enrollment counts. What makes this controlled redundancy?','["An undocumented background copy nobody owns", "A claim that duplicate data can never disagree", "Defined ownership, maintenance rules, and an understood freshness contract", "No way to compare the summary with source records"]'::jsonb,2,'Deliberate duplicate representations need rules that keep them useful and aligned with their source or permitted staleness.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-6','pt-dbx2-dbms-goals-application','An additional index speeds up a report but slows frequent inserts. What should decide whether to keep it?','["Measured read/write workload costs and required performance", "The assumption that every index is free", "Only the length of the index name", "A rule forbidding all access structures"]'::jsonb,0,'An index can save read work while adding maintenance work. Evaluate the actual workload and requirements.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-7','pt-dbx2-dbms-goals-application','A database accepts mark 84 for the wrong student. Does a successful range check establish factual accuracy?','["Yes; a range check verifies all real-world facts", "No; the value can satisfy the range while describing the wrong person", "Yes; numbers inside the range are always true", "No; range checks cannot reject 140"]'::jsonb,1,'A constraint enforces its declared condition, not facts that were never represented in that condition.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-8','pt-dbx2-dbms-goals-application','A system acknowledges a commit before the required durable write. What crash risk must be considered?','["Some recently acknowledged changes may not survive", "Every earlier backup is necessarily deleted", "All reads become unauthorized automatically", "The product must invent missing data"]'::jsonb,0,'Recovery can only preserve changes supported by the configured persistence guarantees and actual storage behavior.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-9','pt-dbx2-dbms-goals-application','A student can read their own registrations. What further authorization check is useful?','["Confirming every account has administrative access", "Confirming they cannot read or change another student''s restricted records", "Removing identity checks to improve convenience", "Assuming read access implies permission to change marks"]'::jsonb,1,'Least privilege distinguishes users, records, and operations. Denied-actor tests are necessary evidence.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-dbms-goals-2-10','pt-dbx2-dbms-goals-application','Which statement best evaluates a DBMS deployment?','["A successful login proves all recovery procedures", "Check each required guarantee and its failure cases, rather than only whether a connection works", "A quick query proves every returned row was authorized", "One valid insert proves all invalid values are rejected"]'::jsonb,1,'Connectivity, performance, authorization, integrity and recovery are separate claims requiring appropriate evidence.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
