select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-8-sql-fundamentals/dcl' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'dcl'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'dcl'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('9c2c76da6983bf8187caae9e91786fbd','16062652e6c94094ddbd5e6307321d46')) then raise exception 'Notes changed since seed; review before applying: %', 'dcl'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-dcl' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'dcl'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-dcl' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'dcl'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-8-dcl','pt-dbms-sql-8-dcl-application')) then raise exception 'Extra topic tests require manual integration: %', 'dcl'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-8-dcl-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'dcl'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Effective paths in the synthetic access policy", "description": "This is the exercise model, not the complete MySQL grant system. Either a direct or active matching role path allows the request once.", "columns": ["Direct match", "Active role match", "Decision"], "rows": [["Yes", "No", "Allowed"], ["No", "Yes", "Allowed"], ["Yes", "Yes", "Allowed once"], ["No", "No", "Denied"], ["No", "Inactive membership only", "Denied"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'dcl'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Effective paths in the synthetic access policy", "description": "This is the exercise model, not the complete MySQL grant system. Either a direct or active matching role path allows the request once.", "columns": ["Direct match", "Active role match", "Decision"], "rows": [["Yes", "No", "Allowed"], ["No", "Yes", "Allowed"], ["Yes", "Yes", "Allowed once"], ["No", "No", "Denied"], ["No", "Inactive membership only", "Denied"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Effective paths in the synthetic access policy", "description": "This is the exercise model, not the complete MySQL grant system. Either a direct or active matching role path allows the request once.", "columns": ["Direct match", "Active role match", "Decision"], "rows": [["Yes", "No", "Allowed"], ["No", "Yes", "Allowed"], ["Yes", "Yes", "Allowed once"], ["No", "No", "Denied"], ["No", "Inactive membership only", "Denied"]]}]'::jsonb;
