if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dcl-2' and (question_text,options,correct_index,explanation) is distinct from ('What does GRANT SELECT ON employees TO app_readonly_role accomplish?','["It deletes all employee data", "It gives the app_readonly_role permission to read (SELECT) from the employees table, and nothing else implied by this statement", "It creates a new table called app_readonly_role", "It removes all permissions from app_readonly_role"]'::jsonb,1,'GRANT SELECT specifically authorizes reading, not writing or structural changes.') and (question_text,options,correct_index,explanation) is distinct from ('What does a narrow SELECT grant establish by itself?','["It deletes all employee data", "The specified reading capability, while other effective rights still require review", "It creates a new table called app_readonly_role", "It removes all permissions from app_readonly_role"]'::jsonb,1,'A new narrow grant does not erase older direct or role-derived authority.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dcl-2'; end if;
