if not exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dcl-3' and test_id='pt-dbms-sql-8-dcl') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-8-dcl-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dcl-3' and (question_text,options,correct_index,explanation) is distinct from ('What is the ''principle of least privilege'' that DCL is meant to implement?','["Every account should be granted every possible privilege by default", "Each account should have exactly the permissions it needs to do its job, and no more", "Privileges should be granted randomly to test the system", "Only the database administrator should ever be able to log in"]'::jsonb,1,'Least privilege means scoping each account''s access as narrowly as its actual job requires.') and (question_text,options,correct_index,explanation) is distinct from ('What is the ''principle of least privilege'' that DCL is meant to implement?','["Every account should be granted every possible privilege by default", "Each account should have exactly the permissions it needs to do its job, and no more", "Privileges should be granted randomly to test the system", "Only the database administrator should ever be able to log in"]'::jsonb,1,'Least privilege means scoping each account''s access as narrowly as its actual job requires.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dcl-3'; end if;
