if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dcl-6' and (question_text,options,correct_index,explanation) is distinct from ('In many database systems, what is a ''role'' in the context of DCL?','["A synonym for a single specific user account", "A named bundle of privileges that can be granted to users as a unit, rather than granting many individual privileges one at a time", "A type of table constraint", "A kind of index"]'::jsonb,1,'Roles group privileges together so they can be assigned and managed as a single unit, which scales better than per-user, per-privilege grants.') and (question_text,options,correct_index,explanation) is distinct from ('In many database systems, what is a ''role'' in the context of DCL?','["A synonym for a single specific user account", "A named bundle of privileges that can be granted to users as a unit, rather than granting many individual privileges one at a time", "A type of table constraint", "A kind of index"]'::jsonb,1,'Roles group privileges together so they can be assigned and managed as a single unit, which scales better than per-user, per-privilege grants.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dcl-6'; end if;
