if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dcl-7' and (question_text,options,correct_index,explanation) is distinct from ('Does REVOKE-ing a privilege necessarily terminate an already-open session immediately on every database engine?','["Yes, always, instantly, on every engine with no exceptions", "Not necessarily \u2014 how and when a revoked privilege takes effect for an already-open session can vary by engine", "REVOKE never has any effect on open sessions, ever", "REVOKE only works if the user is currently disconnected"]'::jsonb,1,'The timing of when a REVOKE actually takes effect for an existing session is engine-dependent — an important operational subtlety.') and (question_text,options,correct_index,explanation) is distinct from ('Does REVOKE-ing a privilege necessarily terminate an already-open session immediately on every database engine?','["Yes, always, instantly, on every engine with no exceptions", "Not necessarily \u2014 how and when a revoked privilege takes effect for an already-open session can vary by engine", "REVOKE never has any effect on open sessions, ever", "REVOKE only works if the user is currently disconnected"]'::jsonb,1,'The timing of when a REVOKE actually takes effect for an existing session is engine-dependent — an important operational subtlety.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dcl-7'; end if;
