if exists(select 1 from public.test_questions where id='pt-dbms-sql-8-dcl-new-9' and (question_text,options,correct_index,explanation) is distinct from ('What must be distinguished from authentication?','["The existence of a principal", "Authorization for a specific action and resource", "The identity established by a connection", "The fact that credentials were accepted"]'::jsonb,1,'Authentication alone does not supply every capability.') and (question_text,options,correct_index,explanation) is distinct from ('What must be distinguished from authentication?','["The existence of a principal", "Authorization for a specific action and resource", "The identity established by a connection", "The fact that credentials were accepted"]'::jsonb,1,'Authentication alone does not supply every capability.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-8-dcl-new-9'; end if;
