update public.learning_topics set short_description='Reason about grants, revocation, roles, and least privilege through explicit action/resource contracts, with synthetic permission audits kept separate from actual database enforcement.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Reason about grants, revocation, roles, and least privilege through explicit action/resource contracts, with synthetic permission audits kept separate from actual database enforcement.';
