insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-1','pt-dbms-sql-8-dcl','Which two verbs form the core of DCL?','["CREATE and DROP", "GRANT and REVOKE", "COMMIT and ROLLBACK", "SELECT and INSERT"]'::jsonb,1,'GRANT and REVOKE manage permissions — the essence of DCL.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-2','pt-dbms-sql-8-dcl','What does a narrow SELECT grant establish by itself?','["It deletes all employee data", "The specified reading capability, while other effective rights still require review", "It creates a new table called app_readonly_role", "It removes all permissions from app_readonly_role"]'::jsonb,1,'A new narrow grant does not erase older direct or role-derived authority.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-3','pt-dbms-sql-8-dcl','What is the ''principle of least privilege'' that DCL is meant to implement?','["Every account should be granted every possible privilege by default", "Each account should have exactly the permissions it needs to do its job, and no more", "Privileges should be granted randomly to test the system", "Only the database administrator should ever be able to log in"]'::jsonb,1,'Least privilege means scoping each account''s access as narrowly as its actual job requires.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-4','pt-dbms-sql-8-dcl','Why might granting ALL PRIVILEGES broadly ''to make things work'' be a bad long-term habit?','["It has no downsides and is always the correct approach", "It defeats least privilege and makes it much harder to reason about what an over-privileged account can''t do, increasing the blast radius of any bug or attack", "ALL PRIVILEGES is not valid SQL syntax", "It only affects DDL statements, not DML"]'::jsonb,1,'Over-granting privileges widens the potential damage from a bug or compromised credential, which is exactly what least privilege tries to prevent.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-5','pt-dbms-sql-8-dcl','Why avoid unnecessary write authority for a reading report?','["Because SELECT is the only privilege that exists in SQL", "It reduces unneeded write capability while confidentiality and resource risks still need controls", "Because SELECT is required before any other GRANT can be issued", "Because dashboards cannot connect to databases that support INSERT"]'::jsonb,1,'Reading is not universally harmless; least privilege is one boundary.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-6','pt-dbms-sql-8-dcl','In many database systems, what is a ''role'' in the context of DCL?','["A synonym for a single specific user account", "A named bundle of privileges that can be granted to users as a unit, rather than granting many individual privileges one at a time", "A type of table constraint", "A kind of index"]'::jsonb,1,'Roles group privileges together so they can be assigned and managed as a single unit, which scales better than per-user, per-privilege grants.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-7','pt-dbms-sql-8-dcl','Does REVOKE-ing a privilege necessarily terminate an already-open session immediately on every database engine?','["Yes, always, instantly, on every engine with no exceptions", "Not necessarily — how and when a revoked privilege takes effect for an already-open session can vary by engine", "REVOKE never has any effect on open sessions, ever", "REVOKE only works if the user is currently disconnected"]'::jsonb,1,'The timing of when a REVOKE actually takes effect for an existing session is engine-dependent — an important operational subtlety.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dcl-8','pt-dbms-sql-8-dcl','Assuming no other effective rights, what bounds a compromised connection with SELECT and INSERT on two objects?','["The impact is identical to full database access, since DCL provides no real protection", "Its effective privileges limit the operations and objects available, although allowed reads and inserts can still cause harm", "The application becomes completely unusable the moment it is compromised", "DCL prevents SQL injection from ever succeeding in the first place"]'::jsonb,1,'Least privilege does not prevent injection or make permitted operations safe in every context.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-dcl-new-9','pt-dbms-sql-8-dcl','What must be distinguished from authentication?','["The existence of a principal", "Authorization for a specific action and resource", "The identity established by a connection", "The fact that credentials were accepted"]'::jsonb,1,'Authentication alone does not supply every capability.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-dcl-new-10','pt-dbms-sql-8-dcl','Does removing one direct grant always remove the action supplied through a role?','["Yes; every role disappears", "Only when the table is empty", "No; the surviving role path needs review", "Only when the name is lowercase"]'::jsonb,2,'Effective rights can have several paths.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
