update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for DDL.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-8-ddl' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-8-ddl-application','MCQ Test 2',category,10,10,'Application and scenarios for DDL.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-8-ddl' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-1','pt-dbms-sql-8-ddl','Which three verbs form the core of DDL?','["SELECT, INSERT, UPDATE", "CREATE, ALTER, DROP", "GRANT, REVOKE, DENY", "COMMIT, ROLLBACK, SAVEPOINT"]'::jsonb,1,'CREATE, ALTER, and DROP define and change the structure of database objects — the essence of DDL.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-2','pt-dbms-sql-8-ddl','What is the key difference between DROP TABLE and DELETE FROM table?','["They are exact synonyms with no difference", "DROP TABLE removes the structure and data together; DELETE FROM only removes the data, keeping the table structure", "DELETE FROM removes the table structure; DROP TABLE only removes data", "DROP TABLE can be undone with UPDATE"]'::jsonb,1,'DROP TABLE eliminates the object entirely (structure + data); DELETE FROM empties the rows but the table itself still exists.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-3','pt-dbms-sql-8-ddl','Can an ordinary successful MySQL permanent CREATE TABLE generally be undone by a later user ROLLBACK?','["Yes, always, on every engine without exception", "No; ordinary permanent CREATE TABLE has implicit-commit behavior and is not reversed that way", "Only if wrapped in a SAVEPOINT", "Only on weekends"]'::jsonb,1,'This question is scoped to MySQL; it does not make the incorrect claim that SQL Server universally lacks transactional CREATE TABLE.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-4','pt-dbms-sql-8-ddl','Which statement correctly distinguishes atomic DDL from transactional DDL?','["MySQL", "Oracle", "Atomic DDL coordinates completion/recovery; transactional DDL concerns undo through user transaction boundaries", "SQLite always without exception"]'::jsonb,2,'MySQL atomic DDL is not a promise of later user rollback.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-5','pt-dbms-sql-8-ddl','Which statement correctly adds a new column to an existing table?','["ALTER TABLE employees ADD COLUMN hire_date DATE;", "CREATE COLUMN hire_date ON employees;", "UPDATE employees ADD hire_date DATE;", "INSERT COLUMN hire_date INTO employees;"]'::jsonb,0,'ALTER TABLE ... ADD COLUMN is the standard way to add a column to an existing table.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-6','pt-dbms-sql-8-ddl','Why should DDL transaction behavior be checked for the exact product and statement?','["Because it''s true on literally every database with zero exceptions, so it''s actually safe", "Different engines and operations have different implicit-commit and rollback rules", "Because DDL never commits on any engine", "Because auto-commit only applies to SELECT statements"]'::jsonb,1,'Avoid universal claims, including about temporary objects and other database products.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-7','pt-dbms-sql-8-ddl','What is a real operational risk of running ALTER TABLE ... DROP COLUMN on a large, live production table?','["There is never any risk — ALTER TABLE is always instantaneous on every engine", "On some engines it can be a slow, locking operation, not an instant metadata-only change", "It always deletes the entire table by accident", "It is impossible to drop a column on a table with any data in it"]'::jsonb,1,'Depending on the engine and table size, structural changes can require rewriting data or holding locks, making them slower and riskier than they look syntactically.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-ddl-8','pt-dbms-sql-8-ddl','What category of SQL statement is CREATE INDEX?','["DML", "DQL", "DDL", "TCL"]'::jsonb,2,'CREATE INDEX defines a structural database object (an index), which makes it DDL, just like CREATE TABLE.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
