insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-ddl-application-new-1','pt-dbms-sql-8-ddl-application','A temporary equipment table is created and the user rolls back. Must the object creation itself be undone?','["Yes; all temporary objects are transactional DDL", "Yes; every table is removed by ROLLBACK", "No; temporary creation does not imply user-rollback support", "Only the table name is rolled back"]'::jsonb,2,'MySQL temporary creation avoids the ordinary create implicit commit but is not itself undone by user rollback.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
