update public.learning_topics set short_description='Distinguish omitted values, explicit DEFAULT and explicit NULL, change future insertion policy without rewriting historical rows, and separate initialization from generated recalculation.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish omitted values, explicit DEFAULT and explicit NULL, change future insertion policy without rewriting historical rows, and separate initialization from generated recalculation.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for DEFAULT.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-10-default' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-10-default-application','MCQ Test 2',category,10,10,'Application and scenarios for DEFAULT.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-10-default' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-1','pt-dbms-sql-10-default','How can the illustrated MySQL INSERT request a column default?','["Whenever the column''s value is NULL, whether explicit or omitted", "By omitting the column or using DEFAULT in a supported assignment", "Only during UPDATE statements", "Only if the table has no PRIMARY KEY"]'::jsonb,1,'Omission is not the only supported request form.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-2','pt-dbms-sql-10-default','A column is declared `quantity INT DEFAULT 0` (nullable, no NOT NULL). What is the result of INSERT INTO products (product_id, quantity) VALUES (2, NULL)?','["quantity is set to 0 via the DEFAULT", "quantity is stored as NULL, since explicit NULL overrides DEFAULT", "The insert fails", "quantity is set to an empty string"]'::jsonb,1,'Explicitly passing NULL always wins over DEFAULT; DEFAULT only fills in when the column is omitted from the statement, not when NULL is explicitly given.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-3','pt-dbms-sql-10-default','Why should CURRENT_TIMESTAMP not be taught as a different wall-clock sample for every inserted row?','["Once, at the moment the table is created", "Evaluation semantics depend on the product and statement or transaction context", "Once per session, cached for all inserts in that session", "Never automatically; it must be set manually per insert"]'::jsonb,1,'MySQL current-time evaluation can be consistent within a statement.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-4','pt-dbms-sql-10-default','If you run ALTER TABLE products ALTER COLUMN status SET DEFAULT ''active''; on a table with existing rows, what happens to those existing rows'' status values?','["They are all immediately updated to ''active''", "They remain unchanged; only future inserts that omit the column get the new default", "They become NULL until manually updated", "The ALTER TABLE fails if rows already exist"]'::jsonb,1,'Changing a DEFAULT clause only affects future inserts; it is not retroactively applied to rows already stored in the table.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-5','pt-dbms-sql-10-default','Which MySQL-specific extension allows a TIMESTAMP column to automatically refresh its value whenever the row is updated?','["DEFAULT CURRENT_TIMESTAMP alone", "ON UPDATE CURRENT_TIMESTAMP", "AUTO REFRESH TIMESTAMP", "TRIGGER BEFORE UPDATE"]'::jsonb,1,'MySQL supports an ON UPDATE CURRENT_TIMESTAMP clause on a column, a non-standard extension not part of ANSI SQL, that auto-updates the value on every row update.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-6','pt-dbms-sql-10-default','Can MySQL 8.4 expression defaults reference other table columns?','["Yes, in all standard SQL engines", "Yes in supported cases, subject to documented expression and dependency restrictions", "Yes, but only in PostgreSQL", "Yes, but only for numeric columns"]'::jsonb,1,'The blanket prohibition is incorrect for this target; initialization still differs from ongoing generation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-7','pt-dbms-sql-10-default','Is a table''s auto-increment mechanism (AUTO_INCREMENT / SERIAL / IDENTITY) the same feature as the DEFAULT clause?','["Yes, they are exactly the same keyword", "No, auto-increment is conceptually similar but is usually a distinct feature/keyword, not the DEFAULT clause itself", "Yes, but only in Oracle", "No, auto-increment is a type of CHECK constraint"]'::jsonb,1,'While auto-increment behaves like an automatically-supplied value, it is implemented via its own dedicated syntax (AUTO_INCREMENT, SERIAL, GENERATED ... AS IDENTITY) rather than the generic DEFAULT clause.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-default-8','pt-dbms-sql-10-default','Under the stated strict ordinary-column fixture, what happens to explicit NULL in NOT NULL status?','["status becomes ''pending'' via DEFAULT", "It is rejected rather than treated as an omission requesting the default", "status becomes an empty string", "The insert succeeds with status left as NULL"]'::jsonb,1,'SQL modes and special column rules must be scoped instead of generalized universally.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-default-new-9','pt-dbms-sql-10-default','Does changing a default rewrite every existing row?','["Yes", "No", "Only if the column is text", "Only when sorted"]'::jsonb,1,'Future initialization and backfill are different operations.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-default-new-10','pt-dbms-sql-10-default','What does explicit NULL mean for the stated ordinary nullable quantity?','["Always store ten", "Delete the row", "Store the missing marker rather than request the literal default", "Allocate a sequence token"]'::jsonb,2,'The input is different from omission.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-default-application-new-1','pt-dbms-sql-10-default-application','Does DEFAULT pending restrict every supplied status to pending?','["Yes", "Only for VARCHAR", "No", "Only if named"]'::jsonb,2,'Initialization is not a vocabulary constraint.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-default-application-new-2','pt-dbms-sql-10-default-application','Can a defaulted historical amount be assumed to recalculate after every source change?','["Yes", "Only when indexed", "Only if aliases match", "No"]'::jsonb,3,'Continuing derivation is a different contract.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
