if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-deferred-constraint-concepts-3' and (question_text,options,correct_index,explanation) is distinct from ('When is a constraint declared DEFERRABLE INITIALLY DEFERRED actually validated?','["After every individual INSERT/UPDATE statement, same as immediate constraints", "Once, at COMMIT time, for the entire transaction", "Only when the table is dropped", "Immediately, but only for the first statement in the transaction"]'::jsonb,1,'INITIALLY DEFERRED means the constraint check is postponed until the transaction commits, allowing temporary mid-transaction inconsistency.') and (question_text,options,correct_index,explanation) is distinct from ('When must a still-deferred eligible PostgreSQL constraint hold?','["After every individual INSERT/UPDATE statement, same as immediate constraints", "At its required final check, normally commit unless an earlier immediate check is requested", "Only when the table is dropped", "Immediately, but only for the first statement in the transaction"]'::jsonb,1,'It is not necessarily checked only once at commit in every workflow.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-deferred-constraint-concepts-3'; end if;
