if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-deferred-constraint-concepts-4' and (question_text,options,correct_index,explanation) is distinct from ('Does MySQL support PostgreSQL-style DEFERRABLE INITIALLY DEFERRED constraints?','["Yes, identically to PostgreSQL", "No, MySQL does not support deferrable constraints; a common workaround is SET FOREIGN_KEY_CHECKS=0", "Yes, but only for UNIQUE constraints", "Yes, but only in MySQL 8.0.16 and later"]'::jsonb,1,'MySQL has no true deferred-constraint mechanism; the typical workaround for circular references or bulk loads is temporarily disabling foreign key checks entirely, which is cruder than per-transaction deferral.') and (question_text,options,correct_index,explanation) is distinct from ('Is disabling MySQL foreign-key checking equivalent to PostgreSQL deferred enforcement?','["Yes, identically to PostgreSQL", "No; it does not provide the same required final-state validation contract", "Yes, but only for UNIQUE constraints", "Yes, but only in MySQL 8.0.16 and later"]'::jsonb,1,'Do not recommend weakening checks as a routine deferral substitute.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-deferred-constraint-concepts-4'; end if;
