if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-deferred-constraint-concepts-6' and (question_text,options,correct_index,explanation) is distinct from ('If data is still genuinely inconsistent at COMMIT time for a transaction using a deferred constraint, what happens?','["The commit silently succeeds anyway", "The entire transaction is rolled back, just as immediate checking would reject an individual bad statement", "Only the last statement in the transaction is rolled back", "The constraint is automatically dropped"]'::jsonb,1,'Deferred constraints still fire eventually — if the data hasn''t become consistent by COMMIT time, the whole transaction fails and rolls back.') and (question_text,options,correct_index,explanation) is distinct from ('What if an eligible deferred rule remains violated at its required final check?','["The commit silently succeeds anyway", "The transaction cannot complete as a successful inconsistent commit; the application must handle the failure state", "Only the last statement in the transaction is rolled back", "The constraint is automatically dropped"]'::jsonb,1,'Do not assume every client automatically recovers a usable transaction.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-deferred-constraint-concepts-6'; end if;
