insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-deferred-constraint-concepts-1','pt-dbms-sql-10-deferred-constraint-concepts','Without supported deferral, how should constraint timing be interpreted?','["Only at COMMIT time for the whole transaction", "Under the target’s normal immediate rules for the specific constraint kind", "Only when explicitly requested via SET CONSTRAINTS", "Never, unless the table is queried afterward"]'::jsonb,1,'Not every kind has one identical internal per-statement checking point.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-deferred-constraint-concepts-2','pt-dbms-sql-10-deferred-constraint-concepts','What real-world scenario is the classic motivating example for DEFERRABLE INITIALLY DEFERRED constraints?','["Improving SELECT query performance", "Circular foreign key references between two tables, where inserting the first row of either table would otherwise violate the other''s FK", "Enforcing uniqueness across two different tables", "Making CHECK constraints run faster on large tables"]'::jsonb,1,'A mutual foreign key dependency (e.g., employees referencing departments and departments referencing employees) cannot be populated under strict immediate checking without deferring at least one constraint to COMMIT time.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-deferred-constraint-concepts-3','pt-dbms-sql-10-deferred-constraint-concepts','When must a still-deferred eligible PostgreSQL constraint hold?','["After every individual INSERT/UPDATE statement, same as immediate constraints", "At its required final check, normally commit unless an earlier immediate check is requested", "Only when the table is dropped", "Immediately, but only for the first statement in the transaction"]'::jsonb,1,'It is not necessarily checked only once at commit in every workflow.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
