insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-1','pt-dbms-sql-4-degree','What does the degree of a relation measure?','["The number of tuples currently stored", "The number of attributes in the relation''s schema", "The number of foreign keys", "The number of distinct values in the primary key"]'::jsonb,1,'Degree is defined as the count of attributes (columns) in the relation schema.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-2','pt-dbms-sql-4-degree','What is the degree of Students(id, name, department, gpa)?','["1", "3", "4", "It depends on the number of rows"]'::jsonb,2,'There are 4 attributes (id, name, department, gpa), so the degree is 4.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-3','pt-dbms-sql-4-degree','A relation with exactly one attribute is called:','["Binary", "Unary", "Ternary", "Null"]'::jsonb,1,'A relation of degree 1 (one attribute) is called unary.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-4','pt-dbms-sql-4-degree','If Students currently holds 4 rows and later grows to 10,000 rows, what happens to its degree?','["It grows proportionally with the number of rows", "It stays exactly the same, since degree only depends on the schema''s attribute count", "It becomes undefined", "It doubles every time rows double"]'::jsonb,1,'Degree is a schema-level property (attribute count) and is completely unaffected by how many rows exist.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-5','pt-dbms-sql-4-degree','Which action changes the degree of a relation?','["Inserting a new tuple", "Deleting a tuple", "Running ALTER TABLE Students ADD COLUMN email varchar(100)", "Updating a gpa value"]'::jsonb,2,'Adding a new attribute (column) increases the degree by one; row-level operations never change degree.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-6','pt-dbms-sql-4-degree','Which of the following correctly distinguishes Degree from its closest sibling concept, Cardinality?','["Degree counts rows; Cardinality counts columns", "Degree counts schema attributes; cardinality counts tuples in the current instance", "They are the same measurement expressed differently", "Degree changes with every INSERT; Cardinality never changes"]'::jsonb,1,'Degree remains stable while the attribute list is unchanged; schema evolution can change it.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-7','pt-dbms-sql-4-degree','After adding a nullable email VARCHAR(100) column with no explicit non-NULL default, how are existing SQL rows represented?','["They are deleted", "They include the new email attribute with NULL under that definition", "They automatically get a randomly generated email", "The table becomes invalid until every row supplies an email"]'::jsonb,1,'The rows follow the new attribute structure; nullability and default rules determine the added value.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-degree-8','pt-dbms-sql-4-degree','Is a relation of degree 0 (a schema with zero attributes) theoretically valid in relational algebra?','["No, every relation must have at least one attribute", "Yes; some relational formalisms allow zero-attribute relations, separately from ordinary SQL table support", "No, degree 0 is only valid for cardinality, not for relations", "Yes, but only if cardinality is also 0"]'::jsonb,1,'Over an empty heading the set model permits either no tuples or the one empty tuple; ordinary MySQL table syntax is a separate question.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
