update public.learning_topics set short_description='Remove exactly the intended row population while retaining its table contract, preserve the salary-threshold checker, and distinguish predicate correctness from dependency, transaction and recovery guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Remove exactly the intended row population while retaining its table contract, preserve the salary-threshold checker, and distinguish predicate correctness from dependency, transaction and recovery guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for DELETE.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-11-delete' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-11-delete-application','MCQ Test 2',category,10,10,'Application and scenarios for DELETE.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-11-delete' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-1','pt-dbms-sql-11-delete','What does DELETE do?','["Removes a table''s structure entirely", "Removes rows matching a condition, leaving the table structure intact", "Modifies existing row values", "Adds new rows"]'::jsonb,1,'DELETE removes rows only; the table itself (columns, indexes, constraints) remains.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-2','pt-dbms-sql-11-delete','Under an enforced restrictive parent reference, what can a DELETE of the referenced parent do?','["The delete succeeds and the child row''s reference becomes invalid", "Be rejected to preserve the accepted reference", "The child row is automatically deleted too", "The parent row''s key is automatically changed"]'::jsonb,1,'Other declared actions and timing modes have their own outcomes.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-3','pt-dbms-sql-11-delete','Why can whole-table TRUNCATE have different cost from DELETE?','["TRUNCATE and DELETE have identical performance in every engine", "The engine can use a different table-level path with different semantics", "DELETE always fails on large tables", "TRUNCATE only works on empty tables"]'::jsonb,1,'This does not mean zero logging or universal speed, and it cannot preserve a WHERE subset.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-4','pt-dbms-sql-11-delete','When is rollback of deleted rows a supported expectation?','["No, DELETE is always immediately permanent", "Within the actual transactional engine and uncommitted operation contract", "Only on NoSQL databases", "Only if no WHERE clause is used"]'::jsonb,1,'Do not generalize to nontransactional engines or every surrounding side effect.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-5','pt-dbms-sql-11-delete','What is the safety practice recommended before running a DELETE with an uncertain WHERE clause?','["Run it directly and check the result afterward", "Preview the affected rows first with an equivalent SELECT using the same WHERE clause", "Always delete without a WHERE clause to be thorough", "Rename the table before deleting"]'::jsonb,1,'Previewing with SELECT is the standard, reliable safety practice.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-6','pt-dbms-sql-11-delete','Does DELETE change a table''s column structure?','["Yes, it can drop columns", "No — DELETE only removes rows; columns, indexes, and constraints remain unchanged", "Only if CASCADE is specified", "DELETE always resets the table''s AUTO_INCREMENT counter"]'::jsonb,1,'DELETE is purely a row-removal operation with no effect on the table''s structure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-7','pt-dbms-sql-11-delete','Can DELETE be filtered to remove only specific rows?','["No, DELETE always removes every row", "Yes — a WHERE clause targets DELETE to only the matching rows", "Only TRUNCATE supports filtering", "DELETE can only remove exactly one row at a time"]'::jsonb,1,'WHERE is exactly what makes DELETE selective rather than total.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-delete-8','pt-dbms-sql-11-delete','What must a DELETE-versus-TRUNCATE choice compare?','["No trade-off — TRUNCATE is strictly better in every way", "Required population, structure, identity, triggers, dependencies and transaction rules before measured cost", "DELETE is always faster than TRUNCATE", "TRUNCATE always requires a WHERE clause, unlike DELETE"]'::jsonb,1,'A vague faster-or-safer slogan is not a complete semantic comparison.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-delete-new-9','pt-dbms-sql-11-delete','Does salary exactly 60000 match salary<60000?','["Yes", "No", "Only with an index", "Only when unnamed"]'::jsonb,1,'The cutoff is strict.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-delete-new-10','pt-dbms-sql-11-delete','Which cleanup row matches expired=1 AND state=staging?','["An expired published row", "A current staging row", "An expired staging row", "Every row with a state"]'::jsonb,2,'Both conditions are required.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-delete-application-new-1','pt-dbms-sql-11-delete-application','Does DELETE remove the table definition?','["Yes", "Only if no rows remain", "No", "Only with a primary key"]'::jsonb,2,'Row removal differs from DROP.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-delete-application-new-2','pt-dbms-sql-11-delete-application','Why read survivor identities rather than only a removed count?','["Counts always prove exact membership", "Names are globally unique", "Reading identities creates rows", "An equal count could hide removal of the wrong rows"]'::jsonb,3,'The postcondition includes which facts remain.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
