update public.learning_topics set short_description='Compute directional missing membership, compare complete tuple roles, and distinguish native distinct difference from NULL-sensitive exclusion predicates and duplicate-preserving anti-joins.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Compute directional missing membership, compare complete tuple roles, and distinguish native distinct difference from NULL-sensitive exclusion predicates and duplicate-preserving anti-joins.';
