insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-1','pt-dbms-sql-7-difference','What does the Difference operation (A − B) return?','["Rows in either A or B", "Rows in A that are NOT in B", "Rows in both A and B", "Rows in B that are not in A"]'::jsonb,1,'Difference specifically returns what''s in the first relation but absent from the second.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-2','pt-dbms-sql-7-difference','Which SQL keyword expresses distinct set difference in MySQL 8.4 as well as the cited PostgreSQL and SQL Server forms?','["INTERSECT", "EXCEPT", "MINUS", "SUBTRACT"]'::jsonb,1,'EXCEPT is supported in the stated MySQL 8.4 target. Actual provider execution remains separate from documentation and local MariaDB checks.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-3','pt-dbms-sql-7-difference','Which vendor historically uses MINUS for the same operation as EXCEPT?','["MySQL", "PostgreSQL", "Oracle", "SQLite"]'::jsonb,2,'Oracle''s MINUS is the same relational-algebra Difference operation, just a different keyword spelling.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-4','pt-dbms-sql-7-difference','Does operand order matter for the Difference operation?','["No, A - B always equals B - A", "Yes — A - B and B - A are generally different results, unlike Union and Intersection", "Order only matters if the relations are empty", "Order matters only for numeric columns"]'::jsonb,1,'Unlike Union/Intersection, Difference is order-sensitive: subtracting A from B is different from subtracting B from A.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-5','pt-dbms-sql-7-difference','What real-world question does `all_required_courses EXCEPT completed_courses` answer?','["Which courses were completed", "Which required courses are still missing/not yet completed", "The total number of courses offered", "Which courses have the highest enrollment"]'::jsonb,1,'This is the classic ''what''s missing'' pattern that Difference is well suited for.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-6','pt-dbms-sql-7-difference','What requirement do the two relations combined by EXCEPT/MINUS share with UNION and INTERSECT?','["They must be union-compatible: same column count, compatible types", "They must have identical primary keys", "They must both be non-empty", "There is no shared requirement"]'::jsonb,0,'Compatible positions and types are implementation requirements; corresponding tuple roles must also represent the same kind of fact.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-7','pt-dbms-sql-7-difference','If honors = {1,2,5} and deans = {2,3}, what is honors EXCEPT deans?','["{2}", "{1,5}", "{1,2,3,5}", "{3}"]'::jsonb,1,'Removing the overlapping value (2) from honors leaves {1,5}.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-difference-8','pt-dbms-sql-7-difference','Is Difference closely related to the Division operation (7.12)?','["No, they are completely unrelated", "Yes — both are commonly used for ''what satisfies/is missing relative to a full set'' style questions, though Division answers a more complex per-group version of that question", "Division is simply another name for Difference", "Difference can only be used with numeric relations, unlike Division"]'::jsonb,1,'Difference helps express missing memberships; division adds a per-candidate universal requirement and needs its own candidate universe and empty-set policy.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
