insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-division-1','pt-dbms-sql-7-division','What kind of question does the Division operation answer?','["Which rows satisfy a single condition", "Which X are related to EVERY Y in a given set (e.g. which students have taken ALL required courses)", "How many rows two relations have in common", "Which columns two relations share"]'::jsonb,1,'Division specifically answers ''relates to every member of a set'' questions.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-division-2','pt-dbms-sql-7-division','Does SQL have a single dedicated keyword for Division, like UNION for Union?','["Yes, the DIVIDE keyword", "No; use constructs such as nested NOT EXISTS or a carefully defined aggregate formulation", "Yes, the DIVISION keyword", "Yes, it''s implemented via the / operator"]'::jsonb,1,'Arithmetic DIV and slash do not implement universal relationship matching.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-division-3','pt-dbms-sql-7-division','In a distinct-course counting formulation, what must the compared counts represent?','["That the student has enrolled in at least one course", "Distinct required courses matched by the candidate and the distinct required course total", "That the student''s GPA exceeds a threshold", "That the student has no duplicate enrollments"]'::jsonb,1,'Both sides must count the same obligation domain; empty requirement handling also needs the candidate universe.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-division-4','pt-dbms-sql-7-division','Why is COUNT(DISTINCT course_id) used instead of plain COUNT(course_id) in the Division pattern?','["DISTINCT has no effect here", "Without DISTINCT, a student enrolled twice in the same required course would be miscounted as satisfying more requirements than they actually completed", "COUNT(course_id) is invalid syntax", "DISTINCT makes the query run faster with no correctness implication"]'::jsonb,1,'Duplicate enrollments in the same course must not inflate the count of distinct requirements satisfied.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-division-5','pt-dbms-sql-7-division','What is a common mistake when attempting to write a Division query?','["Forgetting to use SELECT", "Comparing against the student''s own total enrollment count instead of the required-courses total, which answers a different (wrong) question", "Using too many JOIN clauses", "Using WHERE instead of HAVING for every condition"]'::jsonb,1,'Comparing to the wrong total changes the question being answered — a classic, subtle bug in Division-style queries.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
