if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dml-3' and (question_text,options,correct_index,explanation) is distinct from ('Are DML changes (INSERT/UPDATE/DELETE) transactional — can they be rolled back before COMMIT — on mainstream engines?','["No, DML changes are permanent the instant they run, like DDL on most engines", "Yes \u2014 DML is transactional and can be undone with ROLLBACK before COMMIT", "Only INSERT is transactional; UPDATE and DELETE are not", "Only on weekends"]'::jsonb,1,'Unlike DDL on most engines, DML participates fully in transactions and can be rolled back before commit.') and (question_text,options,correct_index,explanation) is distinct from ('When can a MySQL row change be reversed with ROLLBACK?','["No, DML changes are permanent the instant they run, like DDL on most engines", "When it belongs to an uncommitted transaction on a transactional engine, subject to its actual statement rules", "Only INSERT is transactional; UPDATE and DELETE are not", "Only on weekends"]'::jsonb,1,'Autocommit and nontransactional engines prevent a universal rollback claim.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dml-3'; end if;
