insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dml-1','pt-dbms-sql-8-dml','Which three verbs form the core of DML?','["CREATE, ALTER, DROP", "INSERT, UPDATE, DELETE", "SELECT, JOIN, GROUP BY", "GRANT, REVOKE, COMMIT"]'::jsonb,1,'INSERT, UPDATE, and DELETE change the data stored in existing tables — the essence of DML.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dml-2','pt-dbms-sql-8-dml','What happens if you run `UPDATE employees SET salary = 0;` with no WHERE clause?','["Nothing happens without a WHERE clause — it is required and the statement fails", "Every single row in the table gets its salary set to 0", "Only the first row is updated by default", "Only rows with a NULL salary are updated"]'::jsonb,1,'Without a WHERE clause, UPDATE applies to every row in the table — a classic, dangerous mistake.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
