insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-1','pt-dbms-sql-3-document-model','What is the defining storage unit of the document model?','["A fixed-schema table row", "A self-contained, semi-structured document (e.g., JSON/BSON) that can nest objects and arrays", "An opaque binary blob addressable only by key", "A wide sparse column family"]'::jsonb,1,'Document databases store data as self-contained documents, typically JSON or BSON, which can include nested objects and arrays.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-2','pt-dbms-sql-3-document-model','What does flexible document structure imply about validation?','["The schema is enforced strictly at write time by the database", "Documents can vary, while configured write validation and reader contracts can still impose rules", "Every document must be validated against a fixed schema before insertion", "Reads are not permitted until a schema is defined"]'::jsonb,1,'Flexible does not mean unvalidated or without a shared schema.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-3','pt-dbms-sql-3-document-model','Which of these databases is a well-known document-model implementation?','["MongoDB", "Redis", "Cassandra", "Neo4j"]'::jsonb,0,'MongoDB is one of the most widely used document databases, storing data as BSON documents.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-4','pt-dbms-sql-3-document-model','Which capability distinguishes rich document access from the simplest opaque-value key-value abstraction?','["Whether the database uses a network connection", "Querying supported internal fields, while real product capabilities can overlap", "Whether the database supports replication", "Whether the database is open source"]'::jsonb,1,'This is not a universal classification test for every modern product.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-5','pt-dbms-sql-3-document-model','How should an embedded addresses array be evaluated against separate address facts?','["Because arrays are not allowed in relational databases", "Review aggregate ownership, shared identity, access patterns, and whether authoritative facts are duplicated", "Because the document has no _id field", "Because JSON cannot represent arrays"]'::jsonb,1,'Embedding is not automatically redundant duplication or a universal normalization violation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-6','pt-dbms-sql-3-document-model','What is a key trade-off of embedding denormalized data (like duplicated address info) across many documents?','["There are no trade-offs; it is strictly better", "Updating a piece of duplicated data requires updating every document copy, risking inconsistency", "It makes single-document reads slower", "It requires a JOIN operation for every query"]'::jsonb,1,'Because data is duplicated across documents rather than normalized once, updates must be propagated to every copy, which can introduce inconsistency if missed.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-document-model-7','pt-dbms-sql-3-document-model','How should document and wide-column models be compared?','["They are functionally identical", "Compare actual structure and access contracts rather than assuming a universal performance ranking", "Column-family databases cannot store more than one row", "Document databases cannot be distributed across servers"]'::jsonb,1,'Cassandra and other products have specific schema and consistency behavior.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
