if exists(select 1 from public.test_questions where id='pt-dbms-sql-4-domain-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('What risk arises when narrowing an existing domain?','["All values become sorted", "Every key disappears", "Previously accepted stored values or writes may violate the new rule", "The table degree always doubles"]'::jsonb,2,'A validity change affects data and caller compatibility.') and (question_text,options,correct_index,explanation) is distinct from ('What risk arises when narrowing an existing domain?','["All values become sorted", "Every key disappears", "Previously accepted stored values or writes may violate the new rule", "The table degree always doubles"]'::jsonb,2,'A validity change affects data and caller compatibility.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-4-domain-application-new-9'; end if;
