update public.learning_topics set short_description='Define legal attribute values, separate business domains from storage types, and validate ranges, absence and rejected SQL writes.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Define legal attribute values, separate business domains from storage types, and validate ranges, absence and rejected SQL writes.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Domain.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-4-domain' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-4-domain-application','MCQ Test 2',category,10,10,'Application and scenarios for Domain.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-4-domain' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-1','pt-dbms-sql-4-domain','What is a domain in the relational model?','["The set of all legal, atomic values an attribute may take", "A synonym for relation schema", "The number of tuples in a relation", "The physical storage location of a table"]'::jsonb,0,'A domain defines the pool of legal atomic values permitted for an attribute.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-2','pt-dbms-sql-4-domain','If the documented GPA scale runs from 0.0 to 10.0 and permits fractional grades, which domain fits?','["Any string of text", "Decimal values in the range [0.0, 10.0]", "Only the integers 0 through 10", "An enumerated set of department codes"]'::jsonb,1,'The stated contract permits decimal grades in the closed zero-to-ten range; grading scales are not universal.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-3','pt-dbms-sql-4-domain','Which of these values would violate the domain of the ''department'' attribute if its domain is {CS, ECE, ME, EEE, CE}?','["''CS''", "''ME''", "9.1", "''ECE''"]'::jsonb,2,'9.1 is a decimal number, not one of the valid enumerated department codes, so it violates the domain constraint.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-4','pt-dbms-sql-4-domain','How does a Domain differ from an Attribute?','["A domain is the pool of legal values; an attribute is the named role/column bound to that pool", "A domain is a row; an attribute is a table", "They are the same thing", "A domain always has fewer values than its attribute"]'::jsonb,0,'The attribute names the column; the domain defines what values that column may legally contain.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-5','pt-dbms-sql-4-domain','Can two different attributes in the same schema share the identical domain?','["No, each attribute must have a unique domain", "Yes — e.g., ''id'' and ''advisor_id'' can both be integer-domain attributes while remaining distinct attributes", "Yes, but only within the same relation schema they must merge into one attribute", "No, this would violate entity integrity"]'::jsonb,1,'Multiple attributes may share a domain (like integer IDs) yet remain separately named, distinct attributes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-6','pt-dbms-sql-4-domain','In an introductory first-normal-form design, why should a course-code attribute hold one code rather than an informal comma-separated list?','["To reduce storage space", "Each attribute should represent one value of its declared domain, with independent enrollments modeled separately", "To allow attributes to store lists of values", "Atomicity is not actually required in the relational model"]'::jsonb,1,'Atomicity concerns the chosen domain and modeled facts; dates and strings can still have internal structure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-7','pt-dbms-sql-4-domain','How should SQL NULL be understood relative to ordinary score-domain values?','["Yes, NULL is just another value drawn from the domain", "It marks absence rather than an ordinary numeric score; nullability is specified separately", "Only for numeric domains", "Only if the domain is explicitly defined to include it"]'::jsonb,1,'NULL is an absence marker, and NOT NULL controls whether the SQL column permits that absence.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-domain-8','pt-dbms-sql-4-domain','Comparing ''id'' (student-id domain) with ''course_credits'' (an integer domain) in a query is:','["Meaningless in practice, even though both are integer-typed, because they represent unrelated concepts", "Always meaningful since both are integers", "Impossible for the DBMS to execute", "Only valid if they share the exact same attribute name"]'::jsonb,0,'Sharing a domain (type-compatibility) does not imply the values are semantically comparable in a meaningful way.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-domain-new-9','pt-dbms-sql-4-domain','Only scores 60 and 80 are stored under a 0-to-100 integer domain. Is 70 legal?','["No; domains equal observed values", "Yes; legality does not require current occurrence", "Only after altering the column", "Only if every student receives 70"]'::jsonb,1,'A domain describes permitted rather than merely observed values.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
