insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-domain-application-new-3','pt-dbms-sql-4-domain-application','In MySQL 8.4, why can CHECK(score BETWEEN 0 AND 100) alone permit NULL?','["The CHECK expression is UNKNOWN, which is accepted", "NULL always equals zero", "BETWEEN ignores its bounds", "CHECK always disables validation"]'::jsonb,0,'Add NOT NULL when absence must be rejected.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
