insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-domain-application-new-5','pt-dbms-sql-4-domain-application','A course code changes catalogue membership over time. What can model the valid codes?','["A row display order", "A wider VARCHAR alone", "A reference relation with appropriate referential integrity", "A COUNT query alone"]'::jsonb,2,'The catalogue makes permitted codes explicit and maintainable.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
