insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-domain-application-new-7','pt-dbms-sql-4-domain-application','Both interval endpoints are in range, but start exceeds end. What is needed?','["A cross-attribute ordering constraint", "Only another type synonym", "A row counter", "A name alias"]'::jsonb,0,'Individual domain membership does not validate their relationship.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-domain-application-new-8','pt-dbms-sql-4-domain-application','Why can comparing student_id with course_credits be incorrect even if SQL executes it?','["SQL execution proves conceptual correctness", "Compatible storage types do not establish meaningful business comparison", "Both must be text", "The comparison always creates a foreign key"]'::jsonb,1,'Semantic roles matter beyond type compatibility.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
