if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-dql-4' and (question_text,options,correct_index,explanation) is distinct from ('Why can a JOIN cause an aggregate result (like a SUM) to be silently wrong?','["JOINs always produce exactly one row per input row with no exceptions", "An unintended many-to-many relationship in the JOIN can multiply rows (''fan-out''), causing values to be double- or over-counted", "Aggregates cannot be used together with JOIN under any circumstances", "JOIN always removes duplicate rows automatically"]'::jsonb,1,'Row-multiplying JOINs are a classic, easy-to-miss source of incorrect aggregate results — the query runs fine and looks plausible while being wrong.') and (question_text,options,correct_index,explanation) is distinct from ('Why can a JOIN cause an aggregate result (like a SUM) to be silently wrong?','["JOINs always produce exactly one row per input row with no exceptions", "An unintended many-to-many relationship in the JOIN can multiply rows (''fan-out''), causing values to be double- or over-counted", "Aggregates cannot be used together with JOIN under any circumstances", "JOIN always removes duplicate rows automatically"]'::jsonb,1,'Row-multiplying JOINs are a classic, easy-to-miss source of incorrect aggregate results — the query runs fine and looks plausible while being wrong.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-dql-4'; end if;
