insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-1','pt-dbms-sql-8-dql','Which single statement makes up essentially all of DQL?','["INSERT", "UPDATE", "SELECT", "CREATE"]'::jsonb,2,'DQL is essentially just SELECT — reading data without modifying it.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-2','pt-dbms-sql-8-dql','Does the ordinary employee listing directly change stored salaries or departments?','["Yes, every SELECT updates a ''last accessed'' timestamp on the data", "No; this ordinary retrieval example reads those business values without directly changing them", "Only SELECT statements with a JOIN modify data", "SELECT always modifies data unless LIMIT is used"]'::jsonb,1,'This is not a universal claim that every SELECT is effect-free: locking and invoked behavior require separate review.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-3','pt-dbms-sql-8-dql','Why is `SELECT *` generally discouraged in real application code?','["It is always slower than naming columns by a fixed, large amount", "It silently returns extra/changed columns if the table''s shape changes later, and breaks intention-revealing code", "SELECT * is not valid SQL syntax", "It can only be used with GROUP BY"]'::jsonb,1,'SELECT * is convenient for exploration but fragile in application code, since it implicitly depends on the table''s current column set.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-4','pt-dbms-sql-8-dql','Why can a JOIN cause an aggregate result (like a SUM) to be silently wrong?','["JOINs always produce exactly one row per input row with no exceptions", "An unintended many-to-many relationship in the JOIN can multiply rows (''fan-out''), causing values to be double- or over-counted", "Aggregates cannot be used together with JOIN under any circumstances", "JOIN always removes duplicate rows automatically"]'::jsonb,1,'Row-multiplying JOINs are a classic, easy-to-miss source of incorrect aggregate results — the query runs fine and looks plausible while being wrong.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-5','pt-dbms-sql-8-dql','Why does `LIMIT 5` without an ORDER BY not reliably give you a meaningful ''top 5''?','["LIMIT is illegal without ORDER BY in every dialect", "Without ORDER BY, which rows come back is not guaranteed to be stable or meaningful — LIMIT just caps a count, it doesn''t rank anything", "LIMIT always returns the 5 most recently inserted rows regardless of ORDER BY", "LIMIT and ORDER BY cannot be used in the same statement"]'::jsonb,1,'LIMIT only caps the row count; it needs ORDER BY to determine WHICH rows those are in a reproducible, meaningful way.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-6','pt-dbms-sql-8-dql','Why do SQL classifications differ about whether SELECT belongs in DQL or a broader DML family?','["Because SELECT actually deletes rows after reading them", "The categories group language responsibilities differently; the distinction does not change the actual query semantics", "Because DML and DQL use completely unrelated keywords", "Because DQL was invented before DML existed"]'::jsonb,1,'DQL emphasizes retrieval, while broader DML classifications can include querying as well as row manipulation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-dql-7','pt-dbms-sql-8-dql','In `SELECT department, SUM(salary) DIV COUNT(*) AS avg_salary FROM employees GROUP BY department HAVING COUNT(*) >= 2`, what does the HAVING clause do?','["Filters individual employee rows before grouping", "Filters entire department groups, keeping only those with 2 or more employees", "Sorts the departments alphabetically", "Limits the result to 2 rows"]'::jsonb,1,'HAVING filters the grouped results (departments), keeping only groups satisfying the aggregate condition — here, at least 2 employees.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
