update public.learning_topics set short_description='Read an enhanced ER model as an explicit contract for identities, roles and constraints, then compare its membership and reference rules with a concrete relational mapping.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Read an enhanced ER model as an explicit contract for identities, roles and constraints, then compare its membership and reference rules with a concrete relational mapping.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for EER Diagram.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-eer-diagram' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-eer-diagram-application','MCQ Test 2',category,10,10,'Application and scenarios for EER Diagram.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-eer-diagram' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-1','pt-dbms-sql-6-eer-diagram','What is an EER (Enhanced Entity-Relationship) diagram?','["A diagram using only entities and attributes, with no relationships", "The extended ER notation that adds generalization, specialization, and aggregation on top of the basic ER constructs", "A purely physical database schema diagram", "A diagram that can only represent weak entities"]'::jsonb,1,'Enhanced ER modeling includes additional semantic abstractions; exact supported constructs and symbols vary by modeling convention.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-2','pt-dbms-sql-6-eer-diagram','Which conceptual construct is explicitly represented by enhanced subtype notation in the convention used here?','["A simple 1:N relationship between Department and Course", "An ISA hierarchy specializing Person into Student and Employee", "An attribute like Date_of_Birth on Student", "A binary relationship Enrolls_In between Student and Course"]'::jsonb,1,'Generalization/specialization (ISA hierarchies) are EER-specific extensions not present in plain ER notation.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-3','pt-dbms-sql-6-eer-diagram','Can an enhanced modeling framework represent a basic ER design that uses none of its optional advanced constructs?','["No, they are entirely incompatible notations", "Yes — a plain ER diagram simply doesn''t use the extended constructs (ISA hierarchies, aggregation), but is still a valid (simple) EER diagram", "Only if it contains at least one weak entity", "Only if it uses ternary relationships"]'::jsonb,1,'A basic design can remain a valid simpler model; the concrete syntax and legend still need to be consistent.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-4','pt-dbms-sql-6-eer-diagram','Which set of advanced modeling constructs is emphasized in this tutorial’s enhanced diagram convention?','["Entities, attributes, and relationships", "Cardinality, participation, and degree", "Generalization, specialization, and aggregation", "Primary key, foreign key, and candidate key"]'::jsonb,2,'These three EER-specific constructs, plus their disjoint/overlapping and total/partial constraints, are what EER adds beyond basic ER.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-5','pt-dbms-sql-6-eer-diagram','Is an EER diagram itself a physical database schema?','["Yes, it can be executed directly as SQL", "No — it is a conceptual/logical design artifact that must still be converted into a relational schema via ER-to-relational mapping", "Yes, but only for weak entities", "No, EER diagrams cannot represent database design at all"]'::jsonb,1,'EER diagrams remain a conceptual design tool, one step before the physical schema is derived through mapping rules.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-6','pt-dbms-sql-6-eer-diagram','In a full college-database EER diagram, which element would represent the aggregation of Student-Enrolls_In-Course being monitored by Faculty?','["An ISA triangle connecting Student and Employee", "A labeled aggregation boundary grouping the enrollment association, connected through Monitoring to Faculty; exact boundary style follows the notation", "A double-line rectangle around Student", "A dashed oval attached to Course"]'::jsonb,1,'The boundary communicates the association occurrence as the monitoring subject rather than enforcing SQL or selecting one universal line style.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-7','pt-dbms-sql-6-eer-diagram','Does replacing an essential ISA structure with unlabeled ordinary relationships automatically preserve all its subtype semantics?','["Yes, always, with no loss of meaning", "No; shared identity, membership, overlap and coverage rules must still be represented explicitly", "Yes, but only if all subclasses are disjoint", "No EER diagram can ever be simplified"]'::jsonb,1,'Alternative encodings can carry extra constraints; a plain redraw without them is not automatically equivalent.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-eer-diagram-8','pt-dbms-sql-6-eer-diagram','What typically comes right after an EER diagram is finalized in the database design lifecycle?','["Query optimization", "Physical indexing strategy only", "ER-to-relational mapping, converting the diagram into tables, keys, and constraints", "User interface design"]'::jsonb,2,'The next logical design step is translating the EER diagram into a relational schema.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-eer-diagram-new-9','pt-dbms-sql-6-eer-diagram','Does an EER diagram determine a complete physical storage layout?','["Yes; every oval names a disk page", "No; a mapping and implementation decisions are still needed", "Only for empty diagrams", "Only if it has a subtype"]'::jsonb,1,'The diagram primarily communicates conceptual facts and rules.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
