insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-1','pt-dbms-sql-5-entity-integrity','What does entity integrity guarantee?','["That every column value is unique", "That the primary key is always unique and never NULL", "That every table has at least 10 rows", "That foreign keys always match a parent row"]'::jsonb,1,'Entity integrity is specifically about the primary key''s uniqueness and non-nullability.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-2','pt-dbms-sql-5-entity-integrity','How is entity integrity enforced in SQL?','["By writing a custom trigger for every table", "Through a supported PRIMARY KEY declaration over the chosen identifying attributes", "By adding a CHECK constraint manually", "Entity integrity cannot be enforced by SQL"]'::jsonb,1,'PRIMARY KEY bundles both the uniqueness and NOT NULL requirements automatically.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-3','pt-dbms-sql-5-entity-integrity','Why is a NULL primary key value considered a serious problem?','["It merely wastes a small amount of storage", "It violates the requirement that the designated primary identity be complete and definite", "NULL values take longer to compare than other values", "It is not actually a problem in modern databases"]'::jsonb,1,'The primary identity must be nonmissing. Another identifier may exist, but that does not satisfy the declared primary-key contract.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-4','pt-dbms-sql-5-entity-integrity','Does entity integrity apply to alternate keys enforced via UNIQUE?','["Yes, identically to primary keys", "The primary-key rule is distinct; a required alternate identity needs its own appropriate uniqueness and nonmissing policy", "Only if the alternate key is also composite", "Entity integrity applies to every column in the table"]'::jsonb,1,'Do not conflate nullable UNIQUE behaviour with a required alternate candidate identity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-5','pt-dbms-sql-5-entity-integrity','For a composite primary key, what does entity integrity require about its individual component columns?','["Only the first column needs to be NOT NULL", "None of the component columns may be NULL — a NULL in any part breaks the row''s overall identity guarantee", "At least one component column must be NULL", "Composite keys are exempt from entity integrity"]'::jsonb,1,'Since the full combination defines the row''s identity, every component column must be non-null for that identity to be complete and known.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-6','pt-dbms-sql-5-entity-integrity','Does satisfying entity integrity guarantee that a row''s data is otherwise correct?','["Yes, entity integrity guarantees full data correctness", "No — entity integrity only guarantees the row has a valid, unique, non-null identity; other columns could still contain wrong or nonsensical values", "Entity integrity guarantees correctness only for numeric columns", "This question doesn''t apply to entity integrity"]'::jsonb,1,'Entity integrity is necessary but not sufficient — it says nothing about whether the rest of the row''s data is accurate.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-7','pt-dbms-sql-5-entity-integrity','What real ambiguity would arise from two rows both having primary key value 7?','["No ambiguity — the database would simply pick one at random consistently", "Any query or foreign key referencing ''the row with id 7'' would have no way to know which of the two rows was meant", "SQL would automatically rename one of the rows", "This scenario is impossible to describe in relational terms, but has no practical consequence"]'::jsonb,1,'Duplicate primary key values destroy the ability to unambiguously reference a specific row, which is exactly what entity integrity prevents.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-entity-integrity-8','pt-dbms-sql-5-entity-integrity','Is entity integrity a relational-model concept, a SQL-specific feature, or both?','["A relational-model concept, which SQL happens to implement via the PRIMARY KEY constraint", "A SQL-only feature with no theoretical basis", "A NoSQL-only concept", "A concept that applies only to foreign keys"]'::jsonb,0,'Entity integrity is one of the relational model''s foundational integrity rules; PRIMARY KEY is simply how SQL implements it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-entity-integrity-new-9','pt-dbms-sql-5-entity-integrity','Can different students with valid distinct primary identifiers share a name?','["No; every column becomes unique", "Yes, if no separate rule forbids it", "Only if score is zero", "Only if names are missing"]'::jsonb,1,'Entity integrity constrains the chosen primary identity.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-entity-integrity-new-10','pt-dbms-sql-5-entity-integrity','Does a valid primary key prove every score is factually correct?','["Yes; the key verifies all facts", "Only for numeric keys", "No; identification and factual accuracy differ", "Only for one-row tables"]'::jsonb,2,'Other validity and external truth concerns need separate checks.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
