insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-entity-integrity-application-new-2','pt-dbms-sql-5-entity-integrity-application','Two rows share id 7 but differ in name. Does DISTINCT over all columns fix primary identity?','["Yes; DISTINCT enforces the primary key", "Only if sorted", "Only if names are long", "No; both different rows can remain while claiming the same id"]'::jsonb,3,'Complete-row equality differs from the identifying subset.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-entity-integrity-application-new-3','pt-dbms-sql-5-entity-integrity-application','What is a staging proposal_id’s role?','["It identifies the submission separately from the proposed business identity", "It makes every proposed student id valid", "It replaces the entire schema", "It grants correction authority"]'::jsonb,0,'Submission identity and proposed accepted identity are different roles.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
