if exists(select 1 from public.test_questions where id='pt-dbms-sql-6-entity-set-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('Does excluding a row through WHERE delete the source entity?','["Yes; WHERE always writes", "Only if sorted", "No; it changes the returned population", "Only if no rows remain"]'::jsonb,2,'Retrieval filtering differs from data modification.') and (question_text,options,correct_index,explanation) is distinct from ('Does excluding a row through WHERE delete the source entity?','["Yes; WHERE always writes", "Only if sorted", "No; it changes the returned population", "Only if no rows remain"]'::jsonb,2,'Retrieval filtering differs from data modification.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-6-entity-set-application-new-9'; end if;
