update public.learning_topics set short_description='Distinguish an entity type from its current population, define membership clearly, and report sets without confusing shared attributes or changing relationships with identity.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish an entity type from its current population, define membership clearly, and report sets without confusing shared attributes or changing relationships with identity.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Entity Set.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-entity-set' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-entity-set-application','MCQ Test 2',category,10,10,'Application and scenarios for Entity Set.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-entity-set' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-1','pt-dbms-sql-6-entity-set','What is an entity set?','["A single, uniquely identified real-world object", "The modeled collection of current occurrences sharing an entity type and its attribute roles", "A rule limiting the values of an attribute", "A diagram showing cardinalities between entities"]'::jsonb,1,'Common attribute roles do not imply equal values across members.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-2','pt-dbms-sql-6-entity-set','In an ER diagram, how is an entity set typically drawn?','["As a diamond", "As an oval", "As a rectangle", "As a double rectangle"]'::jsonb,2,'A rectangle represents an entity set (a double rectangle is reserved for weak entity sets).',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-3','pt-dbms-sql-6-entity-set','For a simple strong-entity relational mapping, which correspondence is a useful introductory analogy?','["Entity = table, Entity set = row", "Entity = row (tuple), Entity set = table (relation)", "Entity = column, Entity set = table", "Entity = database, Entity set = schema"]'::jsonb,1,'A simple mapping often uses one tuple per occurrence and a relation for the set; more elaborate mappings need not be one physical table per conceptual entity.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-4','pt-dbms-sql-6-entity-set','Can an entity set validly exist with zero current entities in it?','["No, an entity set must always contain at least one entity", "Yes; the type definition remains meaningful while its current member population is empty", "Only weak entity sets can be empty", "Only if it has no attributes"]'::jsonb,1,'The definition and its current population must be distinguished.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-5','pt-dbms-sql-6-entity-set','Both ''Student'' and ''Faculty'' entity sets have an attribute called ''Email''. What does this imply?','["They are actually the same entity set", "Attribute names can be reused across different entity sets; they remain distinct sets", "This is not allowed in the ER model", "One of them must be a weak entity set"]'::jsonb,1,'Different entity sets can share attribute names; what makes them distinct is their overall structure and identity, not unique attribute names.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-6','pt-dbms-sql-6-entity-set','Which of these statements distinguishes an entity from an entity set most precisely?','["An entity has attributes; an entity set does not", "An entity is one occurrence; an entity set is the named collection/category of all such occurrences", "An entity set can only contain one entity", "There is no meaningful distinction in practice"]'::jsonb,1,'This instance-vs-category distinction is the essence of entity vs. entity set.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-7','pt-dbms-sql-6-entity-set','A weak entity set differs from a (strong) entity set primarily because:','["It has more attributes", "Its conceptual identification depends on an owner and local discriminator rather than an independent complete identifier", "It cannot be drawn in an ER diagram", "It never has any attributes"]'::jsonb,1,'A conventional relational weak-entity mapping can still have a complete composite primary key including the owner key.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-set-8','pt-dbms-sql-6-entity-set','When converting ER to a relational schema, what typically happens to a strong entity set?','["It is discarded and merged into its relationships", "It becomes a table whose columns are its attributes and whose rows are its entities", "It becomes a foreign key in another table", "It becomes an index"]'::jsonb,1,'A strong entity set maps directly to a table: attributes become columns, and each entity instance becomes a row.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-entity-set-new-9','pt-dbms-sql-6-entity-set','Do common student attribute roles require every student to share the same programme value?','["Yes; otherwise they are different types automatically", "No; values can differ across members", "Only for empty sets", "Only if names repeat"]'::jsonb,1,'Type structure and current property values differ.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-entity-set-new-10','pt-dbms-sql-6-entity-set','Can Student and Faculty both use an email attribute without being the same set?','["No; shared names merge sets", "Only if email is numeric", "Yes; names are interpreted within their modeled roles", "Only if neither has keys"]'::jsonb,2,'Attribute spelling does not establish identity or membership equivalence.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-entity-set-application-new-1','pt-dbms-sql-6-entity-set-application','Must all named entity sets be disjoint?','["Yes; separate rectangles prove disjointness", "Only empty sets overlap", "No; the model can permit overlapping roles", "Only tables without keys overlap"]'::jsonb,2,'Role overlap is an explicit modeling decision.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-entity-set-application-new-2','pt-dbms-sql-6-entity-set-application','What establishes that one person belongs to both Student and Faculty?','["The same displayed name alone", "The same row position", "A similar email label alone", "The model’s shared identity or explicit relationship evidence"]'::jsonb,3,'Descriptive coincidence is not enough.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
