insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-1','pt-dbms-sql-6-entity','Which of the following best defines an entity in the ER model?','["A table stored in a relational database", "A distinctly identifiable real-world object or concept about which data is captured", "A named collection of similar objects", "A rule that restricts the values an attribute may take"]'::jsonb,1,'An entity is a single, distinguishable real-world object or concept — the basic unit the ER model captures data about.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-2','pt-dbms-sql-6-entity','In the college database, which of these is an entity (a single occurrence), not a category?','["Student", "Course", "Aditi Sharma, Roll No. 21CS045", "Department"]'::jsonb,2,'A named, specific individual is one occurrence — an entity — while ''Student'' or ''Department'' names the whole category (entity set).',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
