insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-entity-5','pt-dbms-sql-6-entity','What minimally must be true for something to qualify as an entity?','["It must be stored in more than one table", "The model treats it as a distinguishable occurrence about which relevant properties or relationships are recorded", "It must participate in a relationship", "It must have a multi-valued attribute"]'::jsonb,1,'Entity modeling follows identifiable occurrences and required facts; a fixed minimum count of descriptive attributes is not a universal definition.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
