update public.learning_topics set short_description='Match explicit equality roles across relations, preserve complete composite identities, and distinguish predicate form from output projection, duplicate elimination and outer preservation.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Match explicit equality roles across relations, preserve complete composite identities, and distinguish predicate form from output projection, duplicate elimination and outer preservation.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Equi Join.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-7-equi-join' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-7-equi-join-application','MCQ Test 2',category,10,10,'Application and scenarios for Equi Join.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-7-equi-join' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-1','pt-dbms-sql-7-equi-join','What makes a join specifically an Equi Join?','["It always involves exactly two tables", "Its join condition uses ONLY equality (=) comparisons", "It never returns duplicate column names", "It requires the ON clause to be omitted"]'::jsonb,1,'Equi Join is precisely the equality-restricted special case of Theta Join.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-2','pt-dbms-sql-7-equi-join','In the illustrated explicit ON inner equi join with SELECT *, are both compared source columns available in the output?','["No, duplicate-valued columns are automatically merged", "Yes — an Equi Join''s result keeps both matched columns from each side, even though their values are identical for matched rows", "Only department_id appears in the result", "This causes an error"]'::jsonb,1,'The explicit ON equality does not merge columns. Projection and supported USING/NATURAL output conventions can produce other shapes.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-3','pt-dbms-sql-7-equi-join','Is `ON a.x = b.x AND a.y > b.y` a pure Equi Join?','["Yes, since it contains an equality comparison", "No — since it mixes an equality with a non-equality comparison, the overall condition makes this a (non-equi) Theta Join", "This is a Natural Join", "This is an invalid join condition"]'::jsonb,1,'''Equi Join'' specifically requires EVERY comparison in the condition to be equality; mixing in a non-equality comparison makes it a general Theta Join.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-4','pt-dbms-sql-7-equi-join','Can an Equi Join match on multiple column pairs at once?','["No, only a single equality comparison is ever allowed", "Yes — multiple equality comparisons can be combined with AND, and it remains an Equi Join as long as all comparisons are equality", "Multiple column pairs would make it a Cartesian Product instead", "This would require a Theta Join instead"]'::jsonb,1,'A composite-key style match using several equality comparisons combined with AND is still a valid Equi Join.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-5','pt-dbms-sql-7-equi-join','Why might Equi Join be preferred over Natural Join when the matching columns have different names?','["Equi Join cannot handle differently-named columns either", "Equi Join lets you explicitly specify which columns to equate regardless of their names, while Natural Join specifically requires matching column NAMES", "Natural Join is always faster regardless of column names", "There is no meaningful difference between them"]'::jsonb,1,'Equi Join''s explicit ON condition works regardless of column naming; Natural Join''s automatic matching depends on identical names.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-6','pt-dbms-sql-7-equi-join','Is Equi Join a special case of Theta Join, or a completely separate concept?','["A completely separate, unrelated concept", "A special case — Equi Join is exactly a Theta Join whose condition is restricted to equality only", "Theta Join is a special case of Equi Join instead", "They are exact synonyms with no distinction at all"]'::jsonb,1,'Equi Join narrows Theta Join''s general ''any comparison'' condition down to equality specifically.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-7','pt-dbms-sql-7-equi-join','Which is a common appropriate equi-join task when the modeled reference is valid?','["Comparing date ranges between two tables", "Matching a foreign key in one table to the primary key it references in another table", "Finding rows with the maximum value in a column", "Sorting a table''s rows"]'::jsonb,1,'An explicit foreign-key-to-parent-key comparison is common, but an arbitrary equality query does not itself prove native reference enforcement.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-equi-join-8','pt-dbms-sql-7-equi-join','How can an explicit ON equi join omit one redundant displayed comparison column without changing its matching predicate?','["Theta Join", "Use an explicit SELECT list; supported NATURAL or USING forms also have their own merged-column conventions", "Cartesian Product", "Outer Join"]'::jsonb,1,'Natural join is not the only way to avoid displaying both compared columns. Matching and selected output roles are different concerns.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
