update public.learning_topics set short_description='Translate conceptual identities, attribute collections and relationships into explicit relational contracts, distinguishing conventional mapping patterns from complete constraint enforcement.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Translate conceptual identities, attribute collections and relationships into explicit relational contracts, distinguishing conventional mapping patterns from complete constraint enforcement.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for ER to Relational Mapping.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-er-to-relational-mapping' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-er-to-relational-mapping-application','MCQ Test 2',category,10,10,'Application and scenarios for ER to Relational Mapping.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-er-to-relational-mapping' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-1','pt-dbms-sql-6-er-to-relational-mapping','What is ER-to-Relational Mapping?','["The process of drawing an ER diagram from an existing database", "The systematic process of converting a completed ER/EER diagram into relational tables following defined rules", "A way to normalize an already-existing relational schema", "A technique for writing SQL queries"]'::jsonb,1,'This mapping bridges conceptual ER/EER design and the physical relational schema.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-2','pt-dbms-sql-6-er-to-relational-mapping','How does a strong entity set typically map to a relational table?','["Its attributes become columns and its key becomes the table''s primary key", "It is discarded and merged into relationships", "It always requires a junction table", "It becomes a foreign key in another table"]'::jsonb,0,'A strong entity set maps directly and simply to a table using its own attributes and key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-3','pt-dbms-sql-6-er-to-relational-mapping','In the conventional owner-plus-partial-key weak-entity mapping taught here, how is its complete identity represented?','["They are mapped identically", "The weak entity''s table must include the owner''s primary key as a foreign key, and its own primary key is a composite of the owner''s key plus its partial key", "Weak entity tables never have any foreign keys", "Weak entity tables cannot have a primary key at all"]'::jsonb,1,'The mapped pair includes the owner key and discriminator with supported owner reference enforcement; alternative physical surrogates must preserve the business identity explicitly.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-4','pt-dbms-sql-6-er-to-relational-mapping','How is a 1:N relationship (e.g., Department Offers Course) typically mapped, without needing a separate table?','["By adding a foreign key column (e.g., Dept_Code) into the table on the ''many'' side (Course)", "By creating a junction table regardless", "By merging Department and Course into one table always", "By making Course a multi-valued attribute of Department"]'::jsonb,0,'For 1:N, a single foreign key on the many side is sufficient and standard.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-5','pt-dbms-sql-6-er-to-relational-mapping','Why does the conventional normalized mapping use a separate association relation for an M:N enrollment?','["Because M:N relationships never have attributes", "It represents each independently manageable participation with complete participant references, identity and relationship properties", "Because M:N relationships are always weak entities", "Because SQL forbids M:N relationships entirely"]'::jsonb,1,'Structured SQL types exist, but an informal list is not equivalent to the explicit conventional relationship mapping and constraints.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-6','pt-dbms-sql-6-er-to-relational-mapping','What generally happens to a derived attribute (like Age) during ER-to-relational mapping?','["It always gets its own dedicated column", "It is typically NOT given a stored column; it is recomputed via queries or views from its source attributes", "It becomes a foreign key", "It becomes the primary key of a new table"]'::jsonb,1,'Computing on demand can avoid independent drift. Deliberate caches or snapshots are also possible when authority and refresh or reference-state policies are defined.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-7','pt-dbms-sql-6-er-to-relational-mapping','Which of these is NOT one of the standard strategies for mapping a generalization/specialization hierarchy to tables?','["Superclass table plus one table per subclass, linked by a shared key", "One single combined table with nullable subclass-specific columns", "One table per subclass only, duplicating superclass attributes into each", "Always deleting the superclass and keeping only a multi-valued attribute"]'::jsonb,3,'This is not a real mapping strategy; the three legitimate strategies are the other three options listed.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-er-to-relational-mapping-8','pt-dbms-sql-6-er-to-relational-mapping','When an enrollment can have several faculty monitors, which mapping preserves monitoring of its specific association occurrence?','["A separate Monitoring relation referencing the complete existing enrollment identity and the faculty identity", "By creating an entirely new unrelated table with no foreign keys", "Aggregation cannot be mapped to relational tables at all", "By duplicating the Faculty table''s data into Student and Course"]'::jsonb,0,'A scalar Faculty_ID on Enrollment only fits an at-most-one-monitor policy; aggregation itself does not determine that multiplicity.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
