update public.learning_topics set short_description='Design task-specific database views with explicit columns, row filters, aliases, and joins while preserving result meaning, access boundaries, and compatible application contracts.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Design task-specific database views with explicit columns, row filters, aliases, and joins while preserving result meaning, access boundaries, and compatible application contracts.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for External Schema.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-external-schema' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-external-schema-application','MCQ Test 2',category,10,10,'Application and scenarios for External Schema.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-external-schema' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-1','pt-dbms-sql-2-external-schema','What does the External Schema represent in the three-schema architecture?','["The physical storage layout of the database", "A user- or application-specific subset or reshaping of the conceptual schema", "The complete organization-wide logical design", "The network protocol used between client and server"]'::jsonb,1,'The external schema is the view-level abstraction tailored to what a specific user or application needs to see.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-2','pt-dbms-sql-2-external-schema','In the Student example, what does the Result Portal''s external schema expose?','["(StudentID, Name, FeeBalance)", "(StudentID, Name, Marks)", "(StudentID, DOB, FeeBalance)", "All columns of the Student table"]'::jsonb,1,'The Result Portal is described as seeing only StudentID, Name, and Marks — never fee data.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-3','pt-dbms-sql-2-external-schema','What database mechanism is typically used to implement an external schema?','["Indexes", "Views", "Connection pools", "Disk partitions"]'::jsonb,1,'Views are the concrete SQL construct commonly used to realize the abstract external-schema concept.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-4','pt-dbms-sql-2-external-schema','The Class Teacher Portal''s external schema exposes `(StudentID, Name, CourseName, Marks)` by combining Student and Enrollment data. What does this demonstrate?','["An external schema can only ever expose one table at a time", "An external schema can be built by joining multiple conceptual entities into one simplified view", "This is actually an internal schema, not an external one", "Joining tables is only possible at the conceptual level"]'::jsonb,1,'External schemas are not limited to a single table; they can join and reshape multiple conceptual entities.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-5','pt-dbms-sql-2-external-schema','Result Portal and Accounts Portal both have external schemas over the same Student conceptual schema. What does this show?','["Only one external schema can exist per conceptual schema at a time", "Multiple external schemas can coexist over the same conceptual schema, each restricted differently", "The conceptual schema must be duplicated for each external schema", "External schemas must always include every conceptual column"]'::jsonb,1,'Many external schemas can be defined simultaneously over one shared conceptual schema, each tailored to a different audience.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-6','pt-dbms-sql-2-external-schema','Restricting which columns an external schema shows versus restricting which rows it shows (e.g., only a teacher''s own department) are examples of what two different techniques?','["Column-level restriction and row-level restriction, which solve different access needs", "Both are the same technique applied twice", "Internal schema tuning and external schema tuning", "Middleware routing and connection pooling"]'::jsonb,0,'Column restriction limits which fields are visible, while row restriction limits which records are visible — both are used in external schemas but address different concerns.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-7','pt-dbms-sql-2-external-schema','A MySQL view still selects Marks after the base column has been renamed Score. No replacement mapping is installed. What is the dependency problem?','["Nothing, external schemas are automatically immune to conceptual renames", "The view still refers to the missing base column and needs a compatible definition", "The conceptual schema automatically reverts the rename", "The internal schema silently fixes the mismatch"]'::jsonb,1,'The dependent definition must be updated, for example by projecting Score AS Marks when the measurement is unchanged.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-external-schema-8','pt-dbms-sql-2-external-schema','A new external schema is created that shows the same columns as the Result Portal''s view but only for students with `Marks >= 90`. Why is this a meaningfully different external schema even though the columns are identical?','["It isn''t different — external schemas are defined by columns only", "Because it applies a row-level restriction, so a different subset of records is visible even though the column set matches", "Because it requires a separate conceptual schema", "Because it must be implemented at the internal schema level instead"]'::jsonb,1,'External schemas can differ by row restrictions as well as column restrictions; identical columns with different row filters are still distinct external schemas.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-new-9','pt-dbms-sql-2-external-schema','What does the grain of an external result describe?','["The physical page size", "What one output row represents", "The number of disk files", "The network packet format"]'::jsonb,1,'A student-course perspective may have one row per enrollment rather than one per student.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-new-10','pt-dbms-sql-2-external-schema','Which mapping explains the source of a portal field?','["Disk-sector mapping", "Connection-pool routing", "External-to-conceptual mapping", "Buffer replacement mapping"]'::jsonb,2,'It links the task-facing attribute to conceptual facts and calculations.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-1','pt-dbms-sql-2-external-schema-application','Mira has 92 marks and Kabir has 76. A perspective keeps Marks >= 90. Who appears?','["Both students", "Kabir only", "Mira only", "Neither student"]'::jsonb,2,'Ninety-two meets the inclusive threshold; seventy-six does not.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-2','pt-dbms-sql-2-external-schema-application','A score is NULL. Does Marks >= 90 retain that row?','["Yes; NULL means a perfect score", "Yes; NULL equals ninety", "Only if the name is unique", "No; the comparison is unknown"]'::jsonb,3,'WHERE retains true conditions; unknown does not pass the filter.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-3','pt-dbms-sql-2-external-schema-application','A teacher perspective returns two courses for the same student. What should be checked before removing a row?','["Whether the intended grain is one enrollment per row", "Whether the student name is short", "Whether the database uses an SSD", "Whether the view name contains Portal"]'::jsonb,0,'Multiple courses can correctly produce multiple rows for one student.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-4','pt-dbms-sql-2-external-schema-application','Two students have the same name but different identifiers. Which join is safer for matching enrollments?','["Join on the name alone", "Join on the declared student identifier", "Join on the name length", "Use an unconstrained cross join"]'::jsonb,1,'Identifiers express the intended relationship without confusing people who share a name.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-5','pt-dbms-sql-2-external-schema-application','An old interface promises Marks; the equivalent base attribute is now Score. Which projection preserves the promised label?','["Marks AS Score when Marks no longer exists", "SELECT * with no dependency review", "Score AS Marks", "Remove the score from the output"]'::jsonb,2,'An alias can retain the external label when the underlying meaning remains equivalent.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-6','pt-dbms-sql-2-external-schema-application','A portal hides FeeBalance on screen but its response includes it. What conclusion follows?','["The fee information is certainly inaccessible", "The database must contain no fee column", "An index automatically encrypts the field", "Visual hiding has not removed the field from the response"]'::jsonb,3,'Access and data minimization must be assessed at the trusted query and response boundaries.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-7','pt-dbms-sql-2-external-schema-application','A ResultPortal view excludes DOB, but a user can directly SELECT the base Student table. Is the view alone a sufficient access boundary?','["No; the direct base-table permission permits bypass", "Yes; view names override all permissions", "Yes; omitting DOB deletes it", "Only the browser theme determines access"]'::jsonb,0,'The actual privileges and available access paths must enforce the intended restriction.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-8','pt-dbms-sql-2-external-schema-application','A report requires StudentID order. Where should that requirement be explicit?','["In the insertion sequence alone", "In the consuming query ORDER BY StudentID", "In an assumption about disk placement", "In the view title"]'::jsonb,1,'A consumer requiring order should request it explicitly.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-9','pt-dbms-sql-2-external-schema-application','An inner-join teacher perspective omits an unenrolled student. What explains that result?','["The student must have been deleted", "The view has copied the wrong physical page", "There is no matching enrollment for the inner join", "Every view must exclude the youngest student"]'::jsonb,2,'Inner joins keep matching combinations; preserving unmatched students requires a suitable alternative.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-external-schema-application-new-10','pt-dbms-sql-2-external-schema-application','A new formula converts raw marks into percentages but keeps the old field name. What must compatibility review examine?','["Only the spelling of the column", "Only the total number of views", "Only whether the SQL ends in a semicolon", "Measurement meaning and scale as well as the name"]'::jsonb,3,'Matching labels do not establish that old consumers receive the same kind of value.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
