if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-external-schema-result-projection' and description is distinct from 'Write a SELECT producing student_id, name, marks for every student. Omit fee_balance and order by student_id. This query models an external perspective; do not create users or alter privileges.

**MySQL dialect.**

```sql
CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));
INSERT INTO students VALUES (32,''Kabir'',76,0.00),(31,''Mira'',92,500.00),(33,''Mira'',NULL,0.00);
```

**Required ordering:** student_id ascending

**Edge cases:**
- Repeated names must remain separate students
- Preserve NULL scores
- An empty input returns no result rows') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-external-schema-result-projection'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-external-schema-result-projection',null::text,'Expose a result portal projection','Easy','external-schema-result-projection','Write a SELECT producing student_id, name, marks for every student. Omit fee_balance and order by student_id. This query models an external perspective; do not create users or alter privileges.

**MySQL dialect.**

```sql
CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));
INSERT INTO students VALUES (32,''Kabir'',76,0.00),(31,''Mira'',92,500.00),(33,''Mira'',NULL,0.00);
```

**Required ordering:** student_id ascending

**Edge cases:**
- Repeated names must remain separate students
- Preserve NULL scores
- An empty input returns no result rows','[{"input": "INSERT INTO students VALUES (32,''Kabir'',76,0.00),(31,''Mira'',92,500.00),(33,''Mira'',NULL,0.00);", "output": "student_id\tname\tmarks\n31\tMira\t92\n32\tKabir\t76\n33\tMira\tNULL", "explanation": "An explicit projection omits fee balances while retaining identity and the original score, including missing scores. Ordering by the key gives a deterministic presentation."}]'::jsonb,'[{"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO students VALUES (9,''Isha'',0,10.00);", "expected": "student_id\tname\tmarks\n9\tIsha\t0", "hidden": true}]'::jsonb,'["student_id is unique and non-null", "marks can be NULL or between 0 and 100", "names are not unique"]'::jsonb,'["List only the three promised fields", "Use the identifier for deterministic ordering"]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'An explicit projection omits fee balances while retaining identity and the original score, including missing scores. Ordering by the key gives a deterministic presentation.','{"sql": "SELECT student_id, name, marks FROM students ORDER BY student_id;"}'::jsonb,'An explicit projection omits fee balances while retaining identity and the original score, including missing scores. Ordering by the key gives a deterministic presentation.',array['sql'],'CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));','INSERT INTO students VALUES (32,''Kabir'',76,0.00),(31,''Mira'',92,500.00),(33,''Mira'',NULL,0.00);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-2-external-schema' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='dsa-dbms-sql-external-schema-course-perspective' or slug='external-schema-course-perspective') and (id<>'dsa-dbms-sql-external-schema-course-perspective' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'dsa-dbms-sql-external-schema-course-perspective'; end if;
if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-external-schema-course-perspective' and description is distinct from 'Return student_id, name, course_name, marks for enrollments with marks >= 90. Join students to enrollments on student_id. One output row represents one enrollment; order by student_id then course_name. Do not expose fee balances or include students without a qualifying enrollment.

**MySQL dialect.**

```sql
CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));
CREATE TABLE enrollments (student_id INT NOT NULL, course_name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), PRIMARY KEY (student_id, course_name));
INSERT INTO students VALUES (31,''Mira'',92,500.00),(32,''Kabir'',76,0.00),(33,''Mira'',NULL,0.00);
INSERT INTO enrollments VALUES (31,''Databases'',92),(31,''Networks'',90),(32,''Databases'',89),(33,''Databases'',NULL);
```

**Required ordering:** student_id ascending, then course_name ascending

**Edge cases:**
- Exactly 90 qualifies
- NULL and 89 do not qualify
- Two qualifying enrollments for one student produce two rows
- Students without enrollments are excluded') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-external-schema-course-perspective'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-external-schema-course-perspective',null::text,'Build a high-score course perspective','Medium','external-schema-course-perspective','Return student_id, name, course_name, marks for enrollments with marks >= 90. Join students to enrollments on student_id. One output row represents one enrollment; order by student_id then course_name. Do not expose fee balances or include students without a qualifying enrollment.

**MySQL dialect.**

```sql
CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));
CREATE TABLE enrollments (student_id INT NOT NULL, course_name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), PRIMARY KEY (student_id, course_name));
INSERT INTO students VALUES (31,''Mira'',92,500.00),(32,''Kabir'',76,0.00),(33,''Mira'',NULL,0.00);
INSERT INTO enrollments VALUES (31,''Databases'',92),(31,''Networks'',90),(32,''Databases'',89),(33,''Databases'',NULL);
```

**Required ordering:** student_id ascending, then course_name ascending

**Edge cases:**
- Exactly 90 qualifies
- NULL and 89 do not qualify
- Two qualifying enrollments for one student produce two rows
- Students without enrollments are excluded','[{"input": "INSERT INTO students VALUES (31,''Mira'',92,500.00),(32,''Kabir'',76,0.00),(33,''Mira'',NULL,0.00);\nINSERT INTO enrollments VALUES (31,''Databases'',92),(31,''Networks'',90),(32,''Databases'',89),(33,''Databases'',NULL);", "output": "student_id\tname\tcourse_name\tmarks\n31\tMira\tDatabases\t92\n31\tMira\tNetworks\t90", "explanation": "The identifier join preserves student identity, while the enrollment predicate selects qualifying course scores. One row per enrollment preserves both courses for a qualifying student."}]'::jsonb,'[{"seed_sql": "INSERT INTO students VALUES (1,''Noor'',100,0.00);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO students VALUES (2,''Sam'',20,0.00),(1,''Sam'',100,0.00); INSERT INTO enrollments VALUES (2,''Logic'',90),(1,''Logic'',NULL);", "expected": "student_id\tname\tcourse_name\tmarks\n2\tSam\tLogic\t90", "hidden": true}]'::jsonb,'["Each student-course pair is unique", "Every enrollment in the fixtures references an existing student; the query must join identifiers", "Enrollment marks can be NULL", "Use the enrollment score, not the simplified student score"]'::jsonb,'["Qualify marks with the enrollment alias", "Filter enrollment marks after defining the identifier join"]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The identifier join preserves student identity, while the enrollment predicate selects qualifying course scores. One row per enrollment preserves both courses for a qualifying student.','{"sql": "SELECT s.student_id, s.name, e.course_name, e.marks FROM students s JOIN enrollments e ON e.student_id = s.student_id WHERE e.marks >= 90 ORDER BY s.student_id, e.course_name;"}'::jsonb,'The identifier join preserves student identity, while the enrollment predicate selects qualifying course scores. One row per enrollment preserves both courses for a qualifying student.',array['sql'],'CREATE TABLE students (student_id INT PRIMARY KEY, name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), fee_balance DECIMAL(8,2) NOT NULL CHECK (fee_balance >= 0));
CREATE TABLE enrollments (student_id INT NOT NULL, course_name VARCHAR(40) NOT NULL, marks INT NULL CHECK (marks BETWEEN 0 AND 100), PRIMARY KEY (student_id, course_name));','INSERT INTO students VALUES (31,''Mira'',92,500.00),(32,''Kabir'',76,0.00),(33,''Mira'',NULL,0.00);
INSERT INTO enrollments VALUES (31,''Databases'',92),(31,''Networks'',90),(32,''Databases'',89),(33,''Databases'',NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-2-external-schema' on conflict(id) do nothing;
