if exists(select 1 from public.test_questions where id='tq-dbms-sql-10-foreign-key-constraint-syntax-1' and (question_text,options,correct_index,explanation) is distinct from ('Which SQL clause form is required when a foreign key references a composite (multi-column) primary key in the parent table?','["Column-level REFERENCES on each child column separately", "The table-level FOREIGN KEY (col1, col2) REFERENCES parent(col1, col2) clause", "Two separate single-column foreign keys", "A CHECK constraint combined with REFERENCES"]'::jsonb,1,'A composite foreign key must be declared as one table-level FOREIGN KEY clause listing all referencing and referenced columns together; it cannot be split across column-level REFERENCES clauses.') and (question_text,options,correct_index,explanation) is distinct from ('Which SQL clause form is required when a foreign key references a composite (multi-column) primary key in the parent table?','["Column-level REFERENCES on each child column separately", "The table-level FOREIGN KEY (col1, col2) REFERENCES parent(col1, col2) clause", "Two separate single-column foreign keys", "A CHECK constraint combined with REFERENCES"]'::jsonb,1,'A composite foreign key must be declared as one table-level FOREIGN KEY clause listing all referencing and referenced columns together; it cannot be split across column-level REFERENCES clauses.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-10-foreign-key-constraint-syntax-1'; end if;
