insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-foreign-key-constraint-syntax-1','pt-dbms-sql-10-foreign-key-constraint-syntax','Which SQL clause form is required when a foreign key references a composite (multi-column) primary key in the parent table?','["Column-level REFERENCES on each child column separately", "The table-level FOREIGN KEY (col1, col2) REFERENCES parent(col1, col2) clause", "Two separate single-column foreign keys", "A CHECK constraint combined with REFERENCES"]'::jsonb,1,'A composite foreign key must be declared as one table-level FOREIGN KEY clause listing all referencing and referenced columns together; it cannot be split across column-level REFERENCES clauses.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
