 and negative cases exercise optional matching without a query-only simulation.',array['sql'],'CREATE TABLE department_input (department_id INT PRIMARY KEY); CREATE TABLE employee_input (employee_id INT PRIMARY KEY,department_id INT NULL);','INSERT INTO department_input VALUES (10); INSERT INTO employee_input VALUES (1,10),(2,NULL);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-10-foreign-key-constraint-syntax' on conflict(id) do nothing;
