update public.learning_topics set short_description='Factor common facts into a meaningful Person supertype, preserve shared identity across student and employee roles, and distinguish overlap, coverage and mapping enforcement.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Factor common facts into a meaningful Person supertype, preserve shared identity across student and employee roles, and distinguish overlap, coverage and mapping enforcement.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Generalization.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-generalization' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-generalization-application','MCQ Test 2',category,10,10,'Application and scenarios for Generalization.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-generalization' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-1','pt-dbms-sql-6-generalization','What is generalization in EER modeling?','["A top-down process of splitting an entity set into subclasses", "A bottom-up process of abstracting common attributes of two or more entity sets into a single superclass", "Treating a relationship as an entity", "A rule that limits attribute values"]'::jsonb,1,'Generalization identifies a meaningful common supertype while retaining the specific roles and identity semantics.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-2','pt-dbms-sql-6-generalization','When their meanings agree across the two roles, which properties can be factored into a common Person supertype?','["Attributes unique to Student only", "Attributes unique to Employee only", "Attributes shared by both, like Name, Date_of_Birth, and Email", "Derived attributes only"]'::jsonb,2,'Only genuinely common properties should be shared; an official work email and a preferred contact can require different role-specific meanings.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-3','pt-dbms-sql-6-generalization','How does generalization differ from specialization in terms of design direction?','["They are identical processes with no directional difference", "Generalization is bottom-up (merging existing subclasses into a superclass); specialization is top-down (splitting an existing superclass into new subclasses)", "Generalization is top-down; specialization is bottom-up", "Neither has a defined direction"]'::jsonb,1,'This is the core distinguishing feature: generalization merges upward, specialization splits downward, though both yield an ISA hierarchy.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-4','pt-dbms-sql-6-generalization','Which of these is NOT part of what generalization/specialization constraints describe?','["Disjoint vs. overlapping subclasses", "Total vs. partial coverage of the superclass", "The number of entity sets in a relationship (degree)", "Whether a Person must be a Student, an Employee, or possibly neither/both"]'::jsonb,2,'Relationship degree is an unrelated concept (6.12); disjoint/overlapping and total/partial are the EER-specific constraints on generalization hierarchies.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-5','pt-dbms-sql-6-generalization','How can the superclass-subclass link be represented in a common EER notation?','["As an ordinary diamond, same as any relationship", "As an ISA triangle/arrow notation, distinct from the relationship diamond", "As a double-line rectangle", "As a dashed oval"]'::jsonb,1,'ISA notation communicates the subtype relationship; exact symbols depend on the convention.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-6','pt-dbms-sql-6-generalization','Which statement correctly separates generalization from aggregation?','["They are two names for the same EER concept", "Generalization forms an is-a hierarchy; EER aggregation abstracts a relationship occurrence for further association, serving a different modeling purpose", "Aggregation always requires a weak entity; generalization never does", "Generalization only applies to binary relationships"]'::jsonb,1,'Both are modeling abstractions, but shared type identity and relationship abstraction answer different questions.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-7','pt-dbms-sql-6-generalization','If Student and Employee are generalized into Person, and it turns out some people are BOTH students and employees (e.g., teaching assistants), what constraint would apply?','["Disjoint", "Overlapping", "Total participation only, with no bearing on overlap", "This scenario is impossible in EER modeling"]'::jsonb,1,'When a single instance can belong to more than one subclass simultaneously, the hierarchy is overlapping rather than disjoint.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-generalization-8','pt-dbms-sql-6-generalization','What is the main design benefit of generalization?','["It increases data redundancy for performance", "It reduces redundancy by factoring shared attributes of similar entity sets into one common superclass", "It removes the need for primary keys", "It converts entities into relationships"]'::jsonb,1,'By pulling shared attributes into a superclass, generalization avoids storing the same attributes redundantly in each subclass.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
