insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-generalization-membership',null::text,'Classify the partial overlapping Person population','Medium','generalization-membership','Return every person_id and role_state: both, student-only, employee-only or neither, based on current membership in the two role tables.

