update public.learning_topics set short_description='Derive a row property through an engine-managed expression, choose stored or virtual representation deliberately, and test recalculation without assuming indexing or cross-engine support.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Derive a row property through an engine-managed expression, choose stored or virtual representation deliberately, and test recalculation without assuming indexing or cross-engine support.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Generated Columns.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-9-generated-columns' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-9-generated-columns-application','MCQ Test 2',category,10,10,'Application and scenarios for Generated Columns.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-9-generated-columns' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-1','pt-dbms-sql-9-generated-columns','What is a generated (computed) column?','["A column whose value is manually entered by the user on every insert", "A column whose value is automatically derived from an expression over other columns in the same row", "A column that stores a foreign key reference", "A column used only for indexing purposes"]'::jsonb,1,'Generated columns compute their value from an expression rather than accepting a directly supplied value.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-2','pt-dbms-sql-9-generated-columns','What representation distinction do STORED and VIRTUAL make in the illustrated MySQL forms?','["There is no difference, they are synonyms", "STORED retains the calculated base-row value; VIRTUAL evaluates it when needed, with supported indexes having their own storage", "VIRTUAL is only available in PostgreSQL; STORED is only available in MySQL", "STORED columns cannot be indexed while VIRTUAL columns always can"]'::jsonb,1,'Both derive from the formula; virtual indexing support is engine specific.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-3','pt-dbms-sql-9-generated-columns','Can an ordinary explicit non-DEFAULT value replace a PostgreSQL generated expression value?','["It succeeds and overrides the computed value", "No; the defined expression supplies it rather than an independent ordinary value", "It is silently ignored", "It sets the column to NULL"]'::jsonb,1,'DEFAULT is different from overriding with an arbitrary computed result.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-4','pt-dbms-sql-9-generated-columns','Can MySQL support indexes involving virtual generated columns in applicable cases?','["Indexing rules are unrelated to storage", "Yes; support and restrictions depend on the engine and feature rules", "VIRTUAL columns are always faster to index", "STORED columns are always primary keys"]'::jsonb,1,'Do not teach the false blanket rule that only stored generated columns can be indexed.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-5','pt-dbms-sql-9-generated-columns','Which kind of expression is typically NOT allowed in a generated column definition?','["Arithmetic on other columns in the same row", "String concatenation of other columns in the same row", "A call to a volatile, non-deterministic function like now() or random()", "A CASE expression over other columns in the same row"]'::jsonb,2,'Generated column expressions must generally be deterministic, so volatile functions are typically disallowed.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-6','pt-dbms-sql-9-generated-columns','What typically happens if you try to drop a source column that a generated column''s expression depends on?','["It succeeds silently, leaving the generated column broken", "Most engines block the drop unless the generated column is altered or dropped first", "The generated column automatically becomes a regular column", "It is impossible to ever create such a dependency"]'::jsonb,1,'Dependency enforcement typically prevents dropping a column that a generated expression relies on.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-7','pt-dbms-sql-9-generated-columns','When is a generated full-name property worth considering for indexing?','["To reduce the total number of columns in the table", "When a supported definition serves a real query pattern and measured benefit justifies maintenance costs", "Because PostgreSQL requires it for text columns", "To avoid needing a primary key"]'::jsonb,1,'The expression and index do not automatically guarantee a faster query.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-generated-columns-8','pt-dbms-sql-9-generated-columns','What is a cost of using STORED generated columns extensively on a write-heavy table?','["They have no cost at all", "They consume extra disk space and add CPU/write cost whenever source columns change", "They prevent the table from ever being indexed", "They disable transactions on the table"]'::jsonb,1,'STORED columns are recalculated and rewritten to disk on relevant changes, incurring real storage and write overhead.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-generated-columns-new-9','pt-dbms-sql-9-generated-columns','Does a generated total decide whether a historical invoice should change?','["Yes, always", "No; historical fact policy is a separate design decision", "Only with STORED", "Only if indexed"]'::jsonb,1,'A current formula and a frozen accepted charge are different facts.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-generated-columns-new-10','pt-dbms-sql-9-generated-columns','What should an insert ordinarily supply for a generated total?','["Any conflicting total", "Only an alias", "The required base inputs while omitting an independent total", "A random override"]'::jsonb,2,'The definition supplies the derived value.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-generated-columns-application-new-1','pt-dbms-sql-9-generated-columns-application','Quantity rises from 2 to 3 at price 4.50. What is the defined new total?','["9.00", "4.50", "13.50", "2.00"]'::jsonb,2,'Generation follows the current source inputs.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-generated-columns-application-new-2','pt-dbms-sql-9-generated-columns-application','Does a multiplication formula itself reject negative quantity?','["Yes, by definition", "Only for virtual columns", "Only if sorted", "No"]'::jsonb,3,'Domain constraints are separate from calculation consistency.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
