if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-graph-model-2' and (question_text,options,correct_index,explanation) is distinct from ('What is a ''property graph'', as implemented by databases like Neo4j?','["A graph where only nodes can have properties, never edges", "A graph model where both nodes and edges can carry their own key-value properties", "A graph stored entirely as a relational table", "A graph with no labels or types at all"]'::jsonb,1,'In a property graph, both nodes and relationships can have attached properties, unlike a plain mathematical graph with unlabeled edges.') and (question_text,options,correct_index,explanation) is distinct from ('What is a ''property graph'', as implemented by databases like Neo4j?','["A graph where only nodes can have properties, never edges", "A graph model where both nodes and edges can carry their own key-value properties", "A graph stored entirely as a relational table", "A graph with no labels or types at all"]'::jsonb,1,'In a property graph, both nodes and relationships can have attached properties, unlike a plain mathematical graph with unlabeled edges.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-graph-model-2'; end if;
