if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-graph-model-4' and (question_text,options,correct_index,explanation) is distinct from ('Why would a query like ''friends of Alice''s friends'' become increasingly expensive in a relational database as the friendships table grows?','["Because relational databases cannot store friendship data", "Because it requires a multi-way self-join whose cost grows with table size, unlike a graph database''s constant-time pointer hops per edge", "Because SQL cannot express WHERE clauses", "Because relational databases do not support recursive queries at all"]'::jsonb,1,'Relational databases must perform expensive self-joins to traverse relationships, and this cost scales with data size, whereas graph databases traverse via direct pointers.') and (question_text,options,correct_index,explanation) is distinct from ('How should a two-hop relational query be compared with native graph traversal?','["Because relational databases cannot store friendship data", "Measure actual plans, indexes, degrees, and required output rather than assume one universal cost ranking", "Because SQL cannot express WHERE clauses", "Because relational databases do not support recursive queries at all"]'::jsonb,1,'Selective relational joins can be effective; graph paths can also expand greatly.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-graph-model-4'; end if;
