insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-1','pt-dbms-sql-8-identifiers','What is a SQL ''identifier''?','["A row''s primary key value", "A name given to a database object such as a table, column, or index", "A type of join", "A function that returns TRUE or FALSE"]'::jsonb,1,'An identifier is simply the name used to refer to a database object.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-2','pt-dbms-sql-8-identifiers','Which token cannot be an unquoted MySQL identifier because it consists entirely of digits?','["student_id", "department2", "123", "_temp"]'::jsonb,2,'MySQL permits some digit-leading names, but a wholly numeric token needs quoting to act as an identifier.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-3','pt-dbms-sql-8-identifiers','In MySQL, how would you name a table `order` despite ORDER being a reserved keyword?','["It is impossible to ever use a reserved word as a name", "Quote it, e.g. with backticks: `` `order` ``", "Reserved words automatically become valid table names with no special handling", "Only by renaming ORDER BY itself"]'::jsonb,1,'Quoting (backticks in MySQL) lets a reserved word be used as an identifier.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-4','pt-dbms-sql-8-identifiers','What is the accurate MySQL statement about quoting and identifier case?','["Backticks make every name case-sensitive", "Backticks delimit names; case behavior depends on the identifier category and environment", "Backticks always force lowercase", "Quoting a name changes string-data collation"]'::jsonb,1,'Do not transfer another dialect''s quoted-case rules. MySQL table and column categories have different behavior.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-5','pt-dbms-sql-8-identifiers','Why is MySQL table-name case-sensitivity described as inconsistent across environments?','["MySQL never varies in any way across environments", "On Linux, table names are stored as files, so case-sensitivity can depend on the host filesystem, unlike column names", "Table names are always case-sensitive in every OS", "MySQL doesn''t support case-sensitive names anywhere"]'::jsonb,1,'Platform and lower_case_table_names affect table/database naming behavior; this does not establish the same rules for column names.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-6','pt-dbms-sql-8-identifiers','What is a practical reason to avoid identifiers with spaces, like "Student Name"?','["Spaces are completely forbidden and will always cause an immediate crash", "Every reference to that identifier then requires quoting, which is easy to forget and error-prone", "Spaces make queries run faster", "Spaces are only a problem in SELECT, never elsewhere"]'::jsonb,1,'An identifier containing a space must be quoted every time it''s referenced, which increases the chance of a missed-quote error.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-7','pt-dbms-sql-8-identifiers','Which naming convention avoids most identifier-quoting headaches altogether?','["Using spaces and mixed case freely", "Naming things exactly after SQL reserved words", "Lowercase names with underscores, avoiding reserved words", "Randomly capitalizing letters"]'::jsonb,2,'Lowercase-with-underscores names that avoid reserved words rarely need quoting at all, sidestepping case-sensitivity and reserved-word conflicts.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-identifiers-8','pt-dbms-sql-8-identifiers','Why prefer registered_on over a vague column name such as date in a registration table?','["No consequence whatsoever in any dialect", "It expresses the intended event and avoids unnecessary keyword/type-name confusion", "It automatically renames itself to avoid conflict", "It becomes the table''s primary key automatically"]'::jsonb,1,'DATE is not universally forbidden as an identifier. Descriptive names improve meaning and reduce dialect-related confusion.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-new-9','pt-dbms-sql-8-identifiers','What distinguishes an identifier from a literal?','["Both always name tables", "An identifier names a query object; a literal supplies a value", "Both always represent character data", "A literal grants permission"]'::jsonb,1,'Separating names from data is necessary to interpret SQL correctly.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-new-10','pt-dbms-sql-8-identifiers','Why qualify attendee_id in a join where both inputs have that column?','["To convert it into a string", "To remove all duplicates automatically", "To identify which source column is intended", "To change the table''s primary key"]'::jsonb,2,'A qualifier resolves the source of a potentially ambiguous name.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-1','pt-dbms-sql-8-identifiers-application','A MySQL query selects single-quoted customer name text for every order. What can it return?','["The stored customer-name column automatically", "A renamed table", "The constant text customer name on each row", "Only a syntax error in every mode"]'::jsonb,2,'Single quotes normally describe string data rather than an object reference.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-2','pt-dbms-sql-8-identifiers-application','Which MySQL query correctly reads a legacy column containing a space?','["SELECT ''customer name'' FROM `order`;", "SELECT customer name FROM `order` with no alias intent", "SELECT customer-name FROM `order`;", "SELECT `customer name` FROM `order`;"]'::jsonb,3,'Backticks delimit the actual column name instead of constructing a constant or expression.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-3','pt-dbms-sql-8-identifiers-application','ANSI_QUOTES is enabled. What does a double-quoted name denote?','["An identifier", "Always a string value", "An integer literal", "A transaction boundary"]'::jsonb,0,'That SQL mode changes double-quote interpretation; single quotes remain the clear string form.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-4','pt-dbms-sql-8-identifiers-application','Does backtick-quoting a column name decide whether stored Mira equals MIRA?','["Yes; every quoted column forces case-sensitive data", "No; data comparison has its own collation rules", "Yes; all strings become lowercase", "Only the table alias controls data collation"]'::jsonb,1,'Identifier parsing and string-value comparison are different concerns.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-5','pt-dbms-sql-8-identifiers-application','A query introduces alias a and later writes A. What is the portable habit?','["Assume every platform folds aliases identically", "Remove the join predicate", "Use the exact alias spelling consistently", "Quote all string values as identifiers"]'::jsonb,2,'Alias case handling can differ across environments.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-identifiers-application-new-6','pt-dbms-sql-8-identifiers-application','A developer wants a user-selectable sort column. Can a normal value placeholder simply become an arbitrary identifier?','["Yes; placeholders grant access to any object", "Yes; names and string values are interchangeable", "Only if the name contains spaces", "No; use a validated mapping to supported SQL structure"]'::jsonb,3,'Binding values does not automatically bind statement structure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
