if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-identifying-relationship-5' and (question_text,options,correct_index,explanation) is distinct from ('Can a weak entity participate in relationships other than its identifying relationship?','["No, a weak entity may only ever appear in its identifying relationship", "Yes \u2014 it can have other ordinary relationships to other entity sets, in addition to exactly one identifying relationship with its owner", "Only if it becomes a strong entity first", "Only in EER diagrams, never in plain ER diagrams"]'::jsonb,1,'The identifying relationship is specifically the one supplying the owner''s key; a weak entity can still have additional unrelated relationships.') and (question_text,options,correct_index,explanation) is distinct from ('Can a weak entity participate in relationships other than its identifying relationship?','["No, a weak entity may only ever appear in its identifying relationship", "Yes; a weak room can have booking or other ordinary relationships in addition to the identifying owner relationship in this model", "Only if it becomes a strong entity first", "Only in EER diagrams, never in plain ER diagrams"]'::jsonb,1,'The identifying association supplies owner context; other relationships do not automatically replace it or become identifying.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-identifying-relationship-5'; end if;
