if exists(select 1 from public.test_questions where id='pt-dbms-sql-6-identifying-relationship-application-new-8' and (question_text,options,correct_index,explanation) is distinct from ('What does an invalid booking-pair audit authorize by itself?','["Creation of every missing building", "No automatic correction or creation action", "Reassignment to any matching room number", "Deletion of all proposals"]'::jsonb,1,'Diagnosis and authority are separate.') and (question_text,options,correct_index,explanation) is distinct from ('What does an invalid booking-pair audit authorize by itself?','["Creation of every missing building", "No automatic correction or creation action", "Reassignment to any matching room number", "Deletion of all proposals"]'::jsonb,1,'Diagnosis and authority are separate.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-6-identifying-relationship-application-new-8'; end if;
