if exists(select 1 from public.test_questions where id='pt-dbms-sql-6-identifying-relationship-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('What does the double Room participation connection express?','["Every owner needs two rooms", "Every capacity is unique", "Every room needs its identifying owner link", "All bookings must be deleted"]'::jsonb,2,'The dependent minimum is mandatory in this model.') and (question_text,options,correct_index,explanation) is distinct from ('What does the double Room participation connection express?','["Every owner needs two rooms", "Every capacity is unique", "Every room needs its identifying owner link", "All bookings must be deleted"]'::jsonb,2,'The dependent minimum is mandatory in this model.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-6-identifying-relationship-application-new-9'; end if;
