update public.learning_topics set short_description='Connect owner identity to a weak entity discriminator, distinguish identifying dependence from ordinary references, and preserve complete room identity in related booking facts.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Connect owner identity to a weak entity discriminator, distinguish identifying dependence from ordinary references, and preserve complete room identity in related booking facts.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Identifying Relationship.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-identifying-relationship' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-identifying-relationship-application','MCQ Test 2',category,10,10,'Application and scenarios for Identifying Relationship.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-identifying-relationship' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-1','pt-dbms-sql-6-identifying-relationship','What is an identifying relationship?','["Any relationship between two strong entities", "The special relationship connecting a weak entity set to its owner entity set, providing the identification the weak entity lacks on its own", "A relationship that has no cardinality", "A synonym for a recursive relationship"]'::jsonb,1,'The identifying relationship supplies the owner''s key that, combined with the partial key, uniquely identifies the weak entity.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-2','pt-dbms-sql-6-identifying-relationship','In the Chen-style convention used here, how is the identifying relationship shown?','["As a single-line diamond", "As a double-line diamond", "As a dashed oval", "As a rectangle"]'::jsonb,1,'A double-line diamond pairs with the double-line rectangle of the weak entity to visually flag the identifying relationship.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-3','pt-dbms-sql-6-identifying-relationship','What is the participation of the weak entity''s side in its identifying relationship?','["Always partial", "Always total, because the weak entity cannot exist or be identified without this link", "It varies case by case with no structural rule", "It depends on the cardinality only"]'::jsonb,1,'Total participation on the weak entity''s side is a structural requirement, not a case-by-case design choice.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-4','pt-dbms-sql-6-identifying-relationship','In this lesson’s conventional single-owner Building-Room model, can one room have several interchangeable identifying buildings without changing the model?','["Yes, this is the most common case", "No; the model specifies exactly one identifying owner per room, and changing that requirement requires a new explicit identification account", "Yes, but only for recursive weak entities", "M:N does not apply to identifying relationships at all"]'::jsonb,1,'This is the stated single-owner pattern, not a proof that every more elaborate combined identification context is impossible.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-5','pt-dbms-sql-6-identifying-relationship','Can a weak entity participate in relationships other than its identifying relationship?','["No, a weak entity may only ever appear in its identifying relationship", "Yes; a weak room can have booking or other ordinary relationships in addition to the identifying owner relationship in this model", "Only if it becomes a strong entity first", "Only in EER diagrams, never in plain ER diagrams"]'::jsonb,1,'The identifying association supplies owner context; other relationships do not automatically replace it or become identifying.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-6','pt-dbms-sql-6-identifying-relationship','How does the identifying relationship relate to the concept of a weak entity''s key?','["It has no relation to the key at all", "It supplies the owner entity''s primary key, which combines with the weak entity''s partial key to form its full composite key", "It replaces the need for a partial key entirely", "It only matters for recursive relationships"]'::jsonb,1,'This relationship is precisely what lets the weak entity''s composite key (owner key + partial key) be formed.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-7','pt-dbms-sql-6-identifying-relationship','In the Employee/Dependent example, what is the identifying relationship most likely called, and what is its degree?','["Manages; degree 1 (recursive)", "Belongs_To (or similar), connecting Dependent to Employee; degree 2 (binary)", "Offers; degree 3 (ternary)", "Enrolls_In; degree 2 (binary)"]'::jsonb,1,'The identifying relationship links the weak entity (Dependent) to its owner (Employee) — a binary, degree-2 relationship.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-identifying-relationship-8','pt-dbms-sql-6-identifying-relationship','Which statement correctly separates ''weak entity'' from ''identifying relationship''?','["They are exactly the same construct with two names", "A weak entity is the entity set lacking its own full key; the identifying relationship is the specific association that links it to its owner and supplies that missing key information", "An identifying relationship is a type of attribute", "A weak entity can exist without any identifying relationship at all"]'::jsonb,1,'Weak entity (6.4) and identifying relationship (6.16) are two distinct but tightly linked concepts: one is the entity set, the other is the connecting relationship that makes its identification possible.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-identifying-relationship-new-9','pt-dbms-sql-6-identifying-relationship','Which ingredient distinguishes Room 101 in Building 7 from Room 101 in Building 9?','["Capacity alone", "The owner identity combined with the local discriminator", "The insertion position", "The displayed font"]'::jsonb,1,'The identifying context is part of complete room identity.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
