insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-identifying-booking-audit',null::text,'Find unsupported owner-dependent booking references','Medium','identifying-booking-audit','Return proposal_id, building_id and room_number for proposals with no matching complete Room identity. A room with the same local number in another building is not a match.

