insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-identity-columns-1','pt-dbms-sql-9-identity-columns','What does an identity mechanism primarily provide, separately from a key constraint?','["Storing free-text descriptions", "Automatically supplied identifier values; uniqueness needs the appropriate integrity constraint", "Enforcing a CHECK constraint", "Storing computed totals from other columns"]'::jsonb,1,'A generator alone does not establish business uniqueness or all possible key uniqueness.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-identity-columns-2','pt-dbms-sql-9-identity-columns','What is the core distinction between GENERATED ALWAYS AS IDENTITY and GENERATED BY DEFAULT AS IDENTITY?','["They are exact synonyms", "GENERATED ALWAYS rejects explicit insert values by default; GENERATED BY DEFAULT allows an explicit value to override the generated one", "GENERATED BY DEFAULT can only be used with text columns", "GENERATED ALWAYS is only available in MySQL"]'::jsonb,1,'GENERATED ALWAYS enforces engine-assigned values (needing OVERRIDING SYSTEM VALUE to bypass), while GENERATED BY DEFAULT lets an explicit value take precedence when supplied.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
