insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-identity-columns-4','pt-dbms-sql-9-identity-columns','In the illustrated MySQL comparison, what distinguishes DELETE from TRUNCATE for AUTO_INCREMENT?','["Both reset the counter identically", "DELETE does not imply resetting the counter, while TRUNCATE resets it under the stated rules", "DELETE always resets it; TRUNCATE never does", "Neither statement ever affects the counter"]'::jsonb,1,'Other engines and identity options require their own interpretation.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-identity-columns-5','pt-dbms-sql-9-identity-columns','What is the core distinction between an Identity Column and a Sequence?','["They are unrelated concepts with no overlap", "An identity column is bound to one specific column of one table; a sequence is a standalone object that can be shared across multiple tables/columns", "A sequence can only be used once ever", "Identity columns can be shared across tables while sequences cannot"]'::jsonb,1,'Identity columns are column-attached; sequences are independent, reusable generator objects — some engines implement identity columns on top of sequences internally.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
