update public.learning_topics set short_description='Add accepted rows with explicit target roles, preserve the retained employee insertion checker, and distinguish input values, defaults, statement failure and transaction completion.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Add accepted rows with explicit target roles, preserve the retained employee insertion checker, and distinguish input values, defaults, statement failure and transaction completion.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for INSERT.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-11-insert' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-11-insert-application','MCQ Test 2',category,10,10,'Application and scenarios for INSERT.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-11-insert' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-1','pt-dbms-sql-11-insert','What does an INSERT statement add to an existing table?','["Modifies existing rows", "New rows under the table’s applicable acceptance rules", "Removes a row from a table", "Changes a table''s structure"]'::jsonb,1,'The statement can insert one or several rows; it does not define the table itself.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-2','pt-dbms-sql-11-insert','Why explicitly name target columns?','["It is required syntax with no alternative", "It states value roles, reduces dependence on physical ordering and permits deliberate omission", "It makes the INSERT run faster", "Named columns are mandatory for NOT NULL columns only"]'::jsonb,1,'It does not guarantee compatibility with every later schema change.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-3','pt-dbms-sql-11-insert','Why must missing required input be evaluated under the actual target settings?','["The column is set to an empty string automatically", "Defaults, strictness and special column rules determine the supported error or conversion outcome", "The column is set to zero", "SQL infers a value automatically"]'::jsonb,1,'The fixtures use strict ordinary-column rejection rather than a universal permissive-mode claim.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-4','pt-dbms-sql-11-insert','For an ordinary transactional InnoDB insert without IGNORE or an update variant, what does a uniqueness failure imply?','["Only the violating value is skipped; the rest proceeds", "The statement is rejected under its transactional rules rather than accepting an arbitrary partial successful insert", "The constraint is temporarily disabled", "The row is inserted with a NULL instead"]'::jsonb,1,'Surrounding transaction recovery and nontransactional engines need separate treatment.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-5','pt-dbms-sql-11-insert','Is `INSERT INTO employees VALUES (9, ''Farah'', ''Engineering'', 75000)` (no column list) as robust as naming columns explicitly?','["Yes, identically robust", "No — it relies on positional order matching the table''s current column order, which can break if the schema changes", "It is more robust because it''s shorter", "This syntax is invalid SQL"]'::jsonb,1,'Omitting the column list ties the statement to the table''s exact current column order — a fragile assumption.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-6','pt-dbms-sql-11-insert','Can an INSERT trigger additional automatic behavior beyond adding the row?','["No, INSERT only ever does exactly what''s written", "Yes — an INSERT trigger (Chapter 30) can fire automatically as a side effect", "Only DELETE statements can have triggers", "Triggers only fire on SELECT statements"]'::jsonb,1,'Triggers can attach extra automatic behavior to INSERT, UPDATE, or DELETE.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-7','pt-dbms-sql-11-insert','Which constraint types can cause an INSERT to fail?','["Only NOT NULL", "UNIQUE, CHECK, FOREIGN KEY, NOT NULL, and PRIMARY KEY constraints can all reject an INSERT that violates them", "Only PRIMARY KEY", "Constraints never affect INSERT, only UPDATE"]'::jsonb,1,'Any violated constraint on the table can cause the INSERT to be rejected.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-insert-8','pt-dbms-sql-11-insert','What is the relationship between INSERT and the rest of DML (UPDATE, DELETE)?','["INSERT is unrelated to UPDATE/DELETE", "INSERT is the entry point that creates rows which UPDATE and DELETE later modify or remove", "INSERT can only be used after a DELETE", "UPDATE and DELETE must always precede any INSERT"]'::jsonb,1,'INSERT creates the data that subsequent UPDATE/DELETE statements act upon.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-11-insert-new-9','pt-dbms-sql-11-insert','Does INSERT define a missing target table?','["Yes", "No", "Only if it has a key", "Only with text"]'::jsonb,1,'The destination definition is a prerequisite.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
