insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-1','pt-dbms-sql-2-internal-schema','What does the Internal Schema describe in the three-schema architecture?','["The subset of data a specific application is allowed to see", "The complete organization-wide logical structure of entities and relationships", "The physical storage details: file organization, indexing, block size, and data representation", "The network protocol clients use to connect to the server"]'::jsonb,2,'The internal schema is the lowest, physical level, concerned entirely with how data is stored on disk/memory.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-2','pt-dbms-sql-2-internal-schema','Who usually works with internal representation and supported physical tuning details?','["End users of the application", "The DBMS implementation and authorized administrators or performance specialists", "Every external application equally", "Middleware vendors exclusively"]'::jsonb,1,'Engine internals and authorized physical tuning are distinct from ordinary end-user interfaces.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-3','pt-dbms-sql-2-internal-schema','Which of these is an internal-schema-level change?','["Adding a new column to the conceptual Student table", "Switching Student records from a heap file to a B+-tree-indexed structure", "Creating a new external view for the Accounts Portal", "Adding a foreign key constraint between Student and Department"]'::jsonb,1,'Switching storage/indexing structures is purely a physical, internal-schema change.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-4','pt-dbms-sql-2-internal-schema','Why can PostgreSQL and MySQL both implement the exact same conceptual `Student(StudentID, Name, DOB)` schema yet behave very differently in performance tuning?','["Because their conceptual schemas are actually different", "Because their internal schemas (file format, index types, page layout) can differ even when the conceptual schema is identical", "Because MySQL does not support conceptual schemas", "Because performance is unrelated to the internal schema"]'::jsonb,1,'The conceptual schema only fixes logical structure; internal (physical) implementation is free to vary between systems.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-5','pt-dbms-sql-2-internal-schema','A selective lookup on a non-key Student reference is slow, and plan evidence identifies a broad scan with no suitable access index. What kind of issue is being investigated?','["A conceptual schema design flaw", "A physical access-design issue, even when the logical data model is valid", "A middleware misconfiguration", "A violation of the external schema''s row-level restrictions"]'::jsonb,1,'The scenario supplies plan evidence; missing indexes are not a universal explanation of slow queries.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-6','pt-dbms-sql-2-internal-schema','A DBA adds a new index to speed up queries on the Student table. What should ideally happen to the conceptual and external schemas?','["Both must be redesigned to reference the new index", "Neither should need to change, since indexing is purely an internal-schema concern", "Only the external schemas need updating", "The conceptual schema must be dropped and recreated"]'::jsonb,1,'If physical data independence holds, internal-level changes like adding an index stay invisible above the internal schema.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-7','pt-dbms-sql-2-internal-schema','A student assumes that once the internal schema is designed at project launch, it never needs to change again. Why is this a mistake?','["Because internal schemas cannot legally be changed after deployment", "Because DBAs routinely re-tune internal schemas (adding indexes, repartitioning) throughout a system''s life without altering the conceptual design", "Because the internal schema is identical to the conceptual schema", "Because only external schemas can be modified after launch"]'::jsonb,1,'Internal schema tuning is an ongoing DBA activity precisely because it can change independently of the stable conceptual design.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-internal-schema-8','pt-dbms-sql-2-internal-schema','A supported engine reorganizes files and compresses records while preserving logical behavior. Which level changes, and what is the intended compatibility outcome?','["Conceptual schema level; the external schemas must be rewritten", "Internal schema level; conceptual and external contracts can remain unchanged", "External schema level; the internal schema must be redesigned", "It spans all three levels equally by necessity"]'::jsonb,1,'The scenario explicitly assumes supported mechanisms and preserved behavior; operational effects still require review.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-new-9','pt-dbms-sql-2-internal-schema','What does a page or block commonly provide in physical storage?','["A unique application user", "A unit grouping information for storage access and buffering", "A mandatory external view", "A business department identifier"]'::jsonb,1,'Pages organize physical storage; exact formats depend on the engine.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-new-10','pt-dbms-sql-2-internal-schema','Which addition can change logical validity as well as physical access?','["A faster disk with equivalent behavior", "A differently located unchanged file", "A uniqueness requirement enforced by an index", "A larger cache alone"]'::jsonb,2,'Uniqueness changes which stored states are allowed.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-1','pt-dbms-sql-2-internal-schema-application','A query returns one student. Does that prove only one physical disk read occurred?','["Yes; each row always means one disk read", "Yes; identifiers eliminate all disk work", "No; result size does not determine physical I/O", "Only when the name is non-null"]'::jsonb,2,'Caching and the chosen access path affect I/O independently of result count.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-2','pt-dbms-sql-2-internal-schema-application','An InnoDB Student table declares StudentID as its primary key. Is it accurate to say it has no access index on StudentID?','["Yes; primary keys never have indexes", "Yes; only names can be indexed", "Only external views can contain keys", "No; the primary key defines the clustered index"]'::jsonb,3,'InnoDB stores row data in its clustered index, normally based on the declared primary key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
