insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-6','pt-dbms-sql-2-internal-schema-application','A report relies on primary-key encounter order with no ORDER BY. What dependency is unsafe?','["It explicitly requests deterministic ordering", "It defines a foreign key correctly", "It avoids physical assumptions", "It treats a physical encounter order as a promised logical sequence"]'::jsonb,3,'Consumers needing order should request it rather than infer it from a past plan.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-7','pt-dbms-sql-2-internal-schema-application','An engine change drops a previously enforced relationship rule. Can it be called transparent merely because the table names match?','["No; the logical guarantees changed", "Yes; only object names matter", "Yes; storage engines cannot affect guarantees", "Only page count determines transparency"]'::jsonb,0,'Compatibility includes constraints and transaction behavior, not just names.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-8','pt-dbms-sql-2-internal-schema-application','A hot lookup performs no new disk I/O because the page is cached. Which distinction does this show?','["No query was executed", "Logical access and physical reads are different measures", "The student record must be absent", "The external schema was deleted"]'::jsonb,1,'A buffer can satisfy access without a new disk read.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-9','pt-dbms-sql-2-internal-schema-application','A proposal moves records across servers. What must be verified before claiming no application changes?','["Only the new server names", "Only whether StudentID is numeric", "Supported routing, endpoint behavior, and preserved semantics", "Only the number of users in a screenshot"]'::jsonb,2,'Distributed placement is not automatically transparent in every product.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-internal-schema-application-new-10','pt-dbms-sql-2-internal-schema-application','A benchmark improves one read query. Which conclusion still needs evidence?','["That the benchmark query was measured", "That reads can use access structures", "That logical rows have attributes", "The broader workload and operational change are acceptable"]'::jsonb,3,'An isolated result does not prove write costs, maintenance feasibility, or overall readiness.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
