insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-1','pt-dbms-sql-7-intersection','What does the Intersection operation (∩) return?','["Rows present in either of two relations", "Rows present in BOTH of two union-compatible relations", "All rows from the first relation only", "The column names common to two relations"]'::jsonb,1,'Intersection returns exactly the overlap — rows appearing in both relations.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-2','pt-dbms-sql-7-intersection','Which SQL keyword implements native shared-set intersection in MySQL 8.4?','["UNION", "INTERSECT", "EXCEPT", "JOIN"]'::jsonb,1,'INTERSECT is the standard SQL keyword for this operation.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-3','pt-dbms-sql-7-intersection','For required single-column ids, which approach can express distinct intersection when native syntax is unavailable?','["It cannot be simulated at all", "Use membership or a matching join with the full intended comparison and explicit duplicate elimination as needed", "By using UNION twice", "By using ORDER BY on both queries"]'::jsonb,1,'A bare join can multiply duplicate occurrences; nullable inputs need additional semantic care.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-4','pt-dbms-sql-7-intersection','What requirement do the two relations combined with Intersection share with Union?','["They must both be empty", "They must be union-compatible: same number of columns, with compatible types", "They must have the same primary key values", "There is no shared requirement"]'::jsonb,1,'Compatible SQL column counts and types are needed, and corresponding roles must also mean the same kind of fact.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-5','pt-dbms-sql-7-intersection','Is Intersection the same thing as an inner join?','["Yes, they are identical operations", "No — Intersection compares whole rows across same-shaped relations; a join combines rows from potentially differently-shaped relations based on a matching condition", "Inner join is a special, simpler case with no real difference", "Intersection only works on single-column relations, unlike joins"]'::jsonb,1,'The two operations solve different problems: whole-row set overlap vs. combining columns from possibly-different relations via a match condition.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-6','pt-dbms-sql-7-intersection','Does standard SQL''s INTERSECT remove duplicate rows from its result by default?','["No, it preserves every duplicate", "Yes, by default — mirroring the same set-based semantics as UNION", "Only if ORDER BY is also specified", "INTERSECT has no concept of duplicates"]'::jsonb,1,'INTERSECT deduplicates by default, just like UNION, consistent with set semantics.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-7','pt-dbms-sql-7-intersection','Which statement about the target version and historical MySQL support is accurate?','["INTERSECT has always been universally supported with zero exceptions", "MySQL 8.4 supports INTERSECT; older versions can lack it, so syntax support must be tied to the actual version", "PostgreSQL has never supported INTERSECT", "INTERSECT is exclusive to NoSQL databases"]'::jsonb,1,'Do not generalize a historical limitation to the stated modern target; local MariaDB checks remain separate from exact target execution.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-intersection-8','pt-dbms-sql-7-intersection','If honors_students contains {1,2,5} and deans_list contains {2,3}, what does their Intersection return?','["{1,2,3,5}", "{2}", "{1,5}", "{}"]'::jsonb,1,'Only student_id 2 appears in both sets, so the intersection is exactly {2}.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
