insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-intersection-identities',null::text,'Find distinct identities on both distinction lists','Easy','intersection-identities','Use plain INTERSECT to return each student_id present in both honors_students and deans_list exactly once. Input occurrences may repeat.

**MySQL dialect.**

```sql
CREATE TABLE honors_students (student_id INT NOT NULL);
CREATE TABLE deans_list (student_id INT NOT NULL);
INSERT INTO honors_students VALUES (1),(2),(2),(5); INSERT INTO deans_list VALUES (2),(2),(3);
```

**Required ordering:** Ascending student_id.

**Edge cases:**
- Duplicates on both sides must not multiply distinct output.
- One empty input yields an empty result.','[{"input": "INSERT INTO honors_students VALUES (1),(2),(2),(5); INSERT INTO deans_list VALUES (2),(2),(3);", "output": "student_id\n2", "explanation": "The operator returns common selected identities rather than matching source-occurrence combinations. Output fixtures alone do not prove arbitrary code used the requested syntax."}]'::jsonb,'[{"seed_sql": "INSERT INTO honors_students VALUES (9),(2); INSERT INTO deans_list VALUES (9),(2),(9);", "expected": "student_id\n2\n9", "hidden": true}, {"seed_sql": "INSERT INTO honors_students VALUES (1);", "expected": "", "hidden": true}]'::jsonb,'["Student identities are nonmissing integers.", "The syntax targets MySQL 8.4; local execution is recorded as MariaDB compatibility evidence."]'::jsonb,'["Use the native distinct set operator.", "Order the combined result explicitly."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The operator returns common selected identities rather than matching source-occurrence combinations. Output fixtures alone do not prove arbitrary code used the requested syntax.','{"sql": "SELECT student_id FROM honors_students INTERSECT SELECT student_id FROM deans_list ORDER BY student_id;"}'::jsonb,'The operator returns common selected identities rather than matching source-occurrence combinations. Output fixtures alone do not prove arbitrary code used the requested syntax.',array['sql'],'CREATE TABLE honors_students (student_id INT NOT NULL);
CREATE TABLE deans_list (student_id INT NOT NULL);','INSERT INTO honors_students VALUES (1),(2),(2),(5); INSERT INTO deans_list VALUES (2),(2),(3);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-7-intersection' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-intersection-pairs' or slug='intersection-pairs') and (id<>'cx-intersection-pairs' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-intersection-pairs'; end if;
if exists(select 1 from public.dsa_problems where id='cx-intersection-pairs' and description is distinct from 'Return each distinct student_id and course_id pair present in both required_pairs and completed_pairs. Compare both components and collapse repeated source occurrences.

**MySQL dialect.**

```sql
CREATE TABLE required_pairs (student_id INT NOT NULL, course_id INT NOT NULL);
CREATE TABLE completed_pairs (student_id INT NOT NULL, course_id INT NOT NULL);
INSERT INTO required_pairs VALUES (1,10),(1,20),(2,10),(2,10); INSERT INTO completed_pairs VALUES (1,10),(2,10),(2,10),(2,30);
```

**Required ordering:** Ascending student_id, course_id.

**Edge cases:**
- A student can have another nonmatching course.
- Duplicates on both sides must not multiply the pair report.') then raise exception 'New coding ID already has other content: %', 'cx-intersection-pairs'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-intersection-pairs',null::text,'Match complete student-course tuples without join fan-out','Medium','intersection-pairs','Return each distinct student_id and course_id pair present in both required_pairs and completed_pairs. Compare both components and collapse repeated source occurrences.

**MySQL dialect.**

```sql
CREATE TABLE required_pairs (student_id INT NOT NULL, course_id INT NOT NULL);
CREATE TABLE completed_pairs (student_id INT NOT NULL, course_id INT NOT NULL);
INSERT INTO required_pairs VALUES (1,10),(1,20),(2,10),(2,10); INSERT INTO completed_pairs VALUES (1,10),(2,10),(2,10),(2,30);
```

**Required ordering:** Ascending student_id, course_id.

**Edge cases:**
- A student can have another nonmatching course.
- Duplicates on both sides must not multiply the pair report.','[{"input": "INSERT INTO required_pairs VALUES (1,10),(1,20),(2,10),(2,10); INSERT INTO completed_pairs VALUES (1,10),(2,10),(2,10),(2,30);", "output": "student_id\tcourse_id\n1\t10\n2\t10", "explanation": "The full comparison and DISTINCT preserve the intended set intersection rather than a student-only match or bag of join combinations."}]'::jsonb,'[{"seed_sql": "INSERT INTO required_pairs VALUES (1,20); INSERT INTO completed_pairs VALUES (1,10);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO required_pairs VALUES (1,10),(1,10); INSERT INTO completed_pairs VALUES (1,10),(1,10);", "expected": "student_id\tcourse_id\n1\t10", "hidden": true}]'::jsonb,'["All selected components are nonmissing; nullable equivalence is outside this fixture contract."]'::jsonb,'["Use the full participant pair in the matching condition.", "Project distinct pairs if using a join translation."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The full comparison and DISTINCT preserve the intended set intersection rather than a student-only match or bag of join combinations.','{"sql": "SELECT DISTINCT r.student_id, r.course_id FROM required_pairs r JOIN completed_pairs c ON c.student_id = r.student_id AND c.course_id = r.course_id ORDER BY r.student_id, r.course_id;"}'::jsonb,'The full comparison and DISTINCT preserve the intended set intersection rather than a student-only match or bag of join combinations.',array['sql'],'CREATE TABLE required_pairs (student_id INT NOT NULL, course_id INT NOT NULL);
CREATE TABLE completed_pairs (student_id INT NOT NULL, course_id INT NOT NULL);','INSERT INTO required_pairs VALUES (1,10),(1,20),(2,10),(2,10); INSERT INTO completed_pairs VALUES (1,10),(2,10),(2,10),(2,30);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-7-intersection' on conflict(id) do nothing;
