update public.learning_topics set short_description='Define exact-key access, value ownership, expiration, conditional updates, and partitioning trade-offs without assuming every key-value product has opaque strings or identical consistency guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Define exact-key access, value ownership, expiration, conditional updates, and partitioning trade-offs without assuming every key-value product has opaque strings or identical consistency guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Key Value Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-key-value-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-key-value-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Key Value Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-key-value-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-1','pt-dbms-sql-3-key-value-model','What defines the simplest opaque key-value abstraction?','["Data is stored as tables with rows and columns", "A unique key maps to a value interpreted by the caller, while real products can add richer operations", "Data is organized as nodes and edges", "Data is stored as nested JSON documents that are queryable by field"]'::jsonb,1,'Do not treat the simplified abstraction as every product''s complete feature set.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-2','pt-dbms-sql-3-key-value-model','Which of these operations is fundamental to a pure key-value store?','["JOIN two keys together", "GET(key), PUT(key, value), DELETE(key)", "SELECT * WHERE value.field = x", "CREATE TABLE"]'::jsonb,1,'Key-value stores expose a minimal API: get, put, and delete operations addressed by key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-3','pt-dbms-sql-3-key-value-model','Which of these is a widely used key-value database?','["Redis", "Neo4j", "PostgreSQL", "Cassandra"]'::jsonb,0,'Redis is a classic key-value store commonly used for caching and session storage.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-4','pt-dbms-sql-3-key-value-model','Why can exact-key access be efficient without guaranteeing fixed latency?','["They pre-compute all possible queries in advance", "It can use suitable indexed or partitioned access, while network, storage, size, and coordination costs remain", "They store all data in memory only", "They use a graph traversal algorithm"]'::jsonb,1,'The abstraction is not an end-to-end performance guarantee.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-5','pt-dbms-sql-3-key-value-model','What is the biggest limitation of a pure key-value store compared to a document database?','["It cannot store any binary data", "It cannot query or index fields inside the value; only the exact key can be used to retrieve data", "It requires a fixed schema for every key", "It cannot scale horizontally"]'::jsonb,1,'A document database can query nested fields inside a value, while a pure key-value store can only fetch the entire value by its key.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-6','pt-dbms-sql-3-key-value-model','A JSON document is stored through a basic opaque string interface. Who interprets that representation?','["Redis parses and validates it automatically", "The caller, unless it uses a separate supported structured-value interface", "The operating system", "The key itself encodes the schema"]'::jsonb,1,'Redis and other products can offer richer types; specify the actual interface used.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-7','pt-dbms-sql-3-key-value-model','Why do keys help distribution while not removing every scaling difficulty?','["Because they enforce strict cross-key relationships that simplify sharding", "They provide partitioning inputs, but hot keys, replication, and cross-key requirements still matter", "Because they only support a single server", "Because they require all data to fit on one machine"]'::jsonb,1,'Do not claim every product uses one hashing scheme or lacks business relationships.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-key-value-model-8','pt-dbms-sql-3-key-value-model','How does a structured wide-column interface differ from the simplest opaque-value interface?','["They are identical opaque blobs in both models", "It exposes its supported named column and keyed access structure rather than only an uninterpreted value", "A key-value store''s value can be queried by nested field but a column-family store''s cannot", "Column-family stores do not use keys at all"]'::jsonb,1,'Actual product schemas and query limits still need review.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-new-9','pt-dbms-sql-3-key-value-model','Does a predictable key prefix enforce record ownership?','["Yes; prefixes are always secret", "No; trusted authorization still needs enforcement", "Only if keys contain colons", "Only if values are strings"]'::jsonb,1,'Namespacing organizes identity but does not grant authority.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-new-10','pt-dbms-sql-3-key-value-model','What distinguishes a missing key from an empty stored value?','["Nothing; every empty string means missing", "Only the key length", "Absence of an association versus a present value", "Only the network port"]'::jsonb,2,'The result contract should preserve not-found and recorded-empty states.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-1','pt-dbms-sql-3-key-value-model-application','An entry expires exactly at the fixture observation time and the rule requires expires_at > that time. Is it visible?','["Yes; equality always extends expiry", "Only if its version is three", "No", "Only if its key is short"]'::jsonb,2,'The stated expiry boundary is exclusive.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-2','pt-dbms-sql-3-key-value-model-application','The fixture uses NULL expires_at for no time-based expiry. What should a lookup retain?','["Only expired entries", "No NULL-expiry entry", "Only entries with zero version", "That entry if the key matches"]'::jsonb,3,'The absence policy is explicitly defined by the fixture.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-3','pt-dbms-sql-3-key-value-model-application','A caller expects version 3 but current version is 4. What should the conditional update do?','["Leave the current entry unchanged", "Overwrite it unconditionally", "Reset version to one", "Delete unrelated keys"]'::jsonb,0,'The version predicate protects against that stale write.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-4','pt-dbms-sql-3-key-value-model-application','A popular key dominates requests. What can remain despite good distribution of other keys?','["Guaranteed infinite capacity", "A hot-key bottleneck", "No network traffic", "Automatic business consistency"]'::jsonb,1,'One concentrated access pattern can limit the workload.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-5','pt-dbms-sql-3-key-value-model-application','A title cache returns old data after the authoritative source changed. What needs definition?','["Only key capitalization", "Only the number of indexes elsewhere", "Freshness and invalidation policy", "Only whether a GET was fast"]'::jsonb,2,'A cache''s speed does not establish current authoritative meaning.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-6','pt-dbms-sql-3-key-value-model-application','One key update succeeds and a related second write fails. What is not guaranteed by the basic model?','["That keys identify values", "That a first operation may have completed", "That recovery needs a policy", "Atomic consistency across both keys"]'::jsonb,3,'Cross-key workflow guarantees are product-specific.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-7','pt-dbms-sql-3-key-value-model-application','A TTL is assigned to sensitive data. What does it not prove?','["Immediate permanent erasure from every replica, backup, and log", "A configured live-entry expiry policy exists", "Time matters to lookup behavior", "The key has a value"]'::jsonb,0,'Expiry and full retention/deletion guarantees are different scopes.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-8','pt-dbms-sql-3-key-value-model-application','A product exposes hashes or indexed document attributes. Must it behave like the pure opaque-string model in every operation?','["Yes; category labels override features", "No; inspect the actual supported interface", "Only if the key is numeric", "Only if the value is large"]'::jsonb,1,'Real product capabilities overlap model categories.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-key-value-model-application-new-9','pt-dbms-sql-3-key-value-model-application','A SQL mirror conditionally updates one version successfully. What remains unverified?','["The observed fixture transition", "The predicate used in the test", "Native key-value multi-client and failure behavior", "That SQL ran on the recorded engine"]'::jsonb,2,'A representation test is not native engine verification.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
