update public.learning_topics set short_description='Connect superkeys, candidate keys, primary and alternate identities, and foreign references to precise uniqueness rules and SQL verification.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Connect superkeys, candidate keys, primary and alternate identities, and foreign references to precise uniqueness rules and SQL verification.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Keys in the Relational Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-4-keys-in-the-relational-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-4-keys-in-the-relational-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Keys in the Relational Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-4-keys-in-the-relational-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-1','pt-dbms-sql-4-keys-in-the-relational-model','In precise candidate-key terminology, what is a key in a relation?','["Any attribute with a numeric domain", "An attribute or minimal set of attributes whose values uniquely identify each tuple in a relation", "The first column defined in a CREATE TABLE statement", "A synonym for attribute"]'::jsonb,1,'A key is defined by its ability to uniquely identify tuples, using a minimal set of attributes.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-2','pt-dbms-sql-4-keys-in-the-relational-model','Under a schema rule guaranteeing id is unique and nonmissing in every allowed Students state, what is {id}?','["A foreign key", "A candidate key", "A composite key only", "Not a key at all"]'::jsonb,1,'{id} uniquely identifies every tuple and is minimal (no attribute can be removed), making it a candidate key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-3','pt-dbms-sql-4-keys-in-the-relational-model','What distinguishes a Super Key from a Candidate Key?','["A super key must contain exactly one attribute; a candidate key can contain many", "A super key is any uniquely-identifying set of attributes (possibly with extras); a candidate key is a MINIMAL such set", "They are the same thing", "A candidate key can allow duplicate values; a super key cannot"]'::jsonb,1,'Every candidate key is a super key, but a candidate key additionally must be minimal — no attribute can be dropped without losing uniqueness.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-4','pt-dbms-sql-4-keys-in-the-relational-model','If both {email} and {id} are guaranteed nonmissing candidate keys and {id} is chosen as primary, what is {email}?','["A foreign key", "An alternate key", "A composite key", "It is no longer a valid key"]'::jsonb,1,'A candidate key not selected as the primary key is called an alternate key.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-5','pt-dbms-sql-4-keys-in-the-relational-model','If the enrollment pair is guaranteed unique and neither component alone is guaranteed unique, what is {student_id, course_id}?','["A candidate key that happens to be a composite key", "A foreign key only, not a key at all", "A domain constraint", "An attribute"]'::jsonb,0,'Since the combination is minimal and uniquely identifies each enrollment tuple, it is a candidate key that is composite (made of more than one attribute).',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-6','pt-dbms-sql-4-keys-in-the-relational-model','How do Keys differ conceptually from Relational Integrity rules?','["They are identical concepts", "Keys describe identifying and referencing roles; integrity constraints enforce relevant validity rules, including key uniqueness and references", "Integrity rules define which attributes are keys", "Keys only matter for foreign key relationships, never for primary keys"]'::jsonb,1,'Key roles and integrity requirements are connected rather than disjoint; key constraints are themselves integrity rules.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-7','pt-dbms-sql-4-keys-in-the-relational-model','Can a foreign key attribute contain NULL even though the primary key it references cannot?','["No, foreign keys follow the exact same NULL restriction as primary keys", "Yes — an optional foreign key like advisor_id can be NULL, since referential integrity and entity integrity are different rules with different NULL requirements", "No, this would always violate referential integrity", "Yes, but only if the foreign key is also composite"]'::jsonb,1,'Entity integrity forbids NULL primary keys, but referential integrity typically permits a NULL foreign key (meaning ''no reference''), unless declared NOT NULL.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-keys-in-the-relational-model-8','pt-dbms-sql-4-keys-in-the-relational-model','Is {id, name} a candidate key for Students, given that {id} alone already uniquely identifies each tuple?','["Yes, because it also uniquely identifies tuples", "No — it is a super key but not a candidate key, since it is not minimal ({id} alone already suffices)", "No, it isn''t even a super key", "Yes, and it is the only candidate key possible"]'::jsonb,1,'{id, name} does identify tuples uniquely, but since {id} alone is sufficient, adding ''name'' violates minimality, so {id, name} is a super key, not a candidate key.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-keys-in-the-relational-model-new-9','pt-dbms-sql-4-keys-in-the-relational-model','Three sample students have unique names. Does that prove student_name is a candidate key?','["Yes; any sample proves every future state", "No; the allowed-state guarantee must come from the model", "Only if sorted", "Only if all names are short"]'::jsonb,1,'Accidental uniqueness in one state does not establish a key constraint.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-keys-in-the-relational-model-new-10','pt-dbms-sql-4-keys-in-the-relational-model','Why is {student_id, student_name} nonminimal when {student_id} is already a key?','["The identifier can always be removed", "Two-column sets never identify", "The name can be removed without losing identification", "Names cannot be attributes"]'::jsonb,2,'Minimality removes redundant identifying attributes.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-keys-in-the-relational-model-application-new-1','pt-dbms-sql-4-keys-in-the-relational-model-application','Does adding a surrogate primary identifier enforce uniqueness of institutional_number automatically?','["Yes; every generated id validates all labels", "Only if the name matches", "No; the institutional rule still needs its own constraint", "Only for empty relations"]'::jsonb,2,'Internal identity and business uniqueness are separate obligations.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-keys-in-the-relational-model-application-new-2','pt-dbms-sql-4-keys-in-the-relational-model-application','Must each component of a composite enrollment key be independently unique?','["Yes; both must be individual keys", "Only course_id must be", "Only student_id must be", "No; uniqueness applies to the combination"]'::jsonb,3,'Repeating one component can be a valid different relationship fact.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-keys-in-the-relational-model-application-new-3','pt-dbms-sql-4-keys-in-the-relational-model-application','What does a foreign student reference in Enrollment need not do?','["Uniquely identify the enrollment row", "Refer to the defined parent key", "Follow its nullability policy", "Use compatible reference attributes"]'::jsonb,0,'One student can be referenced by many enrollment facts.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
