insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-literals-2','pt-dbms-sql-8-literals','How do you correctly represent an apostrophe inside a single-quoted string literal, e.g. for the name O''Brien?','["''O\\\\''Brien''", "''O''Brien''", "''O''''Brien'' (doubling the apostrophe)", "It cannot be done — apostrophes are forbidden in string literals"]'::jsonb,2,'Standard SQL escapes an embedded single quote by doubling it: ''O''''Brien''.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-literals-3','pt-dbms-sql-8-literals','In standard SQL and PostgreSQL, what does `"students"` (double-quoted) refer to?','["The string value ''students''", "An identifier literally named students (e.g. a table or column)", "A syntax error in every dialect", "A comment"]'::jsonb,1,'Double quotes delimit identifiers in standard SQL/PostgreSQL — this is a common trap for people used to MySQL''s default double-quoted strings.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
