insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-literals-5','pt-dbms-sql-8-literals','Which of these is TRUE about boolean literals across dialects?','["Every SQL dialect has an identical native boolean type and TRUE/FALSE literal", "PostgreSQL and MySQL support TRUE/FALSE, but SQL Server has no true boolean type and commonly uses 1/0 instead", "Boolean literals do not exist in any SQL dialect", "TRUE and FALSE are reserved words that cannot appear in any query"]'::jsonb,1,'MySQL recognizes TRUE/FALSE as 1/0; PostgreSQL has a native boolean type, while SQL Server commonly uses bit. Storage and expressions are dialect-specific.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-literals-6','pt-dbms-sql-8-literals','Why is MySQL''s default acceptance of double-quoted strings ("Asha") considered a dialect quirk rather than standard behavior?','["Because it isn''t actually supported by MySQL at all", "Because in the SQL standard and other engines like PostgreSQL, double quotes mean an identifier, not a string, so the same syntax means different things elsewhere", "Because double quotes are illegal characters in SQL entirely", "Because MySQL requires triple quotes for strings"]'::jsonb,1,'MySQL can accept double-quoted strings unless ANSI_QUOTES makes double quotes delimit identifiers; single quotes are the clear string form.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
