update public.learning_topics set short_description='Reason about matched and unmatched source identities, distinguish native MERGE from a narrow MySQL upsert, and avoid treating one statement as a universal synchronization or concurrency guarantee.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Reason about matched and unmatched source identities, distinguish native MERGE from a narrow MySQL upsert, and avoid treating one statement as a universal synchronization or concurrency guarantee.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for MERGE Concept.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-11-merge-concept' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-11-merge-concept-application','MCQ Test 2',category,10,10,'Application and scenarios for MERGE Concept.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-11-merge-concept' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-1','pt-dbms-sql-11-merge-concept','What does the MERGE statement combine into one operation?','["Only SELECT and INSERT", "INSERT (for new rows) and UPDATE (for existing rows), based on a matching condition, sometimes DELETE too", "Only CREATE and DROP", "Only two SELECT queries"]'::jsonb,1,'MERGE''s defining feature is combining insert-if-absent and update-if-present logic in one statement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-2','pt-dbms-sql-11-merge-concept','What real-world problem does MERGE solve well?','["Sorting a table''s rows", "Syncing a target table with a batch of incoming data, without knowing in advance which rows are new versus already existing", "Renaming a table''s columns", "Compressing a table''s storage"]'::jsonb,1,'MERGE is designed exactly for this ''sync with unknown new-vs-existing'' scenario.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-3','pt-dbms-sql-11-merge-concept','How is MySQL 8.4 related to native standard-style MERGE?','["Yes, identically to SQL Server and Oracle", "It lacks that native statement; INSERT ON DUPLICATE KEY UPDATE supports a narrower related upsert pattern", "MySQL has no way to achieve upsert behavior at all", "MySQL requires a stored procedure for any upsert logic"]'::jsonb,1,'The alternative is not equivalent to every MERGE action and match clause.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-4','pt-dbms-sql-11-merge-concept','What can an applicable WHEN NOT MATCHED BY SOURCE clause support?','["Nothing — this clause doesn''t exist", "Actions on target rows without source matches, such as explicitly authorized deletion in a supporting dialect", "Insert duplicate rows intentionally", "Skip all update logic entirely"]'::jsonb,1,'A partial source must not be treated as a complete authoritative snapshot automatically.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-5','pt-dbms-sql-11-merge-concept','Does using one MERGE statement universally eliminate concurrency races and conflicts?','["There is no real difference between the two approaches", "No; actual matching, isolation, locking and product rules still need verification", "Manual two-statement approaches are always faster", "MERGE cannot be used with WHERE conditions at all"]'::jsonb,1,'A combined command is not a blanket concurrency guarantee.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-6','pt-dbms-sql-11-merge-concept','In the standard MERGE syntax, what does the ON clause specify?','["The final sort order of the result", "The condition used to match source rows against target rows (e.g. matching ids)", "A CHECK constraint to validate", "The name of the resulting merged table"]'::jsonb,1,'ON defines how source rows are matched to target rows, determining which branch (MATCHED/NOT MATCHED) applies.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-7','pt-dbms-sql-11-merge-concept','Which products provide native MERGE features relevant to this comparison?','["Only MySQL", "SQL Server, Oracle and PostgreSQL 15+, with exact clauses depending on product and version", "No real database supports MERGE", "Only SQLite"]'::jsonb,1,'Do not assume identical feature sets across all native implementations.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-11-merge-concept-8','pt-dbms-sql-11-merge-concept','Is ''upsert'' a different concept from what MERGE achieves, or another name for a closely related idea?','["Completely different, unrelated concepts", "Upsert is essentially the insert-or-update half of what MERGE can do, often used as informal/dialect-specific terminology for that pattern", "Upsert only refers to deleting rows", "Upsert is a synonym for TRUNCATE"]'::jsonb,1,'Upsert (covered further in 11.7) refers to the same insert-or-update idea, often via dialect-specific syntax rather than full MERGE.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
