if exists(select 1 from public.dsa_problems where (id='cx-merge-classify-input' or slug='merge-classify-input') and (id<>'cx-merge-classify-input' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-merge-classify-input'; end if;
if exists(select 1 from public.dsa_problems where id='cx-merge-classify-input' and description is distinct from 'For each incoming item_id, report action=update when target_items already has that identity and action=insert otherwise. Do not write any rows. Target rows absent from the incoming batch are outside this report, not candidates for deletion.

**MySQL dialect.**

```sql
CREATE TABLE target_items (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL); CREATE TABLE incoming (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL);
INSERT INTO target_items VALUES (1,''Old''),(2,''Keep''); INSERT INTO incoming VALUES (1,''New''),(3,''Add'');
```

**Required ordering:** Ascending incoming item_id.

**Edge cases:**
- An empty target classifies every supplied input as insert.
- Empty incoming input produces no action row.') then raise exception 'New coding ID already has other content: %', 'cx-merge-classify-input'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-merge-classify-input',null::text,'Classify incoming identities before a proposed synchronization','Easy','merge-classify-input','For each incoming item_id, report action=update when target_items already has that identity and action=insert otherwise. Do not write any rows. Target rows absent from the incoming batch are outside this report, not candidates for deletion.

**MySQL dialect.**

```sql
CREATE TABLE target_items (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL); CREATE TABLE incoming (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL);
INSERT INTO target_items VALUES (1,''Old''),(2,''Keep''); INSERT INTO incoming VALUES (1,''New''),(3,''Add'');
```

**Required ordering:** Ascending incoming item_id.

**Edge cases:**
- An empty target classifies every supplied input as insert.
- Empty incoming input produces no action row.','[{"input": "INSERT INTO target_items VALUES (1,''Old''),(2,''Keep''); INSERT INTO incoming VALUES (1,''New''),(3,''Add'');", "output": "item_id\taction\n1\tupdate\n3\tinsert", "explanation": "The diagnostic makes source membership and identity-based branch choice visible without applying a native MERGE."}]'::jsonb,'[{"seed_sql": "INSERT INTO incoming VALUES (8,''Only'');", "expected": "item_id\taction\n8\tinsert", "hidden": true}, {"seed_sql": "INSERT INTO target_items VALUES (7,''Keep'');", "expected": "", "hidden": true}]'::jsonb,'["Each incoming identity appears once.", "Classification only, no accepted-state mutation."]'::jsonb,'["Match identity with a preserving join.", "Use the target\u2019s non-NULL primary key as the match marker."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The diagnostic makes source membership and identity-based branch choice visible without applying a native MERGE.','{"sql": "SELECT s.item_id,CASE WHEN t.item_id IS NULL THEN ''insert'' ELSE ''update'' END AS action FROM incoming s LEFT JOIN target_items t ON t.item_id=s.item_id ORDER BY s.item_id;"}'::jsonb,'The diagnostic makes source membership and identity-based branch choice visible without applying a native MERGE.',array['sql'],'CREATE TABLE target_items (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL); CREATE TABLE incoming (item_id INT PRIMARY KEY,label VARCHAR(40) NOT NULL);','INSERT INTO target_items VALUES (1,''Old''),(2,''Keep''); INSERT INTO incoming VALUES (1,''New''),(3,''Add'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-11-merge-concept' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-merge-mysql-upsert' or slug='merge-mysql-upsert') and (id<>'cx-merge-mysql-upsert' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-merge-mysql-upsert'; end if;
if exists(select 1 from public.dsa_problems where id='cx-merge-mysql-upsert' and description is distinct from 'Use MySQL INSERT ON DUPLICATE KEY UPDATE to copy incoming item_id,quantity into inventory. A primary-key match replaces quantity exactly; a new identity is inserted. Preserve inventory identities absent from incoming. This is a narrow upsert, not native MERGE or full synchronization. Return item_id,quantity.

**MySQL dialect.**

```sql
SET SESSION sql_mode=''STRICT_ALL_TABLES''; CREATE TABLE inventory (item_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB; CREATE TABLE incoming (item_id INT PRIMARY KEY,quantity INT NOT NULL);
INSERT INTO inventory VALUES (1,10),(2,8); INSERT INTO incoming VALUES (1,7),(3,4);
```

**Required ordering:** Ascending item_id.

**Edge cases:**
- Unrelated item 2 remains.
- Empty incoming leaves all targets unchanged.
- Empty inventory takes insertion paths.') then raise exception 'New coding ID already has other content: %', 'cx-merge-mysql-upsert'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-merge-mysql-upsert',null::text,'Apply a narrow MySQL insert-or-replace-quantity policy','Medium','merge-mysql-upsert','Use MySQL INSERT ON DUPLICATE KEY UPDATE to copy incoming item_id,quantity into inventory. A primary-key match replaces quantity exactly; a new identity is inserted. Preserve inventory identities absent from incoming. This is a narrow upsert, not native MERGE or full synchronization. Return item_id,quantity.

**MySQL dialect.**

```sql
SET SESSION sql_mode=''STRICT_ALL_TABLES''; CREATE TABLE inventory (item_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB; CREATE TABLE incoming (item_id INT PRIMARY KEY,quantity INT NOT NULL);
INSERT INTO inventory VALUES (1,10),(2,8); INSERT INTO incoming VALUES (1,7),(3,4);
```

**Required ordering:** Ascending item_id.

**Edge cases:**
- Unrelated item 2 remains.
- Empty incoming leaves all targets unchanged.
- Empty inventory takes insertion paths.','[{"input": "INSERT INTO inventory VALUES (1,10),(2,8); INSERT INTO incoming VALUES (1,7),(3,4);", "output": "item_id\tquantity\n1\t7\n2\t8\n3\t4", "explanation": "Protected identity selects the supported MySQL update branch while the source quantity supplies the explicit replacement value."}]'::jsonb,'[{"seed_sql": "INSERT INTO inventory VALUES (7,5);", "expected": "item_id\tquantity\n7\t5", "hidden": true}, {"seed_sql": "INSERT INTO incoming VALUES (8,0);", "expected": "item_id\tquantity\n8\t0", "hidden": true}]'::jsonb,'["One source row per identity and only one protected key in this fixture.", "Positive incoming quantities are nonnegative."]'::jsonb,'["Map source roles explicitly.", "Use the selected source quantity for replacement, not addition."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'Protected identity selects the supported MySQL update branch while the source quantity supplies the explicit replacement value.','{"sql": "INSERT INTO inventory (item_id,quantity) SELECT s.item_id,s.quantity FROM incoming s ON DUPLICATE KEY UPDATE quantity=s.quantity; SELECT item_id,quantity FROM inventory ORDER BY item_id;"}'::jsonb,'Protected identity selects the supported MySQL update branch while the source quantity supplies the explicit replacement value.',array['sql'],'SET SESSION sql_mode=''STRICT_ALL_TABLES''; CREATE TABLE inventory (item_id INT PRIMARY KEY,quantity INT NOT NULL CHECK(quantity>=0)) ENGINE=InnoDB; CREATE TABLE incoming (item_id INT PRIMARY KEY,quantity INT NOT NULL);','INSERT INTO inventory VALUES (1,10),(2,8); INSERT INTO incoming VALUES (1,7),(3,4);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-11-merge-concept' on conflict(id) do nothing;
