update public.learning_topics set short_description='Name integrity rules for readable errors and maintenance, inspect engine-specific scope and removal syntax, and avoid confusing a label change with a change in accepted data.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Name integrity rules for readable errors and maintenance, inspect engine-specific scope and removal syntax, and avoid confusing a label change with a change in accepted data.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Named Constraints.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-10-named-constraints' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-10-named-constraints-application','MCQ Test 2',category,10,10,'Application and scenarios for Named Constraints.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-10-named-constraints' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-1','pt-dbms-sql-10-named-constraints','Which prefix names an applicable constraint in the illustrated declaration form?','["NAME <name> ON <constraint-definition>", "CONSTRAINT name followed by the supported rule definition", "<constraint-definition> AS <name>", "ALIAS <name> <constraint-definition>"]'::jsonb,1,'The allowed combination depends on rule kind and product grammar.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-2','pt-dbms-sql-10-named-constraints','Why inspect an unnamed rule before maintenance?','["The constraint is not enforced until named", "Its actual generated representation and engine-specific removal form must be known", "Unnamed constraints run slower at query time", "Unnamed constraints cannot be combined with NOT NULL"]'::jsonb,1,'Not every kind uses an arbitrary generated removal name, such as MySQL PRIMARY.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-3','pt-dbms-sql-10-named-constraints','Why can auto-generated constraint names cause problems specifically in migration scripts across dev/staging/prod environments?','["Migration scripts cannot run against auto-generated names at all", "The generated name can differ between environments if tables were created via slightly different paths, breaking scripts that hardcode one specific name", "Auto-generated names are always identical across environments, so this is not actually a risk", "Migration tools automatically rename constraints on deploy"]'::jsonb,1,'Because the generation algorithm can be sensitive to creation order or path, hardcoding a guessed or observed auto-generated name in a script is fragile across environments; explicit naming avoids this entirely.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-4','pt-dbms-sql-10-named-constraints','Is custom NOT NULL naming universally forbidden across current SQL products?','["CHECK", "UNIQUE", "No; supported forms depend on the engine and version", "FOREIGN KEY"]'::jsonb,2,'PostgreSQL 18 documents not-null constraint forms that invalidate the blanket claim.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-5','pt-dbms-sql-10-named-constraints','Which of these follows a common, readable naming convention for a foreign key from orders to customers?','["fk_orders_customer", "constraint1", "orders_fk_1", "customer_orders_key"]'::jsonb,0,'A widely used convention is fk_<table>_<referenced_table>, making the relationship self-documenting at a glance.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-6','pt-dbms-sql-10-named-constraints','In PostgreSQL, what is generally required to discover the auto-generated name of an unnamed constraint before dropping it?','["Querying a system catalog like pg_constraint", "Restarting the database server", "Recreating the table", "There is no way to discover it; the table must be dropped and recreated"]'::jsonb,0,'PostgreSQL exposes constraint metadata via catalogs such as pg_constraint (or information_schema.table_constraints), which is how you find a generated name to use in DROP CONSTRAINT.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-named-constraints-7','pt-dbms-sql-10-named-constraints','How should a MySQL constraint-label change be planned?','["It supports renaming natively with no workaround needed", "Identify its kind and supported maintenance path, including index rename where applicable", "MySQL constraints cannot be renamed or changed at all", "Renaming automatically happens on the next ALTER TABLE"]'::jsonb,1,'Not every rule universally requires the same drop-and-add sequence.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
