if exists(select 1 from public.dsa_problems where id='cx-named-score-range' and description is distinct from 'Create TEMPORARY scores with score_id INT PRIMARY KEY,score INT NOT NULL and CONSTRAINT chk_score_range CHECK(score BETWEEN 0 AND 100). Copy compatible score_input and return score_id,score. The name must describe the actual inclusive range.

**MySQL dialect.**

```sql
CREATE TABLE score_input (score_id INT PRIMARY KEY,score INT NOT NULL);
INSERT INTO score_input VALUES (1,0),(2,100),(3,55);
```

**Required ordering:** Ascending score_id.

**Edge cases:**
- Both endpoints are valid.
- Outside-range values are rejected.') then raise exception 'New coding ID already has other content: %', 'cx-named-score-range'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-named-score-range',null::text,'Give an explicit name to a score-range rule','Easy','named-score-range','Create TEMPORARY scores with score_id INT PRIMARY KEY,score INT NOT NULL and CONSTRAINT chk_score_range CHECK(score BETWEEN 0 AND 100). Copy compatible score_input and return score_id,score. The name must describe the actual inclusive range.

**MySQL dialect.**

```sql
CREATE TABLE score_input (score_id INT PRIMARY KEY,score INT NOT NULL);
INSERT INTO score_input VALUES (1,0),(2,100),(3,55);
```

**Required ordering:** Ascending score_id.

**Edge cases:**
- Both endpoints are valid.
- Outside-range values are rejected.','[{"input": "INSERT INTO score_input VALUES (1,0),(2,100),(3,55);", "output": "score_id\tscore\n1\t0\n2\t100\n3\t55", "explanation": "The authored rule has a stable descriptive label while the predicate enforces the requested inclusive domain."}]'::jsonb,'[{"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO score_input VALUES (8,100);", "expected": "score_id\tscore\n8\t100", "hidden": true}]'::jsonb,'["Explicit check name and inclusive boundaries.", "Missing score is a separate NOT NULL rule."]'::jsonb,'["Use CONSTRAINT name before CHECK.", "Keep the actual predicate aligned with the label."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The authored rule has a stable descriptive label while the predicate enforces the requested inclusive domain.','{"sql": "CREATE TEMPORARY TABLE scores (score_id INT PRIMARY KEY,score INT NOT NULL,CONSTRAINT chk_score_range CHECK(score BETWEEN 0 AND 100)); INSERT INTO scores SELECT score_id,score FROM score_input; SELECT score_id,score FROM scores ORDER BY score_id;"}'::jsonb,'The authored rule has a stable descriptive label while the predicate enforces the requested inclusive domain.',array['sql'],'CREATE TABLE score_input (score_id INT PRIMARY KEY,score INT NOT NULL);','INSERT INTO score_input VALUES (1,0),(2,100),(3,55);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-10-named-constraints' on conflict(id) do nothing;
