insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-natural-join-1','pt-dbms-sql-7-natural-join','How does Natural Join decide which columns to match on?','["You must specify the columns explicitly in an ON clause", "It automatically matches on ALL identically-named columns shared by the two relations", "It always matches on the first column of each table", "It matches on primary keys only, regardless of name"]'::jsonb,1,'Natural Join''s defining feature is automatic matching based purely on shared column names.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-natural-join-2','pt-dbms-sql-7-natural-join','In the illustrated ordinary natural inner join, how many combined output columns represent each common matching attribute?','["Two — one from each table, just like an Equi Join", "Only one — Natural Join removes the duplicate matched column that an Equi Join would otherwise leave", "Zero — the matched column is dropped entirely", "It varies randomly"]'::jsonb,1,'Common matching columns are merged in the output shape; this does not remove repeated result-row occurrences.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-natural-join-3','pt-dbms-sql-7-natural-join','What is the biggest real-world danger of using NATURAL JOIN?','["It is always slower than an explicit JOIN", "It automatically matches on EVERY identically-named column, including unintended ones, which can silently produce a wrong result if the tables happen to share an unrelated column name", "It cannot be used with more than two tables", "NATURAL JOIN does not exist in standard SQL"]'::jsonb,1,'An unexpected shared column name silently becomes part of the match condition, which is the classic pitfall of NATURAL JOIN.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
