insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-1','pt-dbms-sql-5-natural-key','What is a natural key?','["A key value chosen by a random number generator", "A candidate key based on domain-meaningful attributes, possibly a combination", "A key that is always numeric", "A key with no formal database definition"]'::jsonb,1,'Natural keys derive from meaningful real-world attributes, like an ISBN or national ID.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-2','pt-dbms-sql-5-natural-key','Which is a plausible natural identifier for a publication edition when the issuing policy guarantees the relevant identity?','["An auto-incrementing integer id with no external meaning", "The edition’s applicable ISBN, rather than a physical library-copy identity", "A randomly generated UUID", "A row''s internal storage address"]'::jsonb,1,'The represented object matters: several physical copies can share the publication identifier.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-3','pt-dbms-sql-5-natural-key','What is a genuine operational risk of using a natural key as a primary key?','["Natural keys are always slower to compare than any other data type", "The real-world value might need to change later (e.g. a corrected ID), which is painful once other tables have foreign keys pointing at it", "Natural keys cannot be indexed", "SQL does not allow natural keys as PRIMARY KEY"]'::jsonb,1,'Unlike a surrogate key with no business meaning, a natural key''s value can legitimately need correction or reissue, creating downstream update problems.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-4','pt-dbms-sql-5-natural-key','Why might an assumed natural key turn out to not actually be unique in practice?','["This never happens with natural keys", "Real-world data-entry errors, legacy ID reuse, or coincidental duplicate values can violate an assumption that seemed safe on paper", "Natural keys are unique by mathematical law", "Only surrogate keys can ever have duplicates"]'::jsonb,1,'Real-world data is messier than assumptions — natural keys can have unexpected duplicates that only surface once actually checked or enforced.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-5','pt-dbms-sql-5-natural-key','What is one advantage of a natural key over a surrogate key?','["It requires no design effort and doesn''t need to be independently meaningful", "It''s independently meaningful outside the database, without needing an extra lookup to understand it", "It is always shorter to store", "It never changes over time"]'::jsonb,1,'A natural key already carries real-world meaning, unlike an arbitrary surrogate value.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-6','pt-dbms-sql-5-natural-key','How can a natural key negatively affect foreign key performance?','["Natural keys can never be referenced by foreign keys", "If the natural key is long, composite, or an inconvenient type, foreign keys referencing it become wider and potentially slower to index than a compact surrogate integer", "Foreign keys referencing natural keys are always faster", "This is purely a hypothetical concern with no real basis"]'::jsonb,1,'Wider referenced values and indexes can affect costs, but exact performance requires workload and engine evidence.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-7','pt-dbms-sql-5-natural-key','Is ''a person''s full name'' generally considered a reliable natural key?','["Yes, names are always unique", "No — multiple people can share the same name, making it an unreliable choice for uniqueness", "Only for people whose names start with a vowel", "Names are never allowed as database columns"]'::jsonb,1,'Name collisions are common in the real world, making plain name a poor natural-key candidate.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-natural-key-8','pt-dbms-sql-5-natural-key','What is the fundamental trade-off between natural keys and surrogate keys?','["There is no trade-off; one is strictly better in every case", "Natural identities carry business meaning and need scope/lifecycle guarantees; surrogates separate internal identity but do not remove business rules", "Surrogate keys are always slower to generate", "Natural keys can never be used in a WHERE clause"]'::jsonb,1,'Neither approach is universally superior; stability, reference requirements and actual guarantees determine the design.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
