update public.learning_topics set short_description='Explain CODASYL owner/member sets, navigational access, multiple relationship roles, and association records, with SQL mirrors that distinguish shared links from ownership violations.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Explain CODASYL owner/member sets, navigational access, multiple relationship roles, and association records, with SQL mirrors that distinguish shared links from ownership violations.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Network Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-network-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-network-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Network Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-network-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-network-model-1','pt-dbms-sql-3-network-model','What CODASYL-defined construct represents a relationship between an owner record type and member record types in the network model?','["A join table", "A set", "A collection", "An index"]'::jsonb,1,'The CODASYL network model organizes relationships into named ''sets'', each with one owner record type and one or more member record types.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-network-model-2','pt-dbms-sql-3-network-model','What flexibility does the classical network model add beyond a basic single-parent tree?','["It eliminates the need for pointers", "A record can participate in several named set types and owner/member roles", "It uses SQL for querying", "It requires no schema design at all"]'::jsonb,1,'This does not imply arbitrary multiple owners within one constrained set type.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-network-model-3','pt-dbms-sql-3-network-model','Which system is a well-known industrial implementation of the CODASYL network model?','["IDMS", "MongoDB", "Neo4j", "Cassandra"]'::jsonb,0,'IDMS (Integrated Database Management System) was a widely deployed CODASYL network-model database used in enterprise mainframe systems.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-network-model-4','pt-dbms-sql-3-network-model','How does an application typically retrieve data from a CODASYL network database?','["Declarative SQL SELECT statements", "Procedural navigation using DML calls like FIND and FIND NEXT WITHIN a named set", "Automatic schema-free document queries", "REST API calls"]'::jsonb,1,'CODASYL databases use navigational DML where the program explicitly finds owner records and walks member chains within named sets.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-network-model-5','pt-dbms-sql-3-network-model','Part participates in a supplier-owned set and a warehouse-owned set. What does that establish?','["Parts cannot be shared between sets", "Participation in two differently named relationships, not automatically unrestricted many-to-many cardinality", "This is only possible in relational databases", "Sets can only have one member record type"]'::jsonb,1,'Many-to-many facts may need association records.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
