update public.learning_topics set short_description='Require recorded presence without confusing NULL with empty or invalid values, diagnose legacy missing departments, and enforce a required property only after an approved repair.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Require recorded presence without confusing NULL with empty or invalid values, diagnose legacy missing departments, and enforce a required property only after an approved repair.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for NOT NULL.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-10-not-null' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-10-not-null-application','MCQ Test 2',category,10,10,'Application and scenarios for NOT NULL.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-10-not-null' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-1','pt-dbms-sql-10-not-null','What is the primary effect of applying a NOT NULL constraint to a column?','["It forces the column to contain only unique values", "It forbids the NULL marker from being stored in that column", "It sets a default value for the column", "It forces the column to be indexed"]'::jsonb,1,'NOT NULL only bans the absence-of-value marker NULL; it does not enforce uniqueness, defaults, or indexing.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-2','pt-dbms-sql-10-not-null','In MySQL, which statement correctly adds NOT NULL to an existing nullable column `email VARCHAR(150)`?','["ALTER TABLE employees SET email NOT NULL;", "ALTER TABLE employees ALTER COLUMN email SET NOT NULL;", "ALTER TABLE employees MODIFY email VARCHAR(150) NOT NULL;", "ALTER TABLE employees ADD NOT NULL email;"]'::jsonb,2,'MySQL uses MODIFY with the full column definition restated; ALTER COLUMN ... SET NOT NULL is PostgreSQL syntax.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-3','pt-dbms-sql-10-not-null','What must a required-property transition address before final enforcement?','["The engine automatically deletes those rows", "The engine automatically replaces NULLs with an empty string", "Existing missing values and the target engine’s validation and input-conversion rules", "The constraint is added but silently not enforced for old rows"]'::jsonb,2,'Do not assume every permissive mode produces the same unconditional failure outcome.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-4','pt-dbms-sql-10-not-null','Under the stated strict ordinary-integer fixture, what happens to an explicit NULL in a NOT NULL quantity column?','["qty is set to 10 because of the DEFAULT", "It is rejected rather than replaced merely because a DEFAULT exists", "qty is set to 0", "qty remains NULL since it was explicit"]'::jsonb,1,'An omitted value and an explicit missing marker are different inputs.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-5','pt-dbms-sql-10-not-null','Which column is implicitly NOT NULL even if you never write the keyword?','["Any VARCHAR column", "A column declared UNIQUE", "A PRIMARY KEY column", "A column with a DEFAULT value"]'::jsonb,2,'A PRIMARY KEY column is always implicitly NOT NULL in addition to being unique.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-6','pt-dbms-sql-10-not-null','In MySQL, what risk does `ALTER TABLE employees MODIFY email VARCHAR(150) NOT NULL;` carry compared to PostgreSQL''s `ALTER COLUMN ... SET NOT NULL`?','["It cannot be rolled back", "It requires dropping the table first", "Forgetting to restate other attributes like DEFAULT can silently remove them, since MODIFY replaces the whole definition", "It automatically drops any existing indexes on the column"]'::jsonb,2,'MySQL''s MODIFY rewrites the entire column definition, so omitted attributes (type details, DEFAULT, etc.) can be lost, unlike Postgres''s targeted SET NOT NULL sub-clause.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-7','pt-dbms-sql-10-not-null','Does NOT NULL prevent an empty string ('''') from being stored in a VARCHAR column?','["Yes, empty string is treated as NULL", "No, empty string is a valid value distinct from NULL", "Only in PostgreSQL", "Only if the column is also UNIQUE"]'::jsonb,1,'An empty string is a zero-length value, not the absence of a value, so NOT NULL does not block it; a CHECK constraint would be needed for that.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-not-null-8','pt-dbms-sql-10-not-null','Which syntax statement is accurate for this MySQL exercise and PostgreSQL 18?','["NOT NULL can be written as either a column-level or table-level constraint", "Use MySQL’s supported column property form here; other products and versions can support additional constraint forms", "NOT NULL must always be paired with CHECK", "NOT NULL can only be applied via a trigger"]'::jsonb,1,'PostgreSQL 18 documents a table-level NOT NULL column-name form; there is no universal no-table-level rule.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-not-null-new-9','pt-dbms-sql-10-not-null','Does NOT NULL reject an empty MySQL string by itself?','["Yes", "No", "Only with VARCHAR", "Only if sorted"]'::jsonb,1,'An empty string is a supplied value, distinct from NULL.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-10-not-null-new-10','pt-dbms-sql-10-not-null','Which predicate diagnoses actual missing departments?','["department = NULL", "department = 0 always", "department IS NULL", "department LIKE every row"]'::jsonb,2,'Ordinary equality with NULL is not TRUE for a missing marker.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
