(2, ''Rohan'', ''Engineering'', 72000, 1),
(3, ''Neha'', ''Sales'', 68000, NULL),
(4, ''Vikram'', ''Sales'', 61000, 3),
(5, ''Priya'', ''Engineering'', 79000, 1),
(6, ''Karan'', ''Marketing'', 55000, NULL),
(7, ''Divya'', ''Marketing'', 58000, 6),
(8, ''Aman'', ''Sales'', 64000, 3);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-8-null-semantics' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
