update public.learning_topics set short_description='Explore persistent object identity, state, references, shared ownership, inheritance, and schema evolution, separating model-level ideas from product-specific query and transaction guarantees.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Explore persistent object identity, state, references, shared ownership, inheritance, and schema evolution, separating model-level ideas from product-specific query and transaction guarantees.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Object-Oriented Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-object-oriented-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-object-oriented-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Object-Oriented Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-object-oriented-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-1','pt-dbms-sql-3-object-oriented-model','In the object-oriented data model, what bundles together in a single object?','["Only attributes (state)", "Only methods (behavior)", "Both state (attributes) and behavior (methods)", "Only foreign keys"]'::jsonb,2,'The defining feature of the OO model is that an object bundles state and behavior together, mirroring object-oriented programming languages.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-2','pt-dbms-sql-3-object-oriented-model','What is the useful distinction supplied by persistent object identity?','["A value derived from an object''s attributes, like a relational primary key", "Identity can remain distinct from the current attribute values or physical address", "A foreign key referencing another table", "A hash of the object''s class name"]'::jsonb,1,'OID representation and management depend on the actual product.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-3','pt-dbms-sql-3-object-oriented-model','Which of these is a real-world domain where object-oriented databases saw practical adoption?','["Simple two-column lookup tables", "CAD/CAM systems with deeply nested complex objects", "Basic key-value session caching", "Flat CSV file storage"]'::jsonb,1,'CAD/CAM, telecom configuration, and multimedia repositories are classic domains where OO databases'' native support for complex, nested objects proved useful.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-4','pt-dbms-sql-3-object-oriented-model','What mapping benefit can supported object persistence provide?','["Better support for SQL reporting", "It can reduce translation for suitable application structures, while persistence and evolution contracts still need review", "Simpler horizontal scaling across clusters", "Stronger support for ad-hoc declarative queries"]'::jsonb,1,'No model universally eliminates all mapping or unsupported-state concerns.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-5','pt-dbms-sql-3-object-oriented-model','What query-related consideration can affect adoption of an object database?','["They cannot represent inheritance", "Its actual query and interoperability capabilities may differ from the widely shared SQL ecosystem", "They cannot store any attribute data", "They require no schema at all, making them insecure"]'::jsonb,1,'This is not a claim that object database products have no query facilities.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-6','pt-dbms-sql-3-object-oriented-model','What can a Drawing reference to Shape identities represent?','["Via a separate junction table with foreign keys", "Relationships to persistent objects, including sharing where the domain allows it", "Only through a document embedded as JSON", "Through a column-family wide row"]'::jsonb,1,'Actual loading and storage work still depend on the implementation.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-7','pt-dbms-sql-3-object-oriented-model','How does the object-oriented model differ in emphasis from object-relational extensions?','["They are the same model with different names", "It centers persistent objects and identity, while object-relational designs retain a relational foundation with extensions", "The Object-Relational model cannot support inheritance", "The OO model always requires a schema-free document store"]'::jsonb,1,'Logical model emphasis is not a claim about every physical storage structure.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-oriented-model-8','pt-dbms-sql-3-object-oriented-model','When can a Shape query include Circle and Rectangle occurrences?','["Because SQL UNION is used behind the scenes", "When the selected implementation and query support that polymorphic subtype behavior", "Because Circle and Rectangle are stored in the same table with a type column", "Because OO databases ignore class hierarchies"]'::jsonb,1,'Check actual query semantics rather than assuming a universal engine rule.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
