update public.learning_topics set short_description='Compare relational foundations with composite values, arrays, inheritance, and semi-structured columns, using labeled PostgreSQL examples and MySQL mirrors with explicit verification limits.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Compare relational foundations with composite values, arrays, inheritance, and semi-structured columns, using labeled PostgreSQL examples and MySQL mirrors with explicit verification limits.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Object-Relational Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-object-relational-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-object-relational-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Object-Relational Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-object-relational-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-1','pt-dbms-sql-3-object-relational-model','What characterizes object-relational extensions?','["They are unrelated, competing paradigms", "A relational/SQL foundation with supported richer value or type-related facilities", "The Object-Relational model has no tables at all", "The Object-Relational model replaced SQL with OQL"]'::jsonb,1,'Transaction and security guarantees still depend on the actual implementation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-2','pt-dbms-sql-3-object-relational-model','Which database system is most commonly cited as the textbook example of an object-relational database?','["MongoDB", "Redis", "PostgreSQL", "Neo4j"]'::jsonb,2,'PostgreSQL originated from the Berkeley POSTGRES project explicitly built to add object-oriented concepts to relational databases.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-3','pt-dbms-sql-3-object-relational-model','In PostgreSQL, what does ''CREATE TABLE premium_customers (...) INHERITS (customers)'' demonstrate?','["A foreign key relationship", "Table inheritance, an object-relational extension to the pure relational model", "A many-to-many junction table", "A materialized view"]'::jsonb,1,'INHERITS creates a table inheritance relationship, an OO-style feature layered onto the relational model.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-4','pt-dbms-sql-3-object-relational-model','What is a key behavioral quirk of table inheritance in PostgreSQL that can surprise developers?','["Child tables cannot have any additional columns", "A query on the parent table by default also returns rows from child tables unless ONLY is specified", "Inherited tables cannot be indexed", "Parent table queries never include child rows"]'::jsonb,1,'By default, querying the parent table includes rows from all its child tables; using ONLY customers restricts the query to just the parent table''s own rows.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-5','pt-dbms-sql-3-object-relational-model','What should determine whether a phone array or a child relation fits a design?','["It strictly enforces First Normal Form (1NF)", "The modeled value, per-entry relationships, constraints, and required operations", "It has no relationship to normalization concepts", "It automatically creates a separate join table behind the scenes"]'::jsonb,1,'An array is not automatically the same normalization decision in every domain.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-6','pt-dbms-sql-3-object-relational-model','What emphasis distinguishes object-relational designs from object-centered persistence?','["They are identical; OR is just a marketing term for OO databases", "They retain a relational foundation while adding supported extensions", "OO databases always run on top of relational engines", "OR databases cannot support user-defined types"]'::jsonb,1,'This comparison concerns model emphasis rather than a universal claim about physical storage internals.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-7','pt-dbms-sql-3-object-relational-model','What SQL object-relational feature lets you define a structured column type, such as an ''address'' with street, city, and zip fields?','["A composite (user-defined) type", "A materialized view", "A stored procedure", "A trigger"]'::jsonb,0,'User-defined composite types let a single column hold a structured value, an object-relational extension to plain scalar columns.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-object-relational-model-8','pt-dbms-sql-3-object-relational-model','Is a PostgreSQL JSONB column identical to a composite type or table inheritance?','["Yes, they are identical mechanisms", "No; document values, typed composites, and inheritance have different structures and contracts", "No, because PostgreSQL does not actually support JSONB", "Yes, because both eliminate the need for SQL entirely"]'::jsonb,1,'Nested visual appearance does not make their semantics interchangeable.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
