if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-participation-4' and (question_text,options,correct_index,explanation) is distinct from ('Which best distinguishes participation from cardinality?','["They are the same concept", "Cardinality sets a maximum on how many instances can be linked (1, N, M); participation sets a minimum \u2014 whether at least one link is required (total) or not (partial)", "Participation only applies to weak entities", "Cardinality applies only to unary relationships"]'::jsonb,1,'Cardinality = upper bound on links; participation = whether a link is mandatory at all — separate, combinable constraints.') and (question_text,options,correct_index,explanation) is distinct from ('Which best distinguishes participation from cardinality?','["They are the same concept", "Cardinality sets a maximum on how many instances can be linked (1, N, M); participation sets a minimum \u2014 whether at least one link is required (total) or not (partial)", "Participation only applies to weak entities", "Cardinality applies only to unary relationships"]'::jsonb,1,'Cardinality = upper bound on links; participation = whether a link is mandatory at all — separate, combinable constraints.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-participation-4'; end if;
