if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-physical-data-independence-1' and (question_text,options,correct_index,explanation) is distinct from ('What does Physical Data Independence allow a DBA to change without affecting the conceptual schema or applications?','["The relationships and constraints in the conceptual schema", "The internal/physical schema: file organization, indexing, storage engine, hardware", "The columns visible in an external schema", "The business logic layer of a three-tier application"]'::jsonb,1,'Physical data independence specifically concerns shielding higher levels from changes made at the internal (physical storage) schema.') and (question_text,options,correct_index,explanation) is distinct from ('What does Physical Data Independence allow a DBA to change without affecting the conceptual schema or applications?','["The relationships and constraints in the conceptual schema", "The internal/physical schema: file organization, indexing, storage engine, hardware", "The columns visible in an external schema", "The business logic layer of a three-tier application"]'::jsonb,1,'The intended boundary shields logical consumers from supported internal representation changes that preserve their guarantees.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-physical-data-independence-1'; end if;
