if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-physical-data-independence-2' and (question_text,options,correct_index,explanation) is distinct from ('According to the notes, which is generally considered ''easier'' to achieve — logical or physical data independence?','["Logical data independence", "Physical data independence", "Both are equally difficult", "Neither is achievable in practice"]'::jsonb,1,'Physical independence is described as easier because the conceptual level acts as a stable buffer absorbing storage-level churn without needing to touch relationships or constraints.') and (question_text,options,correct_index,explanation) is distinct from ('According to the notes, which is generally considered ''easier'' to achieve — logical or physical data independence?','["Logical data independence", "Physical data independence", "Both are equally difficult", "Neither is achievable in practice"]'::jsonb,1,'Physical independence is described as easier because the conceptual level acts as a stable buffer absorbing storage-level churn without needing to touch relationships or constraints.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-physical-data-independence-2'; end if;
