if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-physical-data-independence-6' and (question_text,options,correct_index,explanation) is distinct from ('How can an application accidentally undermine physical data independence even though the DBA has done nothing wrong?','["By using the conceptual schema exclusively for all its queries", "By hardcoding a specific index name in a query hint or relying on physical row insertion order instead of an explicit ORDER BY", "By requesting data through a properly defined external schema", "By caching query results in the application tier"]'::jsonb,1,'Leaking storage assumptions (index names, assumed row order) into application queries breaks the isolation physical data independence is supposed to provide.') and (question_text,options,correct_index,explanation) is distinct from ('How can an application accidentally undermine physical data independence even though the DBA has done nothing wrong?','["By using the conceptual schema exclusively for all its queries", "By hardcoding a specific index name in a query hint or relying on physical row insertion order instead of an explicit ORDER BY", "By requesting data through a properly defined external schema", "By caching query results in the application tier"]'::jsonb,1,'Leaking storage assumptions (index names, assumed row order) into application queries breaks the isolation physical data independence is supposed to provide.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-physical-data-independence-6'; end if;
