if not exists(select 1 from public.test_questions where id='tq-dbms-sql-2-physical-data-independence-8' and test_id='pt-dbms-sql-2-physical-data-independence') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-2-physical-data-independence-8'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-physical-data-independence-8' and (question_text,options,correct_index,explanation) is distinct from ('Why does physical data independence generally not require rethinking entity relationships or constraints, unlike logical data independence?','["Because internal-level changes are storage-focused and managed by the internal/conceptual mapping, without altering the logical structure or constraints themselves", "Because physical schemas contain their own separate set of relationships and constraints", "Because physical data independence does not involve any mapping at all", "Because relationships only exist at the external schema level"]'::jsonb,0,'Physical changes operate purely at the storage level and are absorbed by the internal/conceptual mapping, leaving the logical structure and constraints untouched.') and (question_text,options,correct_index,explanation) is distinct from ('Why does physical data independence generally not require rethinking entity relationships or constraints, unlike logical data independence?','["Because internal-level changes are storage-focused and managed by the internal/conceptual mapping, without altering the logical structure or constraints themselves", "Because physical schemas contain their own separate set of relationships and constraints", "Because physical data independence does not involve any mapping at all", "Because relationships only exist at the external schema level"]'::jsonb,0,'Physical changes operate purely at the storage level and are absorbed by the internal/conceptual mapping, leaving the logical structure and constraints untouched.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-physical-data-independence-8'; end if;
