if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-polyglot-persistence-1' and (question_text,options,correct_index,explanation) is distinct from ('What does the term ''polyglot persistence'' describe?','["Using a single database that supports multiple query languages", "Using multiple different databases/data models within one application, each chosen for its best-fit workload", "Translating a database''s stored data into multiple human languages", "Storing all data as plain text files"]'::jsonb,1,'Polyglot persistence means deliberately using several different databases/data models in one system, each matched to the part of the workload it handles best.') and (question_text,options,correct_index,explanation) is distinct from ('What does the term ''polyglot persistence'' describe?','["Using a single database that supports multiple query languages", "Using multiple different databases/data models within one application, each chosen for its best-fit workload", "Translating a database''s stored data into multiple human languages", "Storing all data as plain text files"]'::jsonb,1,'Polyglot persistence means deliberately using several different databases/data models in one system, each matched to the part of the workload it handles best.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-polyglot-persistence-1'; end if;
