if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-polyglot-persistence-2' and (question_text,options,correct_index,explanation) is distinct from ('In the e-commerce example, why would PostgreSQL (relational) be chosen for orders and payments rather than a document or key-value store?','["Because relational databases are always the cheapest option", "Because ACID transactions ensure a payment and an inventory decrement either both succeed or both roll back together", "Because PostgreSQL has the fastest raw key lookups of any database", "Because orders cannot be represented as rows and columns"]'::jsonb,1,'Financial operations like payments typically need strong ACID guarantees so related updates (payment + inventory) commit or fail together, which is the relational model''s strength.') and (question_text,options,correct_index,explanation) is distinct from ('Why might a supported relational engine fit authoritative order or enrollment facts?','["Because relational databases are always the cheapest option", "Its verified local integrity and transaction facilities can fit those facts, without automatically including external provider effects", "Because PostgreSQL has the fastest raw key lookups of any database", "Because orders cannot be represented as rows and columns"]'::jsonb,1,'A local database commit does not itself atomically complete a remote charge.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-polyglot-persistence-2'; end if;
