if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-polyglot-persistence-4' and (question_text,options,correct_index,explanation) is distinct from ('Why is a graph database like Neo4j a natural fit for a ''customers who bought this also bought...'' recommendation feature?','["Because graph databases are the fastest at simple key lookups", "Because the feature is fundamentally a multi-hop relationship traversal, which graph databases handle efficiently via index-free adjacency", "Because graph databases enforce the strictest schema of any model", "Because recommendations require full-text search capability only"]'::jsonb,1,'Recommendation queries like this rely on traversing purchase/co-purchase relationships, which is exactly the graph model''s core strength.') and (question_text,options,correct_index,explanation) is distinct from ('Why consider a graph projection for a relationship feature?','["Because graph databases are the fastest at simple key lookups", "Its supported relationship queries may fit the required workload, subject to actual semantics and performance evidence", "Because graph databases enforce the strictest schema of any model", "Because recommendations require full-text search capability only"]'::jsonb,1,'Multi-hop traversal is not universally constant time or automatically superior.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-polyglot-persistence-4'; end if;
