if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-polyglot-persistence-5' and (question_text,options,correct_index,explanation) is distinct from ('What is the biggest engineering risk introduced by polyglot persistence?','["Databases becoming too fast for applications to handle", "Cross-database consistency drift, since no single ACID transaction can span multiple different database engines", "The complete inability to use SQL anywhere in the system", "Every database in the architecture must use the same query language"]'::jsonb,1,'Because different databases can''t share a single transaction, an update succeeding in one store while failing to propagate to another can cause silent data drift.') and (question_text,options,correct_index,explanation) is distinct from ('What consistency risk does using separate stores introduce?','["Databases becoming too fast for applications to handle", "Independent writes can diverge unless a verified coordination or propagation policy handles the boundary", "The complete inability to use SQL anywhere in the system", "Every database in the architecture must use the same query language"]'::jsonb,1,'Cross-engine atomic coordination can exist, but it is not automatic.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-polyglot-persistence-5'; end if;
