update public.learning_topics set short_description='Use multiple stores only for demonstrated needs, with explicit authority, projection versions, delivery and retry rules, reconciliation, and operational ownership across database boundaries.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use multiple stores only for demonstrated needs, with explicit authority, projection versions, delivery and retry rules, reconciliation, and operational ownership across database boundaries.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Polyglot Persistence.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-polyglot-persistence' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-polyglot-persistence-application','MCQ Test 2',category,10,10,'Application and scenarios for Polyglot Persistence.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-polyglot-persistence' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-1','pt-dbms-sql-3-polyglot-persistence','What does the term ''polyglot persistence'' describe?','["Using a single database that supports multiple query languages", "Using multiple different databases/data models within one application, each chosen for its best-fit workload", "Translating a database''s stored data into multiple human languages", "Storing all data as plain text files"]'::jsonb,1,'Polyglot persistence means deliberately using several different databases/data models in one system, each matched to the part of the workload it handles best.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-2','pt-dbms-sql-3-polyglot-persistence','Why might a supported relational engine fit authoritative order or enrollment facts?','["Because relational databases are always the cheapest option", "Its verified local integrity and transaction facilities can fit those facts, without automatically including external provider effects", "Because PostgreSQL has the fastest raw key lookups of any database", "Because orders cannot be represented as rows and columns"]'::jsonb,1,'A local database commit does not itself atomically complete a remote charge.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-3','pt-dbms-sql-3-polyglot-persistence','When might a document projection help a varied catalog?','["Because document databases cannot store text", "When its aggregate structure and verified access pattern justify the added representation and consistency work", "Because relational tables cannot store product names", "Because document databases automatically translate currencies"]'::jsonb,1,'A relational design can also support varied attributes; a document store is not automatically required.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-4','pt-dbms-sql-3-polyglot-persistence','Why consider a graph projection for a relationship feature?','["Because graph databases are the fastest at simple key lookups", "Its supported relationship queries may fit the required workload, subject to actual semantics and performance evidence", "Because graph databases enforce the strictest schema of any model", "Because recommendations require full-text search capability only"]'::jsonb,1,'Multi-hop traversal is not universally constant time or automatically superior.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-5','pt-dbms-sql-3-polyglot-persistence','What consistency risk does using separate stores introduce?','["Databases becoming too fast for applications to handle", "Independent writes can diverge unless a verified coordination or propagation policy handles the boundary", "The complete inability to use SQL anywhere in the system", "Every database in the architecture must use the same query language"]'::jsonb,1,'Cross-engine atomic coordination can exist, but it is not automatic.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-6','pt-dbms-sql-3-polyglot-persistence','What is a common technique used to mitigate cross-database consistency drift in a polyglot persistence architecture?','["Disabling transactions entirely in all databases", "Change-data-capture (CDC) pipelines or the outbox pattern to asynchronously synchronize data across stores", "Storing all data redundantly in every database at all times", "Only allowing reads, never writes, in secondary databases"]'::jsonb,1,'CDC pipelines (e.g., Debezium) and the outbox pattern are standard patterns for asynchronously propagating changes across separate databases, accepting eventual consistency.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-7','pt-dbms-sql-3-polyglot-persistence','What operational cost does polyglot persistence introduce compared to using a single database?','["None; it is always operationally simpler", "Multiple systems to back up, monitor, secure, and scale, each requiring its own specialized expertise", "The complete elimination of the need for monitoring", "A guaranteed reduction in team headcount"]'::jsonb,1,'Each additional database in a polyglot architecture adds its own operational burden: backups, monitoring, security, scaling, and specialized team knowledge.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-polyglot-persistence-8','pt-dbms-sql-3-polyglot-persistence','When is polyglot persistence generally NOT justified?','["When an application has massive, clearly distinct workloads like search, graph traversal, and high-volume logging", "For a small application with modest scale needs, where a single well-chosen database is usually simpler and sufficient", "When a company has dedicated database administration teams for each system", "When the application already needs ACID transactions"]'::jsonb,1,'For small or simple applications, the operational overhead of multiple databases usually outweighs the fit-for-purpose benefits; a single well-chosen database is typically the better trade-off.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-new-9','pt-dbms-sql-3-polyglot-persistence','What should identify the owner of an authoritative course title?','["Whichever store responds fastest", "An explicit source-of-truth contract", "The latest screenshot", "The most nested representation"]'::jsonb,1,'Representations need clear fact ownership before synchronization.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-new-10','pt-dbms-sql-3-polyglot-persistence','Does an outbox local commit mean the remote projection is already updated?','["Yes; all remote writes are automatic participants", "Only if the event ID is numeric", "No", "Only if the title is short"]'::jsonb,2,'The local source/event boundary differs from remote delivery completion.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-application-new-1','pt-dbms-sql-3-polyglot-persistence-application','Source version 3 exists while the projection remains at 2. What does the audit observe?','["A guaranteed source rollback", "A missing source identity", "A stale projection under the version policy", "A native graph constraint failure"]'::jsonb,2,'The mismatch is concrete evidence to interpret under the freshness contract.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-application-new-2','pt-dbms-sql-3-polyglot-persistence-application','A publisher delivers an event and crashes before recording progress. What must the consumer handle?','["Guaranteed exactly-once receipt", "Automatic deletion of all prior events", "A requirement to reset source versions", "Possible repeated delivery"]'::jsonb,3,'Deduplication or idempotent application needs a defined policy.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-application-new-3','pt-dbms-sql-3-polyglot-persistence-application','Version 3 is applied, then a version 2 event arrives. What should a suitable version rule prevent?','["Regression to stale projection state", "Every future valid update", "Only name changes", "Only event logging"]'::jsonb,0,'Ordering and conditional application protect the current projection.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
