insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-application-new-5','pt-dbms-sql-3-polyglot-persistence-application','A projection exists without a source row in a complete fixture snapshot. What state is reported?','["Current by default", "A newly authoritative entity", "Orphan", "A transaction commit"]'::jsonb,2,'The classification relies on the stated complete-source assumption.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
