insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-polyglot-persistence-application-new-7','pt-dbms-sql-3-polyglot-persistence-application','A pending outbox query returns rows. Does that authorize publishing production events?','["No", "Yes; every SELECT result is an action request", "Only if published_at is NULL", "Only if events are ordered"]'::jsonb,0,'Read-only fixture results are not external-action authorization.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
