insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-primary-key-constraint-syntax-1','pt-dbms-sql-10-primary-key-constraint-syntax','Why must a composite primary key spanning two columns be declared using table-level syntax?','["Because column-level syntax cannot list more than one column at a time", "Because MySQL disallows composite keys entirely", "Because table-level syntax is faster to execute", "Because composite keys require a separate CHECK constraint"]'::jsonb,0,'Column-level PRIMARY KEY syntax attaches inline to a single column definition and has no way to reference a second column, so any multi-column key must use the table-level PRIMARY KEY (col1, col2) clause.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-primary-key-constraint-syntax-2','pt-dbms-sql-10-primary-key-constraint-syntax','In MySQL, how do you drop the primary key from a table named students?','["ALTER TABLE students DROP CONSTRAINT pk_students;", "ALTER TABLE students DROP PRIMARY KEY;", "ALTER TABLE students DROP KEY PRIMARY;", "DROP PRIMARY KEY FROM students;"]'::jsonb,1,'MySQL provides a dedicated DROP PRIMARY KEY clause since it does not let you assign a custom name to the primary key; DROP CONSTRAINT is used in PostgreSQL/Oracle/SQL Server instead.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-primary-key-constraint-syntax-3','pt-dbms-sql-10-primary-key-constraint-syntax','What must be true of existing table data before ALTER TABLE ... ADD CONSTRAINT ... PRIMARY KEY (col) will succeed?','["The column must already be indexed", "The column must contain no NULLs and no duplicate values", "The table must be empty", "The column must be of an integer data type"]'::jsonb,1,'Adding a PRIMARY KEY validates existing rows: any NULL or duplicate value in the target column(s) causes the ALTER TABLE to fail.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-primary-key-constraint-syntax-4','pt-dbms-sql-10-primary-key-constraint-syntax','How many primary-key constraints may one table declaration contain?','["Unlimited, one per candidate key", "At most one, potentially over several columns", "Up to two, for redundancy", "As many as there are UNIQUE constraints"]'::jsonb,1,'A table may omit a primary-key declaration; multiple component columns do not mean multiple primary constraints.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
