insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-primary-key-constraint-syntax-7','pt-dbms-sql-10-primary-key-constraint-syntax','Which statement correctly declares a composite primary key on (student_id, course_id) for an existing empty table enrollments?','["ALTER TABLE enrollments ADD PRIMARY KEY student_id, course_id;", "ALTER TABLE enrollments ADD CONSTRAINT pk_enroll PRIMARY KEY (student_id, course_id);", "ALTER TABLE enrollments MODIFY PRIMARY KEY (student_id) AND (course_id);", "ALTER TABLE enrollments SET PRIMARY KEY = (student_id, course_id);"]'::jsonb,1,'The table-level ADD CONSTRAINT ... PRIMARY KEY (col1, col2) form is the correct portable syntax for adding a composite key to an existing table.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
