update public.learning_topics set short_description='Choose output attribute roles while respecting set duplicate elimination, distinguish SQL bag projection from relational projection, and preserve the intended result grain.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Choose output attribute roles while respecting set duplicate elimination, distinguish SQL bag projection from relational projection, and preserve the intended result grain.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Projection.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-7-projection' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-7-projection-application','MCQ Test 2',category,10,10,'Application and scenarios for Projection.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-7-projection' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-1','pt-dbms-sql-7-projection','What does the Projection operation (π) do?','["Filters rows by a condition", "Selects a subset of columns from a relation", "Joins two relations together", "Sorts a relation''s rows"]'::jsonb,1,'Projection narrows by COLUMNS, keeping only the specified attributes.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-2','pt-dbms-sql-7-projection','Why does `SELECT DISTINCT department FROM students` more accurately model relational-algebra Projection than plain `SELECT department FROM students`?','["DISTINCT has no real effect on the result", "Pure relational algebra projection removes duplicate rows automatically (a relation is a set), while plain SQL SELECT does not by default", "DISTINCT makes the query run in a different order", "SQL never allows duplicate rows in any query result"]'::jsonb,1,'SQL relations behave like multisets by default; DISTINCT is needed to match the pure set-based behavior of algebraic projection.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-3','pt-dbms-sql-7-projection','For a projection of a strict relation retaining its guaranteed unique nonmissing key, can duplicate elimination merge different source tuples?','["Always fewer, due to duplicate elimination", "The same number of rows, since a unique key guarantees no duplicates can arise", "Always exactly one row", "This cannot be determined"]'::jsonb,1,'The retained key distinguishes every source tuple, so the projected cardinality stays the same under those assumptions.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-4','pt-dbms-sql-7-projection','What is a common way Selection and Projection are used together?','["They can never be combined in one query", "Selection filters to the rows of interest, then Projection narrows to just the columns needed to answer the question", "Projection must always run before any Selection, with no exceptions", "They perform the exact same function and are interchangeable"]'::jsonb,1,'Combining filter-then-narrow-columns is one of the most common patterns for answering real queries.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-5','pt-dbms-sql-7-projection','In relational algebra, is a relation formally treated as a set or a bag (multiset) of tuples?','["A bag, allowing duplicates", "A set, meaning no duplicate tuples are allowed", "Neither — relations have no formal structure", "This varies arbitrarily by textbook with no real consensus"]'::jsonb,1,'The classical relational model defines a relation as a SET of tuples, which is exactly why projection in the algebra removes duplicates automatically.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-6','pt-dbms-sql-7-projection','Does Projection ever filter which ROWS appear, the way Selection does?','["Yes, Projection and Selection filter rows identically", "Not directly — any row-count reduction from Projection comes only as a side effect of duplicate elimination after removing columns, not from a row condition", "Projection removes exactly half the rows every time", "Projection always returns all rows unchanged, with duplicates included"]'::jsonb,1,'Projection''s job is picking columns; any fewer rows in the output are purely an artifact of resulting duplicate rows collapsing together.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-7','pt-dbms-sql-7-projection','Which SQL feature is the direct equivalent of relational algebra''s Projection?','["The WHERE clause", "The selected attribute list supplies projection, with DISTINCT needed when SQL output must match classical set duplicate elimination", "The ORDER BY clause", "The FROM clause"]'::jsonb,1,'The SQL column list alone ordinarily retains duplicate output rows; exact classical projection also needs the appropriate set semantics.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-projection-8','pt-dbms-sql-7-projection','Why might forgetting DISTINCT in a query intended to model pure Projection produce a misleading result?','["It never produces a misleading result", "The query could return the same value many times over instead of the distinct set of values a textbook projection would produce", "DISTINCT is required by SQL syntax and its absence causes a syntax error", "Forgetting DISTINCT always returns zero rows"]'::jsonb,1,'Without DISTINCT, repeated values remain in the output, which doesn''t match the duplicate-free guarantee of true relational-algebra projection.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-projection-new-9','pt-dbms-sql-7-projection','Three identified students have departments X,X,Y. What is the classical department projection?','["X,X,Y always", "X and Y once each", "Only X", "Three new department entities"]'::jsonb,1,'Pure projection returns a set of selected tuples.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
