insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-projection-application-new-3','pt-dbms-sql-7-projection-application','Does projection delete source columns?','["No; it derives an output with selected roles", "Yes; it runs ALTER TABLE", "Only if DISTINCT appears", "Only if the output is empty"]'::jsonb,0,'Query result structure and persistent schema differ.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
