insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-query-processor-1','pt-dbms-sql-1-query-processor','What is the primary job of the Query Processor?','["Transforming a declarative SQL statement into an efficient sequence of physical operations", "Physically writing data pages to disk", "Authenticating client connections", "Enforcing ACID properties across transactions"]'::jsonb,0,'The processor interprets and plans physical work for a declarative request. It aims for an appropriate strategy, but efficiency for a deployment needs actual evidence.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-query-processor-2','pt-dbms-sql-1-query-processor','What are the four stages the notes describe the Query Processor taking a SQL statement through?','["Parsing, semantic validation/binding, query optimization, and execution", "Backup, restore, replication, and failover", "Design, development, testing, and deployment", "Encryption, compression, indexing, and caching"]'::jsonb,0,'The notes explicitly list these four stages: parsing, binding, optimization, and execution.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-query-processor-3','pt-dbms-sql-1-query-processor','In the example query filtering by department, what does the optimizer consider choosing between?','["An index scan versus a full table scan", "A backup versus a restore", "A GRANT versus a REVOKE statement", "A naive user versus a sophisticated user"]'::jsonb,0,'The notes describe the optimizer choosing between an index scan and a full table scan for the example query.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
