insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-query-processor-1-9','pt-dbms-sql-1-query-processor','Can syntactically valid SQL refer to a column that does not exist?','["No; every valid-looking name must exist", "Yes; the database must invent the column automatically", "No; a table scan creates missing definitions", "Yes; syntax recognition and resolving actual object names are different checks"]'::jsonb,3,'Binding uses actual definitions to resolve names after the statement structure has been recognized.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-query-processor-1-10','pt-dbms-sql-1-query-processor','Does a matching index prove that the optimizer should always choose it?','["Yes; an index is always cheaper regardless of table size", "No; estimated qualifying rows and other costs can favor another strategy", "Yes; statistics are irrelevant once an index exists", "No; indexes can never support lookups"]'::jsonb,1,'A physical choice depends on the actual access opportunity and cost estimates, not only index existence.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
