update public.learning_topics set short_description='Model one entity type in distinct relationship roles, map supervisor and prerequisite facts correctly, and distinguish direct relationship queries from recursive traversal and cycle enforcement.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Model one entity type in distinct relationship roles, map supervisor and prerequisite facts correctly, and distinguish direct relationship queries from recursive traversal and cycle enforcement.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Recursive Relationship.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-recursive-relationship' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-recursive-relationship-application','MCQ Test 2',category,10,10,'Application and scenarios for Recursive Relationship.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-recursive-relationship' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-1','pt-dbms-sql-6-recursive-relationship','What is a recursive relationship?','["A relationship connecting three or more distinct entity sets", "A relationship in which an entity set is related to itself", "A relationship that has no cardinality", "A relationship involving only weak entities"]'::jsonb,1,'In a recursive relationship, the same entity set participates on both sides, often in different roles.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-2','pt-dbms-sql-6-recursive-relationship','In the Manages relationship on Employee, what are the two role names typically used?','["Owner and Dependent", "Manager and Subordinate", "Parent and Child entity", "Strong and Weak"]'::jsonb,1,'Manager and Subordinate distinguish the two participations of the same Employee entity set.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-3','pt-dbms-sql-6-recursive-relationship','Why should the role meanings be explicit in a recursive relationship?','["Because SQL requires them for foreign keys", "They distinguish participant positions of the same type, such as supervisor versus subordinate, so the association direction is clear", "Because recursive relationships cannot have attributes otherwise", "They are actually optional and rarely used"]'::jsonb,1,'Semantic roles must be understood; the exact naming syntax and rendering convention depend on the notation and implementation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-4','pt-dbms-sql-6-recursive-relationship','Under this lesson’s introductory one-participating-category convention, how is a self-association classified?','["Degree 1 (unary)", "Degree 2 (binary)", "Degree 3 (ternary)", "Degree 0"]'::jsonb,0,'It is called unary or recursive here, while its distinct role positions remain explicit.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-5','pt-dbms-sql-6-recursive-relationship','How is a 1:N recursive relationship like Manages typically implemented in a relational table?','["As a separate junction table with two foreign keys, always", "As a self-referencing foreign key column within the same Employee table (e.g., Manager_ID referencing Employee_ID)", "It cannot be represented in a relational schema", "As a multi-valued attribute on Employee"]'::jsonb,1,'A scalar self-reference fits an at-most-one-current-supervisor policy; native reference enforcement and hierarchy restrictions need their own definitions.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-6','pt-dbms-sql-6-recursive-relationship','Can a recursive relationship have M:N cardinality?','["No, recursive relationships are always 1:1", "Yes — e.g., Prerequisite_Of on Course can be M:N since a course can have multiple prerequisites and be a prerequisite for multiple courses", "No, recursive relationships have no cardinality concept", "Only if the entity set is weak"]'::jsonb,1,'Recursive relationships can carry any cardinality just like ordinary binary relationships; degree and cardinality are independent.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-7','pt-dbms-sql-6-recursive-relationship','Does being a recursive relationship imply that either participating entity is a weak entity?','["Yes, recursion always implies weakness", "No — recursion is purely about the same entity set appearing on both sides; it has no bearing on whether an entity is strong or weak", "Yes, but only for M:N recursive relationships", "It depends on the participation constraint"]'::jsonb,1,'Recursive relationships and weak entities are independent concepts; an entity set in a recursive relationship (like Employee) is commonly strong.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-recursive-relationship-8','pt-dbms-sql-6-recursive-relationship','Which of the following is a valid recursive relationship example in the college database?','["Enrolls_In, between Student and Course", "Offers, between Department and Course", "Prerequisite_Of, between Course and itself", "Headed_By, between Department and Faculty"]'::jsonb,2,'Prerequisite_Of relates Course to Course, making it recursive; the others connect two distinct entity sets.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-recursive-relationship-new-9','pt-dbms-sql-6-recursive-relationship','Does a recursive relationship require both roles to name the same occurrence?','["Yes; every edge must be a self-edge", "No; distinct employees can play the two roles", "Only if names match", "Only if the type is weak"]'::jsonb,1,'The same entity category can supply different participant occurrences.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-recursive-relationship-new-10','pt-dbms-sql-6-recursive-relationship','What does reversing a directed prerequisite pair usually do?','["Always leave the fact unchanged", "Delete a primary key", "State a different fact", "Make the relation unary in SQL"]'::jsonb,2,'Direction is part of the relationship meaning.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
