insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-recursive-relationship-application-new-3','pt-dbms-sql-6-recursive-relationship-application','Why might supervisor_id be nullable under the stated model?','["A top-level employee can have no supervisor", "All employees must be unidentified", "NULL means supervisor zero", "It creates a cycle detector"]'::jsonb,0,'The root policy permits optional participation in that role.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-recursive-relationship-application-new-4','pt-dbms-sql-6-recursive-relationship-application','Can Course prerequisites be many-to-many?','["No; self-associations are always one-to-one", "Yes; several prerequisites and several dependent courses can be allowed", "Only if every course is weak", "Only if names repeat"]'::jsonb,1,'Recursion does not determine multiplicity.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-recursive-relationship-application-new-5','pt-dbms-sql-6-recursive-relationship-application','What does a combined course-prerequisite key protect?','["One prerequisite globally per course", "Global uniqueness of every course label", "Unique directed membership pairs under the stated policy", "All graph cycles"]'::jsonb,2,'Pair identity differs from wider graph constraints.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
