if exists(select 1 from public.dsa_problems where id='cx-recursive-relationship-supervisor' and description is distinct from 'Return employee_id, employee_name and supervisor_name for every employee. A NULL supervisor_id represents a root; return SQL NULL supervisor_name for that row. This is an immediate lookup, not a full traversal.

**MySQL dialect.**

```sql
CREATE TABLE employees (employee_id INT PRIMARY KEY, employee_name VARCHAR(80) NOT NULL, supervisor_id INT NULL);
INSERT INTO employees VALUES (1,''Asha'',NULL),(2,''Mira'',1),(3,''Mira'',1),(4,''Dev'',2);
```

**Required ordering:** Ascending employee_id.

**Edge cases:**
- Several subordinates can share a supervisor.
- Repeated names are distinct employee identities.') then raise exception 'New coding ID already has other content: %', 'cx-recursive-relationship-supervisor'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-recursive-relationship-supervisor',null::text,'Show immediate supervisors while preserving root employees','Easy','recursive-relationship-supervisor','Return employee_id, employee_name and supervisor_name for every employee. A NULL supervisor_id represents a root; return SQL NULL supervisor_name for that row. This is an immediate lookup, not a full traversal.

**MySQL dialect.**

```sql
CREATE TABLE employees (employee_id INT PRIMARY KEY, employee_name VARCHAR(80) NOT NULL, supervisor_id INT NULL);
INSERT INTO employees VALUES (1,''Asha'',NULL),(2,''Mira'',1),(3,''Mira'',1),(4,''Dev'',2);
```

**Required ordering:** Ascending employee_id.

**Edge cases:**
- Several subordinates can share a supervisor.
- Repeated names are distinct employee identities.','[{"input": "INSERT INTO employees VALUES (1,''Asha'',NULL),(2,''Mira'',1),(3,''Mira'',1),(4,''Dev'',2);", "output": "employee_id\temployee_name\tsupervisor_name\n1\tAsha\tNULL\n2\tMira\tAsha\n3\tMira\tAsha\n4\tDev\tMira", "explanation": "The role-qualified self-join follows the directed immediate association and keeps the root without claiming complete hierarchy traversal."}]'::jsonb,'[{"seed_sql": "INSERT INTO employees VALUES (9,''Root'',NULL);", "expected": "employee_id\temployee_name\tsupervisor_name\n9\tRoot\tNULL", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["All supplied nonmissing supervisor references exist.", "This temporary MariaDB query mirror verifies results; actual MySQL/provider temporary-table behaviour and native self-reference enforcement remain unverified."]'::jsonb,'["Use two aliases with clear participant roles.", "Preserve employees who have no supervisor."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The role-qualified self-join follows the directed immediate association and keeps the root without claiming complete hierarchy traversal.','{"sql": "SELECT e.employee_id, e.employee_name, m.employee_name AS supervisor_name FROM employees e LEFT JOIN employees m ON m.employee_id = e.supervisor_id ORDER BY e.employee_id;"}'::jsonb,'The role-qualified self-join follows the directed immediate association and keeps the root without claiming complete hierarchy traversal.',array['sql'],'CREATE TABLE employees (employee_id INT PRIMARY KEY, employee_name VARCHAR(80) NOT NULL, supervisor_id INT NULL);','INSERT INTO employees VALUES (1,''Asha'',NULL),(2,''Mira'',1),(3,''Mira'',1),(4,''Dev'',2);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-6-recursive-relationship' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-recursive-relationship-reciprocal' or slug='recursive-relationship-reciprocal') and (id<>'cx-recursive-relationship-reciprocal' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-recursive-relationship-reciprocal'; end if;
if exists(select 1 from public.dsa_problems where id='cx-recursive-relationship-reciprocal' and description is distinct from 'Return course_a and course_b for distinct courses with both prerequisite directions recorded. Output the smaller id first and report each pair once. Exclude self-edges. This finds two-node cycles only, not every cycle length.

**MySQL dialect.**

```sql
CREATE TABLE prerequisites (course_id INT NOT NULL, prerequisite_id INT NOT NULL, PRIMARY KEY(course_id,prerequisite_id));
INSERT INTO prerequisites VALUES (10,20),(20,10),(20,30),(30,40),(40,50),(50,30),(60,60);
```

**Required ordering:** Ascending course_a, course_b.

**Edge cases:**
- Each detected pair has two possible join orientations.
- Longer cycles can exist without a reciprocal pair.') then raise exception 'New coding ID already has other content: %', 'cx-recursive-relationship-reciprocal'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-recursive-relationship-reciprocal',null::text,'Report reciprocal prerequisite pairs exactly once','Medium','recursive-relationship-reciprocal','Return course_a and course_b for distinct courses with both prerequisite directions recorded. Output the smaller id first and report each pair once. Exclude self-edges. This finds two-node cycles only, not every cycle length.

**MySQL dialect.**

```sql
CREATE TABLE prerequisites (course_id INT NOT NULL, prerequisite_id INT NOT NULL, PRIMARY KEY(course_id,prerequisite_id));
INSERT INTO prerequisites VALUES (10,20),(20,10),(20,30),(30,40),(40,50),(50,30),(60,60);
```

**Required ordering:** Ascending course_a, course_b.

**Edge cases:**
- Each detected pair has two possible join orientations.
- Longer cycles can exist without a reciprocal pair.','[{"input": "INSERT INTO prerequisites VALUES (10,20),(20,10),(20,30),(30,40),(40,50),(50,30),(60,60);", "output": "course_a\tcourse_b\n10\t20", "explanation": "The self-join detects exactly the documented reciprocal pair pattern. It neither traverses all paths nor enforces global acyclicity."}]'::jsonb,'[{"seed_sql": "INSERT INTO prerequisites VALUES (1,2),(2,3),(3,1),(4,4);", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO prerequisites VALUES (4,9),(9,4),(1,2),(2,1);", "expected": "course_a\tcourse_b\n1\t2\n4\t9", "hidden": true}]'::jsonb,'["Pairs are directed and unique; identifiers are positive integers.", "The three-node cycle and self-edge deliberately remain outside the narrow task scope."]'::jsonb,'["Match each directed pair with its reverse.", "Use a strict id ordering to exclude self-links and duplicate orientations."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The self-join detects exactly the documented reciprocal pair pattern. It neither traverses all paths nor enforces global acyclicity.','{"sql": "SELECT a.course_id AS course_a, a.prerequisite_id AS course_b FROM prerequisites a JOIN prerequisites b ON b.course_id = a.prerequisite_id AND b.prerequisite_id = a.course_id WHERE a.course_id < a.prerequisite_id ORDER BY course_a, course_b;"}'::jsonb,'The self-join detects exactly the documented reciprocal pair pattern. It neither traverses all paths nor enforces global acyclicity.',array['sql'],'CREATE TABLE prerequisites (course_id INT NOT NULL, prerequisite_id INT NOT NULL, PRIMARY KEY(course_id,prerequisite_id));','INSERT INTO prerequisites VALUES (10,20),(20,10),(20,30),(30,40),(40,50),(50,30),(60,60);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-6-recursive-relationship' on conflict(id) do nothing;
