update public.learning_topics set short_description='Reason about valid references across a database state, distinguish permitted absence from dangling values, and retain an original orphan-detection exercise with stronger fixtures.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Reason about valid references across a database state, distinguish permitted absence from dangling values, and retain an original orphan-detection exercise with stronger fixtures.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Referential Integrity.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-5-referential-integrity' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-5-referential-integrity-application','MCQ Test 2',category,10,10,'Application and scenarios for Referential Integrity.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-5-referential-integrity' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-1','pt-dbms-sql-5-referential-integrity','What does referential integrity guarantee?','["That every column has a default value", "A declared reference satisfies the defined parent-key relationship, with absence allowed only under its actual policy", "That every table has a foreign key", "That primary keys are always integers"]'::jsonb,1,'Optional single-column absence and composite missing-component behaviour must follow the actual supported definition.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-2','pt-dbms-sql-5-referential-integrity','Which SQL mechanism directly enforces referential integrity?','["UNIQUE constraint", "FOREIGN KEY constraint", "CHECK constraint", "DEFAULT clause"]'::jsonb,1,'The FOREIGN KEY constraint is SQL''s implementation of the referential integrity rule.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-3','pt-dbms-sql-5-referential-integrity','For an optional single-column department reference, which query finds nonmissing employee references with no real parent?','["SELECT * FROM employees WHERE department_id IS NOT NULL", "SELECT e.* FROM employees e LEFT JOIN departments d ON d.id = e.department_id WHERE e.department_id IS NOT NULL AND d.id IS NULL", "SELECT * FROM departments WHERE id IS NULL", "SELECT * FROM employees INNER JOIN departments ON employees.department_id = departments.id"]'::jsonb,1,'A permitted NULL child reference is not an orphan. The parent identity supplies the match test.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-4','pt-dbms-sql-5-referential-integrity','Does referential integrity guarantee that a foreign key reference is semantically correct, not just that it exists?','["Yes, it guarantees full semantic correctness", "No — it only guarantees the referenced row exists, not that it''s the ''right'' one for the business situation", "It guarantees correctness only for numeric foreign keys", "This distinction doesn''t apply to referential integrity"]'::jsonb,1,'Referential integrity is purely about existence of the reference, not about whether it makes business sense.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-5','pt-dbms-sql-5-referential-integrity','In real systems, why is referential integrity sometimes violated despite the concept being well understood?','["It''s impossible for this to happen in any real system", "A FOREIGN KEY constraint may never have actually been declared, letting invalid references accumulate silently over time", "Referential integrity is disabled by default in every SQL engine", "SQL databases automatically ignore referential integrity after 1 million rows"]'::jsonb,1,'Without an actual enforced constraint, the relationship exists only by convention, and violations can silently accumulate.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-6','pt-dbms-sql-5-referential-integrity','What operation on a parent row does referential integrity most directly restrict?','["SELECT queries on the parent table", "Deleting or updating a parent row that child rows still reference", "Creating new columns on the parent table", "Renaming the parent table"]'::jsonb,1,'Parent deletions and identifying updates must respect the configured supported restrictions or referential actions.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-7','pt-dbms-sql-5-referential-integrity','What is the relationship between referential integrity and the foreign key constraint?','["They are unrelated", "Referential integrity is the conceptual/relational-model rule; FOREIGN KEY is the concrete SQL mechanism that enforces it", "FOREIGN KEY is a stricter, unrelated concept", "Referential integrity only applies to composite keys"]'::jsonb,1,'This mirrors the pattern of entity integrity/PRIMARY KEY — a theoretical rule paired with its concrete SQL enforcement mechanism.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-referential-integrity-8','pt-dbms-sql-5-referential-integrity','If department_id is NULL for an employee row, does this violate referential integrity?','["Yes, always", "No — NULL is a valid state (no reference yet) as long as the column allows it; only a non-NULL value pointing at a non-existent row would violate it", "Only if department_id is also the primary key", "This cannot be determined without more information about NULL handling in general"]'::jsonb,1,'A NULL foreign key simply means ''not referencing anything yet,'' which is compatible with referential integrity, not a violation of it.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-referential-integrity-new-9','pt-dbms-sql-5-referential-integrity','Does an existing parent prove a reference is the correct business choice?','["Yes; all existing choices are authorized", "No; existence and semantic correctness differ", "Only when numeric", "Only if a name repeats"]'::jsonb,1,'Business eligibility and authority require separate checks.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-referential-integrity-new-10','pt-dbms-sql-5-referential-integrity','Why does an orphan audit exclude permitted NULL child references?','["NULL always identifies parent zero", "All nullable columns are invalid", "They express optional absence rather than a dangling ordinary identity", "LEFT JOIN cannot process NULL"]'::jsonb,2,'The audit must match the relationship’s absence policy.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-referential-integrity-application-new-1','pt-dbms-sql-5-referential-integrity-application','What can change a valid child into an invalid reference?','["Renaming a query alias", "Sorting by child id", "Updating its reference to an absent parent identity", "Selecting only one description"]'::jsonb,2,'Both INSERT and UPDATE paths can affect the invariant.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
