update public.learning_topics set short_description='Read a relation schema as a contract for attributes, domains and constraints, then implement and test small SQL table definitions.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Read a relation schema as a contract for attributes, domains and constraints, then implement and test small SQL table definitions.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Relation Schema.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-4-relation-schema' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-4-relation-schema-application','MCQ Test 2',category,10,10,'Application and scenarios for Relation Schema.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-4-relation-schema' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-1','pt-dbms-sql-4-relation-schema','What does a relation schema describe?','["The actual current rows stored in a relation", "The structural blueprint: the relation''s name, attributes, and their domains", "The number of tuples currently present", "The physical disk location of the data"]'::jsonb,1,'A relation schema is the intensional/structural definition, not the data itself.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-2','pt-dbms-sql-4-relation-schema','Which of these is an example of a relation schema?','["{(1,Asha,CS,8.7),(2,Ravi,ECE,7.9)}", "Students(id, name, department, gpa)", "4 tuples with a cardinality of 4", "SELECT * FROM Students"]'::jsonb,1,'''Students(id, name, department, gpa)'' names the relation and lists its attributes — that is exactly a relation schema.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-3','pt-dbms-sql-4-relation-schema','If 5 new student rows are inserted into the Students table, what happens to the relation schema?','["It changes to reflect the 5 new rows", "It stays exactly the same; only the relation (instance/data) changes", "Its degree increases by 5", "It is deleted and recreated"]'::jsonb,1,'Inserting rows only changes the data (the relation/instance); the schema (attributes and domains) is untouched.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-4','pt-dbms-sql-4-relation-schema','How does a Relation Schema differ from a Relation?','["A relation schema is the structural blueprint; a relation is the actual set of tuples conforming to it", "They are exactly the same thing", "A relation is fixed, but a relation schema changes with every insert", "A relation schema stores values; a relation stores attribute names"]'::jsonb,0,'The schema defines structure (attributes/domains); the relation is the data instance that conforms to that structure.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-5','pt-dbms-sql-4-relation-schema','How does a Relation Schema relate to a Database Schema?','["They are unrelated concepts", "A database schema is the collection of all relation schemas (plus cross-relation constraints) in the database", "A relation schema contains many database schemas", "A database schema only applies to a single relation"]'::jsonb,1,'The database schema aggregates every relation schema in the system along with constraints spanning them.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-6','pt-dbms-sql-4-relation-schema','Which of the following counts as a change to the relation schema (not just the relation)?','["Deleting a row where gpa < 5.0", "Running ALTER TABLE Students ADD COLUMN email varchar(100)", "Updating Karan''s gpa from 6.8 to 7.0", "Inserting a new student tuple"]'::jsonb,1,'Adding a new column changes the schema''s attribute list; the other options only affect the data (the relation).',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-7','pt-dbms-sql-4-relation-schema','Can a relation schema be constrained (e.g., declare a primary key) as part of its own definition?','["No, constraints can only exist at the database schema level", "Yes, constraints like primary key or NOT NULL are part of the relation schema''s intensional definition", "No, constraints are data, not structure", "Only referential (foreign key) constraints belong to a relation schema"]'::jsonb,1,'Constraints such as PRIMARY KEY and NOT NULL are structural rules declared as part of the relation schema.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relation-schema-8','pt-dbms-sql-4-relation-schema','Is it valid for a relation schema to exist with no relation (instance) populated under it yet?','["No, a schema requires at least one tuple to be considered defined", "Yes — a schema can be validly defined with an empty (zero-tuple) instance", "Only if the schema has degree 0", "No, this would violate entity integrity"]'::jsonb,1,'A freshly created schema with no rows yet inserted still has a valid (empty) relation instance.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-new-9','pt-dbms-sql-4-relation-schema','What extra information is needed beyond Student(id, name) for an executable design?','["Only the current row count", "Types, nullability and relevant integrity constraints", "The first physical page address", "The screen row order"]'::jsonb,1,'Compact notation leaves important enforcement details implicit.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-new-10','pt-dbms-sql-4-relation-schema','What changes when ten valid rows are inserted into a three-attribute relation?','["Degree becomes thirteen", "Attribute names disappear", "Cardinality changes while degree remains three", "The schema must be recreated"]'::jsonb,2,'Insertion changes the instance, not the attribute list.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-1','pt-dbms-sql-4-relation-schema-application','Does DEFAULT active alone restrict every status to active?','["Yes; defaults are unique constraints", "Only in an empty table", "No; an explicit value can differ unless another rule forbids it", "Yes; defaults prevent all updates"]'::jsonb,2,'A default supplies omitted values rather than restricting every supplied value.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-2','pt-dbms-sql-4-relation-schema-application','Which case distinguishes a default from nullability?','["Two students have different identifiers", "A SELECT uses ORDER BY", "A table has zero rows", "Omitting status can use a default while explicit NULL is rejected by NOT NULL"]'::jsonb,3,'Omission and explicit NULL are separate inputs.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-3','pt-dbms-sql-4-relation-schema-application','Why can a primary key on student_name be inappropriate?','["Different students can legitimately share a name", "Names cannot be columns", "Primary keys must always contain three columns", "Names never change"]'::jsonb,0,'The key must follow identity and permitted facts.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-4','pt-dbms-sql-4-relation-schema-application','One enrollment per student-course pair is permitted. Which key matches that grain?','["student_id alone", "The pair student_id and course_id", "student_name alone", "The displayed row number"]'::jsonb,1,'The pair allows one student to enroll in multiple distinct courses.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-5','pt-dbms-sql-4-relation-schema-application','Repeat course attempts are valid. What can distinguish them in a composite key?','["Only student_name", "Only the physical insertion order", "An attempt number alongside student_id and course_id", "Removing every key"]'::jsonb,2,'The identity must distinguish legitimate separate attempts.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
