insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-7','pt-dbms-sql-4-relation-schema-application','Does SELECT name AS display_name rename the stored attribute?','["No; it labels the output attribute", "Yes; it executes ALTER TABLE", "Yes; it replaces every value", "Only when the table is empty"]'::jsonb,0,'A result alias is distinct from persistent schema evolution.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-4-relation-schema-application-new-8','pt-dbms-sql-4-relation-schema-application','Before adding a required attribute, what must be considered for current rows?','["Their screen positions only", "How existing tuples obtain valid values", "Whether SELECT is alphabetically sorted", "Only the number of indexes"]'::jsonb,1,'A new requirement must be satisfiable by existing data.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
