update public.learning_topics set short_description='Compose selections, projections and joins from a precise result contract, trace intermediate relation shapes, and distinguish safe logical rewrites from physical execution.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Compose selections, projections and joins from a precise result contract, trace intermediate relation shapes, and distinguish safe logical rewrites from physical execution.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Relational Algebra Expressions.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-7-relational-algebra-expressions' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-7-relational-algebra-expressions-application','MCQ Test 2',category,10,10,'Application and scenarios for Relational Algebra Expressions.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-7-relational-algebra-expressions' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-1','pt-dbms-sql-7-relational-algebra-expressions','What does a composed relational algebra expression describe?','["A single, atomic operation like Selection alone", "A relational result formed by operators whose outputs can feed later operators", "A special SQL keyword", "A type of database index"]'::jsonb,1,'A simple base or operator expression is also valid; composition builds larger expressions through closure.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-2','pt-dbms-sql-7-relational-algebra-expressions','In π(name)(σ(department = ''Engineering'')(Students)), which operation is applied FIRST?','["Projection (π), since it''s written first", "Selection (σ), since algebra notation nests inside-out like function calls", "Both are applied simultaneously", "Neither — this notation is invalid"]'::jsonb,1,'Just like nested function calls, the innermost operation (Selection here) executes first, feeding its result to the outer operation (Projection).',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-3','pt-dbms-sql-7-relational-algebra-expressions','Does the order operations are conceptually written in an algebra expression always match the order a real database engine executes them?','["Yes, always, exactly", "Not necessarily — a query optimizer can reorder operations (e.g. applying Selection before a Join) to improve performance while preserving the same correct result", "Real engines always execute right-to-left, opposite to the written order", "Execution order has no bearing on correctness or performance"]'::jsonb,1,'Query optimizers routinely reorder logically-equivalent operations for efficiency — this is covered further in Chapter 35.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-4','pt-dbms-sql-7-relational-algebra-expressions','How would you build the expression for ''names of Engineering students with GPA >= 3.5''?','["A single Projection alone is sufficient", "Select the qualifying rows first, then project onto just the name column", "Project first, then select", "Use only a Join operation"]'::jsonb,1,'Filtering to the right rows (Selection) before narrowing to the desired column (Projection) is the natural composition here.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-5','pt-dbms-sql-7-relational-algebra-expressions','Can the same real-world question be expressed by more than one equivalent relational algebra expression?','["No, there is always exactly one correct expression", "Yes — multiple equivalent expressions can answer the same question, and recognizing which is more efficient is a query-optimization skill", "Only if the question involves exactly one table", "Equivalent expressions always have identical performance"]'::jsonb,1,'Equivalent expressions preserve the defined result; performance still needs engine and workload evidence.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-6','pt-dbms-sql-7-relational-algebra-expressions','What is a reliable strategy for constructing a complex relational algebra expression (or SQL query)?','["Always write the entire expression in one attempt with no intermediate checks", "Build it incrementally from the base relations, adding one operation at a time and checking each intermediate result", "Only ever use a single operation, no matter how complex the question", "Memorize a fixed template for every possible question"]'::jsonb,1,'Incremental construction with intermediate verification is a much more reliable method than attempting the full expression at once.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-7','pt-dbms-sql-7-relational-algebra-expressions','How does a question needing data from three related tables typically get expressed?','["It cannot be expressed in relational algebra at all", "By chaining Joins between the tables (matching on shared keys), then applying Selection/Projection as needed on the combined result", "By using only Projection three times", "By using three separate, unrelated queries with no way to combine them"]'::jsonb,1,'Multi-table questions typically chain Joins to combine the data, then filter/narrow with Selection/Projection.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-expressions-8','pt-dbms-sql-7-relational-algebra-expressions','Why does SQL''s clause-based syntax feel more ''linear'' than algebra''s inside-out nested notation, despite expressing the same composition?','["SQL doesn''t actually compose multiple operations the way algebra does", "SQL clauses (FROM/JOIN, WHERE, SELECT) are written in a fixed sequential order rather than as nested function-call-style notation, even though the underlying composition of operations is equivalent", "Algebra and SQL are unrelated concepts with no correspondence", "SQL only ever supports a single operation per query"]'::jsonb,1,'SQL clause syntax differs from nested notation; SQL bags, NULL and ordering need explicit treatment rather than blanket equivalence to classical set algebra.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
