if exists(select 1 from public.test_questions where id='pt-dbms-sql-7-relational-algebra-practice-application-new-8' and (question_text,options,correct_index,explanation) is distinct from ('What does a repeated membership establish under existence semantics?','["A different club becomes satisfied", "The same relationship remains present", "A missing requirement disappears", "Every source constraint becomes enforced"]'::jsonb,1,'Repeated occurrences do not create another distinct obligation.') and (question_text,options,correct_index,explanation) is distinct from ('What does a repeated membership establish under existence semantics?','["A different club becomes satisfied", "The same relationship remains present", "A missing requirement disappears", "Every source constraint becomes enforced"]'::jsonb,1,'Repeated occurrences do not create another distinct obligation.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-7-relational-algebra-practice-application-new-8'; end if;
