update public.learning_topics set short_description='Turn student-facing questions into precise candidate populations, quantifiers and result grains, then test none, some and every using deliberate counterexamples.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Turn student-facing questions into precise candidate populations, quantifiers and result grains, then test none, some and every using deliberate counterexamples.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Relational Algebra Practice.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-7-relational-algebra-practice' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-7-relational-algebra-practice-application','MCQ Test 2',category,10,10,'Application and scenarios for Relational Algebra Practice.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-7-relational-algebra-practice' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-1','pt-dbms-sql-7-relational-algebra-practice','What is the primary skill this topic focuses on?','["Memorizing SQL syntax by rote", "Translating a plain-English question into the correct sequence of relational algebra operations / SQL clauses", "Writing database schemas from scratch", "Optimizing query execution plans"]'::jsonb,1,'This topic is specifically about the translation skill from natural language to algebra/SQL.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-2','pt-dbms-sql-7-relational-algebra-practice','A question asks ''which X have NO relationship to Y'' — which pattern does this typically signal?','["Division", "A Difference/anti-join pattern", "A plain inner join", "Cartesian Product"]'::jsonb,1,'''None of'' language points to Difference (or an anti-join / NOT EXISTS), not Division.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-3','pt-dbms-sql-7-relational-algebra-practice','A question asks ''which X relate to ALL of Y'' — which pattern does this typically signal?','["Division", "Union", "A plain Selection", "Rename"]'::jsonb,0,'''All of'' language is the classic signal for the Division operation covered in 7.12.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-4','pt-dbms-sql-7-relational-algebra-practice','Why is confusing ''none of'' with ''all of'' language a common real mistake?','["They are actually the same pattern with no meaningful difference", "They point to genuinely different operations (Difference/anti-join vs. Division) that produce very different, non-interchangeable results", "This confusion never actually happens in practice", "Both always produce identical results regardless of which pattern is used"]'::jsonb,1,'Difference and Division answer fundamentally different questions, so mixing them up produces an incorrect query.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-5','pt-dbms-sql-7-relational-algebra-practice','What should be identified before choosing the operation sequence?','["The exact column names for the final output", "The candidate population, needed source relations and intended result grain", "Whether to use UNION or INTERSECT", "The query''s expected performance characteristics"]'::jsonb,1,'Starting sources and population matter especially when absent relationships must be reported.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-6','pt-dbms-sql-7-relational-algebra-practice','If a question needs rows that exist in one relation but are unmatched in a related one, which operation category applies?','["Projection", "An absence pattern such as NOT EXISTS or a left join with a reliable non-NULL match-marker test", "Rename", "Intersection"]'::jsonb,1,'An outer join alone also returns matches; an absence condition is required to isolate unmatched candidates.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-7','pt-dbms-sql-7-relational-algebra-practice','What is a practical benefit of breaking a complex question into ''which relations, which filter, which combination''?','["It has no real benefit over guessing", "It decomposes an intimidating question into a short, tractable sequence of the well-defined operations covered in this chapter", "It guarantees the fastest possible query automatically", "It removes the need to ever use a JOIN"]'::jsonb,1,'The checklist turns an overwhelming question into a manageable, step-by-step construction process.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-7-relational-algebra-practice-8','pt-dbms-sql-7-relational-algebra-practice','Is precisely matching the columns a question asks for (Projection) usually straightforward?','["Yes, there is never any ambiguity", "It''s easy to get wrong when several plausible candidate columns exist — the exact wording of the question should be checked carefully", "Projection is not actually relevant to answering questions correctly", "Only Selection matters; Projection is optional"]'::jsonb,1,'Careful attention to exactly which columns were asked for avoids a common, easy-to-miss error.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-relational-algebra-practice-new-9','pt-dbms-sql-7-relational-algebra-practice','A student joins both science and arts. Do they have no science-club membership?','["Yes, because they also joined arts", "No", "Only if names repeat", "Only if sorted"]'::jsonb,1,'One science witness violates none.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-relational-algebra-practice-new-10','pt-dbms-sql-7-relational-algebra-practice','No clubs are required. Who satisfies every required club in an explicit students universe?','["Nobody", "Only arts members", "Every supplied student", "Only students with at least two memberships"]'::jsonb,2,'There is no missing requirement for any candidate.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
