insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relational-integrity-1','pt-dbms-sql-4-relational-integrity','What is relational integrity?','["A performance-tuning technique", "The set of rules (domain, entity, referential, and business constraints) that a legal database instance must satisfy", "A synonym for relation schema", "A method for compressing table storage"]'::jsonb,1,'Integrity rules constrain valid recorded states; they cannot alone prove factual truth or caller authorization.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relational-integrity-2','pt-dbms-sql-4-relational-integrity','Which integrity rule requires that every attribute value belong to its declared type/range of legal values?','["Entity integrity", "Referential integrity", "Domain integrity", "Codd''s Rule 12"]'::jsonb,2,'Domain integrity ensures values stored in an attribute always come from its declared domain.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
