insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-4-relational-integrity-6','pt-dbms-sql-4-relational-integrity','How does Relational Integrity differ from Relational Model Rules (Codd''s 12 Rules)?','["They are identical concepts with different names", "Relational Integrity is specifically about data-validity rules (domain/entity/referential); Relational Model Rules is the much broader checklist for what makes a whole DBMS ''truly relational''", "Relational Model Rules only apply to NULL handling", "Relational Integrity covers catalog and view-updating behavior, while Relational Model Rules covers only keys"]'::jsonb,1,'Integrity is a narrow, data-focused concern; Codd''s Rules is a comprehensive DBMS-evaluation framework that integrity is only one part of.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
