if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-relational-model-rules-1' and (question_text,options,correct_index,explanation) is distinct from ('What are ''Relational Model Rules'' most commonly a reference to?','["The SQL-92 standard syntax", "Codd''s 12 Rules (numbered 0-12), a benchmark for how relational a DBMS truly is", "A list of NULL-handling functions", "The set of ANSI-approved data types"]'::jsonb,1,'This term refers to E. F. Codd''s 12 Rules proposed in 1985 to evaluate whether a DBMS is genuinely relational.') and (question_text,options,correct_index,explanation) is distinct from ('What are ''Relational Model Rules'' most commonly a reference to?','["The SQL-92 standard syntax", "Codd''s twelve rules plus foundation rule 0, a historical relational-capability evaluation framework", "A list of NULL-handling functions", "The set of ANSI-approved data types"]'::jsonb,1,'The conventional twelve rules are numbered 1 through 12, with an additional foundation rule 0.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-relational-model-rules-1'; end if;
