if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-relational-model-rules-2' and (question_text,options,correct_index,explanation) is distinct from ('What does Rule 1 (the Information Rule) require?','["All data must be represented as values within tables (relations), and nothing else", "Every query must run in under 1 second", "NULLs must never be used", "Foreign keys are mandatory on every table"]'::jsonb,0,'The Information Rule states that all information in a relational database is represented explicitly as values in relations.') and (question_text,options,correct_index,explanation) is distinct from ('What does Rule 1 (the Information Rule) require?','["Database information is represented explicitly at the logical level through values in tables", "Every query must run in under 1 second", "NULLs must never be used", "Foreign keys are mandatory on every table"]'::jsonb,0,'The information rule describes logical representation; it does not prescribe a physical byte-storage format.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-relational-model-rules-2'; end if;
