if exists(select 1 from public.test_questions where id='tq-dbms-sql-4-relational-model-rules-4' and (question_text,options,correct_index,explanation) is distinct from ('How does Relational Integrity differ from Relational Model Rules (Codd''s 12 Rules)?','["They are the same list under different names", "Relational Integrity is a narrow set of data-validity rules; Relational Model Rules is a much broader checklist evaluating an entire DBMS''s relational completeness", "Relational Model Rules apply only to NULL handling", "Relational Integrity is broader and includes catalog and distribution rules"]'::jsonb,1,'Integrity (domain/entity/referential) is only a small part of the much larger 12-rule DBMS evaluation framework.') and (question_text,options,correct_index,explanation) is distinct from ('How does Relational Integrity differ from Relational Model Rules (Codd''s 12 Rules)?','["They are the same list under different names", "Relational Integrity is a narrow set of data-validity rules; Relational Model Rules is a much broader checklist evaluating an entire DBMS''s relational completeness", "Relational Model Rules apply only to NULL handling", "Relational Integrity is broader and includes catalog and distribution rules"]'::jsonb,1,'Integrity (domain/entity/referential) is only a small part of the much larger 12-rule DBMS evaluation framework.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-4-relational-model-rules-4'; end if;
