if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-relational-model-6' and (question_text,options,correct_index,explanation) is distinct from ('What is the ''impedance mismatch'' problem often cited as a drawback of the relational model?','["SQL queries run too slowly on large tables", "Object-oriented application code doesn''t map cleanly onto flat, normalized tables, requiring extra translation logic", "Relational databases cannot store numeric data", "Tables cannot have more than one primary key column"]'::jsonb,1,'Since application objects often have nested or list-valued attributes, mapping them to normalized relational tables requires extra joins/translation, motivating ORMs and alternative models like document stores.') and (question_text,options,correct_index,explanation) is distinct from ('What is the ''impedance mismatch'' problem often cited as a drawback of the relational model?','["SQL queries run too slowly on large tables", "Object-oriented application code doesn''t map cleanly onto flat, normalized tables, requiring extra translation logic", "Relational databases cannot store numeric data", "Tables cannot have more than one primary key column"]'::jsonb,1,'Since application objects often have nested or list-valued attributes, mapping them to normalized relational tables requires extra joins/translation, motivating ORMs and alternative models like document stores.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-relational-model-6'; end if;
