update public.learning_topics set short_description='Distinguish relations from SQL tables while tracing tuples, attributes, domains, candidate keys, association facts, declarative queries, and implementation-dependent transaction and scaling behavior.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish relations from SQL tables while tracing tuples, attributes, domains, candidate keys, association facts, declarative queries, and implementation-dependent transaction and scaling behavior.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Relational Model.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-relational-model' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-relational-model-application','MCQ Test 2',category,10,10,'Application and scenarios for Relational Model.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-relational-model' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-1','pt-dbms-sql-3-relational-model','Who introduced the relational model and in what year?','["Edgar F. Codd, 1970", "Charles Bachman, 1969", "Michael Stonebraker, 1980", "Ted Codd, 1985"]'::jsonb,0,'E. F. Codd published the foundational relational model paper in 1970 while at IBM.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-2','pt-dbms-sql-3-relational-model','In the relational model, what is a ''tuple''?','["A column name", "A single row in a table", "A database index", "A stored procedure"]'::jsonb,1,'A tuple corresponds to a single row of a relation (table), representing one record with values for each attribute.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-3','pt-dbms-sql-3-relational-model','What separation does declarative relational querying aim to support?','["It requires more storage space", "The requested logical result is described separately from a particular physical navigation plan", "It cannot represent one-to-many relationships", "It does not support keys or constraints"]'::jsonb,1,'Actual queries can still depend on schema and implementation features.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-4','pt-dbms-sql-3-relational-model','How does the relational model represent a many-to-many relationship, such as students enrolling in multiple courses?','["By duplicating student records under each course", "Using a junction/associative table with foreign keys to both related tables", "By nesting course documents inside student documents", "It cannot represent many-to-many relationships"]'::jsonb,1,'A junction table like Enrollments(student_id, course_id) cleanly represents many-to-many relationships without duplication, unlike hierarchical trees.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-5','pt-dbms-sql-3-relational-model','What does ''ACID'' stand for in the context of relational database transactions?','["Atomicity, Consistency, Isolation, Durability", "Access, Concurrency, Indexing, Distribution", "Aggregation, Caching, Integrity, Denormalization", "Availability, Consistency, Idempotency, Durability"]'::jsonb,0,'ACID properties (Atomicity, Consistency, Isolation, Durability) are the transactional guarantees traditionally associated with relational databases.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-6','pt-dbms-sql-3-relational-model','What is the ''impedance mismatch'' problem often cited as a drawback of the relational model?','["SQL queries run too slowly on large tables", "Object-oriented application code doesn''t map cleanly onto flat, normalized tables, requiring extra translation logic", "Relational databases cannot store numeric data", "Tables cannot have more than one primary key column"]'::jsonb,1,'Since application objects often have nested or list-valued attributes, mapping them to normalized relational tables requires extra joins/translation, motivating ORMs and alternative models like document stores.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-7','pt-dbms-sql-3-relational-model','Why might normalized relations and embedded documents have different read costs?','["Relational databases cannot use indexes", "They organize required facts differently, and actual performance depends on the workload and implementation", "SQL cannot filter on multiple conditions", "Relational tables cannot store text fields"]'::jsonb,1,'Neither model is a universal winner; measure the operation and guarantees required.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-model-8','pt-dbms-sql-3-relational-model','Is horizontal distribution categorically prohibited by the relational model?','["They cannot enforce data integrity", "No; scaling capabilities depend on the actual product and deployment", "They cannot support transactions", "They cannot store more than one table"]'::jsonb,1,'Distributed relational and SQL systems exist; a model label does not fix deployment topology.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-model-new-9','pt-dbms-sql-3-relational-model','What does a candidate key identify under the model''s intended rules?','["The first physical page", "A tuple through a minimal unique attribute set", "Every current display label automatically", "A particular network route"]'::jsonb,1,'Candidate key minimality and uniqueness concern logical identity.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-model-new-10','pt-dbms-sql-3-relational-model','Does a table-shaped display prove all mathematical relation properties hold?','["Yes; rectangles guarantee uniqueness", "Only if column names are short", "No; SQL duplicates, NULL, and constraints need explicit review", "Only if the client uses a dark theme"]'::jsonb,2,'Practical SQL behavior must be distinguished from the mathematical model.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
