if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-relational-vs-nosql-1' and (question_text,options,correct_index,explanation) is distinct from ('What does the term ''NoSQL'' most accurately refer to?','["A single specific database product", "An umbrella term for the family of non-relational data models: document, key-value, column-family, and graph", "A query language that replaced SQL entirely", "A model that only stores numeric data"]'::jsonb,1,'NoSQL is not one model but an umbrella covering multiple distinct non-relational paradigms, each with different trade-offs.') and (question_text,options,correct_index,explanation) is distinct from ('What does the term ''NoSQL'' most accurately refer to?','["A single specific database product", "An umbrella term for the family of non-relational data models: document, key-value, column-family, and graph", "A query language that replaced SQL entirely", "A model that only stores numeric data"]'::jsonb,1,'NoSQL is not one model but an umbrella covering multiple distinct non-relational paradigms, each with different trade-offs.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-relational-vs-nosql-1'; end if;
