if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-relational-vs-nosql-3' and (question_text,options,correct_index,explanation) is distinct from ('What does the BASE consistency model (often associated with distributed NoSQL systems) stand for?','["Basically Available, Soft state, Eventual consistency", "Binary Atomic Strict Execution", "Backup Available, Synchronized, Encrypted", "Batch Access, Single Endpoint"]'::jsonb,0,'BASE stands for Basically Available, Soft state, Eventual consistency — a deliberate trade favoring availability over the strict guarantees of ACID.') and (question_text,options,correct_index,explanation) is distinct from ('What does the BASE consistency model (often associated with distributed NoSQL systems) stand for?','["Basically Available, Soft state, Eventual consistency", "Binary Atomic Strict Execution", "Backup Available, Synchronized, Encrypted", "Batch Access, Single Endpoint"]'::jsonb,0,'BASE stands for Basically Available, Soft state, Eventual consistency — a deliberate trade favoring availability over the strict guarantees of ACID.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-relational-vs-nosql-3'; end if;
