if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-relational-vs-nosql-5' and (question_text,options,correct_index,explanation) is distinct from ('Why do relational databases traditionally scale vertically rather than horizontally?','["Because SQL cannot run on multiple servers under any circumstances", "Because joins and ACID transactions across a normalized schema are hard to distribute correctly across many independent nodes", "Because relational databases are always faster on a single machine regardless of workload", "Because horizontal scaling was not invented until after SQL"]'::jsonb,1,'Maintaining ACID guarantees and efficient joins across a normalized schema is difficult to distribute cleanly, which historically pushed relational systems toward scaling up rather than out.') and (question_text,options,correct_index,explanation) is distinct from ('Does the relational model categorically forbid horizontal distribution?','["Because SQL cannot run on multiple servers under any circumstances", "No; actual coordination, partitioning, and product capabilities determine distribution behavior", "Because relational databases are always faster on a single machine regardless of workload", "Because horizontal scaling was not invented until after SQL"]'::jsonb,1,'Distributed SQL implementations exist; model labels do not fix topology.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-relational-vs-nosql-5'; end if;
