if exists(select 1 from public.test_questions where id='tq-dbms-sql-3-relational-vs-nosql-6' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is a scenario where a relational database is generally the better choice over NoSQL alternatives?','["Petabyte-scale IoT sensor telemetry ingestion", "A banking ledger requiring strong ACID consistency and complex ad-hoc joins", "A simple session cache needing sub-millisecond key lookups", "A social network requiring deep friend-of-friend traversal"]'::jsonb,1,'Banking ledgers need strong consistency and support complex evolving queries across normalized data, which plays to the relational model''s strengths.') and (question_text,options,correct_index,explanation) is distinct from ('What should guide a choice for a ledger-like workflow requiring shared integrity and atomic updates?','["Petabyte-scale IoT sensor telemetry ingestion", "Verified transaction, integrity, access, and operational guarantees for the actual workflow", "A simple session cache needing sub-millisecond key lookups", "A social network requiring deep friend-of-friend traversal"]'::jsonb,1,'Do not assume every relational configuration supplies the needed behavior or every NoSQL product lacks it.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-3-relational-vs-nosql-6'; end if;
