update public.learning_topics set short_description='Compare concrete data and consistency contracts across relational and NoSQL products, avoiding model stereotypes about schema, transactions, CAP, scaling, and performance.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Compare concrete data and consistency contracts across relational and NoSQL products, avoiding model stereotypes about schema, transactions, CAP, scaling, and performance.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Relational vs NoSQL.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-3-relational-vs-nosql' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-3-relational-vs-nosql-application','MCQ Test 2',category,10,10,'Application and scenarios for Relational vs NoSQL.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-3-relational-vs-nosql' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-1','pt-dbms-sql-3-relational-vs-nosql','What does the term ''NoSQL'' most accurately refer to?','["A single specific database product", "An umbrella term for the family of non-relational data models: document, key-value, column-family, and graph", "A query language that replaced SQL entirely", "A model that only stores numeric data"]'::jsonb,1,'NoSQL is not one model but an umbrella covering multiple distinct non-relational paradigms, each with different trade-offs.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-2','pt-dbms-sql-3-relational-vs-nosql','What does ''schema-on-write'' mean, as typically practiced by relational databases?','["The schema is only checked when data is read", "The table structure is defined and enforced before data is inserted", "There is no schema at all", "Schema changes never require a migration"]'::jsonb,1,'Schema-on-write means the structure must be defined and validated at write/insert time, contrasting with schema-on-read used by many NoSQL document stores.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-3','pt-dbms-sql-3-relational-vs-nosql','What does the BASE consistency model (often associated with distributed NoSQL systems) stand for?','["Basically Available, Soft state, Eventual consistency", "Binary Atomic Strict Execution", "Backup Available, Synchronized, Encrypted", "Batch Access, Single Endpoint"]'::jsonb,0,'BASE stands for Basically Available, Soft state, Eventual consistency — a deliberate trade favoring availability over the strict guarantees of ACID.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-4','pt-dbms-sql-3-relational-vs-nosql','Under the CAP model, what tension arises during a network partition?','["The specified consistency and availability guarantees cannot both be maintained for all required requests under the theorem assumptions", "Cost and Performance", "Schema and Storage", "Security and Speed"]'::jsonb,0,'CAP consistency is not simply every business rule or ACID consistency, and the result is not a choose-any-two-forever slogan.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-5','pt-dbms-sql-3-relational-vs-nosql','Does the relational model categorically forbid horizontal distribution?','["Because SQL cannot run on multiple servers under any circumstances", "No; actual coordination, partitioning, and product capabilities determine distribution behavior", "Because relational databases are always faster on a single machine regardless of workload", "Because horizontal scaling was not invented until after SQL"]'::jsonb,1,'Distributed SQL implementations exist; model labels do not fix topology.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-6','pt-dbms-sql-3-relational-vs-nosql','What should guide a choice for a ledger-like workflow requiring shared integrity and atomic updates?','["Petabyte-scale IoT sensor telemetry ingestion", "Verified transaction, integrity, access, and operational guarantees for the actual workflow", "A simple session cache needing sub-millisecond key lookups", "A social network requiring deep friend-of-friend traversal"]'::jsonb,1,'Do not assume every relational configuration supplies the needed behavior or every NoSQL product lacks it.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-7','pt-dbms-sql-3-relational-vs-nosql','Does Cassandra CQL''s SQL-like appearance make its behavior identical to a relational database?','["Yes, CQL syntax guarantees identical consistency and query capabilities to SQL", "No; its supported model, access patterns, and operation guarantees need their own review", "Yes, because CQL supports arbitrary multi-table joins just like SQL", "No, because CQL cannot filter data at all"]'::jsonb,1,'Syntax resemblance does not establish semantic or operational equivalence.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-3-relational-vs-nosql-8','pt-dbms-sql-3-relational-vs-nosql','Does IoT telemetry alone prove a wide-column engine is the best choice?','["No; evaluate the actual keys, queries, consistency, volume, and operational requirements", "Pure hierarchical model", "Object-oriented model", "Graph model"]'::jsonb,0,'A common use case is not a universal product recommendation.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-new-9','pt-dbms-sql-3-relational-vs-nosql','Does flexible document structure imply no possible write validation?','["Yes; all documents are unvalidated", "No", "Only relational JSON can have rules", "Only if a key is absent"]'::jsonb,1,'Real systems can combine optional fields with enforced requirements.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-new-10','pt-dbms-sql-3-relational-vs-nosql','What does a verified capability matrix need to distinguish?','["Only product logos", "Only query indentation", "Actual support evidence from an untested assertion", "Only the number of columns in a demo"]'::jsonb,2,'A claimed feature is not the same as verified support.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-1','pt-dbms-sql-3-relational-vs-nosql-application','A workflow needs atomic multi-record updates. What should selection inspect?','["Only whether the product is called NoSQL", "Only whether its syntax uses SELECT", "The exact supported transaction boundary and failure behavior", "Only whether a demo read is fast"]'::jsonb,2,'Capabilities depend on product, configuration, and operation.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-2','pt-dbms-sql-3-relational-vs-nosql-application','An authoritative count is 12 but a snapshot says 10. What needs evaluation?','["Only the model label", "Only the database file name", "Only the visible table width", "Freshness policy and the cause of the mismatch"]'::jsonb,3,'A concrete inconsistency needs a contract and diagnosis.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-3','pt-dbms-sql-3-relational-vs-nosql-application','Two implementations differ in required returned facts. Is a latency comparison automatically equivalent?','["No", "Yes; any faster response wins", "Only if both use SQL", "Only if the sample is small"]'::jsonb,0,'Performance must be compared for the same result and guarantees.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
