insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-5','pt-dbms-sql-3-relational-vs-nosql-application','A database commits an order. What does that alone not prove about an external charge?','["That local work had a transaction", "That a source record can exist", "That the remote provider effect participated atomically", "That a workflow has requirements"]'::jsonb,2,'Cross-system authority and coordination are separate boundaries.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-6','pt-dbms-sql-3-relational-vs-nosql-application','A small service fits its existing database. What cost should justify adding another engine?','["Only a fashionable model name", "Only a larger benchmark screenshot", "Only a desire for more servers", "A demonstrated unmet requirement weighed against operational complexity"]'::jsonb,3,'Use the smallest adequate verified design.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-7','pt-dbms-sql-3-relational-vs-nosql-application','A store is marked unverified despite claimed joins and transactions. Should the fixture treat it as a verified candidate?','["No", "Yes; claims are enough", "Only if its name sounds relational", "Only if it has a fast connection"]'::jsonb,0,'The decision rule requires evidence status as well as capability flags.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-8','pt-dbms-sql-3-relational-vs-nosql-application','A cache row exists but its count is NULL. Is that the same as no cache row?','["Yes; every missing value has one cause", "No", "Only if the source count is zero", "Only if IDs match"]'::jsonb,1,'A missing projection and an unknown projection value are distinct states.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-3-relational-vs-nosql-application-new-9','pt-dbms-sql-3-relational-vs-nosql-application','A native product has an SQL-like language. What should not be inferred?','["That its grammar may be documented", "That it supports some statements", "Identical model, query, and consistency semantics", "That its actual features can be tested"]'::jsonb,2,'Familiar spelling does not guarantee equivalence.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
