update public.learning_topics set short_description='Distinguish relationship arity from row and column counts, preserve genuine ternary facts, and reject participant triples that are not supported by one complete assignment.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Distinguish relationship arity from row and column counts, preserve genuine ternary facts, and reject participant triples that are not supported by one complete assignment.';
