insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-1','pt-dbms-sql-6-relationship-degree','In the introductory ER convention used here, what does relationship degree classify?','["The number of instances that can relate to each other", "The participating entity categories, with self-associations described as unary or recursive in this convention", "Whether participation is mandatory", "The number of attributes on the relationship"]'::jsonb,1,'Distinguish this classification from role-based arity treatments and SQL relation attribute count.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-2','pt-dbms-sql-6-relationship-degree','What is the degree of the relationship Enrolls_In, connecting Student and Course?','["1 (unary)", "2 (binary)", "3 (ternary)", "It depends on the cardinality"]'::jsonb,1,'Two entity sets (Student, Course) participate, making it a binary (degree 2) relationship.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-3','pt-dbms-sql-6-relationship-degree','In the introductory one-participating-type convention, how is an Employee self-association described?','["A weak relationship", "A recursive relationship, connecting an entity set to itself", "An identifying relationship", "A derived relationship"]'::jsonb,1,'The association is called unary or recursive here, while its two participant roles remain distinct.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-4','pt-dbms-sql-6-relationship-degree','Which best distinguishes relationship degree from cardinality?','["They are the same concept", "Degree classifies association structure; cardinality ratio describes permitted participant multiplicities", "Cardinality counts entity sets; degree counts instances", "Degree only applies to binary relationships"]'::jsonb,1,'Neither is simply the current count of stored relationship instances.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-5','pt-dbms-sql-6-relationship-degree','Why can a genuine ternary relationship like Teaches(Faculty, Course, Semester) NOT always be safely replaced by three separate binary relationships?','["Because SQL forbids ternary relationships", "Because splitting it can lose information about which specific triples of Faculty+Course+Semester are jointly valid", "Because ternary relationships cannot have attributes", "Because binary relationships are always faster to query"]'::jsonb,1,'Decomposing a true ternary association into pairwise binaries can allow reconstructing combinations that were never actually valid together, losing the original constraint.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-6','pt-dbms-sql-6-relationship-degree','Is a binary relationship (degree 2) necessarily 1:1 in cardinality?','["Yes, always", "No — a binary relationship''s degree is independent of its cardinality, which can be 1:1, 1:N, or M:N", "Only if both entity sets are weak", "Only in recursive relationships"]'::jsonb,1,'Degree (2, binary) says nothing about cardinality; these are separate dimensions of the relationship.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-7','pt-dbms-sql-6-relationship-degree','Under this lesson’s introductory convention, what degree label describes Employee Manages Employee?','["0", "1", "2", "It cannot be determined"]'::jsonb,1,'One entity category participates in distinct manager and subordinate roles, so this convention calls it unary.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-relationship-degree-8','pt-dbms-sql-6-relationship-degree','Why should a relationship involving four relevant participant categories be reviewed carefully rather than split into arbitrary pairs?','["They are forbidden by the ER model", "The joint meaning and constraints can be harder to express, but any simplification must preserve the intended information", "They can never have attributes", "They automatically violate entity integrity"]'::jsonb,1,'Higher degree is not automatically wrong. An intermediate occurrence identity or justified decomposition can help when it preserves the actual facts.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-relationship-degree-new-9','pt-dbms-sql-6-relationship-degree','Does a binary relationship necessarily have one-to-one cardinality?','["Yes; binary means exactly one on each side", "No; degree and permitted multiplicity are independent", "Only when names repeat", "Only for empty sets"]'::jsonb,1,'A binary association can support several cardinality ratios.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-relationship-degree-new-10','pt-dbms-sql-6-relationship-degree','A binary enrollment table has four columns. What does four measure?','["The number of entity categories always", "The number of students", "Its relational attribute count, not necessarily ER relationship degree", "The maximum enrollments"]'::jsonb,2,'SQL relation degree and conceptual association degree differ.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-relationship-degree-application-new-1','pt-dbms-sql-6-relationship-degree-application','Why is (1,10,200) unsupported by true triples (1,10,100), (1,20,200), (2,10,200)?','["Its individual values never occur", "Its pairs are all absent", "No recorded row binds that complete triple", "Every semester must be globally unique"]'::jsonb,2,'Pairwise occurrence does not establish joint occurrence.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
