update public.learning_topics set short_description='Rename persistent object labels deliberately, distinguish query aliases from DDL, and verify preserved data without assuming consumers or concurrent workloads are automatically compatible.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Rename persistent object labels deliberately, distinguish query aliases from DDL, and verify preserved data without assuming consumers or concurrent workloads are automatically compatible.';
