insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-1','pt-dbms-sql-9-rename-statement','What is preserved when you rename a table using ALTER TABLE ... RENAME TO?','["Nothing — all data is lost", "The data and indexes; only the object''s name changes", "Only the indexes, not the data", "Only the data, not the indexes"]'::jsonb,1,'Renaming updates the catalog''s name mapping while data and indexes remain intact.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-2','pt-dbms-sql-9-rename-statement','Which SQL Server procedure is used to rename a table or column?','["ALTER RENAME", "sp_rename", "RENAME OBJECT", "MODIFY TABLE"]'::jsonb,1,'SQL Server uses the sp_rename system stored procedure for renaming objects.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-3','pt-dbms-sql-9-rename-statement','Why review dependent view and routine definitions after a table rename?','["The view is automatically renamed too", "Name-based or stored references may not remain compatible automatically under the target engine", "MySQL blocks all renames if any view exists", "Views are unaffected in every MySQL version"]'::jsonb,1,'Avoid an unsupported claim tied only to older MySQL SELECT-star caching.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-4','pt-dbms-sql-9-rename-statement','When might an old-name compatibility view help?','["To improve query performance", "When its tested interface supports the intended old readers during a defined migration", "Because views are required by SQL syntax after a rename", "To reduce storage usage"]'::jsonb,1,'It does not automatically preserve every write, metadata or access behaviour.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-5','pt-dbms-sql-9-rename-statement','Does avoiding a row-copy rewrite guarantee an instant rename?','["Yes, always", "No; metadata locking and operation-specific restrictions can still matter", "Only if the table has more than one index", "Only on PostgreSQL"]'::jsonb,1,'Physical row-copy cost and observed interruption differ.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-6','pt-dbms-sql-9-rename-statement','What is a real risk when renaming a column that is used inside stored procedures or ORM model definitions?','["No risk — all references update automatically everywhere", "Those references are not automatically updated and can cause runtime errors discovered later", "The stored procedures are automatically deleted", "The rename operation itself will fail immediately"]'::jsonb,1,'A rename doesn''t retroactively fix hardcoded references in procedures, triggers, or application code.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-7','pt-dbms-sql-9-rename-statement','Why can a metadata-based rename still affect busy workloads?','["It requires a full table scan", "Coordination and metadata-lock waits can block or delay supported operations", "It always drops and recreates all indexes", "It forces a database restart"]'::jsonb,1,'Do not promise a universally brief exclusive lock interval.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-rename-statement-8','pt-dbms-sql-9-rename-statement','In general, do foreign key constraints continue to function correctly after the referenced table is renamed?','["No, foreign keys are always dropped by a rename", "Generally yes, since most engines track the relationship by internal object identity rather than by name alone, but this should be verified per engine/version", "Only if the constraint is manually recreated after every rename", "Only in MySQL"]'::jsonb,1,'Most engines track foreign keys internally rather than purely by name, so they typically survive a rename, though verification per engine is wise.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
