insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-rename-preserve-labels',null::text,'Rename the supplied temporary table without replacing its rows','Easy','rename-preserve-labels','Use ALTER TABLE to rename TEMPORARY old_labels to current_labels. Return item_id and label from current_labels without changing supplied rows.

**MySQL dialect.**

```sql
CREATE TEMPORARY TABLE old_labels (item_id INT PRIMARY KEY, label VARCHAR(40) NOT NULL);
INSERT INTO old_labels VALUES (2,''Arts''),(1,''Science'');
```

**Required ordering:** Ascending item_id.

**Edge cases:**
- An empty table remains empty under the new name.
- Repeated labels with different identifiers remain distinct rows.','[{"input": "INSERT INTO old_labels VALUES (2,''Arts''),(1,''Science'');", "output": "item_id\tlabel\n1\tScience\n2\tArts", "explanation": "The same supplied population becomes accessible through its new table name."}]'::jsonb,'[{"seed_sql": "", "expected": "", "hidden": true}, {"seed_sql": "INSERT INTO old_labels VALUES (8,''Same''),(7,''Same'');", "expected": "item_id\tlabel\n7\tSame\n8\tSame", "hidden": true}]'::jsonb,'["Preserve identifiers, labels and definition.", "Use the supplied temporary object only."]'::jsonb,'["ALTER the existing object rather than copying a memorized sample.", "Read using the final name."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The same supplied population becomes accessible through its new table name.','{"sql": "ALTER TABLE old_labels RENAME TO current_labels; SELECT item_id,label FROM current_labels ORDER BY item_id;"}'::jsonb,'The same supplied population becomes accessible through its new table name.',array['sql'],'CREATE TEMPORARY TABLE old_labels (item_id INT PRIMARY KEY, label VARCHAR(40) NOT NULL);','INSERT INTO old_labels VALUES (2,''Arts''),(1,''Science'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-9-rename-statement' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cx-rename-staged-swap' or slug='rename-staged-swap') and (id<>'cx-rename-staged-swap' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cx-rename-staged-swap'; end if;
if exists(select 1 from public.dsa_problems where id='cx-rename-staged-swap' and description is distinct from 'In this disposable single-session exercise, swap the names of TEMPORARY blue and green using a free transition name swap_hold and ALTER TABLE statements. Return final_name and marker from both final names, preserving all occurrences. This staged sequence is not asserted atomic for concurrent consumers.

**MySQL dialect.**

```sql
CREATE TEMPORARY TABLE blue (marker VARCHAR(40) NOT NULL); CREATE TEMPORARY TABLE green (marker VARCHAR(40) NOT NULL);
INSERT INTO blue VALUES (''B1''),(''B2''); INSERT INTO green VALUES (''G1'');
```

**Required ordering:** Ascending final_name, marker.

**Edge cases:**
- One source can be empty.
- Repeated source markers remain repeated.') then raise exception 'New coding ID already has other content: %', 'cx-rename-staged-swap'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-rename-staged-swap',null::text,'Trace a single-session temporary name swap','Medium','rename-staged-swap','In this disposable single-session exercise, swap the names of TEMPORARY blue and green using a free transition name swap_hold and ALTER TABLE statements. Return final_name and marker from both final names, preserving all occurrences. This staged sequence is not asserted atomic for concurrent consumers.

**MySQL dialect.**

```sql
CREATE TEMPORARY TABLE blue (marker VARCHAR(40) NOT NULL); CREATE TEMPORARY TABLE green (marker VARCHAR(40) NOT NULL);
INSERT INTO blue VALUES (''B1''),(''B2''); INSERT INTO green VALUES (''G1'');
```

**Required ordering:** Ascending final_name, marker.

**Edge cases:**
- One source can be empty.
- Repeated source markers remain repeated.','[{"input": "INSERT INTO blue VALUES (''B1''),(''B2''); INSERT INTO green VALUES (''G1'');", "output": "final_name\tmarker\nblue\tG1\ngreen\tB1\ngreen\tB2", "explanation": "The transition name resolves the collision while the selected final labels expose where each source population ended."}]'::jsonb,'[{"seed_sql": "INSERT INTO blue VALUES (''B''),(''B'');", "expected": "final_name\tmarker\ngreen\tB\ngreen\tB", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["The transition name is initially unoccupied.", "Do not modify source marker values."]'::jsonb,'["Free the occupied destination by moving the first table to the transition name.", "Track source populations after each step."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The transition name resolves the collision while the selected final labels expose where each source population ended.','{"sql": "ALTER TABLE blue RENAME TO swap_hold; ALTER TABLE green RENAME TO blue; ALTER TABLE swap_hold RENAME TO green; SELECT ''blue'' AS final_name,marker FROM blue UNION ALL SELECT ''green'' AS final_name,marker FROM green ORDER BY final_name,marker;"}'::jsonb,'The transition name resolves the collision while the selected final labels expose where each source population ended.',array['sql'],'CREATE TEMPORARY TABLE blue (marker VARCHAR(40) NOT NULL); CREATE TEMPORARY TABLE green (marker VARCHAR(40) NOT NULL);','INSERT INTO blue VALUES (''B1''),(''B2''); INSERT INTO green VALUES (''G1'');',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-9-rename-statement' on conflict(id) do nothing;
