insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-rename-application-new-9','pt-dbms-sql-7-rename-application','Why qualify two different sources both containing id?','["To prove the ids are semantically related", "To enforce every foreign key", "To identify which role the expression references", "To delete ambiguous source data"]'::jsonb,2,'Qualification resolves source meaning, not domain validity.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-7-rename-application-new-10','pt-dbms-sql-7-rename-application','What must be explicit for stable result presentation?','["A label beginning with first", "The alias a", "A short column name", "An appropriate outer ORDER BY"]'::jsonb,3,'Names do not establish row order.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
