if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-schema-evolution-2' and (question_text,options,correct_index,explanation) is distinct from ('What do tools like Flyway and Liquibase provide for schema evolution?','["Automatic query optimization", "Tracking of schema changes as an ordered, versioned sequence of scripts applied consistently across environments", "A replacement for SQL entirely", "Automatic data visualization"]'::jsonb,1,'Migration tools track and apply versioned schema change scripts in order, ensuring consistency across environments.') and (question_text,options,correct_index,explanation) is distinct from ('What do tools like Flyway and Liquibase provide for schema evolution?','["Automatic query optimization", "Tracking of schema changes as an ordered, versioned sequence of scripts applied consistently across environments", "A replacement for SQL entirely", "Automatic data visualization"]'::jsonb,1,'Migration tools track and apply versioned schema change scripts in order, ensuring consistency across environments.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-schema-evolution-2'; end if;
