if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-schema-evolution-3' and (question_text,options,correct_index,explanation) is distinct from ('In the expand-contract pattern for renaming a live column, what is the correct high-level order of steps?','["Drop old column, then add new column, then backfill", "Add new column, dual-write to both, backfill, switch reads to new column, then drop old column", "Rename the column directly in one atomic step while the app is live", "Backfill first, then create the table"]'::jsonb,1,'Expand-contract adds new structure first, transitions gradually, and removes old structure only once safe.') and (question_text,options,correct_index,explanation) is distinct from ('What must an expand-and-contract transition coordinate?','["Drop old column, then add new column, then backfill", "Compatible expansion, relevant writers, controlled backfill, validated reads and eventual retirement of the old interface", "Rename the column directly in one atomic step while the app is live", "Backfill first, then create the table"]'::jsonb,1,'Dual-write is one possible implementation, not a universal complete consistency solution.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-schema-evolution-3'; end if;
