if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-schema-evolution-4' and (question_text,options,correct_index,explanation) is distinct from ('Why is directly renaming a column in one step risky for a live, actively-deployed application?','["It is never risky", "The application code change must deploy at the exact same instant as the schema change, which rolling deployments can''t guarantee, causing brief breakage", "SQL does not support column renames", "It always corrupts the entire database"]'::jsonb,1,'During a rolling deploy some instances will briefly run mismatched code/schema versions if the change isn''t done gradually.') and (question_text,options,correct_index,explanation) is distinct from ('Why can an immediate live column rename break clients?','["It is never risky", "Supported older callers may still refer to the old name during the overlap period", "SQL does not support column renames", "It always corrupts the entire database"]'::jsonb,1,'A compatible adapter can sometimes help, but the transition needs evidence.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-schema-evolution-4'; end if;
