if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-schema-evolution-5' and (question_text,options,correct_index,explanation) is distinct from ('How does PostgreSQL''s support for transactional DDL benefit multi-step migrations, compared to MySQL?','["It has no practical benefit", "A failed multi-statement migration can be rolled back as a single unit in Postgres, whereas MySQL''s implicit per-statement commits can leave a partially-applied state", "MySQL migrations are always safer as a result", "PostgreSQL cannot run more than one DDL statement per migration"]'::jsonb,1,'Transactional DDL lets Postgres cleanly roll back a whole failed migration, unlike MySQL''s auto-committing DDL.') and (question_text,options,correct_index,explanation) is distinct from ('Why must transactional-DDL claims identify the actual statements?','["It has no practical benefit", "Engines have different commit boundaries and some administrative commands fall outside ordinary transaction blocks", "MySQL migrations are always safer as a result", "PostgreSQL cannot run more than one DDL statement per migration"]'::jsonb,1,'PostgreSQL support for many table changes does not include every command.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-schema-evolution-5'; end if;
