update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for SELECT.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-12-select' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-select-application','MCQ Test 2',category,10,10,'Application and scenarios for SELECT.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-12-select' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-1','pt-dbms-sql-12-select','What does SELECT do?','["Modifies data", "Retrieves data from one or more tables", "Deletes a table", "Creates an index"]'::jsonb,1,'SELECT is the read/retrieval statement in SQL.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-2','pt-dbms-sql-12-select','What does SELECT * FROM products return?','["Only the first column", "Every column of every row in products", "Only distinct rows", "A count of rows"]'::jsonb,1,'The asterisk requests all columns.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-3','pt-dbms-sql-12-select','Can a SELECT column list include a computed expression, not just raw columns?','["No, only column names are allowed", "Yes — expressions like price * 1.18 AS price_with_tax are valid and common", "Only in the WHERE clause, never SELECT", "Only aggregate functions can appear in SELECT"]'::jsonb,1,'SELECT can compute values, not just retrieve stored ones, as long as one value per row results.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-4','pt-dbms-sql-12-select','What determines the ORDER of columns in a SELECT''s output?','["The table''s physical column storage order, always", "The order the columns are written in the SELECT list", "Alphabetical order automatically", "It is randomized each time"]'::jsonb,1,'Output column order follows the SELECT list, independent of the table''s underlying column order.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-5','pt-dbms-sql-12-select','Why is SELECT * considered risky in production application code?','["It is always slower than naming columns by a large fixed amount", "It silently changes shape if the table''s columns change later, and returns unnecessary data", "SELECT * is not valid SQL", "It can only be used with exactly one table"]'::jsonb,1,'Implicit dependence on the table''s current shape is the core risk of SELECT * in real code.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-6','pt-dbms-sql-12-select','Is `SELECT 2 + 2;` (no FROM clause) valid in some dialects?','["No, FROM is always mandatory", "Yes, in dialects that support it — useful for evaluating a plain expression", "Only if a table named ''dual'' exists", "This always returns an error in every dialect"]'::jsonb,1,'Several dialects (e.g. MySQL, PostgreSQL) allow SELECT without FROM for expression-only queries.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-7','pt-dbms-sql-12-select','Can an alias given with AS be used to rename a SELECT column in the output?','["No, aliases only apply to tables", "Yes — AS renames the output column, purely for display/readability", "Aliases change the underlying stored column name", "AS is required for every column"]'::jsonb,1,'AS provides a friendlier or clearer name for the result column without touching the schema.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-12-select-8','pt-dbms-sql-12-select','Does a plain SELECT that only reads table columns and uses ordinary expressions change their stored values?','["Yes, it must update every returned row", "No; this retrieval query only reads the stored data", "Only if ORDER BY is included", "Only for aggregate queries"]'::jsonb,1,'These ordinary retrieval expressions do not assign new stored values. Do not generalize this to side-effecting functions, locking clauses, or output-to-file features.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-1-9','pt-dbms-sql-12-select','Can a WHERE condition use a source column that is absent from the SELECT list?','["No; every filter column must be displayed", "Only if SELECT * is used", "Only when the table is empty", "Yes; the filter and output list serve different purposes"]'::jsonb,3,'WHERE chooses rows; the SELECT list chooses returned values. A stock condition can be used without returning stock.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-1-10','pt-dbms-sql-12-select','Why add a unique identifier after a computed value in ORDER BY?','["It changes the stored primary key", "It gives a deterministic order when computed values tie", "It removes every duplicate product name", "It replaces the WHERE condition"]'::jsonb,1,'A unique secondary sort key resolves ties in the first sort expression.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-1','pt-dbx2-select-application','Using the notes'' catalog, how many rows does SELECT product_name FROM products return without DISTINCT?','["Four", "Two", "Three", "One"]'::jsonb,0,'There are four source rows and no filter or duplicate-removal clause. Both Pen values remain.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-2','pt-dbx2-select-application','What is the output column order for SELECT product_name, product_id FROM products?','["Identifier first, name second", "Name first, identifier second", "Alphabetical column-name order", "The order changes randomly each run"]'::jsonb,1,'The SELECT list defines the output order independently of the table definition.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-3','pt-dbx2-select-application','Which products remain after WHERE unit_price IS NOT NULL AND stock > 0 in the notes'' data?','["Every product", "Only Folder 3", "Notebook 1 and Pen 4", "Pen 2 and Folder 3"]'::jsonb,2,'Notebook and Pen 4 have known prices and positive stock. Pen 2 has zero stock, and Folder has an unknown price.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-4','pt-dbx2-select-application','What stock_value is calculated for Notebook with price 40.00 and stock 3?','["120.00", "43.00", "13.33", "40.00"]'::jsonb,0,'The expression multiplies price by quantity: 40.00 times 3 equals 120.00.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-5','pt-dbx2-select-application','A query calculates unit_price * stock AS stock_value. What happens to the stored unit_price?','["It is replaced by stock_value", "It becomes NULL automatically", "It remains unchanged by this plain retrieval query", "It is renamed to stock_value"]'::jsonb,2,'The expression computes a result value; it does not assign a new value to the source column.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-6','pt-dbx2-select-application','An application uses SELECT * and a new table column is later added. What contract risk arises?','["The query must always become syntactically invalid", "The result can contain an additional column without a query-text change", "Every row is automatically deleted", "The added column is guaranteed to be hidden"]'::jsonb,1,'An asterisk depends on the table''s current column set. Explicit lists make the requested shape deliberate.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-7','pt-dbx2-select-application','Two products have stock_value 120.00. Which ordering makes their relative order deterministic?','["No ORDER BY", "ORDER BY stock_value DESC alone", "An assumption that insertion order is preserved", "ORDER BY stock_value DESC, product_id ASC"]'::jsonb,3,'The unique product identifier breaks the tie in computed stock value.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-8','pt-dbx2-select-application','A filter matches no rows in products. What should the plain table query return?','["A fabricated default product", "Exactly one row of zero values", "A deleted products table", "An empty result set"]'::jsonb,3,'Retrieval returns matching rows. No matches is a valid outcome rather than a reason to invent data.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-9','pt-dbx2-select-application','Is SELECT 2 + 2; valid in the MySQL dialect used here?','["Yes; it returns a single expression result without FROM", "No; every SELECT requires a table", "No; arithmetic is forbidden", "Only after creating a table named 2"]'::jsonb,0,'MySQL allows expression-only SELECT statements. Two plus two evaluates to four.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-select-2-10','pt-dbx2-select-application','Why does the stock-value query test unit_price IS NOT NULL instead of replacing unknown prices with zero?','["It proves all prices are positive", "It keeps unknown value distinct from a known zero price", "It renames the price column", "It orders the table permanently"]'::jsonb,1,'Treating an unknown price as zero would communicate certainty that the stored data does not provide.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
