if exists(select 1 from public.test_questions where id='tq-dbms-sql-7-selection-3' and (question_text,options,correct_index,explanation) is distinct from ('How does Selection differ from Projection?','["They are identical operations with different names", "Selection filters rows (same columns, fewer rows); Projection filters columns (same rows, fewer columns)", "Selection filters columns; Projection filters rows", "Selection can only be used with numeric data"]'::jsonb,1,'This is the key distinction between the two most fundamental relational algebra operations.') and (question_text,options,correct_index,explanation) is distinct from ('How does Selection differ from Projection?','["They are identical operations with different names", "Selection applies a row predicate while preserving attributes; projection chooses attributes and can eliminate duplicate projected tuples", "Selection filters columns; Projection filters rows", "Selection can only be used with numeric data"]'::jsonb,1,'Selection need not strictly reduce cardinality. Pure projection can reduce cardinality through set duplicate elimination.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-7-selection-3'; end if;
