if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-sequences-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a sequence in SQL?','["A column-level auto-increment attribute tied to one table", "A standalone, schema-level object that generates unique numeric values independent of any single table", "A type of index", "A synonym for a view"]'::jsonb,1,'A sequence is an independent generator object, distinct from being bound to one specific column like an identity column.') and (question_text,options,correct_index,explanation) is distinct from ('What is a standalone sequence object?','["A column-level auto-increment attribute tied to one table", "An independently addressable numeric generator with configured progression and reuse rules", "A type of index", "A synonym for a view"]'::jsonb,1,'Uniqueness across stored historical values still requires appropriate constraints and policy.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-sequences-1'; end if;
