if exists(select 1 from public.test_questions where id='tq-dbms-sql-9-sequences-2' and (question_text,options,correct_index,explanation) is distinct from ('What is a key advantage of a sequence over a per-table identity column?','["Sequences are always faster at every scale", "A single sequence can be shared across multiple tables/columns to guarantee globally unique values across them", "Sequences require no syntax to use", "Identity columns cannot be used as primary keys"]'::jsonb,1,'Sequences are standalone and can be reused across several tables, unlike identity columns which are bound to one column.') and (question_text,options,correct_index,explanation) is distinct from ('How can a shared sequence help several tables?','["Sequences are always faster at every scale", "It can coordinate one allocation space if all writers and generator settings obey that contract", "Sequences require no syntax to use", "Identity columns cannot be used as primary keys"]'::jsonb,1,'Cycling, resets or bypassing writers can still introduce collisions.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-9-sequences-2'; end if;
