insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-1','pt-dbms-sql-9-sequences','What is a standalone sequence object?','["A column-level auto-increment attribute tied to one table", "An independently addressable numeric generator with configured progression and reuse rules", "A type of index", "A synonym for a view"]'::jsonb,1,'Uniqueness across stored historical values still requires appropriate constraints and policy.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-2','pt-dbms-sql-9-sequences','How can a shared sequence help several tables?','["Sequences are always faster at every scale", "It can coordinate one allocation space if all writers and generator settings obey that contract", "Sequences require no syntax to use", "Identity columns cannot be used as primary keys"]'::jsonb,1,'Cycling, resets or bypassing writers can still introduce collisions.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-3','pt-dbms-sql-9-sequences','What is a possible consequence of reserving sequence values through caching?','["It stores computed query results; no risk involved", "Some reserved values may never appear in accepted rows, with exact events depending on the engine", "It prevents the sequence from ever producing duplicate values", "It encrypts the sequence''s current value"]'::jsonb,1,'Do not generalize one product’s cache lifetime to every product.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-4','pt-dbms-sql-9-sequences','If a transaction calls nextval(''order_seq'') and then rolls back, what happens to that consumed sequence value in PostgreSQL?','["It is returned to the sequence and reused by the next call", "It is not restored — sequence advancement is non-transactional, so a gap results", "The entire sequence is reset to its start value", "The transaction cannot roll back once nextval is called"]'::jsonb,1,'PostgreSQL intentionally does not roll back sequence advancement, to avoid serializing inserts through a single row lock.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-5','pt-dbms-sql-9-sequences','What risk does a CYCLE sequence introduce after it wraps around to MINVALUE?','["No risk; it is always perfectly safe", "It can reissue a value already used by an old surviving row, risking constraint violations or silent collisions", "The sequence permanently stops working", "It automatically drops the table it''s used in"]'::jsonb,1,'Wrapping around risks reissuing values still in use by existing rows if old data wasn''t cleaned up.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-6','pt-dbms-sql-9-sequences','In an appropriate PostgreSQL context, which form requests a next allocation restart at 5000?','["TRUNCATE SEQUENCE order_seq TO 5000;", "ALTER SEQUENCE order_seq RESTART WITH 5000;", "DELETE SEQUENCE order_seq WHERE value < 5000;", "UPDATE order_seq SET value = 5000;"]'::jsonb,1,'This is PostgreSQL syntax; collision and concurrency review is still needed.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-7','pt-dbms-sql-9-sequences','How is a PostgreSQL identity column related to a generator?','["They are entirely unrelated features", "It uses an associated implicit sequence under the identity dependency rules", "Sequences are implemented using identity columns internally", "Only one of the two features can exist in a given database"]'::jsonb,1,'It is distinct from an arbitrary standalone sequence lifecycle.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-sequences-8','pt-dbms-sql-9-sequences','What does currval(''order_seq'') return, in contrast to nextval(''order_seq'')?','["It advances the sequence and returns a brand-new value, same as nextval", "It returns the last value obtained by nextval() in the current session, without advancing the sequence", "It resets the sequence to its starting value", "It returns the total count of rows in the associated table"]'::jsonb,1,'currval() reads back the most recently obtained value in the current session rather than generating a new one.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
