if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-simple-attribute-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a simple (atomic) attribute?','["An attribute that can take multiple values for one entity", "An attribute that cannot be meaningfully broken down into smaller sub-parts", "An attribute derived from other attributes", "An attribute that is always numeric"]'::jsonb,1,'A simple attribute is indivisible — it has no meaningful sub-components.') and (question_text,options,correct_index,explanation) is distinct from ('What is a simple (atomic) attribute?','["An attribute that can take multiple values for one entity", "A property treated as one domain value without separately modeled components for the application\u2019s purposes", "An attribute derived from other attributes", "An attribute that is always numeric"]'::jsonb,1,'Simple does not mean that a representation has no characters, date components or conceivable internal operations.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-simple-attribute-1'; end if;
