if exists(select 1 from public.test_questions where id='pt-dbms-sql-6-simple-attribute-application-new-9' and (question_text,options,correct_index,explanation) is distinct from ('What must a derived simple value still specify?','["Only its displayed colour", "Only the source filename", "Its calculation rule, units and reference population or point", "Only the code prefix"]'::jsonb,2,'Simplicity does not prove the arithmetic is meaningful.') and (question_text,options,correct_index,explanation) is distinct from ('What must a derived simple value still specify?','["Only its displayed colour", "Only the source filename", "Its calculation rule, units and reference population or point", "Only the code prefix"]'::jsonb,2,'Simplicity does not prove the arithmetic is meaningful.')) then raise exception 'Edited question requires review: %', 'pt-dbms-sql-6-simple-attribute-application-new-9'; end if;
