update public.learning_topics set short_description='Treat a property as one domain value for the application’s purposes, distinguish simplicity from multiplicity and derivation, and query complete values without invented decomposition rules.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Treat a property as one domain value for the application’s purposes, distinguish simplicity from multiplicity and derivation, and query complete values without invented decomposition rules.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Simple Attribute.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-simple-attribute' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-simple-attribute-application','MCQ Test 2',category,10,10,'Application and scenarios for Simple Attribute.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-simple-attribute' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-1','pt-dbms-sql-6-simple-attribute','What is a simple (atomic) attribute?','["An attribute that can take multiple values for one entity", "A property treated as one domain value without separately modeled components for the application’s purposes", "An attribute derived from other attributes", "An attribute that is always numeric"]'::jsonb,1,'Simple does not mean that a representation has no characters, date components or conceivable internal operations.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-2','pt-dbms-sql-6-simple-attribute','Which is a simple attribute under a model that treats Roll_No as an opaque code and models Address components separately?','["Address (Street, City, State, Pincode)", "Roll_No", "Phone_Numbers (a list of numbers)", "Address with separately modeled city and postal code"]'::jsonb,1,'The question states the modeled component policy; derivation and simplicity are separate dimensions.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-3','pt-dbms-sql-6-simple-attribute','Why can Address be modeled as composite when city and postal code need independent management?','["Because it is always stored as a single VARCHAR column", "Because it naturally decomposes into meaningful independent sub-parts like Street, City, State, and Pincode", "Because it is a multi-valued attribute", "Because it is a derived attribute"]'::jsonb,1,'Address breaks into City/State/etc., which are individually useful — the defining trait of a composite attribute, unlike a simple attribute.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-4','pt-dbms-sql-6-simple-attribute','Is whether an attribute is simple or composite an absolute, fixed property of real-world data?','["Yes, it never depends on application requirements", "No — it is a design decision based on whether sub-parts need to be queried or referenced independently", "Yes, but only for weak entities", "No, all attributes are composite by default"]'::jsonb,1,'The same real-world value (e.g., Name) can be modeled as simple or composite depending on application needs.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-5','pt-dbms-sql-6-simple-attribute','Can a simple attribute also be multi-valued?','["No, simple and multi-valued are mutually exclusive by definition", "Yes — e.g., Phone_Number can be indivisible as a unit (simple) while a student can still have several of them (multi-valued)", "Only composite attributes can be multi-valued", "Only derived attributes can be multi-valued"]'::jsonb,1,'Simplicity (structural indivisibility) and single/multi-valued (occurrence count) are independent classification axes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-6','pt-dbms-sql-6-simple-attribute','When a composite property is recursively decomposed into leaf roles, what can those leaves be?','["Other composite attributes only", "Relationships", "Simple attributes, even though intermediate components may themselves be composite", "Derived attributes only"]'::jsonb,2,'Nested composition is possible; not every immediate component must already be a simple leaf.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-7','pt-dbms-sql-6-simple-attribute','A database that never needs to query the local-part or domain of an email separately would model `Email` as:','["Composite", "Multi-valued", "Simple", "Derived"]'::jsonb,2,'Without a need to reference sub-parts, Email is treated as a single indivisible (simple) attribute.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-simple-attribute-8','pt-dbms-sql-6-simple-attribute','Which statement about simple attributes is FALSE?','["They have no meaningful sub-parts for the application''s purposes", "They can never appear as part of a composite attribute", "Their classification as ''simple'' depends on the application''s querying needs", "CGPA and Gender are typical examples"]'::jsonb,1,'Simple attributes are exactly what composite attributes are composed of, so this statement is false.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-simple-attribute-new-9','pt-dbms-sql-6-simple-attribute','Does a date having calendar components automatically forbid treating it as one simple domain value?','["Yes; every date must become three entity attributes", "No; the modeled role can still be one date", "Only if the date is missing", "Only if stored as text"]'::jsonb,1,'Representation structure and conceptual decomposition differ.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-simple-attribute-new-10','pt-dbms-sql-6-simple-attribute','Can a simple attribute also be derived?','["No; calculated values are never attributes", "Only if no source data exists", "Yes; derivation and structural decomposition are separate dimensions", "Only if it is multivalued"]'::jsonb,2,'A computed total can still be one simple output value.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-simple-attribute-application-new-1','pt-dbms-sql-6-simple-attribute-application','Why preserve CS-007 as a code rather than blindly converting it to a number?','["All codes support meaningful addition", "Leading zeros always mean NULL", "Its documented identifier representation can matter", "Only integers can be keys"]'::jsonb,2,'An identifier need not be a quantity.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-simple-attribute-application-new-2','pt-dbms-sql-6-simple-attribute-application','What evidence justifies inferring programme from a registration-code prefix?','["A similar-looking sample alone", "The first character on screen", "A short alias", "A documented issuing and modeling contract requiring that component"]'::jsonb,3,'Do not invent semantics from a visual pattern.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-simple-attribute-application-new-3','pt-dbms-sql-6-simple-attribute-application','Can several simple phone values belong to one student?','["Yes, under a multivalued-phone policy", "No; simple implies one occurrence", "Only if phone values are numbers", "Only if the student has no identity"]'::jsonb,0,'Multiplicity and structural simplicity differ.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
