update public.learning_topics set short_description='Refine a Person supertype into meaningful role subtypes, state membership and completeness rules, and audit disjointness and coverage separately from parent references.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Refine a Person supertype into meaningful role subtypes, state membership and completeness rules, and audit disjointness and coverage separately from parent references.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Specialization.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-6-specialization' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-6-specialization-application','MCQ Test 2',category,10,10,'Application and scenarios for Specialization.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-6-specialization' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-1','pt-dbms-sql-6-specialization','What is specialization in EER modeling?','["A bottom-up merging of entity sets into a superclass", "A top-down process of dividing an existing entity set into more specific subclasses with their own extra attributes", "Treating a relationship as a higher-level entity", "A constraint limiting attribute domains"]'::jsonb,1,'Specialization refines a supertype into meaningful subtypes; shared identity and inherited facts remain part of the resulting model.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-2','pt-dbms-sql-6-specialization','Starting from Person and creating Student and Employee subclasses, each with their own extra attributes, is an example of:','["Generalization", "Aggregation", "Specialization", "Recursion"]'::jsonb,2,'This top-down split of an existing superclass into subclasses is specialization.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-3','pt-dbms-sql-6-specialization','How does specialization differ from generalization, given both can produce the same ISA hierarchy?','["There is no real difference between them", "Specialization is top-down (splitting an existing superclass); generalization is bottom-up (merging existing entity sets into a new superclass)", "Specialization always requires weak entities; generalization never does", "Generalization is top-down; specialization is bottom-up"]'::jsonb,1,'The direction of the design process is the key distinguishing factor, even though the resulting diagram structure can be identical.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-4','pt-dbms-sql-6-specialization','What does it mean for a specialization to be ''partial'' rather than ''total''?','["An instance can belong to more than one subclass", "Some superclass instances may not belong to any of the defined subclasses at all", "The subclass has fewer attributes than the superclass", "The relationship has M:N cardinality"]'::jsonb,1,'Partial completeness means membership in a subclass is optional — some Person instances (e.g., a guest) might be neither Student nor Employee.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-5','pt-dbms-sql-6-specialization','What does it mean for a specialization to be ''overlapping'' rather than ''disjoint''?','["Every superclass instance must belong to exactly one subclass", "An instance can simultaneously belong to more than one subclass, e.g., a Person who is both a Student and an Employee", "The subclasses have no attributes of their own", "The superclass has no primary key"]'::jsonb,1,'Overlapping allows an entity to be a member of multiple subclasses at once, unlike disjoint, which restricts it to at most one.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-6','pt-dbms-sql-6-specialization','In the conceptual hierarchy and direct shared-person-id mapping used here, how is subtype identity related to Person?','["Yes, always a brand-new unrelated key", "It denotes the same underlying Person identity; the chosen mapping uses that shared key rather than an unrelated identity", "Only if the specialization is total", "Only if the specialization is disjoint"]'::jsonb,1,'Other physical mappings must preserve conceptual identity explicitly; shared entity meaning is the essential requirement.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-7','pt-dbms-sql-6-specialization','Can specialization be applied more than once, layer by layer (e.g., specializing Employee further into Teaching_Staff and Non_Teaching_Staff)?','["No, only one level of specialization is allowed per entity set", "Yes — specialization can be nested/repeated to create multi-level ISA hierarchies", "Only if the first specialization was overlapping", "Only for weak entities"]'::jsonb,1,'Specialization hierarchies can have multiple levels, refining subclasses further as needed.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-specialization-8','pt-dbms-sql-6-specialization','Which of the following would NOT typically be considered specialization?','["Splitting Employee into Teaching_Staff and Non_Teaching_Staff", "Splitting Person into Student and Employee", "Creating a brand-new, independent entity set Library_Book with its own separate primary key unrelated to any existing entity set", "Splitting Vehicle into Car and Truck subclasses"]'::jsonb,2,'Specialization requires an ISA relationship to an existing superclass with inherited identity; an unrelated new entity set with its own key is not specialization.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-specialization-new-9','pt-dbms-sql-6-specialization','Does a subtype occurrence denote an unrelated second person?','["Yes; every subtype creates a new human", "No; it specializes the same underlying supertype occurrence", "Only if the name matches", "Only if it has no key"]'::jsonb,1,'Shared conceptual identity is fundamental.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-6-specialization-new-10','pt-dbms-sql-6-specialization','What does total disjoint specialization require for each relevant Person?','["Any number including none", "Exactly both roles", "Exactly one specified subtype membership", "No role rows"]'::jsonb,2,'Total gives at least one and disjoint gives at most one.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
