update public.learning_topics set short_description='Adapt SQL concepts to the actual engine and version, comparing row limits, arithmetic, generated identifiers, quoting, time values, and the silent differences that syntax checks miss.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Adapt SQL concepts to the actual engine and version, comparing row limits, arithmetic, generated identifiers, quoting, time values, and the silent differences that syntax checks miss.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for SQL Dialects.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-8-sql-dialects' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-8-sql-dialects-application','MCQ Test 2',category,10,10,'Application and scenarios for SQL Dialects.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-8-sql-dialects' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-1','pt-dbms-sql-8-sql-dialects','What is a SQL ''dialect''?','["A completely different language unrelated to SQL", "A product/version-specific implementation of supported SQL features, extensions, and behavior", "An old, deprecated version of SQL no longer used", "A dialect only exists for spoken languages, not SQL"]'::jsonb,1,'Dialects include behavioral differences as well as proprietary syntax; installed versions and settings matter.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-2','pt-dbms-sql-8-sql-dialects','Which keyword does SQL Server use to limit the number of returned rows, where MySQL and PostgreSQL use LIMIT?','["TOP", "FIRST", "ROWNUM", "CAP"]'::jsonb,0,'SQL Server uses TOP N in the SELECT clause instead of a trailing LIMIT clause.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-3','pt-dbms-sql-8-sql-dialects','In a normal SQLite rowid table, which declaration commonly aliases the rowid and permits automatic integer assignment?','["AUTO_INCREMENT", "IDENTITY(1,1)", "INTEGER PRIMARY KEY (which auto-generates the rowid)", "SERIAL"]'::jsonb,2,'INTEGER PRIMARY KEY has special rowid behavior in ordinary SQLite tables. WITHOUT ROWID tables are an exception, and AUTOINCREMENT changes allocation policy.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-4','pt-dbms-sql-8-sql-dialects','Why can a query that works on MySQL fail on SQL Server even though both are ''doing SQL''?','["SQL Server does not actually support SELECT statements", "Dialect-specific syntax (e.g. LIMIT vs TOP, function names) differs even when the underlying task is the same", "MySQL is not a real relational database", "It is impossible for any query to be dialect-specific"]'::jsonb,1,'The concept can be identical while the exact keyword or function name required differs by vendor dialect.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-5','pt-dbms-sql-8-sql-dialects','Which of these is a genuinely SILENT dialect difference (no error, just a different result) rather than a syntax error?','["Using AUTO_INCREMENT on a database that doesn''t support that keyword", "Integer division truncating in one engine but returning a decimal in another", "Misspelling the SELECT keyword", "Forgetting a closing parenthesis"]'::jsonb,1,'Integer division behavior differing (truncate vs decimal result) produces a different but still ''successful'' result — a silent correctness bug, not an obvious syntax error.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-6','pt-dbms-sql-8-sql-dialects','A student copies a SQL example from an online tutorial and it fails to run. What is a likely, commonly-overlooked cause?','["SQL never fails for any reason related to dialect", "The tutorial''s example may target a different database dialect than the one the student is using", "All SQL tutorials are always broken", "The student''s database has stopped supporting SQL entirely"]'::jsonb,1,'Dialect mismatch between the tutorial''s target database and the student''s actual database is one of the most common sources of this kind of failure.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-7','pt-dbms-sql-8-sql-dialects','Which function is standard SQL and widely supported across dialects for getting the current timestamp?','["NOW()", "GETDATE()", "CURRENT_TIMESTAMP", "SYSDATE"]'::jsonb,2,'CURRENT_TIMESTAMP is part of the SQL standard; NOW(), GETDATE(), and SYSDATE are vendor-specific spellings for similar behavior.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-dialects-8','pt-dbms-sql-8-sql-dialects','What is the best general practice when learning SQL from any single tutorial or course?','["Assume every dialect behaves identically in every respect, with no exceptions", "Learn the underlying relational concept first, then look up how that concept is spelled in your specific target dialect", "Never learn more than one dialect, since switching is impossible", "Avoid using any vendor-specific feature under any circumstance, even when it is the right tool"]'::jsonb,1,'Understanding the concept independent of syntax, then mapping it to the target dialect''s specific spelling, is the transferable skill.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-new-9','pt-dbms-sql-8-sql-dialects','Which MySQL operator requests integer division explicitly?','["AS", "DIV", "LIKE", "ORDER BY"]'::jsonb,1,'DIV returns the integer quotient rather than the ordinary fractional division result.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-new-10','pt-dbms-sql-8-sql-dialects','Why must a top-three query define a tie-breaker when exact selection matters?','["LIMIT sorts every column automatically", "TOP eliminates every duplicate value", "Equal primary sort values can otherwise leave the boundary selection unspecified", "Every identifier must become a timestamp"]'::jsonb,2,'A stable unique tie-breaker makes the intended ranking deterministic.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-1','pt-dbms-sql-8-sql-dialects-application','In the MySQL example, what are CAST(5 / 2 AS DECIMAL(8,2)) and 5 DIV 2?','["2 and 2.50", "0 and 5", "2.50 and 2", "5 and 0"]'::jsonb,2,'The slash operator preserves the fractional result while DIV gives whole groups.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-2','pt-dbms-sql-8-sql-dialects-application','An integer expression returns 2 in one engine and 2.5 in another without errors. What should be reviewed?','["Only whether the query ends in a semicolon", "Only the result column name", "Only the number of connected users", "Operand types and division semantics in each dialect"]'::jsonb,3,'Successful parsing can conceal a silent arithmetic difference.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-3','pt-dbms-sql-8-sql-dialects-application','A ratio is defined as missing for zero denominator. What can NULLIF(denominator,0) provide before division?','["A NULL denominator for the zero case", "A denominator of one for every row", "An automatic authorization check", "A guaranteed percentage of one hundred"]'::jsonb,0,'NULLIF expresses the stated missing-result policy without inventing a valid ratio.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-4','pt-dbms-sql-8-sql-dialects-application','Two applicants have equal scores and only one remaining limited-result slot. What determines a stable choice?','["The current physical insertion order by assumption", "An explicit additional ordering key such as applicant_id", "The length of the SQL statement", "The database logo"]'::jsonb,1,'A tie policy must be part of the requested order.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-5','pt-dbms-sql-8-sql-dialects-application','A normal SQLite INTEGER PRIMARY KEY generates a value when omitted. Is AUTOINCREMENT always required for that?','["Yes; no rowid can be generated without it", "Only MySQL can generate integers", "No; AUTOINCREMENT changes the allocation policy", "Only if every row has a NULL name"]'::jsonb,2,'Ordinary rowid assignment does not require SQLite AUTOINCREMENT.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-6','pt-dbms-sql-8-sql-dialects-application','A MySQL statement uses a SQL Server TOP form and fails. What should guide the rewrite?','["Removing the WHERE clause indiscriminately", "Disabling all constraints", "Assuming the server must be unavailable", "The required result and supported MySQL syntax"]'::jsonb,3,'Translate the intended task rather than dropping semantics until parsing succeeds.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-dialects-application-new-7','pt-dbms-sql-8-sql-dialects-application','A query compares names under a new collation after migration. What can change even if the syntax stays identical?','["Which text values compare equal and qualify", "The identifier of every database user automatically", "The number of tiers necessarily increases", "Every NULL becomes zero"]'::jsonb,0,'Collation can alter case and accent comparison behavior.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
