insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-overview-3','pt-dbms-sql-8-sql-overview','Which statement directly modifies existing rows in this tutorial''s DML grouping?','["SELECT", "CREATE TABLE", "UPDATE", "GRANT"]'::jsonb,2,'UPDATE changes stored rows. SELECT retrieves results; CREATE TABLE defines an object; GRANT manages permissions. DML/DQL category terminology can vary, so focus on the operation.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
