insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-4','pt-dbx2-sql-overview-application','Which command changes the definition of an existing table rather than a stored student value?','["UPDATE", "SELECT", "ALTER TABLE", "COMMIT"]'::jsonb,2,'ALTER TABLE is a definition statement. UPDATE changes rows; SELECT retrieves results; COMMIT controls a transaction boundary.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-5','pt-dbx2-sql-overview-application','A developer assumes that SELECT and select are different commands. Which correction is appropriate?','["Every string comparison is case-sensitive", "Every identifier behaves identically on every operating system", "Keyword capitalization is a readability choice, while string comparisons depend on collation", "Lowercase keywords always delete records"]'::jsonb,2,'Keywords and string data have different case-handling rules. Inspect the actual collation for string comparisons.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-6','pt-dbx2-sql-overview-application','Two queries return the same required rows in the same required order. Can their performance differ?','["No; equal results force identical plans", "Yes; their execution plans and work can differ", "No; SQL permits only one valid query per result", "Yes; one must therefore be syntactically invalid"]'::jsonb,1,'Declarative queries can have equivalent results while leading to different execution strategies.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-7','pt-dbx2-sql-overview-application','A script combines CREATE TABLE with other work inside a transaction. What MySQL behavior must be checked?','["All DDL is guaranteed to roll back with ROLLBACK", "COMMIT removes the need to inspect errors", "Every SELECT changes the table definition", "Many DDL statements cause implicit commits"]'::jsonb,3,'MySQL definition statements can commit implicitly. Do not promise transactional reversal of an arbitrary DDL script.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-8','pt-dbx2-sql-overview-application','An available-course query returns the correct two records but no ORDER BY. What remains unspecified?','["The order in which those result rows are returned", "Which table was named in FROM", "Whether the two qualifying identifiers exist", "The spelling of the SELECT keyword"]'::jsonb,0,'A stable-looking current output order is not a substitute for requesting the required order.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-9','pt-dbx2-sql-overview-application','A user who can read public courses tries to grant themselves administrative access. Which concern is involved?','["Only whether the query uses uppercase keywords", "Authorization for the requested control operation", "Only the number of available seats", "Whether a string literal contains a space"]'::jsonb,1,'Knowing SQL syntax and having read access do not grant permission for privileged control operations.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-sql-overview-2-10','pt-dbx2-sql-overview-application','A query executes without an error but includes sold-out offerings in a requested available-course report. What failed?','["The lack of a syntax error proves correctness", "The server must have granted every permission", "The report must be faster than all alternatives", "The query''s semantics do not match the requested filter"]'::jsonb,3,'Successful parsing/execution is separate from producing the information the task requested.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
