if exists(select 1 from public.dsa_problems where id='cp-dbx2-sql-overview-open-courses' and description is distinct from 'Return offering_id and course_name for offerings with seats_remaining greater than zero. Do not modify any records.

**MySQL dialect.**

```sql
CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));
INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);
```

**Required ordering:** Ascending offering_id.

**Edge cases:**
- Zero seats means the offering is not returned.
- Multiple offerings can share a course_name.
- An empty table returns no rows.') then raise exception 'New coding ID already has other content: %', 'cp-dbx2-sql-overview-open-courses'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbx2-sql-overview-open-courses',null::text,'Find Courses with Available Seats','Easy','dbx2-sql-overview-open-courses','Return offering_id and course_name for offerings with seats_remaining greater than zero. Do not modify any records.

**MySQL dialect.**

```sql
CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));
INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);
```

**Required ordering:** Ascending offering_id.

**Edge cases:**
- Zero seats means the offering is not returned.
- Multiple offerings can share a course_name.
- An empty table returns no rows.','[{"input": "INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);", "output": "offering_id\tcourse_name\n10\tDatabases\n30\tOperating Systems", "explanation": "The query requests two explicit columns and filters on the stored seat count. Ordering by the unique offering identifier makes the result deterministic. It does not reserve a seat or update a row."}]'::jsonb,'[{"seed_sql": "INSERT INTO course_offerings VALUES (9,''Databases'',0),(3,''Databases'',1),(5,''Databases'',2);", "expected": "offering_id\tcourse_name\n3\tDatabases\n5\tDatabases", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["offering_id is a unique non-NULL integer.", "course_name is required.", "seats_remaining is an integer between 0 and 100."]'::jsonb,'["Use SELECT for retrieval.", "Filter with WHERE seats_remaining > 0."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'The query requests two explicit columns and filters on the stored seat count. Ordering by the unique offering identifier makes the result deterministic. It does not reserve a seat or update a row.','{"sql": "SELECT offering_id, course_name FROM course_offerings WHERE seats_remaining > 0 ORDER BY offering_id;"}'::jsonb,'The query requests two explicit columns and filters on the stored seat count. Ordering by the unique offering identifier makes the result deterministic. It does not reserve a seat or update a row.',array['sql'],'CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));','INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-8-sql-overview' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='cp-dbx2-sql-overview-seat-summary' or slug='dbx2-sql-overview-seat-summary') and (id<>'cp-dbx2-sql-overview-seat-summary' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'cp-dbx2-sql-overview-seat-summary'; end if;
if exists(select 1 from public.dsa_problems where id='cp-dbx2-sql-overview-seat-summary' and description is distinct from 'Return one row with offering_count and total_seats for all offerings, including offerings with zero seats. For an empty table, both values must be zero.

**MySQL dialect.**

```sql
CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));
INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);
```

**Required ordering:** Exactly one summary row; no row ordering is needed.

**Edge cases:**
- Include offerings with zero seats in offering_count.
- Use zero for total_seats when there are no rows.
- Duplicate course names still represent distinct offerings.') then raise exception 'New coding ID already has other content: %', 'cp-dbx2-sql-overview-seat-summary'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cp-dbx2-sql-overview-seat-summary',null::text,'Summarize Available Course Places','Medium','dbx2-sql-overview-seat-summary','Return one row with offering_count and total_seats for all offerings, including offerings with zero seats. For an empty table, both values must be zero.

**MySQL dialect.**

```sql
CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));
INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);
```

**Required ordering:** Exactly one summary row; no row ordering is needed.

**Edge cases:**
- Include offerings with zero seats in offering_count.
- Use zero for total_seats when there are no rows.
- Duplicate course names still represent distinct offerings.','[{"input": "INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);", "output": "offering_count\ttotal_seats\n3\t5", "explanation": "An aggregate query without GROUP BY produces one summary row. COUNT(*) counts every offering. SUM adds the seat counts and returns NULL for an empty input, so COALESCE replaces that unknown aggregate with the explicitly required zero."}]'::jsonb,'[{"seed_sql": "", "expected": "offering_count\ttotal_seats\n0\t0", "hidden": true}, {"seed_sql": "INSERT INTO course_offerings VALUES (1,''Same'',0),(2,''Same'',0);", "expected": "offering_count\ttotal_seats\n2\t0", "hidden": true}]'::jsonb,'["offering_id is unique and non-NULL.", "seats_remaining is required and between 0 and 100."]'::jsonb,'["COUNT(*) counts rows.", "Use COALESCE(SUM(seats_remaining), 0) for the empty-table case."]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'An aggregate query without GROUP BY produces one summary row. COUNT(*) counts every offering. SUM adds the seat counts and returns NULL for an empty input, so COALESCE replaces that unknown aggregate with the explicitly required zero.','{"sql": "SELECT COUNT(*) AS offering_count, COALESCE(SUM(seats_remaining), 0) AS total_seats FROM course_offerings;"}'::jsonb,'An aggregate query without GROUP BY produces one summary row. COUNT(*) counts every offering. SUM adds the seat counts and returns NULL for an empty input, so COALESCE replaces that unknown aggregate with the explicitly required zero.',array['sql'],'CREATE TABLE course_offerings (offering_id INT PRIMARY KEY, course_name VARCHAR(40) NOT NULL, seats_remaining INT NOT NULL CHECK (seats_remaining BETWEEN 0 AND 100));','INSERT INTO course_offerings VALUES (10,''Databases'',3),(20,''Networks'',0),(30,''Operating Systems'',2);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-8-sql-overview' on conflict(id) do nothing;
