if exists(select 1 from public.test_questions where id='tq-dbms-sql-8-sql-standards-3' and (question_text,options,correct_index,explanation) is distinct from ('Do database vendors implement the full SQL standard with no additions?','["Yes, every vendor implements exactly and only the standard", "No \u2014 vendors implement it partially and add their own proprietary extensions", "The standard forbids any vendor extensions", "Only open-source databases follow the standard"]'::jsonb,1,'In practice, every vendor implements a subset of the standard and layers proprietary extensions on top.') and (question_text,options,correct_index,explanation) is distinct from ('Do database vendors implement the full SQL standard with no additions?','["Yes, every vendor implements exactly and only the standard", "No \u2014 vendors implement it partially and add their own proprietary extensions", "The standard forbids any vendor extensions", "Only open-source databases follow the standard"]'::jsonb,1,'In practice, every vendor implements a subset of the standard and layers proprietary extensions on top.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-8-sql-standards-3'; end if;
