insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-1','pt-dbms-sql-8-sql-standards','Who maintains the SQL standard?','["A single database vendor", "ISO/IEC (with ANSI)", "Each database has its own independent ''standard''", "There is no standard for SQL"]'::jsonb,1,'SQL is an ISO/IEC standard (with ANSI involvement), not owned by any one vendor.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-2','pt-dbms-sql-8-sql-standards','What is the main benefit of SQL being standardized?','["It guarantees every database looks visually identical", "It gives a common syntax/behavior baseline that makes SQL skills and code more portable across products", "It prevents vendors from adding any extra features", "It makes SQL a compiled, not interpreted, language"]'::jsonb,1,'Standardization creates a shared baseline so the same core SQL works similarly across different database engines.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-3','pt-dbms-sql-8-sql-standards','Do database vendors implement the full SQL standard with no additions?','["Yes, every vendor implements exactly and only the standard", "No — vendors implement it partially and add their own proprietary extensions", "The standard forbids any vendor extensions", "Only open-source databases follow the standard"]'::jsonb,1,'In practice, every vendor implements a subset of the standard and layers proprietary extensions on top.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-4','pt-dbms-sql-8-sql-standards','`SELECT TOP 10 * FROM students` is an example of what?','["Pure ISO standard SQL supported identically everywhere", "A vendor-specific (SQL Server) extension for limiting rows", "Invalid SQL in every database", "A DDL statement"]'::jsonb,1,'TOP is a SQL Server-specific way to limit rows; other engines use LIMIT or the standard FETCH FIRST ... ROWS ONLY.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-5','pt-dbms-sql-8-sql-standards','A language feature appears in an SQL standard revision. What determines whether a particular deployment can use it?','["The standard automatically enables it everywhere", "Every database driver rewrites it identically", "The installed engine/version and its supported feature restrictions", "The number of rows in an unrelated table"]'::jsonb,2,'Standards define capabilities, while implementations and versions determine the actual supported operation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-6','pt-dbms-sql-8-sql-standards','A team assumes their SQL is fully portable simply because it ''runs on our database.'' What''s the risk in that assumption?','["There is no risk — running proves full standard compliance", "The code may rely on vendor-specific syntax that isn''t standard and won''t run unchanged on a different engine", "SQL code can never run on more than one database", "Portability only matters for DDL, never for queries"]'::jsonb,1,'Code can run successfully on one vendor while still depending on non-standard, vendor-specific syntax that breaks portability.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-7','pt-dbms-sql-8-sql-standards','A query uses a feature from a recent SQL standard revision. What should you check before assuming it will work?','["Nothing — all standard features are automatically available on every installed database version", "Whether the specific target engine AND its installed version actually implements that feature", "Only whether the query is syntactically well-formed", "Whether the feature existed in SQL-86"]'::jsonb,1,'Standard compliance is partial and version-dependent; an older engine version may not implement a newer standard feature.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-standards-8','pt-dbms-sql-8-sql-standards','What is the practical trade-off when a developer chooses a vendor-specific extension over standard SQL syntax?','["There is no trade-off — extensions are strictly better in every way", "They may gain convenience or performance specific to that vendor, at the cost of portability to other database engines", "Extensions always make the query slower", "Extensions are illegal under the SQL standard"]'::jsonb,1,'Vendor extensions can be genuinely useful but tie the code to that vendor, trading portability for vendor-specific capability.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-standards-new-9','pt-dbms-sql-8-sql-standards','What is a SQL standard rather than a database product?','["A server every application must connect to", "A language specification and common behavioral baseline", "A universal production credential", "A guarantee that every extension is implemented"]'::jsonb,1,'A specification supports shared reasoning but is not itself the running database.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-standards-new-10','pt-dbms-sql-8-sql-standards','Which portability question is not answered by successful parsing alone?','["Whether the parser accepted that statement", "Whether the text was sent to the tested engine", "Whether results and failure behavior preserve the promised meaning", "Whether the test had SQL input"]'::jsonb,2,'Semantics and operational behavior need evidence beyond syntax acceptance.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
