insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-standards-application-new-2','pt-dbms-sql-8-sql-standards-application','A query asks for the first three students without ORDER BY. What is underspecified?','["Whether SQL supports rows", "Whether the result has columns", "Whether the engine stores data", "Which ordered sequence defines first"]'::jsonb,3,'Row limiting alone does not define a stable ranking.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-standards-application-new-3','pt-dbms-sql-8-sql-standards-application','A feature works on a new local engine but production uses an older release. What is required?','["Verify the actual target version supports the required operation", "Assume the product name guarantees every new feature", "Change production secretly", "Remove all validation tests"]'::jsonb,0,'Version and configuration determine support in the environment that matters.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
