insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-standards-application-new-5','pt-dbms-sql-8-sql-standards-application','Two engines return the same ordinary sample but differ on NULL. What did the initial sample fail to establish?','["That either engine could execute any query", "That the columns had names", "Result-semantic compatibility for the missing-value case", "That the result was observed"]'::jsonb,2,'Representative edge cases are necessary to test the promised behavior.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
