update public.learning_topics set short_description='Build SELECT statements in the correct written clause order, distinguish row and group filters, and reason about projection, aliases, ordering, limits, and statement boundaries.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Build SELECT statements in the correct written clause order, distinguish row and group filters, and reason about projection, aliases, ordering, limits, and statement boundaries.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for SQL Statement Structure.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-8-sql-statement-structure' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-8-sql-statement-structure-application','MCQ Test 2',category,10,10,'Application and scenarios for SQL Statement Structure.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-8-sql-statement-structure' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-1','pt-dbms-sql-8-sql-statement-structure','In the written order of a SELECT statement, which clause comes first?','["WHERE", "SELECT", "HAVING", "FROM"]'::jsonb,1,'SELECT is written first in a normal SELECT statement. FROM is considered earlier in a conceptual account of result formation, which is a different ordering.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-2','pt-dbms-sql-8-sql-statement-structure','Which clause filters individual rows BEFORE any grouping happens?','["HAVING", "WHERE", "ORDER BY", "GROUP BY"]'::jsonb,1,'WHERE filters rows before GROUP BY collapses them into groups.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-3','pt-dbms-sql-8-sql-statement-structure','Which clause is used to filter GROUPS after GROUP BY has run?','["WHERE", "HAVING", "LIMIT", "FROM"]'::jsonb,1,'HAVING filters aggregated groups, which is why it can reference aggregate functions like COUNT(*).',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-4','pt-dbms-sql-8-sql-statement-structure','Why does `WHERE COUNT(*) > 5` fail, while `HAVING COUNT(*) > 5` works?','["WHERE and HAVING are exact synonyms, so this shouldn''t matter, and both should work", "WHERE runs before grouping/aggregation happens, so aggregate values like COUNT(*) don''t exist yet at that stage", "COUNT(*) is not a valid function in any clause", "HAVING can only be used without GROUP BY"]'::jsonb,1,'Aggregates are computed during/after GROUP BY, so only HAVING (which runs after grouping) can filter on them.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-5','pt-dbms-sql-8-sql-statement-structure','What terminates one SQL statement and separates it from the next in a multi-statement script?','["A comma", "A semicolon", "A colon", "Two blank lines"]'::jsonb,1,'The semicolon is the standard statement terminator.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-6','pt-dbms-sql-8-sql-statement-structure','Can a WHERE clause be written after a GROUP BY clause in the same statement?','["Yes, clause order is completely free-form", "No — the required written order places WHERE before GROUP BY; writing it after is a syntax error", "Only in SQLite", "Only if no JOIN is present"]'::jsonb,1,'The written clause order is fixed by the SQL grammar; WHERE must precede GROUP BY.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-7','pt-dbms-sql-8-sql-statement-structure','What risk does omitting a semicolon between two statements in a batch script create?','["No risk at all — SQL always infers statement boundaries perfectly", "The client may combine text into one malformed statement or fail to recognize the intended boundary; behavior depends on the runner", "The database refuses to start", "Only the second statement will ever run"]'::jsonb,1,'Missing delimiters often produce a syntax error or continued input collection. A silently changed successful operation is not guaranteed.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-sql-statement-structure-8','pt-dbms-sql-8-sql-statement-structure','A query needs to: read from two joined tables, keep only rows from this year, group by department, keep only groups with more than 10 employees, and sort by department name. In what written order must these clauses appear?','["ORDER BY, HAVING, GROUP BY, WHERE, FROM/JOIN", "FROM/JOIN, WHERE, GROUP BY, HAVING, ORDER BY", "WHERE, FROM/JOIN, HAVING, GROUP BY, ORDER BY", "GROUP BY, WHERE, FROM/JOIN, ORDER BY, HAVING"]'::jsonb,1,'This is exactly the canonical written order: FROM/JOIN, WHERE, GROUP BY, HAVING, ORDER BY.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-new-9','pt-dbms-sql-8-sql-statement-structure','What does a change from one row per item to one row per category describe?','["A new network protocol", "A change in result grain", "A required schema rename", "A physical page split"]'::jsonb,1,'Grouping changes what one output row represents.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-new-10','pt-dbms-sql-8-sql-statement-structure','Is the logical explanation of a query necessarily its exact physical execution trace?','["Yes; each written clause runs as a separate physical scan", "Only when the table has no rows", "No; the optimizer can choose a supported equivalent strategy", "Only when SELECT is uppercase"]'::jsonb,2,'Written order, logical interpretation, and physical strategy are different concepts.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-1','pt-dbms-sql-8-sql-statement-structure-application','An active item costs exactly 100. Does active = 1 AND price >= 100 retain it?','["No; the boundary is excluded", "Only if it was inserted first", "Yes", "Only if its name is unique"]'::jsonb,2,'The numeric comparison is inclusive and the active condition is satisfied.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-2','pt-dbms-sql-8-sql-statement-structure-application','A category has three items but only one is active. The query filters active rows then requires COUNT(*) >= 2. Does it appear?','["Yes; all three original rows count", "Yes; GROUP BY ignores WHERE", "Only if its name is quoted", "No; only one qualifying row contributes"]'::jsonb,3,'WHERE determines the input population before the grouped count.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-3','pt-dbms-sql-8-sql-statement-structure-application','Which condition belongs in HAVING for a per-category report?','["COUNT(*) >= 2", "An individual row''s active = 1 before grouping", "The table alias declaration", "The connection password"]'::jsonb,0,'The grouped count is an aggregate property.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-4','pt-dbms-sql-8-sql-statement-structure-application','A grouped query selects category, COUNT(*), and an arbitrary unrelated item_name. What should be reviewed?','["Only the number of commas", "Whether every selected expression is defined for the intended group", "Only the indentation", "Only the result table color"]'::jsonb,1,'A group does not inherently have one meaningful unrelated item name.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-5','pt-dbms-sql-8-sql-statement-structure-application','A ranking uses LIMIT 3 with no ORDER BY. What is missing?','["The existence of SELECT", "The ability to return rows", "The sequence that defines which three are requested", "The requirement that a table has columns"]'::jsonb,2,'A row bound does not specify a ranking.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-6','pt-dbms-sql-8-sql-statement-structure-application','Two items have the same price. What makes their price-ranked sequence deterministic?','["ORDER BY price DESC alone always breaks ties", "Relying on insertion order", "Removing both item identifiers", "ORDER BY price DESC, item_id ASC when item_id is unique"]'::jsonb,3,'An explicit unique tie-breaker defines relative order.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-7','pt-dbms-sql-8-sql-statement-structure-application','A query uses WHERE COUNT(*) > 5 at the same aggregation level. What is misplaced?','["A group aggregate in the row-filtering clause", "The statement delimiter only", "The use of an identifier", "The database connection itself"]'::jsonb,0,'The grouped aggregate is not an input-row property at that level.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-8','pt-dbms-sql-8-sql-statement-structure-application','A semicolon appears inside a quoted string. Is it necessarily a statement boundary?','["Yes; every semicolon ends execution", "No; it can be part of the string value", "Only if it has no spaces", "Only if the table is empty"]'::jsonb,1,'Parsing must respect quoting rather than naively split every semicolon.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-9','pt-dbms-sql-8-sql-statement-structure-application','The driver executes one statement without a trailing semicolon. Does that prove SQL has no statement boundaries?','["Yes; all scripts must concatenate statements", "Yes; commas replace every semicolon", "No; API submission and interactive script delimiters differ", "Only if ORDER BY is absent"]'::jsonb,2,'One API call can supply a complete statement independently of client-side script collection.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-sql-statement-structure-application-new-10','pt-dbms-sql-8-sql-statement-structure-application','A new join multiplies each item into several sales rows before COUNT(*). What must the report revisit?','["Only the FROM keyword spelling", "Only whether SELECT is written first", "Only the client font", "The population and grain that the count measures"]'::jsonb,3,'A syntactically correct aggregate can count joined combinations rather than items.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
