if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-structure-row-group-filters' and description is distinct from 'For active items only, group by category and return category, active_items, known_stock, total_stock. Count all active rows, count non-NULL stock_qty, and sum stock_qty without replacing an all-missing total. Keep only categories with at least two active items. Order by category.

**MySQL dialect.**

```sql
CREATE TABLE inventory (item_id INT PRIMARY KEY, item_name VARCHAR(40) NOT NULL, category VARCHAR(20) NOT NULL, price DECIMAL(8,2) NULL CHECK (price >= 0), active INT NOT NULL CHECK (active IN (0,1)), stock_qty INT NULL CHECK (stock_qty >= 0));
INSERT INTO inventory VALUES (1,''Book'',''stationery'',100.00,1,2),(2,''Pad'',''stationery'',90.00,1,NULL),(3,''Pen'',''stationery'',20.00,0,8),(4,''Box'',''storage'',50.00,1,0),(5,''Crate'',''storage'',70.00,1,5),(6,''Cable'',''electronics'',80.00,1,9);
```

**Required ordering:** category ascending

**Edge cases:**
- Inactive rows must not raise the group count
- A group with one active item is excluded
- Known zero stock counts as recorded
- An all-missing sum remains NULL') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-structure-row-group-filters'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-structure-row-group-filters',null::text,'Separate row filters from group filters','Medium','structure-row-group-filters','For active items only, group by category and return category, active_items, known_stock, total_stock. Count all active rows, count non-NULL stock_qty, and sum stock_qty without replacing an all-missing total. Keep only categories with at least two active items. Order by category.

**MySQL dialect.**

```sql
CREATE TABLE inventory (item_id INT PRIMARY KEY, item_name VARCHAR(40) NOT NULL, category VARCHAR(20) NOT NULL, price DECIMAL(8,2) NULL CHECK (price >= 0), active INT NOT NULL CHECK (active IN (0,1)), stock_qty INT NULL CHECK (stock_qty >= 0));
INSERT INTO inventory VALUES (1,''Book'',''stationery'',100.00,1,2),(2,''Pad'',''stationery'',90.00,1,NULL),(3,''Pen'',''stationery'',20.00,0,8),(4,''Box'',''storage'',50.00,1,0),(5,''Crate'',''storage'',70.00,1,5),(6,''Cable'',''electronics'',80.00,1,9);
```

**Required ordering:** category ascending

**Edge cases:**
- Inactive rows must not raise the group count
- A group with one active item is excluded
- Known zero stock counts as recorded
- An all-missing sum remains NULL','[{"input": "INSERT INTO inventory VALUES (1,''Book'',''stationery'',100.00,1,2),(2,''Pad'',''stationery'',90.00,1,NULL),(3,''Pen'',''stationery'',20.00,0,8),(4,''Box'',''storage'',50.00,1,0),(5,''Crate'',''storage'',70.00,1,5),(6,''Cable'',''electronics'',80.00,1,9);", "output": "category\tactive_items\tknown_stock\ttotal_stock\nstationery\t2\t1\t2\nstorage\t2\t2\t5", "explanation": "WHERE defines the active input population before aggregation. HAVING tests the resulting group size, while the separate count and sum preserve stock missingness."}]'::jsonb,'[{"seed_sql": "INSERT INTO inventory VALUES (1,''A'',''tools'',1.00,1,NULL),(2,''B'',''tools'',1.00,1,NULL),(3,''C'',''other'',1.00,1,2),(4,''D'',''other'',1.00,0,3);", "expected": "category\tactive_items\tknown_stock\ttotal_stock\ntools\t2\t0\tNULL", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["One inventory item per row", "Only active rows contribute", "Stock quantities can be missing"]'::jsonb,'["Place active filtering in WHERE", "Place the count threshold in HAVING", "COUNT(*) and COUNT(stock_qty) measure different things"]'::jsonb,'{"sql": "-- Write your SELECT query here\n"}'::jsonb,'WHERE defines the active input population before aggregation. HAVING tests the resulting group size, while the separate count and sum preserve stock missingness.','{"sql": "SELECT category, COUNT(*) AS active_items, COUNT(stock_qty) AS known_stock, SUM(stock_qty) AS total_stock FROM inventory WHERE active = 1 GROUP BY category HAVING COUNT(*) >= 2 ORDER BY category;"}'::jsonb,'WHERE defines the active input population before aggregation. HAVING tests the resulting group size, while the separate count and sum preserve stock missingness.',array['sql'],'CREATE TABLE inventory (item_id INT PRIMARY KEY, item_name VARCHAR(40) NOT NULL, category VARCHAR(20) NOT NULL, price DECIMAL(8,2) NULL CHECK (price >= 0), active INT NOT NULL CHECK (active IN (0,1)), stock_qty INT NULL CHECK (stock_qty >= 0));','INSERT INTO inventory VALUES (1,''Book'',''stationery'',100.00,1,2),(2,''Pad'',''stationery'',90.00,1,NULL),(3,''Pen'',''stationery'',20.00,0,8),(4,''Box'',''storage'',50.00,1,0),(5,''Crate'',''storage'',70.00,1,5),(6,''Cable'',''electronics'',80.00,1,9);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-8-sql-statement-structure' on conflict(id) do nothing;
