update public.learning_topics set short_description='Understand how storage management connects rows to pages, buffers, indexes, space reuse, and recovery, with product-specific limits on page sizes and maintenance effects.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Understand how storage management connects rows to pages, buffers, indexes, space reuse, and recovery, with product-specific limits on page sizes and maintenance effects.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Storage Manager.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-1-storage-manager' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbx2-storage-manager-application','MCQ Test 2',category,10,10,'Application and scenarios for Storage Manager.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-1-storage-manager' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-1','pt-dbms-sql-1-storage-manager','What is the core responsibility of the Storage Manager?','["Translating between the logical view of data (tables/rows) and its physical byte-level layout on disk", "Parsing and optimizing SQL queries", "Enforcing ACID transaction properties", "Authenticating client connections to the DBMS"]'::jsonb,0,'The notes define the Storage Manager''s job as bridging the logical (tables/rows) and physical (bytes on disk) views of data.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-2','pt-dbms-sql-1-storage-manager','What unit does the Storage Manager typically use to organize data on disk?','["Fixed-size pages or blocks, such as 8 KB in PostgreSQL or 16 KB in InnoDB", "Individual bytes with no grouping at all", "Whole tables as a single indivisible unit", "One page per row regardless of row size"]'::jsonb,0,'The notes explicitly describe fixed-size pages (8 KB in PostgreSQL, 16 KB in InnoDB) as the organizing unit.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-3','pt-dbms-sql-1-storage-manager','What is a modified in-memory page called when it differs from the persistent copy that needs to be maintained?','["Dirty", "Encrypted", "Read-only", "Archived"]'::jsonb,0,'The notes state the Storage Manager marks a modified page as ''dirty'' to signal it needs eventual flushing to disk.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-4','pt-dbms-sql-1-storage-manager','Which statement accurately distinguishes maintenance behavior across database products?','["Ordinary PostgreSQL VACUUM generally makes dead-tuple space reusable; MySQL OPTIMIZE TABLE has engine/version-specific reorganization behavior", "Every maintenance command immediately returns all file space to the operating system", "VACUUM and OPTIMIZE TABLE always have identical physical effects", "A large file alone proves which maintenance command is authorized"]'::jsonb,0,'Space reuse, file shrinking, and rebuilding are different outcomes. Check the actual product, mode, target and operational requirements.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-5','pt-dbms-sql-1-storage-manager','Why does the notes say indexes are not a ''free'' performance improvement?','["Indexes use space and need maintenance when relevant indexed representation, membership, or row references change", "Indexes require no storage", "Every index eliminates every write cost", "All updates in all implementations must perform identical index maintenance"]'::jsonb,0,'Index work depends on the operation and engine. The access benefit is not free, but every update need not rewrite every index in every implementation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-6','pt-dbms-sql-1-storage-manager','According to the notes, what physical design choice can hurt I/O efficiency even when the logical schema is well designed?','["A very wide row spanning multiple physical pages, or a poorly chosen page fill-factor", "Using a NOT NULL constraint on a column", "Naming a table with lowercase letters", "Choosing a primary key of type INT instead of BIGINT"]'::jsonb,0,'The notes cite wide rows spanning multiple pages and poor fill-factor choices as physical-layout pitfalls independent of logical schema quality.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-7','pt-dbms-sql-1-storage-manager','A table has relatively few visible rows but a large footprint. Which conclusion is justified before choosing maintenance?','["Investigate allocated/reusable space, versions, indexes, and value storage rather than diagnose one cause from size alone", "The file must always be corrupt", "Every stored byte must be immediately returned by an ordinary delete", "A maintenance command is automatically authorized"]'::jsonb,0,'An apparent size mismatch is an observation. Its cause and the appropriate action require product-specific evidence.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-storage-manager-8','pt-dbms-sql-1-storage-manager','Which responsibilities can participate in a conceptual row insertion, without asserting one universal internal function order?','["Find or allocate space, represent the row, maintain affected structures, and track changed pages under transaction/recovery rules", "Only draw the final response", "Always write every index identically before any other work", "Skip every transaction and recovery facility"]'::jsonb,0,'The responsibilities cooperate. Their exact implementation boundaries and ordering are product-specific.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-1-9','pt-dbms-sql-1-storage-manager','Does a large table file with relatively few visible rows diagnose one specific cause by itself?','["Yes; it always proves one kind of corruption", "No; allocation, versions, indexes, and value storage may need investigation", "Yes; every visible row must be duplicated identically", "No; physical measurements can never be useful"]'::jsonb,1,'A file-size observation is evidence to investigate, not a complete explanation of its cause.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-1-10','pt-dbms-sql-1-storage-manager','Does ordinary PostgreSQL VACUUM guarantee that every table file immediately shrinks at the operating-system level?','["Yes; every deleted row instantly returns all disk bytes", "Yes; it has identical effects to every MySQL maintenance command", "No; it generally makes dead-tuple space reusable without that universal shrink guarantee", "No; it can never make any space reusable"]'::jsonb,2,'Different products and maintenance modes have different physical effects. Reuse and returned filesystem space are distinct.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-1','pt-dbx2-storage-manager-application','An application inserts student 103. Which storage responsibility can be involved?','["Finding or allocating suitable physical space for the row representation", "Inventing a new business identity policy without a model", "Granting the caller every privilege", "Changing every unrelated table name"]'::jsonb,0,'A logical insertion needs an appropriate physical representation, along with relevant index, transaction and integrity work.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-2','pt-dbx2-storage-manager-application','An in-memory P7 page contains a new row that its persistent copy does not yet contain. What state can describe that page?','["Necessarily corrupted", "Dirty", "Automatically a deleted table", "Necessarily already durably committed"]'::jsonb,1,'Dirty means changed relative to the persistent representation; it does not independently establish corruption or commit status.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-3','pt-dbx2-storage-manager-application','A page is already available in a valid buffer. Which cost can be avoided for that access?','["Every possible permission check", "Every other data access in the query", "Every computation needed for the result", "Fetching that page again from persistent storage"]'::jsonb,3,'A cache hit describes that page access, not zero work for the complete request.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-4','pt-dbx2-storage-manager-application','Why is a dirty page not simply discardable as an unchanged cached copy?','["Every dirty page must already be corrupt", "A dirty page can never be replaced by any safe protocol", "Buffering eliminates the need to preserve changes", "Its modifications need suitable persistence and recovery handling"]'::jsonb,3,'The system must coordinate changed contents with its persistence and recovery guarantees.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-5','pt-dbx2-storage-manager-application','A database uses a write-ahead logging recovery protocol. Which ordering matters?','["The log is always discarded before the page changes", "The page must always bypass memory", "Required log information is durable before the corresponding changed data page is persisted", "Every logical change immediately writes every table page"]'::jsonb,2,'The recovery protocol constrains log/data persistence ordering rather than imposing the same immediate flush behavior on every operation.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-6','pt-dbx2-storage-manager-application','A query benefits from an index. Which additional fact should the explanation include?','["The index consumes space and needs maintenance when relevant operations affect it", "Every index is free to store and update", "Every update in every engine rewrites every index identically", "The index removes transaction and recovery responsibilities"]'::jsonb,0,'Access benefits must be considered together with actual storage and maintenance costs.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-7','pt-dbx2-storage-manager-application','A wide logical row includes large variable-length values. What should be checked before predicting its page-access cost?','["An assumption that every row occupies exactly one page", "The actual engine and row format, including possible additional/off-page storage", "A rule that logical meaning determines a universal byte layout", "Only the number of letters in the table name"]'::jsonb,1,'Physical representation varies. One logical row can involve additional access depending on the implementation and data.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-8','pt-dbx2-storage-manager-application','A delete frees space for reuse inside a table but its file remains the same size. Is that inherently contradictory?','["Yes; a delete must always shrink a file immediately", "Yes; every unchanged file is corrupt", "No; reusable internal space and returned filesystem space are different outcomes", "No; the deleted row must still be visible to every query"]'::jsonb,2,'Allocation and maintenance policies can retain space for future use without the same filesystem footprint change.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-9','pt-dbx2-storage-manager-application','An operator proposes OPTIMIZE TABLE based only on a vague fragmentation claim. What is missing?','["Only a shorter command name", "Product-specific diagnosis, exact target, operational planning, and required authorization", "A guarantee that every rebuild is instantaneous", "Proof that all maintenance modes are identical"]'::jsonb,1,'Maintenance can be expensive and have concurrency consequences. It needs relevant evidence and authorization.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbx2-storage-manager-2-10','pt-dbx2-storage-manager-application','A student record moves to a different physical location. What does that not inherently change?','["The logical student identity represented by its key", "Every possible storage byte", "The exact physical access structure", "Every relevant cache observation"]'::jsonb,0,'Logical identity is distinct from where the engine currently represents the row.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
