select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-6-er-and-eer-modeling/strong-entity' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'strong-entity'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'strong-entity'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('5a387b953d778bd5e440501442d7e611','72367bbf9e8b5f74e272315bac203057')) then raise exception 'Notes changed since seed; review before applying: %', 'strong-entity'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-6-strong-entity' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'strong-entity'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-6-strong-entity' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'strong-entity'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-6-strong-entity','pt-dbms-sql-6-strong-entity-application')) then raise exception 'Extra topic tests require manual integration: %', 'strong-entity'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-6-strong-entity-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'strong-entity'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Independent identification and relationship participation are different properties", "description": "Department identity follows department_id, while the presence of courses depends on the separate participation policy. Neither row count nor key width defines strength.", "columns": ["Property", "Question", "Example answer"], "rows": [["Identification", "Does the occurrence need an owner identity to complete its key?", "Department has its own department_id"], ["Participation", "May it currently have no related courses?", "Yes under this example’s policy"], ["Descriptive label", "Can another department share the same name?", "Yes if the domain permits it"], ["Relational mapping", "Is a complete required identity enforced?", "PRIMARY KEY(department_id) in the fixture"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'strong-entity'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Independent identification and relationship participation are different properties", "description": "Department identity follows department_id, while the presence of courses depends on the separate participation policy. Neither row count nor key width defines strength.", "columns": ["Property", "Question", "Example answer"], "rows": [["Identification", "Does the occurrence need an owner identity to complete its key?", "Department has its own department_id"], ["Participation", "May it currently have no related courses?", "Yes under this example’s policy"], ["Descriptive label", "Can another department share the same name?", "Yes if the domain permits it"], ["Relational mapping", "Is a complete required identity enforced?", "PRIMARY KEY(department_id) in the fixture"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Independent identification and relationship participation are different properties", "description": "Department identity follows department_id, while the presence of courses depends on the separate participation policy. Neither row count nor key width defines strength.", "columns": ["Property", "Question", "Example answer"], "rows": [["Identification", "Does the occurrence need an owner identity to complete its key?", "Department has its own department_id"], ["Participation", "May it currently have no related courses?", "Yes under this example’s policy"], ["Descriptive label", "Can another department share the same name?", "Yes if the domain permits it"], ["Relational mapping", "Is a complete required identity enforced?", "PRIMARY KEY(department_id) in the fixture"]]}]'::jsonb;
if exists(select 1 from public.test_questions where test_id='pt-dbms-sql-6-strong-entity' and id not in ('tq-dbms-sql-6-strong-entity-1','tq-dbms-sql-6-strong-entity-2','tq-dbms-sql-6-strong-entity-3','tq-dbms-sql-6-strong-entity-4','tq-dbms-sql-6-strong-entity-5','tq-dbms-sql-6-strong-entity-6','tq-dbms-sql-6-strong-entity-7','tq-dbms-sql-6-strong-entity-8','pt-dbms-sql-6-strong-entity-new-9','pt-dbms-sql-6-strong-entity-new-10')) then raise exception 'Unexpected questions require review: %', 'pt-dbms-sql-6-strong-entity'; end if;
