if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-1' and (question_text,options,correct_index,explanation) is distinct from ('What defines a strong entity?','["It participates in every relationship in the schema", "It possesses its own complete primary key and can be uniquely identified without relying on another entity", "It has at least ten attributes", "It only has single-valued attributes"]'::jsonb,1,'A strong entity has attributes sufficient to form its own primary key, independent of any other entity set.') and (question_text,options,correct_index,explanation) is distinct from ('What defines a strong entity?','["It participates in every relationship in the schema", "Its complete conceptual identifying key does not require an owner entity\u2019s identity for completion", "It has at least ten attributes", "It only has single-valued attributes"]'::jsonb,1,'Strength concerns identification; participation and other domain dependencies can still be mandatory.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-strong-entity-1'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-2' and test_id<>'pt-dbms-sql-6-strong-entity') then raise exception 'Question ID collision: %', 'tq-dbms-sql-6-strong-entity-2'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-2' and test_id='pt-dbms-sql-6-strong-entity') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-6-strong-entity-2'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-2' and (question_text,options,correct_index,explanation) is distinct from ('Which of the following is the correct ER-diagram convention for a strong entity set?','["A double-line rectangle", "A single-line rectangle", "A diamond", "A dashed oval"]'::jsonb,1,'Strong entities use a single-line rectangle; the double-line rectangle is reserved for weak entities.') and (question_text,options,correct_index,explanation) is distinct from ('In the common Chen-style ER convention used here, how is a strong entity set drawn?','["A double-line rectangle", "A single-line rectangle", "A diamond", "A dashed oval"]'::jsonb,1,'Strong entities use a single-line rectangle; the double-line rectangle is reserved for weak entities.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-strong-entity-2'; end if;
