if not exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-3' and test_id='pt-dbms-sql-6-strong-entity') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-6-strong-entity-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-3' and (question_text,options,correct_index,explanation) is distinct from ('A `Department` can exist in the database with zero students enrolled and zero courses defined. This supports classifying `Department` as:','["A weak entity, because it needs students to be meaningful", "A strong entity, because it can be uniquely identified by its own key regardless of related data", "Neither strong nor weak", "A derived entity"]'::jsonb,1,'Being identifiable purely from its own attributes (e.g., Dept_Code) makes Department a strong entity.') and (question_text,options,correct_index,explanation) is distinct from ('Department has an independent department_id key and can be recorded with no students or courses under the model. Which classification fits its identification?','["A weak entity, because it needs students to be meaningful", "A strong entity, because it can be uniquely identified by its own key regardless of related data", "Neither strong nor weak", "A derived entity"]'::jsonb,1,'The independent identifying key establishes strength. Zero current participation is compatible with the stated policy but is not the sole definition.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-strong-entity-3'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-4' and test_id<>'pt-dbms-sql-6-strong-entity') then raise exception 'Question ID collision: %', 'tq-dbms-sql-6-strong-entity-4'; end if;
if not exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-4' and test_id='pt-dbms-sql-6-strong-entity') then raise exception 'Original question was removed; review required: %', 'tq-dbms-sql-6-strong-entity-4'; end if;
if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-4' and (question_text,options,correct_index,explanation) is distinct from ('True or false: a strong entity can never have mandatory (total) participation in a relationship.','["True \u2014 strength and participation are the same property", "False \u2014 strength (self-identification) and participation constraints are independent properties", "True, but only for weak entities", "False, but only in EER diagrams"]'::jsonb,1,'A strong entity can still be required to participate in a relationship; identifiability and participation are separate concepts.') and (question_text,options,correct_index,explanation) is distinct from ('True or false: a strong entity can never have mandatory (total) participation in a relationship.','["True \u2014 strength and participation are the same property", "False \u2014 strength (self-identification) and participation constraints are independent properties", "True, but only for weak entities", "False, but only in EER diagrams"]'::jsonb,1,'A strong entity can still be required to participate in a relationship; identifiability and participation are separate concepts.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-strong-entity-4'; end if;
