if exists(select 1 from public.test_questions where id='tq-dbms-sql-6-strong-entity-5' and (question_text,options,correct_index,explanation) is distinct from ('What is the key differentiator between a strong entity and a weak entity?','["Strong entities have more attributes overall", "A strong entity has its own full primary key; a weak entity does not and depends on an owner entity for full identification", "Weak entities cannot have any attributes", "Strong entities cannot participate in recursive relationships"]'::jsonb,1,'This is the core strong-vs-weak distinction: self-sufficient identification vs. dependence on an owner.') and (question_text,options,correct_index,explanation) is distinct from ('What is the key differentiator between a strong entity and a weak entity?','["Strong entities have more attributes overall", "A strong entity has its own full primary key; a weak entity does not and depends on an owner entity for full identification", "Weak entities cannot have any attributes", "Strong entities cannot participate in recursive relationships"]'::jsonb,1,'This is the core strong-vs-weak distinction: self-sufficient identification vs. dependence on an owner.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-6-strong-entity-5'; end if;
