insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-1','pt-dbms-sql-6-strong-entity','What defines a strong entity?','["It participates in every relationship in the schema", "Its complete conceptual identifying key does not require an owner entity’s identity for completion", "It has at least ten attributes", "It only has single-valued attributes"]'::jsonb,1,'Strength concerns identification; participation and other domain dependencies can still be mandatory.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-2','pt-dbms-sql-6-strong-entity','In the common Chen-style ER convention used here, how is a strong entity set drawn?','["A double-line rectangle", "A single-line rectangle", "A diamond", "A dashed oval"]'::jsonb,1,'Strong entities use a single-line rectangle; the double-line rectangle is reserved for weak entities.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-3','pt-dbms-sql-6-strong-entity','Department has an independent department_id key and can be recorded with no students or courses under the model. Which classification fits its identification?','["A weak entity, because it needs students to be meaningful", "A strong entity, because it can be uniquely identified by its own key regardless of related data", "Neither strong nor weak", "A derived entity"]'::jsonb,1,'The independent identifying key establishes strength. Zero current participation is compatible with the stated policy but is not the sole definition.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-4','pt-dbms-sql-6-strong-entity','True or false: a strong entity can never have mandatory (total) participation in a relationship.','["True — strength and participation are the same property", "False — strength (self-identification) and participation constraints are independent properties", "True, but only for weak entities", "False, but only in EER diagrams"]'::jsonb,1,'A strong entity can still be required to participate in a relationship; identifiability and participation are separate concepts.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-5','pt-dbms-sql-6-strong-entity','What is the key differentiator between a strong entity and a weak entity?','["Strong entities have more attributes overall", "A strong entity has its own full primary key; a weak entity does not and depends on an owner entity for full identification", "Weak entities cannot have any attributes", "Strong entities cannot participate in recursive relationships"]'::jsonb,1,'This is the core strong-vs-weak distinction: self-sufficient identification vs. dependence on an owner.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-6-strong-entity-6','pt-dbms-sql-6-strong-entity','Under a conventional identifying weak-entity mapping, how do the identity choices differ from a strong-entity mapping?','["The strong type has an independent complete conceptual key; the weak mapping combines owner identity with a local discriminator", "They are mapped identically", "A strong entity never becomes a table", "A weak entity''s table has no foreign key at all"]'::jsonb,0,'The strong key can itself be composite. A weak mapped relation still has a complete combined identity under the conventional mapping.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
