if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-super-key-1' and (question_text,options,correct_index,explanation) is distinct from ('What is a super key?','["Any set of attributes that uniquely identifies every row in a relation", "A key that is always exactly one column", "A key used only for foreign key relationships", "A key that can never be a primary key"]'::jsonb,0,'A super key is any attribute set — however large — that uniquely identifies each tuple.') and (question_text,options,correct_index,explanation) is distinct from ('What is a super key?','["An attribute set whose combined values identify tuples across the allowed states of a relation", "A key that is always exactly one column", "A key used only for foreign key relationships", "A key that can never be a primary key"]'::jsonb,0,'A super key is any attribute set — however large — that uniquely identifies each tuple.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-super-key-1'; end if;
