if exists(select 1 from public.test_questions where id='tq-dbms-sql-5-super-key-2' and (question_text,options,correct_index,explanation) is distinct from ('In students(id, name, email, department_id), is {id, name} a super key?','["No, because it contains two columns", "Yes \u2014 since {id} alone is already unique, adding name keeps it unique", "Only if name is also unique on its own", "It is a super key but never a candidate key... this is undecidable"]'::jsonb,1,'Adding any attribute to an already-unique set cannot break uniqueness, so {id, name} remains a super key.') and (question_text,options,correct_index,explanation) is distinct from ('Given a guaranteed student key {id}, is {id, name} a superkey?','["No, because it contains two columns", "Yes \u2014 since {id} alone is already unique, adding name keeps it unique", "Only if name is also unique on its own", "It is a super key but never a candidate key... this is undecidable"]'::jsonb,1,'Adding any attribute to an already-unique set cannot break uniqueness, so {id, name} remains a super key.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-5-super-key-2'; end if;
