update public.learning_topics set short_description='Recognize identifying attribute sets, reason about supersets and functional dependencies, and audit current uniqueness without claiming a sample proves a schema guarantee.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Recognize identifying attribute sets, reason about supersets and functional dependencies, and audit current uniqueness without claiming a sample proves a schema guarantee.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Super Key.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-5-super-key' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-5-super-key-application','MCQ Test 2',category,10,10,'Application and scenarios for Super Key.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-5-super-key' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-1','pt-dbms-sql-5-super-key','What is a super key?','["An attribute set whose combined values identify tuples across the allowed states of a relation", "A key that is always exactly one column", "A key used only for foreign key relationships", "A key that can never be a primary key"]'::jsonb,0,'A super key is any attribute set — however large — that uniquely identifies each tuple.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-2','pt-dbms-sql-5-super-key','Given a guaranteed student key {id}, is {id, name} a superkey?','["No, because it contains two columns", "Yes — since {id} alone is already unique, adding name keeps it unique", "Only if name is also unique on its own", "It is a super key but never a candidate key... this is undecidable"]'::jsonb,1,'Adding any attribute to an already-unique set cannot break uniqueness, so {id, name} remains a super key.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-3','pt-dbms-sql-5-super-key','Given that {id} alone is a key, why is {id, name} not minimal?','["Because id is redundant", "Because name is redundant — {id} alone is already sufficient to uniquely identify rows", "Because it has too few attributes", "Minimality doesn''t apply to super keys"]'::jsonb,1,'Since id alone uniquely identifies rows, including name adds nothing — making the set non-minimal.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-4','pt-dbms-sql-5-super-key','Does every strict set-based relation have a superkey consisting of its full attribute set?','["No, some relations have none", "Yes — in the worst case, the set of all attributes qualifies", "Only relations with a declared PRIMARY KEY have one", "Only relations with fewer than 5 columns have one"]'::jsonb,1,'The full heading distinguishes tuples in the duplicate-free set model; unconstrained SQL bags are a separate case.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-5','pt-dbms-sql-5-super-key','How many super keys can a single relation have?','["Always exactly one", "Always exactly two", "Potentially many — any superset of an existing super key is also one", "Zero, unless a PRIMARY KEY is declared"]'::jsonb,2,'Because adding attributes to a super key produces another super key, relations generally have many possible super keys.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-6','pt-dbms-sql-5-super-key','What is the relationship between a candidate key and a super key?','["They are unrelated concepts", "Every candidate key is a super key, but not every super key is a candidate key (it may not be minimal)", "Every super key is a candidate key", "Candidate keys can never be super keys"]'::jsonb,1,'A candidate key is specifically a MINIMAL super key — so the candidate-key set is a subset of the super-key set.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-7','pt-dbms-sql-5-super-key','If a requirement casually says use the key without naming the intended identity, what is the precise response?','["A super key", "Resolve which identifying constraint is intended; the phrase alone does not specify every key role", "They always mean every possible super key at once", "They mean a foreign key"]'::jsonb,1,'Key terminology should name the intended identifying set instead of relying on a generalization about casual language.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-super-key-8','pt-dbms-sql-5-super-key','If {email} is guaranteed to be a nonmissing identifier, is {email, department_id} a superkey?','["No, adding department_id breaks uniqueness", "Yes, since {email} alone is already unique, any superset of it is also a super key", "Only if department_id is also independently unique", "This cannot be determined without seeing the data"]'::jsonb,1,'Once a set is unique, any superset remains unique — a direct consequence of the super key definition.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-new-9','pt-dbms-sql-5-super-key','Why does adding attributes to a superkey preserve its identifying power?','["New attributes delete old dependencies", "Agreement on the larger set implies agreement on the existing superkey", "Every added attribute is independently unique", "A larger name always identifies"]'::jsonb,1,'The original identifying subset still distinguishes facts.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-new-10','pt-dbms-sql-5-super-key','Can a composite minimal identifying pair also be a superkey?','["No; superkeys are single columns", "Only if both components are individual keys", "Yes; every candidate key is a superkey", "Only if the table has one row"]'::jsonb,2,'Minimality is an additional property within the superkey category.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-1','pt-dbms-sql-5-super-key-application','A sample has unique programmes. Does that prove programme is a schema-level superkey?','["Yes; one sample establishes every state", "Only if alphabetical", "No; future allowed states may repeat a programme", "Only if there are three rows"]'::jsonb,2,'The model needs a guaranteed identification rule.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-2','pt-dbms-sql-5-super-key-application','Under A determines B, B determines C and C determines D, what is the closure of A in R(A,B,C,D)?','["{A} only", "{A, B} only", "{B, C, D} without A", "{A, B, C, D}"]'::jsonb,3,'Repeated dependency application reaches the full heading.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-3','pt-dbms-sql-5-super-key-application','Under the same dependencies only, does B determine A?','["Not established", "Yes; dependencies always reverse", "Only if D is numeric", "Yes; every attribute determines every other"]'::jsonb,0,'A dependency cannot be inverted without an additional guarantee.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-4','pt-dbms-sql-5-super-key-application','What does a duplicate proposed campus-number pair demonstrate?','["A violation by every possible schema", "A current counterexample to pair uniqueness", "That the staging row identifier also repeats", "That names must be keys"]'::jsonb,1,'An audit gives evidence about the tested data.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-5','pt-dbms-sql-5-super-key-application','Why should a pair-identity audit group on both campus_code and local_number?','["Campus never repeats", "Local numbers are globally unique by definition", "Each component participates in the combined identity", "Grouping on proposal_id would find more conflicts"]'::jsonb,2,'Cross-campus reuse can be valid while repeated full pairs conflict.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
