insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-super-key-application-new-8','pt-dbms-sql-5-super-key-application','What does no duplicate group in one audit establish?','["A universal future identity guarantee", "No observed conflict in that dataset", "A primary-key declaration", "Every dependency in the model"]'::jsonb,1,'Absence of a sample counterexample is weaker than an enforced rule.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
