insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-1','pt-dbms-sql-5-surrogate-key','What defines a surrogate key?','["A key with deep real-world business meaning", "An artificial identifying value introduced independently of the descriptive business attributes", "A key that must always be a UUID specifically", "A backup key used only when the primary key fails"]'::jsonb,1,'A surrogate supplies internal identity; its public visibility and generation mechanism are separate decisions.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-2','pt-dbms-sql-5-surrogate-key','Why can a surrogate key often remain stable when a student’s business labels change?','["Because it is encrypted", "Its internal identity role is separate from those labels, though exceptional migrations or corrections still need review", "Because SQL forbids updating surrogate keys", "Because surrogate keys are always the same value for every row"]'::jsonb,1,'Stability is a policy and design advantage, not a universal impossibility of change.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-3','pt-dbms-sql-5-surrogate-key','If an institutional number is genuinely required and unique by policy, does a surrogate primary key remove that obligation?','["No, the surrogate key makes that unnecessary", "Yes — it should still be enforced with a UNIQUE constraint, or duplicate real-world entities could be inserted as if they were different rows", "Only if the table has fewer than 100 rows", "Natural keys cannot coexist with surrogate keys in the same table"]'::jsonb,1,'The independently justified business uniqueness rule still needs appropriate enforcement; not every email field inherently has that rule.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-4','pt-dbms-sql-5-surrogate-key','What potential downside does a simple auto-incrementing integer surrogate key have?','["It cannot be indexed", "Exposed sequential patterns can reveal information, but gaps mean they do not reliably give exact counts or event times", "It always takes more storage than a UUID", "It cannot be used as a primary key"]'::jsonb,1,'Identifier patterns and exposure need deliberate handling; authorization must remain enforced independently.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-5','pt-dbms-sql-5-surrogate-key','Why might a distributed system (e.g. offline mobile clients generating their own new-record ids) avoid a simple incrementing counter as the surrogate key scheme?','["Incrementing counters are illegal in distributed systems", "Uncoordinated counters can collide; a suitable allocation or decentralized identifier scheme can address the risk", "Distributed systems cannot use surrogate keys at all", "This scenario has no real bearing on key design"]'::jsonb,1,'Collision risk depends on the actual scheme and correct generation. UUID terminology alone does not prove a perfect no-collision guarantee.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-6','pt-dbms-sql-5-surrogate-key','What is the main trade-off of choosing a surrogate key over a natural key?','["No trade-off exists", "Gaining stability/simplicity at the cost of the key having no meaning outside the database", "Surrogate keys are always slower for every operation", "Surrogate keys cannot be used with foreign keys"]'::jsonb,1,'This mirrors the natural-key trade-off from the other direction: stability and simplicity vs. real-world meaningfulness.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-surrogate-key-7','pt-dbms-sql-5-surrogate-key','Is `customer_id = 4821` on its own informative to a human reading it?','["Yes, it reveals the customer''s name", "It does not by itself reveal the customer’s descriptive identity; a lookup and authorized access may be needed", "It reveals the customer''s registration date exactly", "It reveals the customer''s email address"]'::jsonb,1,'A surrogate has no required descriptive semantics, though allocation patterns can still reveal limited information.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
