insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-table-constraints-1','pt-dbms-sql-10-table-constraints','What structurally distinguishes a table constraint from a column constraint in CREATE TABLE syntax?','["A table constraint must always be CHECK", "A table constraint is written as its own separate clause naming its target column(s) explicitly, rather than being attached inline to one column''s definition", "A table constraint cannot be named", "A table constraint can only be added via ALTER TABLE, never CREATE TABLE"]'::jsonb,1,'Table constraints appear as standalone clauses within CREATE TABLE, listing the relevant column(s) in parentheses, unlike column constraints which are embedded in a single column''s definition.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
