update public.learning_topics set short_description='Control transactional row changes with START TRANSACTION, COMMIT, ROLLBACK, and SAVEPOINT, while distinguishing session ownership, autocommit, statement errors, and implicit commits.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Control transactional row changes with START TRANSACTION, COMMIT, ROLLBACK, and SAVEPOINT, while distinguishing session ownership, autocommit, statement errors, and implicit commits.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for TCL.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-8-tcl' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-8-tcl-application','MCQ Test 2',category,10,10,'Application and scenarios for TCL.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-8-tcl' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-1','pt-dbms-sql-8-tcl','What does COMMIT do for a valid current InnoDB transaction?','["ROLLBACK", "It completes the transaction and accepts its pending transactional effects", "SAVEPOINT", "GRANT"]'::jsonb,1,'Durability and confirmation still depend on the actual engine and operational guarantees.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-2','pt-dbms-sql-8-tcl','What does a full ROLLBACK discard in the current transaction?','["COMMIT", "Its pending transactional changes, not every earlier committed or nontransactional effect", "REVOKE", "ALTER"]'::jsonb,1,'The scope is transactional work still pending in the current boundary.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-3','pt-dbms-sql-8-tcl','Why group the debit and credit of a transfer under a correct transaction and failure policy?','["To make the query run faster", "To commit both valid effects together or roll back the intended unit when it cannot complete", "Because SQL requires every UPDATE to be paired with another UPDATE", "To avoid needing a WHERE clause"]'::jsonb,1,'The application must handle errors and enforce the full trusted business rules; keywords alone are insufficient.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-4','pt-dbms-sql-8-tcl','What does a SAVEPOINT let you do that plain COMMIT/ROLLBACK cannot?','["Permanently save data even without ever committing", "Mark an intermediate point inside a longer transaction that you can roll back to, without discarding the whole transaction", "Grant privileges to another user", "Create a new table"]'::jsonb,1,'SAVEPOINT allows partial rollback to a marked point, rather than an all-or-nothing rollback of the entire transaction.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-5','pt-dbms-sql-8-tcl','What does ''auto-commit mode'' mean for a database connection?','["Every statement automatically becomes part of one giant, permanent transaction that never ends", "Each individual statement is implicitly wrapped in and completed by its own commit, unless an explicit transaction is started", "COMMIT is disabled entirely in auto-commit mode", "Auto-commit mode disables all DML statements"]'::jsonb,1,'In auto-commit mode (the common default), each statement commits on its own; an explicit BEGIN groups multiple statements into one atomic unit instead.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-6','pt-dbms-sql-8-tcl','Which ACID property does TCL most directly implement and control at the SQL level?','["Atomicity", "Consistency alone, with no relation to atomicity", "Only Durability", "None of the ACID properties relate to TCL"]'::jsonb,0,'TCL''s all-or-nothing COMMIT/ROLLBACK model is specifically how atomicity — one of the four ACID guarantees — is expressed and controlled via SQL.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-7','pt-dbms-sql-8-tcl','Why can a long-running, idle-but-open transaction be an operational hazard even if it never gets rolled back?','["It has no real cost as long as it is eventually committed", "It can continue holding locks and blocking other work the whole time it stays open, regardless of whether the application is actively using it", "Open transactions automatically time out and self-commit after one second", "Idle transactions consume no database resources at all"]'::jsonb,1,'Held locks from an open transaction can block other sessions for as long as the transaction remains open, whether or not it''s doing active work — a real, easy-to-overlook cost.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-8-tcl-8','pt-dbms-sql-8-tcl','Can ROLLBACK be assumed to undo any DDL operation on any database?','["Yes, this is guaranteed identically on every SQL database", "No; implicit-commit and rollback behavior depend on the exact product, engine, and operation", "ROLLBACK only ever affects SELECT statements", "DDL statements cannot appear inside a transaction on any engine"]'::jsonb,1,'This avoids the incorrect universal SQL Server claim in the retained question.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-new-9','pt-dbms-sql-8-tcl','Does ROLLBACK TO SAVEPOINT commit the changes before the marker?','["Yes; it always commits them", "No; retained changes remain pending in the open transaction", "Only on the first connection", "Only if the marker name is short"]'::jsonb,1,'Partial rollback and successful transaction completion are distinct.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-new-10','pt-dbms-sql-8-tcl','Why keep all statements of the ordinary session-based transaction on the intended connection?','["Every session shares one global transaction", "Pooling disables all state", "The transaction context belongs to that session", "Consecutive API calls always use the same connection"]'::jsonb,2,'A sequence of calls can otherwise use unrelated transactional contexts.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-1','pt-dbms-sql-8-tcl-application','Quantity 3 is changed to 0 and then rolled back before commit in the fixture. What is the final quantity?','["0", "1", "3", "6"]'::jsonb,2,'The uncommitted row change is discarded.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-2','pt-dbms-sql-8-tcl-application','Item 1 is increased before a savepoint; item 2 is increased after it. ROLLBACK TO that marker then COMMIT occurs. Which increase survives?','["Both increases", "Only item 2''s later increase", "Neither because savepoints always remove earlier work", "Only item 1''s earlier increase"]'::jsonb,3,'The partial rollback removes the later change and the commit accepts the retained one.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-3','pt-dbms-sql-8-tcl-application','A savepoint is released and a full ROLLBACK follows. What should not be assumed?','["That releasing the marker committed earlier pending changes", "That the transaction has a lifecycle", "That a marker can be removed", "That rollback scope matters"]'::jsonb,0,'Releasing a savepoint is not a subtransaction commit.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-4','pt-dbms-sql-8-tcl-application','An autocommitted update succeeded long before ROLLBACK is issued. What is unsafe to expect?','["That the successful update had a boundary", "That the later rollback reverses that completed statement", "That actual session mode matters", "That explicit transactions can group work"]'::jsonb,1,'A later rollback does not undo arbitrary previous commits.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-5','pt-dbms-sql-8-tcl-application','A later statement errors but earlier writes remain pending. What must the caller do?','["Assume every earlier statement vanished", "Return the connection unfinished", "Apply the intended failure policy and complete or roll back the correct unit", "Report unconditional success"]'::jsonb,2,'Statement failure and full transaction rollback can have different scopes.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-6','pt-dbms-sql-8-tcl-application','The commit response is lost and the client reconnects. What remains uncertain?','["Whether a new session can exist", "Whether the caller lacked a timely response", "Whether errors need handling", "Whether the earlier transaction committed"]'::jsonb,3,'A new connection does not resolve the previous commit outcome.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
