insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-8-tcl-application-new-8','pt-dbms-sql-8-tcl-application','An open transaction becomes idle after holding locks. Why can it still matter?','["Idle always means resource-free", "It can retain resources and block other work", "It automatically commits after one second", "Locks only exist while the UI animates"]'::jsonb,1,'Transaction lifetime can outlast active statement execution.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
