if exists(select 1 from public.dsa_problems where learning_topic_id=topic_uuid and id not in ('dsa-dbms-sql-tcl-full-rollback','dsa-dbms-sql-tcl-savepoint')) then raise exception 'Existing coding problems require explicit integration: %', 'tcl'; end if;
if exists(select 1 from public.dsa_problems where (id='dsa-dbms-sql-tcl-full-rollback' or slug='tcl-full-rollback') and (id<>'dsa-dbms-sql-tcl-full-rollback' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'dsa-dbms-sql-tcl-full-rollback'; end if;
if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-tcl-full-rollback' and description is distinct from 'Start a transaction, set quantity to 0 for item_id 1, and roll back that transaction. Return item_id, quantity for all stock rows ordered by item_id. The provided InnoDB fixture is established before your transaction.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;
INSERT INTO stock VALUES (2,8),(1,3);
```

**Required ordering:** item_id ascending

**Edge cases:**
- Missing item 1 leaves other rows unchanged
- Original zero remains zero
- Empty input returns no rows') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-tcl-full-rollback'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-tcl-full-rollback',null::text,'Discard a provisional stock reset','Easy','tcl-full-rollback','Start a transaction, set quantity to 0 for item_id 1, and roll back that transaction. Return item_id, quantity for all stock rows ordered by item_id. The provided InnoDB fixture is established before your transaction.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;
INSERT INTO stock VALUES (2,8),(1,3);
```

**Required ordering:** item_id ascending

**Edge cases:**
- Missing item 1 leaves other rows unchanged
- Original zero remains zero
- Empty input returns no rows','[{"input": "INSERT INTO stock VALUES (2,8),(1,3);", "output": "item_id\tquantity\n1\t3\n2\t8", "explanation": "The final read occurs after rollback, so the provisional transactional update does not replace the fixture quantity. The output check alone cannot prove a student used transaction controls; the reference script is executed and reviewed."}]'::jsonb,'[{"seed_sql": "INSERT INTO stock VALUES (9,4);", "expected": "item_id\tquantity\n9\t4", "hidden": true}, {"seed_sql": "", "expected": "", "hidden": true}]'::jsonb,'["InnoDB transactional rows", "Quantity required and nonnegative", "Do not create or alter objects inside the transaction"]'::jsonb,'["Use START TRANSACTION before UPDATE", "Use full ROLLBACK before the final SELECT"]'::jsonb,'{"sql": "-- Begin, update the target, roll back, then read final rows.\n"}'::jsonb,'The final read occurs after rollback, so the provisional transactional update does not replace the fixture quantity. The output check alone cannot prove a student used transaction controls; the reference script is executed and reviewed.','{"sql": "START TRANSACTION;\nUPDATE stock SET quantity = 0 WHERE item_id = 1;\nROLLBACK;\nSELECT item_id,quantity FROM stock ORDER BY item_id;"}'::jsonb,'The final read occurs after rollback, so the provisional transactional update does not replace the fixture quantity. The output check alone cannot prove a student used transaction controls; the reference script is executed and reviewed.',array['sql'],'CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;','INSERT INTO stock VALUES (2,8),(1,3);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-8-tcl' on conflict(id) do nothing;
if exists(select 1 from public.dsa_problems where (id='dsa-dbms-sql-tcl-savepoint' or slug='tcl-savepoint') and (id<>'dsa-dbms-sql-tcl-savepoint' or learning_topic_id is distinct from topic_uuid)) then raise exception 'Coding ID/slug collision: %', 'dsa-dbms-sql-tcl-savepoint'; end if;
if exists(select 1 from public.dsa_problems where id='dsa-dbms-sql-tcl-savepoint' and description is distinct from 'Start a transaction. Add 2 to quantity for item_id 1, set a savepoint named after_primary, add 5 to item_id 2, roll back to after_primary, and commit. Return item_id, quantity for all rows ordered by item_id. Preserve unrelated stock rows.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;
INSERT INTO stock VALUES (3,0),(2,8),(1,3);
```

**Required ordering:** item_id ascending

**Edge cases:**
- Missing item 1 must not change the item 2 rollback policy
- An unrelated item is unchanged
- Item 2 may be absent
- Empty input remains empty') then raise exception 'New coding ID already has other content: %', 'dsa-dbms-sql-tcl-savepoint'; end if;
insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'dsa-dbms-sql-tcl-savepoint',null::text,'Commit an earlier change after partial rollback','Medium','tcl-savepoint','Start a transaction. Add 2 to quantity for item_id 1, set a savepoint named after_primary, add 5 to item_id 2, roll back to after_primary, and commit. Return item_id, quantity for all rows ordered by item_id. Preserve unrelated stock rows.

**MySQL dialect.**

```sql
CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;
INSERT INTO stock VALUES (3,0),(2,8),(1,3);
```

**Required ordering:** item_id ascending

**Edge cases:**
- Missing item 1 must not change the item 2 rollback policy
- An unrelated item is unchanged
- Item 2 may be absent
- Empty input remains empty','[{"input": "INSERT INTO stock VALUES (3,0),(2,8),(1,3);", "output": "item_id\tquantity\n1\t5\n2\t8\n3\t0", "explanation": "The marker follows the first increment. Partial rollback discards the later increment while leaving the earlier one pending, and COMMIT accepts the retained change. Output fixtures validate final state; exact use of the required controls also needs source review."}]'::jsonb,'[{"seed_sql": "INSERT INTO stock VALUES (2,0),(7,9);", "expected": "item_id\tquantity\n2\t0\n7\t9", "hidden": true}, {"seed_sql": "INSERT INTO stock VALUES (1,0);", "expected": "item_id\tquantity\n1\t2", "hidden": true}]'::jsonb,'["All rows use InnoDB", "No structural or implicit-commit operation inside the transaction", "Quantities nonnegative"]'::jsonb,'["Create the savepoint after the first update", "ROLLBACK TO SAVEPOINT keeps the transaction open", "COMMIT the retained work before reading"]'::jsonb,'{"sql": "-- Use both full transaction completion and a partial rollback marker.\n"}'::jsonb,'The marker follows the first increment. Partial rollback discards the later increment while leaving the earlier one pending, and COMMIT accepts the retained change. Output fixtures validate final state; exact use of the required controls also needs source review.','{"sql": "START TRANSACTION;\nUPDATE stock SET quantity = quantity + 2 WHERE item_id = 1;\nSAVEPOINT after_primary;\nUPDATE stock SET quantity = quantity + 5 WHERE item_id = 2;\nROLLBACK TO SAVEPOINT after_primary;\nCOMMIT;\nSELECT item_id,quantity FROM stock ORDER BY item_id;"}'::jsonb,'The marker follows the first increment. Partial rollback discards the later increment while leaving the earlier one pending, and COMMIT accepts the retained change. Output fixtures validate final state; exact use of the required controls also needs source review.',array['sql'],'CREATE TABLE stock (item_id INT PRIMARY KEY, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;','INSERT INTO stock VALUES (3,0),(2,8),(1,3);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,1 from public.practice_tests parent where parent.id='pt-dbms-sql-8-tcl' on conflict(id) do nothing;
