update public.learning_topics set short_description='Use connection-scoped working tables for inspectable stages, keep pooling and transaction lifetimes explicit, and avoid inferring persistent integrity or recovery from temporary lab state.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Use connection-scoped working tables for inspectable stages, keep pooling and transaction lifetimes explicit, and avoid inferring persistent integrity or recovery from temporary lab state.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Temporary Tables.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-9-temporary-tables' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-9-temporary-tables-application','MCQ Test 2',category,10,10,'Application and scenarios for Temporary Tables.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-9-temporary-tables' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-1','pt-dbms-sql-9-temporary-tables','What scope defines the illustrated MySQL temporary table?','["It cannot contain any data", "Its creating session controls visibility and lifetime", "It must always be empty", "It can only contain one column"]'::jsonb,1,'Do not infer that every product has the same transaction-end policy.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-2','pt-dbms-sql-9-temporary-tables','Why must SQL Server local and global temporary-table lifetimes be read from product rules?','["They are identical in every respect", "They have different visibility and removal conditions involving the creating session and relevant active references", "##temp is local; #temp is global", "#temp tables persist forever like normal tables"]'::jsonb,1,'Global lifetime is not simply every connected session must disconnect.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-3','pt-dbms-sql-9-temporary-tables','What does PostgreSQL''s ON COMMIT DROP option do for a temporary table?','["Prevents the table from ever being dropped", "Automatically drops the table at the end of the transaction that created it", "Drops the table only when the database server restarts", "Converts the temp table into a permanent table"]'::jsonb,1,'ON COMMIT DROP scopes the temp table''s lifetime to just the current transaction rather than the whole session.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-4','pt-dbms-sql-9-temporary-tables','Why can heavy use of temporary tables become a serious performance concern specifically on SQL Server?','["Temporary tables are always stored in RAM with no limits", "Because they are stored in tempdb, and contention there under heavy concurrent use is a well-known bottleneck", "SQL Server does not support temporary tables at all", "Temporary tables automatically lock the entire database"]'::jsonb,1,'tempdb contention from heavy temp-table use is a recognized SQL Server operational issue.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-5','pt-dbms-sql-9-temporary-tables','Why might an application see a ''table not found'' error for a temp table it just created, in an environment using connection pooling?','["Temp tables are never supported with connection pooling", "A subsequent operation may run on a different physical pooled connection that never created and cannot see that session-scoped temp table", "The temp table was automatically renamed", "The database ran out of storage"]'::jsonb,1,'Session-scoped temp tables aren''t visible across different physical connections, which pooling can silently switch between.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-6','pt-dbms-sql-9-temporary-tables','Should ordinary durable recovery be assumed to restore a session’s temporary working state?','["Yes, always, just like permanent tables", "No; transient state is not a durable application-record contract", "Only if explicitly requested at creation time", "Only global temp tables are backed up"]'::jsonb,1,'Explicit export is possible but creates a different artifact and lifecycle.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-7','pt-dbms-sql-9-temporary-tables','What can staged temporary tables improve without guaranteeing better performance?','["It always makes the query run faster with zero trade-offs", "Inspection of intermediate contracts, with possible additional materialization cost", "It eliminates the need for any indexes", "It automatically parallelizes the whole report"]'::jsonb,1,'Measure actual resource and optimizer effects rather than assuming a speedup.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-temporary-tables-8','pt-dbms-sql-9-temporary-tables','What is a common constraint-related limitation involving temporary tables in several engines?','["Temporary tables can never have a primary key", "Some engines restrict or disallow foreign keys between temporary tables and permanent tables", "Temporary tables must always have exactly one column", "Temporary tables cannot store numeric data"]'::jsonb,1,'Cross-referencing constraints between temp and permanent tables are limited or disallowed in a number of engines.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-temporary-tables-new-9','pt-dbms-sql-9-temporary-tables','Does a logical web request necessarily use one database session?','["Yes, on every provider", "No", "Only if it has headings", "Only when SQL is short"]'::jsonb,1,'Connection pooling needs an explicit supported scope.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-temporary-tables-new-10','pt-dbms-sql-9-temporary-tables','What can happen if a pooled physical connection outlives a request?','["All tables automatically become permanent", "Every constraint disappears", "Its temporary state can remain until cleanup or session end", "The request gains admin rights"]'::jsonb,2,'Request lifetime and connection lifetime differ.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
