if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-three-schema-architecture-5' and (question_text,options,correct_index,explanation) is distinct from ('If Payroll names a field `Salary` and Finance names the same conceptual attribute `Pay`, at what point must this naming conflict be resolved?','["In the internal schema''s storage layout", "In each external schema''s own mapping to the conceptual schema", "It cannot be resolved without merging both applications", "By renaming the conceptual attribute itself to match both"]'::jsonb,1,'Each external schema has its own external/conceptual mapping, so naming differences are resolved per view without altering the shared conceptual schema.') and (question_text,options,correct_index,explanation) is distinct from ('If Payroll names a field `Salary` and Finance names the same conceptual attribute `Pay`, at what point must this naming conflict be resolved?','["In the internal schema''s storage layout", "In each external schema''s own mapping to the conceptual schema", "It cannot be resolved without merging both applications", "By renaming the conceptual attribute itself to match both"]'::jsonb,1,'Each external schema has its own external/conceptual mapping, so naming differences are resolved per view without altering the shared conceptual schema.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-three-schema-architecture-5'; end if;
