if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-three-tier-architecture-2' and (question_text,options,correct_index,explanation) is distinct from ('In three-tier architecture, where does the business logic reside, in contrast to two-tier?','["On the client, same as two-tier", "On the middle application-server tier, not the client", "On the database server", "Nowhere; three-tier has no business logic layer"]'::jsonb,1,'Three-tier architecture moves business logic off the client and into a dedicated middle tier, unlike two-tier''s client-embedded logic.') and (question_text,options,correct_index,explanation) is distinct from ('In three-tier architecture, where does the business logic reside, in contrast to two-tier?','["On the client, same as two-tier", "On the middle application-server tier, not the client", "On the database server", "Nowhere; three-tier has no business logic layer"]'::jsonb,1,'The application tier owns shared orchestration, while the database retains its configured integrity and transaction rules and the client can still manage UI logic.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-three-tier-architecture-2'; end if;
