if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-three-tier-architecture-3' and (question_text,options,correct_index,explanation) is distinct from ('What is Tier 1 commonly called in three-tier architecture, since it contains only the UI?','["A fat client", "A thin client", "A database driver", "A middleware gateway"]'::jsonb,1,'Tier 1 is called a thin client because it holds only presentation logic, with business logic moved to Tier 2.') and (question_text,options,correct_index,explanation) is distinct from ('What is the presentation client commonly called when shared protected workflows live in the application tier?','["A fat client", "A thin client", "A database driver", "A middleware gateway"]'::jsonb,1,'Thin client refers to the responsibility split; a rich interface can still have formatting, state, and usability logic.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-three-tier-architecture-3'; end if;
