update public.learning_topics set short_description='Trace presentation, application, and database responsibilities in a three-tier portal, including trusted validation, connection budgets, deployment compatibility, and failure handling.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Trace presentation, application, and database responsibilities in a three-tier portal, including trusted validation, connection budgets, deployment compatibility, and failure handling.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Three Tier Architecture.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-three-tier-architecture' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-three-tier-architecture-application','MCQ Test 2',category,10,10,'Application and scenarios for Three Tier Architecture.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-three-tier-architecture' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-1','pt-dbms-sql-2-three-tier-architecture','What are the three tiers in Three-Tier Architecture?','["Client, database, and network", "Presentation/client (thin client), application server (business logic), and database server", "Internal schema, conceptual schema, and external schema", "Driver, middleware, and API"]'::jsonb,1,'Three-tier architecture separates presentation, business logic, and data storage into three distinct tiers.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-2','pt-dbms-sql-2-three-tier-architecture','In three-tier architecture, where does the business logic reside, in contrast to two-tier?','["On the client, same as two-tier", "On the middle application-server tier, not the client", "On the database server", "Nowhere; three-tier has no business logic layer"]'::jsonb,1,'The application tier owns shared orchestration, while the database retains its configured integrity and transaction rules and the client can still manage UI logic.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-3','pt-dbms-sql-2-three-tier-architecture','What is the presentation client commonly called when shared protected workflows live in the application tier?','["A fat client", "A thin client", "A database driver", "A middleware gateway"]'::jsonb,1,'Thin client refers to the responsibility split; a rich interface can still have formatting, state, and usability logic.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-4','pt-dbms-sql-2-three-tier-architecture','How can a three-tier application reduce persistent database-session demand from many end users?','["By requiring every client to still open its own direct database connection", "By letting the middle tier pool and share database connections across many users instead of one connection per client", "By removing the database server entirely", "By moving business logic back onto the client"]'::jsonb,1,'A configured middle-tier pool can reuse bounded sessions over time. It is not automatic and total demand includes every instance.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-5','pt-dbms-sql-2-three-tier-architecture','What is the practical benefit of moving business logic off the client and into the application server tier?','["A business rule change only requires updating the application server once, not redeploying to every client machine", "It makes the database server unnecessary", "It increases the number of direct connections to the database", "It removes the need for a presentation layer"]'::jsonb,0,'Central service changes reduce fleet distribution work, but existing API compatibility and database contracts still need review.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-6','pt-dbms-sql-2-three-tier-architecture','What new architectural risk does adding a middle application-server tier introduce, according to the notes?','["The database server no longer needs to enforce integrity", "The application server itself can become a bottleneck or single point of failure, typically mitigated with load-balanced instances", "Clients can no longer connect to any tier", "Business logic can no longer be centralized"]'::jsonb,1,'The middle tier, now handling logic and connections for many users, can itself become a bottleneck unless multiple load-balanced instances are used.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-7','pt-dbms-sql-2-three-tier-architecture','A developer claims three-tier architecture makes the database server (Tier 3) unimportant since business logic has moved to Tier 2. Why is this claim incorrect?','["It is correct; Tier 3 becomes irrelevant in three-tier systems", "Tier 3 still fully owns data storage and integrity enforcement; only business logic and connection management moved to Tier 2", "Tier 3 is merged into Tier 2 in three-tier architecture", "Three-tier architecture removes the need for any database at all"]'::jsonb,1,'The database server continues to store data and enforce integrity in three-tier architecture; what changed is where business logic and connection handling live, not the database''s role.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-three-tier-architecture-8','pt-dbms-sql-2-three-tier-architecture','In a portal whose measurements show higher per-request latency after adding the application tier, which added cost can help explain the difference?','["The extra network hop introduced between client and database (client to app server to database)", "The removal of the database server", "The elimination of business logic altogether", "A reduction in the number of tiers"]'::jsonb,0,'The added boundary can introduce hop and processing overhead. Actual latency depends on the full implementation and may improve in other workloads.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-new-9','pt-dbms-sql-2-three-tier-architecture','Does a rich browser form with local state contradict three-tier architecture?','["Yes; a thin client can contain no code", "No; protected shared authority can remain in the trusted application and database tiers", "Yes; every form field is a database tier", "Only if no validation is shown"]'::jsonb,1,'The split concerns ownership and trust, not the absence of client-side behavior.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-new-10','pt-dbms-sql-2-three-tier-architecture','What must a trusted enrollment service establish about a submitted StudentID?','["Only that it is present in the request", "Only that its text is short", "That the actor may perform this operation for that student", "Only that the browser dropdown included it"]'::jsonb,2,'A client-controlled identifier does not prove permission.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-1','pt-dbms-sql-2-three-tier-architecture-application','Two application instances read one remaining seat and both approve enrollment locally. What is still needed?','["A third application instance alone", "A brighter success message", "Trusted concurrent enforcement in the actual write operation", "A larger dropdown"]'::jsonb,2,'A check-then-write sequence is not made atomic by a middle tier.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-2','pt-dbms-sql-2-three-tier-architecture-application','Four application instances each allow twenty pooled sessions. What capacity budget must include their combined potential?','["Twenty sessions regardless of instance count", "Four sessions only", "Exactly one session per signed-in user", "Eighty sessions plus other database clients"]'::jsonb,3,'Pools may be per instance, so their limits add.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-3','pt-dbms-sql-2-three-tier-architecture-application','An application release changes an API field used by older clients. Does central deployment remove the compatibility obligation?','["No; older callers still rely on their contracts", "Yes; all clients update automatically", "Yes; the database rewrites every response", "Only the number of tiers matters"]'::jsonb,0,'Centralizing logic does not make response changes invisible to existing callers.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-4','pt-dbms-sql-2-three-tier-architecture-application','A browser sends another student''s ID, and the server trusts it without checking. Which tier boundary failed?','["Only page rendering", "Trusted actor-to-operation authorization", "Only connection-pool cleanup", "Only the internal index choice"]'::jsonb,1,'The application must not treat a caller-controlled identity reference as authority.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-5','pt-dbms-sql-2-three-tier-architecture-application','A duplicate enrollment request arrives after the first response was lost. What should govern the outcome?','["An assumption that no commit happened", "Blind repetition of every side effect", "The operation''s defined duplicate and retry behavior", "The page title alone"]'::jsonb,2,'Uncertain outcomes need an explicit contract across retries.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-6','pt-dbms-sql-2-three-tier-architecture-application','A local-memory workflow is routed to a different application instance and disappears. What must be reviewed?','["Only the number of columns in Student", "Only whether SQL is uppercase", "Only the CSS display property", "State placement and routing assumptions"]'::jsonb,3,'Scaling changes where requests execute; instance-local state may not follow them.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-7','pt-dbms-sql-2-three-tier-architecture-application','The application tier validates references. Why retain appropriate database foreign keys?','["They protect shared integrity across trusted write paths", "They only affect page styling", "They are unnecessary whenever a server exists", "They automatically authenticate every browser"]'::jsonb,0,'Application validation does not replace shared database integrity guarantees.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-8','pt-dbms-sql-2-three-tier-architecture-application','An extra network hop is introduced, but measured latency falls because queries and transfer volume improve. Is that impossible?','["Yes; tier count alone fixes latency", "No; total latency depends on all costs and savings", "Yes; pooling never changes setup costs", "Only the number of HTML tags matters"]'::jsonb,1,'A hop is one cost among many in the implemented path.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-9','pt-dbms-sql-2-three-tier-architecture-application','A load-balanced application has the same flawed access check on every instance. What does redundancy fail to solve?','["The ability to route a request", "The existence of several processes", "The shared authorization defect", "The configured pool limit"]'::jsonb,2,'Replicating incorrect logic does not make it correct.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-three-tier-architecture-application-new-10','pt-dbms-sql-2-three-tier-architecture-application','The application builds successfully. Which claim still requires separate evidence?','["The build command completed", "The source contains application code", "The tiers can have distinct responsibilities", "Database behavior, live deployment, and end-to-end verification are correct"]'::jsonb,3,'A build is not proof of enforcement, deployment, or live behavior.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
-- transaction-manager
select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-1-database-foundations/transaction-manager' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'transaction-manager'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'transaction-manager'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('1d4e54e1420fffaef6ee2cf51b81413e','620a49851987e966c218e7c442b465c0')) then raise exception 'Notes changed since seed; review before applying: %', 'transaction-manager'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-1-transaction-manager' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'transaction-manager'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-1-transaction-manager' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'transaction-manager'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-1-transaction-manager','pt-dbx2-transaction-manager-application')) then raise exception 'Extra topic tests require manual integration: %', 'transaction-manager'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbx2-transaction-manager-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'transaction-manager'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Conceptual transfer outcomes under an assumed atomic transaction", "description": "These are illustrative balances, not executed SQL results. A working state is not a promised public snapshot. The intended operation moves 100 from A to B; a correct committed outcome preserves total 1,500, while a canceled transaction restores the initial balances.", "columns": ["Illustrated state", "Account A", "Account B", "Meaning"], "rows": [["Initial", "1,000", "500", "Starting balances"], ["After debit inside unfinished work", "900", "500", "Intermediate working state; not the intended committed result"], ["After complete successful transaction", "900", "600", "Intended debit and credit together"], ["After rollback before commit", "1,000", "500", "Uncommitted grouped work undone"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'transaction-manager'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Conceptual transfer outcomes under an assumed atomic transaction", "description": "These are illustrative balances, not executed SQL results. A working state is not a promised public snapshot. The intended operation moves 100 from A to B; a correct committed outcome preserves total 1,500, while a canceled transaction restores the initial balances.", "columns": ["Illustrated state", "Account A", "Account B", "Meaning"], "rows": [["Initial", "1,000", "500", "Starting balances"], ["After debit inside unfinished work", "900", "500", "Intermediate working state; not the intended committed result"], ["After complete successful transaction", "900", "600", "Intended debit and credit together"], ["After rollback before commit", "1,000", "500", "Uncommitted grouped work undone"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Conceptual transfer outcomes under an assumed atomic transaction", "description": "These are illustrative balances, not executed SQL results. A working state is not a promised public snapshot. The intended operation moves 100 from A to B; a correct committed outcome preserves total 1,500, while a canceled transaction restores the initial balances.", "columns": ["Illustrated state", "Account A", "Account B", "Meaning"], "rows": [["Initial", "1,000", "500", "Starting balances"], ["After debit inside unfinished work", "900", "500", "Intermediate working state; not the intended committed result"], ["After complete successful transaction", "900", "600", "Intended debit and credit together"], ["After rollback before commit", "1,000", "500", "Uncommitted grouped work undone"]]}]'::jsonb;
