if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-transaction-manager-2' and (question_text,options,correct_index,explanation) is distinct from ('In the fund-transfer example, what does ''Atomicity'' guarantee?','["Either both UPDATE statements take effect, or neither does", "The transaction always completes within one second", "Only the DBA can see the transaction''s changes", "The transaction is automatically logged to a printed report"]'::jsonb,0,'The notes define atomicity as an all-or-nothing guarantee across the transaction''s statements.') and (question_text,options,correct_index,explanation) is distinct from ('In the fund-transfer example, what does ''Atomicity'' guarantee?','["Either both UPDATE statements take effect, or neither does", "The transaction always completes within one second", "Only the DBA can see the transaction''s changes", "The transaction is automatically logged to a printed report"]'::jsonb,0,'The notes define atomicity as an all-or-nothing guarantee across the transaction''s statements.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-transaction-manager-2'; end if;
