if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-transaction-manager-3' and (question_text,options,correct_index,explanation) is distinct from ('Which mechanism does the notes give as a way the Transaction Manager achieves Isolation?','["Locking or multi-version concurrency control (MVCC)", "Write-ahead logging alone", "The Query Processor''s cost-based optimizer", "The Storage Manager''s page fill-factor setting"]'::jsonb,0,'The notes state isolation is achieved through locking or MVCC, distinct from durability''s write-ahead logging mechanism.') and (question_text,options,correct_index,explanation) is distinct from ('Which mechanism does the notes give as a way the Transaction Manager achieves Isolation?','["Locking or multi-version concurrency control (MVCC)", "Write-ahead logging alone", "The Query Processor''s cost-based optimizer", "The Storage Manager''s page fill-factor setting"]'::jsonb,0,'The notes state isolation is achieved through locking or MVCC, distinct from durability''s write-ahead logging mechanism.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-transaction-manager-3'; end if;
