if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-transaction-manager-5' and (question_text,options,correct_index,explanation) is distinct from ('What mechanism does the notes say typically guarantees Durability?','["Write-ahead logging (WAL), where the change is durably logged before being confirmed to the client", "Locking of rows during the transaction", "Full table scans on every commit", "Physical redundancy of the Query Processor"]'::jsonb,0,'The notes attribute durability specifically to write-ahead logging, where changes are logged durably before confirmation.') and (question_text,options,correct_index,explanation) is distinct from ('Which mechanism can support durable commits when coordinated with the required persistence settings and storage guarantees?','["Write-ahead logging with the necessary durable log and acknowledgement ordering", "An arbitrary log message that is never persisted", "A guarantee inferred solely from the word transaction", "Discarding every recovery record before commit"]'::jsonb,0,'Logging is part of a recovery/persistence contract, not an unconditional guarantee independent of configuration and storage behavior.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-transaction-manager-5'; end if;
