if exists(select 1 from public.test_questions where id='tq-dbms-sql-1-transaction-manager-6' and (question_text,options,correct_index,explanation) is distinct from ('What is the risk of using READ UNCOMMITTED isolation for a workload that actually needs strong guarantees, per the notes?','["It permits dirty reads, where a transaction reads data from another transaction that is later rolled back", "It guarantees perfect durability with zero performance cost", "It automatically upgrades itself to SERIALIZABLE when needed", "It prevents any transaction from ever committing"]'::jsonb,0,'The notes explicitly describe the dirty-read risk of READ UNCOMMITTED isolation for workloads needing stronger guarantees.') and (question_text,options,correct_index,explanation) is distinct from ('What is the risk of using READ UNCOMMITTED isolation for a workload that actually needs strong guarantees, per the notes?','["It permits dirty reads, where a transaction reads data from another transaction that is later rolled back", "It guarantees perfect durability with zero performance cost", "It automatically upgrades itself to SERIALIZABLE when needed", "It prevents any transaction from ever committing"]'::jsonb,0,'The notes explicitly describe the dirty-read risk of READ UNCOMMITTED isolation for workloads needing stronger guarantees.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-1-transaction-manager-6'; end if;
