if exists(select 1 from public.test_questions where id='tq-dbx2-transaction-manager-2-8' and (question_text,options,correct_index,explanation) is distinct from ('An application exception leaves a transaction and connection open. What should be investigated?','["Only the spelling of the button label", "A certainty that no locks or snapshots can remain", "Retained transaction resources and a missing completion/rollback path", "A claim that all disconnected sessions last forever"]'::jsonb,2,'An active open transaction can retain resources. Its actual operations determine which ones.') and (question_text,options,correct_index,explanation) is distinct from ('An application exception leaves a transaction and connection open. What should be investigated?','["Only the spelling of the button label", "A certainty that no locks or snapshots can remain", "Retained transaction resources and a missing completion/rollback path", "A claim that all disconnected sessions last forever"]'::jsonb,2,'An active open transaction can retain resources. Its actual operations determine which ones.')) then raise exception 'Edited question requires review: %', 'tq-dbx2-transaction-manager-2-8'; end if;
