insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-transaction-manager-3','pt-dbms-sql-1-transaction-manager','Which mechanism does the notes give as a way the Transaction Manager achieves Isolation?','["Locking or multi-version concurrency control (MVCC)", "Write-ahead logging alone", "The Query Processor''s cost-based optimizer", "The Storage Manager''s page fill-factor setting"]'::jsonb,0,'The notes state isolation is achieved through locking or MVCC, distinct from durability''s write-ahead logging mechanism.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-1-transaction-manager-4','pt-dbms-sql-1-transaction-manager','With a correctly designed atomic conditional capacity update and appropriate conflict handling, how can transaction facilities support reserving the last seat?','["One eligible request can succeed while the competing operation waits, retries safely, or is rejected under the actual algorithm", "Every separate read followed by an unconditional write becomes correct automatically", "All callers can reserve the same final seat without a conflict", "Transaction boundaries remove every need for application checks"]'::jsonb,0,'The DBMS supports a correct algorithm. Transaction support alone does not fix an arbitrary read-then-write counter design.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
