update public.learning_topics set short_description='Clear a complete table while preserving its usable definition, distinguish MySQL identity and transaction behaviour from other engines, and validate reload boundaries on disposable data.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Clear a complete table while preserving its usable definition, distinguish MySQL identity and transaction behaviour from other engines, and validate reload boundaries on disposable data.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for TRUNCATE TABLE.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-9-truncate-table' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-9-truncate-table-application','MCQ Test 2',category,10,10,'Application and scenarios for TRUNCATE TABLE.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-9-truncate-table' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-1','pt-dbms-sql-9-truncate-table','What logical population change does TRUNCATE TABLE request?','["Removes the table structure entirely", "Remove all current rows while retaining a usable table definition", "Removes only rows matching a WHERE clause", "Renames the table"]'::jsonb,1,'Actual duration depends on engine, dependencies and workload.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-2','pt-dbms-sql-9-truncate-table','Which statement can be filtered with a WHERE clause: TRUNCATE TABLE or DELETE?','["Both can", "Neither can", "Only DELETE", "Only TRUNCATE TABLE"]'::jsonb,2,'TRUNCATE always removes every row; only DELETE supports a WHERE clause.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-3','pt-dbms-sql-9-truncate-table','Why can truncation cost differ from ordinary row-by-row deletion?','["It uses a different programming language internally", "The engine can use table-level storage operations rather than the same per-row delete path", "It compresses the data first", "It only removes half the rows"]'::jsonb,1,'This does not imply zero logging or a guaranteed speedup.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-4','pt-dbms-sql-9-truncate-table','Is it accurate to say ''TRUNCATE can never be rolled back'' across all database engines?','["Yes, this is universally true", "No — it is engine-dependent: PostgreSQL and SQL Server support rollback within a transaction, while MySQL/InnoDB implicitly commits and cannot roll it back", "No, TRUNCATE can never be used inside any transaction", "Yes, but only for temporary tables"]'::jsonb,1,'This is a common oversimplification; rollback support for TRUNCATE varies by engine.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-5','pt-dbms-sql-9-truncate-table','What happens to AUTO_INCREMENT in the illustrated MySQL truncate case?','["Both reset the counter identically", "Its counter resets, unlike an ordinary DELETE that does not imply that reset", "DELETE always resets it; TRUNCATE never does", "Neither statement affects the counter"]'::jsonb,1,'Other engines have their own identity options and rules.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-6','pt-dbms-sql-9-truncate-table','Why can MySQL/InnoDB reject truncating a parent even when the child table is empty?','["TRUNCATE never fails under any condition", "An enforced foreign-key definition from another table can still block the operation", "Because TRUNCATE requires the table to have no indexes", "Because foreign keys are automatically dropped by TRUNCATE"]'::jsonb,1,'The structural dependency is not removed merely because no child rows currently exist.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-7','pt-dbms-sql-9-truncate-table','What is a practical consequence of TRUNCATE typically not firing row-level AFTER DELETE triggers?','["Nothing, triggers always fire regardless of the statement used", "Auditing/logging logic that relies on delete triggers may silently miss truncations", "The table becomes read-only afterward", "TRUNCATE becomes slower than DELETE as a result"]'::jsonb,1,'Since most engines skip row-level triggers during TRUNCATE, trigger-based auditing can miss these events.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-9-truncate-table-8','pt-dbms-sql-9-truncate-table','A nightly ETL job uses TRUNCATE TABLE staging_orders; followed by a bulk load, wrapped in BEGIN...COMMIT on PostgreSQL. What happens if the bulk load fails before COMMIT?','["The truncate is already permanent and cannot be undone", "Both the truncate and the failed load are rolled back together since Postgres supports transactional TRUNCATE", "Only the load is rolled back; the table stays truncated", "The database crashes"]'::jsonb,1,'Because PostgreSQL treats TRUNCATE as transactional, a failure before COMMIT rolls back the whole block, including the truncate.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-truncate-table-new-9','pt-dbms-sql-9-truncate-table','Can TRUNCATE use WHERE to retain another batch?','["Yes, like DELETE", "No", "Only for old rows", "Only when indexed"]'::jsonb,1,'The illustrated statement resets the whole table population.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-9-truncate-table-new-10','pt-dbms-sql-9-truncate-table','Does an empty result after reset prove constraints were retained?','["Yes, always", "Only with ORDER BY", "No; accepted and rejected writes provide additional evidence", "Only with no indexes"]'::jsonb,2,'An unconstrained replacement could also initially be empty.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
