insert into public.dsa_problems (id,topic_id,title,difficulty,slug,description,examples,test_cases,constraints,hints,starter_code,editorial,solution_code,solution_approach,supported_languages,sql_schema_sql,sql_seed_sql,learning_topic_id,status,is_premium,show_on_website,show_on_mobile,sort_order) select 'cx-truncate-auto-increment',null::text,'Observe a disposable auto-increment reset after truncation','Easy','truncate-auto-increment','TRUNCATE the supplied temporary import_items table, insert label fresh without specifying item_id, then return item_id and label. The isolated MySQL-style exercise expects the AUTO_INCREMENT counter to reset to 1. Preserve the table definition.

