if exists(select 1 from public.test_questions where id='tq-dbms-sql-2-two-tier-architecture-1' and (question_text,options,correct_index,explanation) is distinct from ('In Two-Tier Architecture, where does the application/business logic reside?','["On the client, bundled together with the user interface", "On a separate middle application-server tier", "Only on the database server", "Distributed evenly across three tiers"]'::jsonb,0,'Two-tier architecture bundles UI and business logic together on the client (Tier 1), with no middle tier.') and (question_text,options,correct_index,explanation) is distinct from ('In the common two-tier teaching arrangement, where are the interface and much application workflow logic located?','["On the client, while trusted database rules can still enforce shared validity", "On a separate middle application-server tier", "Only on the database server", "Distributed evenly across three tiers"]'::jsonb,0,'The placement of workflow logic does not authorize an untrusted client to be the sole enforcement point.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-2-two-tier-architecture-1'; end if;
