update public.learning_topics set short_description='Evaluate direct client-to-database applications through deployment, connection ownership, driver coupling, concurrency, and the trusted enforcement needed beyond client-side business checks.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Evaluate direct client-to-database applications through deployment, connection ownership, driver coupling, concurrency, and the trusted enforcement needed beyond client-side business checks.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for Two Tier Architecture.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-2-two-tier-architecture' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-2-two-tier-architecture-application','MCQ Test 2',category,10,10,'Application and scenarios for Two Tier Architecture.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-2-two-tier-architecture' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-1','pt-dbms-sql-2-two-tier-architecture','In the common two-tier teaching arrangement, where are the interface and much application workflow logic located?','["On the client, while trusted database rules can still enforce shared validity", "On a separate middle application-server tier", "Only on the database server", "Distributed evenly across three tiers"]'::jsonb,0,'The placement of workflow logic does not authorize an untrusted client to be the sole enforcement point.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-2','pt-dbms-sql-2-two-tier-architecture','How many tiers does Two-Tier Architecture have, and what are they?','["Three: client, application server, database server", "Two: client (UI + business logic) and database server", "One: a combined client-database system", "Four: presentation, business, data, and network"]'::jsonb,1,'Two-tier architecture consists of exactly two layers: the client and the database server, connected directly.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-3','pt-dbms-sql-2-two-tier-architecture','In the teller example, which rule can the client check for immediate feedback but must also be enforced on the trusted write path?','["That interest rates must be recalculated nightly", "That a withdrawal must not exceed the available permitted amount", "That the database must use a B+-tree index", "That all queries must go through a connection pool"]'::jsonb,1,'Displayed balances can be stale and clients can be modified; trusted concurrent enforcement is still required.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-4','pt-dbms-sql-2-two-tier-architecture','What is the ''fat client'' problem specific to two-tier architecture?','["Clients use too much disk space for temporary files", "Because business logic lives on every client machine, a rule change requires updating and redeploying the application on every client", "The client cannot connect to the database at all", "The database server becomes too large to manage"]'::jsonb,1,'Embedding business logic on each client means every rule change must be redeployed across all client machines, a defining two-tier drawback.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-5','pt-dbms-sql-2-two-tier-architecture','Assume each active desktop client retains exactly one direct database session. Why can client growth pressure the server?','["Under that assumption, more active clients demand proportionally more server sessions", "Because two-tier systems limit all clients to a single shared connection", "Because the database server cannot accept more than one client ever", "Because two-tier architecture requires no network connection at all"]'::jsonb,0,'The one-session assumption defines the arithmetic; actual clients can use other lifecycle strategies.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-6','pt-dbms-sql-2-two-tier-architecture','What is the key structural difference between two-tier and three-tier architecture regarding business logic?','["There is no difference; both place logic on the client", "In two-tier, logic lives on the client; in three-tier, logic moves to a middle application-server tier", "In two-tier, logic lives on the database server; in three-tier, it lives on the client", "Three-tier architecture has no business logic at all"]'::jsonb,1,'The defining distinction between the two architectures is where business logic resides — client-side in two-tier versus a dedicated middle tier in three-tier.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-7','pt-dbms-sql-2-two-tier-architecture','A bank needs to change its maximum withdrawal limit and must redeploy the updated application to 5,000 teller PCs to do so. Which two-tier pitfall does this best illustrate?','["The connection-scaling bottleneck", "The fat client problem, since business logic embedded on every client machine must be updated wherever it lives", "A conceptual schema design flaw", "A violation of physical data independence"]'::jsonb,1,'Needing to redeploy logic changes across every client machine is precisely the fat-client maintenance burden described for two-tier architecture.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-2-two-tier-architecture-8','pt-dbms-sql-2-two-tier-architecture','Why does tightly coupling two-tier client logic to one database vendor''s driver create a specific long-term risk?','["It has no long-term risk since drivers are interchangeable by default", "It creates vendor lock-in, making it harder to migrate to a different database later since the client talks directly to that vendor''s protocol", "It automatically enables connection pooling", "It eliminates the fat client problem"]'::jsonb,1,'Because the client connects directly to the database vendor''s driver/dialect in two-tier architecture, switching vendors later becomes significantly harder.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-new-9','pt-dbms-sql-2-two-tier-architecture','What distinguishes the two-tier request path in this topic?','["Every SQL statement passes through a separate application server", "The application client communicates directly with the database service", "Every user shares one browser process", "The database has no configured constraints"]'::jsonb,1,'Direct client-to-database communication defines the arrangement.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-new-10','pt-dbms-sql-2-two-tier-architecture','Can trusted database procedures enforce rules in a two-tier design?','["No; all rules must be client-only", "Only if the design has five tiers", "Yes; direct clients do not imply that the database lacks trusted logic", "Only after constraints are disabled"]'::jsonb,2,'Database procedures and constraints can remain authoritative on the trusted path.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-1','pt-dbms-sql-2-two-tier-architecture-application','Two tellers read balance 100 and each locally approves withdrawal 80. What is missing from local checks alone?','["A larger font for the balance", "A second copy of the same stale read", "Trusted coordination or an atomic operation against current shared state", "An arbitrary delay in both clients"]'::jsonb,2,'Both checks can pass against stale data; concurrent integrity needs trusted enforcement.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-2','pt-dbms-sql-2-two-tier-architecture-application','A rule change requires updating 5,000 installed clients. Which cost is exposed?','["Automatic elimination of all database locks", "A requirement to delete account identifiers", "A guaranteed increase in database speed", "Fleet-wide deployment and version coordination"]'::jsonb,3,'Embedded changing logic must be distributed to each relevant installation.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-3','pt-dbms-sql-2-two-tier-architecture-application','Each of 200 clients keeps three direct sessions. What is their configured session demand?','["600 sessions", "200 sessions", "Three sessions", "Sixty sessions"]'::jsonb,0,'The count follows the stated sessions per client, not user count alone.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-4','pt-dbms-sql-2-two-tier-architecture-application','A desktop process uses a local connection pool. Is that structurally impossible in two-tier architecture?','["Yes; pooling requires a browser", "No; a client process can manage its own pool", "Yes; only SQL views can reuse sessions", "Only if every request reads the whole database"]'::jsonb,1,'A shared middle tier is common but not required for process-local reuse.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-5','pt-dbms-sql-2-two-tier-architecture-application','The interface blocks an unauthorized account number, but direct SQL through the same credentials can read it. What failed?','["Only the dropdown styling", "The conceptual meaning of currency", "Trusted access enforcement behind the UI", "The existence of a database server"]'::jsonb,2,'Client-side restrictions cannot be the sole authority.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-6','pt-dbms-sql-2-two-tier-architecture-application','A vendor migration touches SQL and type handling in hundreds of client builds. What is the coupling risk?','["The clients have no data-access dependencies", "All standard APIs guarantee identical semantics", "The database must have lost its primary keys", "Database-specific assumptions are distributed across the fleet"]'::jsonb,3,'Distributed vendor assumptions increase migration and rollout cost.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-7','pt-dbms-sql-2-two-tier-architecture-application','A client loses its commit response and reconnects. What must it avoid assuming?','["That the previous write definitely rolled back", "That a new connection is a separate session", "That errors need handling", "That writes require a trusted contract"]'::jsonb,0,'An uncertain outcome can require reconciliation before retry.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-8','pt-dbms-sql-2-two-tier-architecture-application','A managed small desktop fleet uses a narrow database API and strong server checks. What is a fair architectural assessment?','["Every two-tier application is necessarily unsafe", "Two-tier suitability depends on its actual trust, workload, and maintenance requirements", "Three-tier is always faster for every query", "Client validation eliminates all server checks"]'::jsonb,1,'Architecture choices should follow requirements and verified boundaries.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-9','pt-dbms-sql-2-two-tier-architecture-application','A developer calls a large UI a fat client solely because its binary is large. What should be inspected instead?','["Only compressed download size", "Only the number of icons", "Which changing logic and database assumptions are deployed in it", "Only the table names"]'::jsonb,2,'The maintenance issue concerns responsibilities and coupling rather than byte size alone.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-2-two-tier-architecture-application-new-10','pt-dbms-sql-2-two-tier-architecture-application','A third application tier is proposed. Which evaluation is necessary?','["Only whether three is greater than two", "Only whether the new service has a logo", "Only whether SQL is still capitalized", "Its ownership benefits along with new latency and operational failure paths"]'::jsonb,3,'A middle tier adds capabilities and costs that need evidence.',1,9) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
