select t.id into strict topic_uuid from public.learning_topics t join public.learning_grids g on g.id=t.grid_id where t.source_kind='dbms_sql_tutorial' and t.source_ref='chapter-7-relational-algebra/union' and lower(g.slug)='dbms-sql-tutorial';
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed') <> 1 then raise exception 'Expected one canonical note block: %', 'union'; end if;
if (select count(*) from public.learning_contents c where c.topic_id=topic_uuid) <> 1 then raise exception 'Additional content blocks require review: %', 'union'; end if;
if exists(select 1 from public.learning_contents c where c.topic_id=topic_uuid and c.metadata->>'source'='dbms_sql_tutorial_seed' and md5(c.body) not in ('a6fa7ff5cc3f9b376e9c1a1c332ba200','e9a705844299a4da36e0f80aab326c18')) then raise exception 'Notes changed since seed; review before applying: %', 'union'; end if;
if not exists(select 1 from public.practice_tests where id='pt-dbms-sql-7-union' and learning_topic_id=topic_uuid and scope='topic') then raise exception 'Missing original topic test: %', 'union'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-7-union' and coalesce(negative_marking,0)<>0) then raise exception 'Custom scoring requires review: %', 'union'; end if;
if exists(select 1 from public.practice_tests where learning_topic_id=topic_uuid and scope='topic' and id not in ('pt-dbms-sql-7-union','pt-dbms-sql-7-union-application')) then raise exception 'Extra topic tests require manual integration: %', 'union'; end if;
if exists(select 1 from public.practice_tests where id='pt-dbms-sql-7-union-application' and learning_topic_id is distinct from topic_uuid) then raise exception 'Test ID collision: %', 'union'; end if;
if exists(select 1 from public.learning_contents where topic_id=topic_uuid and metadata->'dbms_diagrams_v1' is not null and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Distinct membership and combined source occurrences are different results", "description": "Plain union returns one identity regardless of repetition, whereas an occurrence count deliberately preserves every contributing source row.", "columns": ["Student identity", "Honors occurrences", "DeanList occurrences", "Distinct union copies", "Combined occurrence count"], "rows": [["1", "1", "0", "1", "1"], ["2", "2", "1", "1", "3"], ["3", "0", "1", "1", "1"]]}]'::jsonb) then raise exception 'Edited diagram metadata requires review: %', 'union'; end if;
update public.learning_contents set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{dbms_diagrams_v1}','[{"kind": "table", "caption": "Distinct membership and combined source occurrences are different results", "description": "Plain union returns one identity regardless of repetition, whereas an occurrence count deliberately preserves every contributing source row.", "columns": ["Student identity", "Honors occurrences", "DeanList occurrences", "Distinct union copies", "Combined occurrence count"], "rows": [["1", "1", "0", "1", "1"], ["2", "2", "1", "1", "3"], ["3", "0", "1", "1", "1"]]}]'::jsonb),updated_at=now() where topic_id=topic_uuid and metadata->>'source'='dbms_sql_tutorial_seed' and metadata->'dbms_diagrams_v1' is distinct from '[{"kind": "table", "caption": "Distinct membership and combined source occurrences are different results", "description": "Plain union returns one identity regardless of repetition, whereas an occurrence count deliberately preserves every contributing source row.", "columns": ["Student identity", "Honors occurrences", "DeanList occurrences", "Distinct union copies", "Combined occurrence count"], "rows": [["1", "1", "0", "1", "1"], ["2", "2", "1", "1", "3"], ["3", "0", "1", "1", "1"]]}]'::jsonb;
