if exists(select 1 from public.test_questions where id='tq-dbms-sql-7-union-3' and (question_text,options,correct_index,explanation) is distinct from ('How does SQL''s plain UNION handle duplicate rows appearing in both queries?','["It keeps every occurrence, duplicating them", "It automatically removes duplicates, matching the algebra''s set-based semantics", "It raises an error whenever duplicates are found", "It keeps duplicates only from the first query"]'::jsonb,1,'Plain UNION deduplicates, mirroring the mathematical union-of-sets behavior that the algebra models.') and (question_text,options,correct_index,explanation) is distinct from ('How does SQL''s plain UNION handle duplicate rows appearing in both queries?','["It keeps every occurrence, duplicating them", "It automatically removes duplicates, matching the algebra''s set-based semantics", "It raises an error whenever duplicates are found", "It keeps duplicates only from the first query"]'::jsonb,1,'Plain UNION removes repeated equal selected tuples, including duplicates within a branch and across branches.')) then raise exception 'Edited question requires review: %', 'tq-dbms-sql-7-union-3'; end if;
