insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-1','pt-dbms-sql-5-unique-constraint','For a single nullable MySQL UNIQUE column, which distinctness rule applies to ordinary non-NULL values?','["That a column can never be NULL", "That a column''s (non-NULL) values contain no duplicates", "That a column must be numeric", "That a table has at most 100 rows"]'::jsonb,1,'UNIQUE forbids duplicate values among the non-NULL entries in a column.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-2','pt-dbms-sql-5-unique-constraint','For a required non-NULL email column, which query finds repeated values in the current data?','["SELECT * FROM employees WHERE email IS NULL", "SELECT email, COUNT(*) FROM employees GROUP BY email HAVING COUNT(*) > 1", "SELECT DISTINCT email FROM employees", "SELECT email FROM employees ORDER BY email"]'::jsonb,1,'Grouping by the target column and filtering for groups with more than one row reveals exactly the duplicate values.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-3','pt-dbms-sql-5-unique-constraint','Can a nullable MySQL UNIQUE column permit multiple NULLs?','["No, at most one NULL is ever allowed", "Yes — NULL is not treated as equal to another NULL, so multiple rows can each have NULL", "Only if the column is also PRIMARY KEY", "UNIQUE columns cannot be NULL under any circumstances"]'::jsonb,1,'MySQL permits multiple NULLs under this declaration. Optional uniqueness is operation-specific behaviour, not a claim that ordinary NULL inequality is TRUE.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-4','pt-dbms-sql-5-unique-constraint','What happens if you try to add a UNIQUE constraint to a column that already has duplicate values?','["The duplicates are silently deleted", "The constraint addition fails until the existing duplicates are resolved", "Only the first duplicate is kept automatically", "SQL renames the duplicates to make them unique"]'::jsonb,1,'The database refuses to apply a constraint the current data already violates — cleanup must happen first.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-5','pt-dbms-sql-5-unique-constraint','Can a UNIQUE constraint span multiple columns?','["No, UNIQUE only ever applies to a single column", "Yes — a composite UNIQUE constraint enforces that the combination of columns is distinct, similar to a composite key", "Only PRIMARY KEY can be composite", "Composite UNIQUE constraints are deprecated"]'::jsonb,1,'A composite UNIQUE constrains combinations under the engine’s actual rules; required identity components need an appropriate nonmissing policy.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-6','pt-dbms-sql-5-unique-constraint','When is a UNIQUE constraint actually checked by the database?','["Only once, when the table is first created", "On every INSERT and UPDATE that could affect the constrained column(s)", "Only during a nightly maintenance job", "Only when explicitly requested via a CHECK command"]'::jsonb,1,'UNIQUE is enforced continuously at write time, not just at schema-creation time.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-7','pt-dbms-sql-5-unique-constraint','What real trade-off does enforcing a UNIQUE constraint introduce?','["None — there is no cost to enforcing UNIQUE", "Constraint and supporting-index work can add write costs whose magnitude depends on engine, workload and contention", "UNIQUE constraints make SELECT queries slower, never writes", "UNIQUE constraints prevent all future schema changes"]'::jsonb,1,'The overhead is real but cannot be characterized as universally small without measurements.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-5-unique-constraint-8','pt-dbms-sql-5-unique-constraint','Is UNIQUE the correct mechanism to enforce an alternate key (5.4)?','["No, alternate keys cannot be enforced in SQL", "Yes, together with the appropriate nonmissing policy when the alternate candidate identity is required", "Only PRIMARY KEY can enforce any kind of key", "Alternate keys require a CHECK constraint instead"]'::jsonb,1,'Required alternate identities need both their uniqueness and absence policies represented correctly.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('pt-dbms-sql-5-unique-constraint-new-9','pt-dbms-sql-5-unique-constraint','Why does a pre-insert form lookup not replace a UNIQUE constraint?','["Every form lookup locks the whole database forever", "A concurrent or alternative write can bypass the precheck’s assumption", "SELECT always creates a unique index", "Only a form can validate data"]'::jsonb,1,'The accepted trusted write boundary must preserve the rule.',1,8) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
