(3, ''Marketing'');

INSERT INTO employees (id, name, email, department_id) VALUES
(1, ''Asha'', ''asha@co.com'', 1),
(2, ''Rohan'', ''rohan@co.com'', 1),
(3, ''Neha'', ''neha@co.com'', 2),
(4, ''Vikram'', ''asha@co.com'', 2),
(5, ''Priya'', ''priya@co.com'', 99),
(6, ''Karan'', ''karan@co.com'', 3),
(7, ''Divya'', ''karan@co.com'', 3),
(8, ''Aman'', ''aman@co.com'', 88);',topic_uuid,parent.status,parent.is_premium,parent.show_on_website,parent.show_on_mobile,0 from public.practice_tests parent where parent.id='pt-dbms-sql-5-unique-constraint' on conflict(id) do update set description=excluded.description,examples=excluded.examples,test_cases=excluded.test_cases,constraints=excluded.constraints,hints=excluded.hints,editorial=excluded.editorial,solution_code=excluded.solution_code,solution_approach=excluded.solution_approach,updated_at=now() where (dsa_problems.description,dsa_problems.examples,dsa_problems.test_cases,dsa_problems.constraints,dsa_problems.hints,dsa_problems.editorial,dsa_problems.solution_code,dsa_problems.solution_approach) is distinct from (excluded.description,excluded.examples,excluded.test_cases,excluded.constraints,excluded.hints,excluded.editorial,excluded.solution_code,excluded.solution_approach);
