update public.learning_topics set short_description='Declare single and composite uniqueness at the intended grain, account for NULL and collation rules, and distinguish deduplicating proposed input from enforcing accepted state.',updated_at=now() where id=topic_uuid and short_description is distinct from 'Declare single and composite uniqueness at the intended grain, account for NULL and collation rules, and distinguish deduplicating proposed input from enforcing accepted state.';
update public.practice_tests set title='MCQ Test 1',question_count=10,total_marks=10,pass_marks=4,duration_minutes=10,description='Concepts and fundamentals for UNIQUE.',instructions='Answer all ten questions. One mark each; no negative marking.',updated_at=now() where id='pt-dbms-sql-10-unique' and (title<>'MCQ Test 1' or question_count<>10 or total_marks<>10);
insert into public.practice_tests (id,title,category,question_count,duration_minutes,description,total_marks,pass_marks,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,negative_marking,instructions,show_on_website,show_on_mobile,scope) select 'pt-dbms-sql-10-unique-application','MCQ Test 2',category,10,10,'Application and scenarios for UNIQUE.',10,4,is_published,difficulty,learning_grid_id,learning_topic_id,status,is_premium,0,'Answer all ten questions. One mark each; no negative marking.',show_on_website,show_on_mobile,'topic' from public.practice_tests where id='pt-dbms-sql-10-unique' on conflict(id) do nothing;
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-1','pt-dbms-sql-10-unique','Which SQL clause is required when a uniqueness rule must span two columns together, such as (student_id, course_id)?','["Two separate column-level UNIQUE clauses, one per column", "A table-level UNIQUE clause listing both columns", "A CHECK constraint referencing both columns", "A FOREIGN KEY referencing both columns"]'::jsonb,1,'Column-level UNIQUE applies to a single column only; a composite uniqueness rule requires the table-level UNIQUE (col1, col2) form.',1,0) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-2','pt-dbms-sql-10-unique','Under ordinary nullable UNIQUE behaviour in the illustrated MySQL definition, can several rows have NULL?','["Zero — NULL is forbidden in a UNIQUE column", "Exactly one", "Yes; repeated missing markers are permitted by this chosen rule", "Unlimited only if the column is also indexed manually"]'::jsonb,2,'Products and options such as PostgreSQL NULLS NOT DISTINCT can choose different uniqueness treatment.',1,1) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-3','pt-dbms-sql-10-unique','What is the correct way to drop a named UNIQUE constraint `uq_users_username` in MySQL?','["ALTER TABLE users DROP CONSTRAINT uq_users_username;", "ALTER TABLE users DROP UNIQUE uq_users_username;", "ALTER TABLE users DROP INDEX uq_users_username;", "DROP UNIQUE ON users.uq_users_username;"]'::jsonb,2,'MySQL implements UNIQUE constraints as unique indexes internally, so they are dropped with DROP INDEX rather than DROP CONSTRAINT.',1,2) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-4','pt-dbms-sql-10-unique','What happens when you run ALTER TABLE users ADD CONSTRAINT uq_username UNIQUE (username); on a table that already has two rows with the same username value?','["The constraint is added and future duplicates are blocked, but the existing duplicates remain", "The statement fails because existing data violates the new constraint", "MySQL silently deletes one of the duplicate rows", "The constraint is added in a disabled state"]'::jsonb,1,'Adding a UNIQUE constraint validates existing data first; duplicates already present cause the ALTER TABLE to be rejected.',1,3) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-5','pt-dbms-sql-10-unique','How many primary-key constraints can a table declare?','["At most one; it may also declare several supported unique rules", "Any number of both", "Exactly one of each", "Any number of PRIMARY KEY, exactly one UNIQUE"]'::jsonb,0,'SQL permits a table with no declared primary key.',1,4) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-6','pt-dbms-sql-10-unique','How should PRIMARY KEY be distinguished from a required UNIQUE rule?','["They are unrelated features with no overlap", "They overlap in presence and uniqueness but differ in designated key role and possible engine-specific behaviour", "UNIQUE is a stricter version of PRIMARY KEY", "PRIMARY KEY allows NULLs while UNIQUE does not"]'::jsonb,1,'They are not universally identical metadata or storage declarations.',1,5) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-7','pt-dbms-sql-10-unique','In a composite constraint UNIQUE (a, b), which of the following is allowed?','["Duplicate values in column a alone, as long as the (a, b) pair as a whole is not duplicated", "Any duplicate row where a matches another row''s a", "No duplicates in either column individually", "Duplicate (a, b) pairs as long as a is not the primary key"]'::jsonb,0,'A composite UNIQUE constraint only forbids duplicate combinations of the listed columns; individual columns may repeat freely on their own.',1,6) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
insert into public.test_questions (id,test_id,question_text,options,correct_index,explanation,marks,sort_order) values ('tq-dbms-sql-10-unique-8','pt-dbms-sql-10-unique','Why might a database administrator avoid adding a UNIQUE constraint to a column that doesn''t strictly need one?','["UNIQUE constraints prevent the column from ever being updated", "UNIQUE automatically creates a supporting index in most engines, adding overhead to write-heavy workloads", "UNIQUE constraints cannot coexist with NOT NULL", "UNIQUE constraints are deprecated in modern SQL"]'::jsonb,1,'Most engines back a UNIQUE constraint with an index to enforce it efficiently, and that index carries maintenance cost on every insert/update, which matters for high-write tables.',1,7) on conflict(id) do update set question_text=excluded.question_text,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation where (test_questions.question_text,test_questions.options,test_questions.correct_index,test_questions.explanation) is distinct from (excluded.question_text,excluded.options,excluded.correct_index,excluded.explanation);
