insert into public.learning_topics (id,section_id,grid_id,title,slug,short_description,sort_order,status,is_premium,show_on_website,show_on_mobile,source_kind,source_ref) select '142a77c8-5f3a-5460-8ae3-33dc2af3dd65',s.id,s.grid_id,'Window Functions, Ranking, and Frames','window-functions-ranking-and-frames','Preserve row identity while deriving partitioned rankings and moving totals, with explicit tie policies, result ordering and row-frame boundaries.',1,'draft',g.is_premium,g.show_on_website and s.show_on_website,g.show_on_mobile and s.show_on_mobile,'dbms_sql_tutorial','chapter-33-advanced-sql-window-functions/window-functions-ranking-and-frames' from public.learning_sections s join public.learning_grids g on g.id=s.grid_id where s.id=section_uuid on conflict(id) do nothing;
